-- بيانات مقرر كيمياء 3 (المقرر 4، قيد الإعداد) — الجزء 2 من 5. نفّذ الأجزاء بالترتيب.
-- مولّد آليًا بواسطة scripts/build-chem3-seed.js — لا تعدّله يدويًا.
begin;
insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K3-C1-L3-O05'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'كمية من السكر المطحون وكمية مساوية لها من مكعبات السكر وُضعتا في الظروف نفسها. أيهما يذوب أسرع؟', null, '["مكعبات السكر","يذوبان في الزمن نفسه","يتوقف ذلك على نوع المذيب","السكر المطحون الناعم"]'::jsonb, 'تذكر', 'استرجاع مثال', 'سهل', 'الكتاب ص 32 — العوامل المؤثرة في الذوبان: مساحة السطح'),
('mcq', 2, 'لماذا يزيد تكسير المذاب إلى قطع صغيرة من سرعة ذوبانه؟', null, '["لأنه يقلل كتلة المذاب الكلية","لأنه يزيد مساحة سطحه فيزداد عدد التصادمات مع جسيمات المذيب","لأنه يزيد ذائبية المذاب في المذيب","لأنه يرفع درجة حرارة المذيب"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 32 — العوامل المؤثرة في الذوبان: مساحة السطح'),
('mcq', 3, 'أيّ الصور الآتية لكتلة 10 g من الملح تذوب أسرع في ماء عند درجة الحرارة نفسها ودون تحريك؟', null, '["قطعة واحدة كبيرة","قطعتان متساويتان","مسحوق ناعم","حبيبات خشنة كبيرة"]'::jsonb, 'تطبيق', 'مقارنة بين أشكال', 'سهل', 'الكتاب ص 32 — العوامل المؤثرة في الذوبان: مساحة السطح'),
('mcq', 4, 'مكعب من مادة صلبة طول ضلعه 2 cm قُطع إلى 8 مكعبات طول ضلع كل منها 1 cm. كم تصبح مساحة السطح الكلية؟', null, '["48 cm² أي ضعف المساحة الأصلية","24 cm² أي المساحة نفسها","8 cm² أي ثلث المساحة الأصلية","6 cm² أي ربع المساحة الأصلية"]'::jsonb, 'تطبيق', 'حساب مساحة سطح', 'صعب', 'الكتاب ص 32 — مساحة السطح (تطبيق حسابي)'),
('mcq', 5, 'على ماذا تعتمد زيادة سرعة الذوبان الناتجة عن زيادة مساحة سطح المذاب؟', null, '["زيادة الطاقة الحركية لجسيمات المذيب","زيادة قطبية جسيمات المذاب","إبعاد الجسيمات الذائبة عن سطح التماس بسرعة","زيادة عدد جسيمات المذاب المعرّضة للتصادم مع المذيب"]'::jsonb, 'فهم', 'تفسير جسيمي', 'متوسط', 'الكتاب ص 32 — العوامل المؤثرة في الذوبان: مساحة السطح'),
('mcq', 6, 'أراد طالب تسريع ذوبان قرص دواء فوّار في كأس ماء دون أن يغيّر درجة الحرارة أو يحرّك الماء. أيّ إجراء يحقق ذلك؟', null, '["إلقاء قرصين كاملين بدل قرص واحد","سحق القرص قبل إلقائه في الماء","وضع القرص كاملًا في كمية ماء أقل","تغطية الكأس بعد إلقاء القرص فيه"]'::jsonb, 'تطبيق', 'تطبيق في موقف حياتي', 'متوسط', 'الكتاب ص 32 — العوامل المؤثرة في الذوبان: مساحة السطح'),
('mcq', 7, 'طُحن 20 g من ملح الطعام طحنًا ناعمًا ووُضع في الماء. أيّ العبارات الآتية صحيحة مقارنة بوضع 20 g من الملح نفسه في صورة قطع كبيرة؟', null, '["يذوب الملح المطحون أسرع، وتزداد أقصى كمية تذوب منه","تذوب القطع الكبيرة أسرع لأن كتلة كل قطعة أكبر","يذوب الملح المطحون أسرع، وأقصى كمية تذوب منه لا تتغير","لا فرق بينهما في السرعة ولا في الكمية القصوى"]'::jsonb, 'تحليل', 'تمييز بين السرعة والذائبية', 'صعب', 'الكتاب ص 32–33 — مساحة السطح والذائبية'),
('essay', 1, 'فسّر لماذا تذوب ملعقة من السكر المطحون أسرع من الكمية نفسها من السكر في صورة مكعبات.', null, null, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 32 — العوامل المؤثرة في الذوبان: مساحة السطح'),
('essay', 2, 'مكعب سكر طول ضلعه 3 cm قُطع إلى مكعبات صغيرة طول ضلع كل منها 1 cm. احسب: (أ) مساحة سطح المكعب الأصلي، (ب) عدد المكعبات الصغيرة ومساحة سطحها الكلية، (ج) كم مرة تضاعفت مساحة السطح؟ ثم وضّح أثر ذلك في سرعة الذوبان.', null, null, 'تطبيق', 'حساب وتفسير', 'صعب', 'الكتاب ص 32 — مساحة السطح (تطبيق حسابي)'),
('essay', 3, 'لديك ملح على هيئة قطع كبيرة وملح ناعم وماء وكؤوس وساعة إيقاف. صف تجربة توضح أثر مساحة السطح في سرعة الذوبان، مع ذكر المتغيرات التي يجب ضبطها والنتيجة المتوقعة.', null, null, 'تحليل', 'تصميم تجربة', 'متوسط', 'الكتاب ص 32 — العوامل المؤثرة في الذوبان: مساحة السطح')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C1-L3-O05') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'ملعقة من السكر المطحون تذوب أسرع من الكمية نفسها التي تكون في صورة مكعبات، لأن مساحة سطحها أكبر.', '["المكعبات مساحة سطحها المعرض للمذيب أقل، فتذوب أبطأ.","تساوي الكتلة لا يعني تساوي مساحة السطح التي تحدد عدد التصادمات.","المذيب نفسه في الحالتين، والفرق الوحيد مساحة السطح.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T11:36:22.372Z"}'::jsonb),
('mcq', 2, 1, 'تكسير المذاب إلى قطع صغيرة يزيد مساحة سطحه، وهذه الزيادة تساعد على زيادة عدد التصادمات بين جسيماته وجسيمات المذيب، فيزداد سرعة الذوبان.', '["التكسير لا يغيّر الكتلة الكلية للمذاب.","","الذائبية لا تتغير بالتكسير؛ تتغير سرعة الذوبان فقط.","التكسير لا يغير درجة حرارة المذيب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.372Z"}'::jsonb),
('mcq', 3, 2, 'المسحوق الناعم له أكبر مساحة سطح معرضة للمذيب بين الصور المذكورة، فتحدث فيه أكبر عدد من التصادمات مع جزيئات الماء ويذوب أسرع.', '["القطعة الواحدة أقل مساحة سطح، فتذوب أبطأ.","التقسيم إلى قطعتين يزيد المساحة قليلًا فقط مقارنة بالمسحوق.","","الحبيبات الخشنة مساحة سطحها أقل من المسحوق الناعم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.372Z"}'::jsonb),
('mcq', 4, 0, 'مساحة سطح المكعب الأصلي = 6 × (2 cm)² = 24 cm². بعد التقطيع: 8 × 6 × (1 cm)² = 48 cm²، أي تضاعفت مساحة السطح المعرضة للمذيب مع بقاء الكتلة نفسها، فتزداد سرعة الذوبان.', '["","هذا افتراض أن التقطيع لا يغير المساحة، مع أنه يكشف أوجهًا جديدة.","هذا مجموع أحجام المكعبات الصغيرة (8 cm³) لا مساحة سطحها.","هذه مساحة سطح مكعب صغير واحد فقط، دون الضرب في عدد المكعبات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-10-17T11:36:22.373Z"}'::jsonb),
('mcq', 5, 3, 'الذوبان يحدث عند السطح حيث تتصادم جسيمات المذيب مع جسيمات المذاب، فزيادة مساحة السطح تزيد عدد الجسيمات المكشوفة للمذيب، فيزداد عدد التصادمات في الوقت نفسه.', '["زيادة الطاقة الحركية أثر رفع درجة الحرارة لا زيادة مساحة السطح.","تكسير المذاب لا يغير قطبية جسيماته.","هذا أثر التحريك لا أثر مساحة السطح.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.373Z"}'::jsonb),
('mcq', 6, 1, 'مع تثبيت درجة الحرارة وعدم التحريك يبقى العامل المتاح هو مساحة السطح؛ وسحق القرص يزيد مساحة سطحه فتزداد التصادمات مع الماء ويذوب أسرع.', '["زيادة كمية المذاب لا تسرّع ذوبان القرص الواحد.","","تقليل الماء لا يزيد مساحة سطح القرص ولا يسرّع ذوبانه.","تغطية الكأس لا تؤثر في مساحة سطح المذاب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.373Z"}'::jsonb),
('mcq', 7, 2, 'الطحن يزيد مساحة السطح فيزيد التصادمات وسرعة الذوبان، أما الذائبية (أقصى كمية تذوب في كمية محددة من المذيب عند درجة حرارة معينة) فتعتمد على طبيعة المذاب والمذيب ودرجة الحرارة، لا على حجم الحبيبات.', '["الطحن لا يغير الذائبية، بل سرعة الذوبان فقط.","القطع الكبيرة أقل مساحة سطح فتذوب أبطأ.","","مساحة السطح تؤثر في سرعة الذوبان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T11:36:22.373Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يحدث الذوبان عند تصادم جسيمات المذاب مع جسيمات المذيب على سطح المذاب. السكر المطحون مقسم إلى قطع صغيرة جدًّا، فمساحة سطحه المعرض للمذيب أكبر بكثير من مساحة سطح المكعبات ذات الكتلة نفسها. وزيادة مساحة السطح تزيد عدد التصادمات بين جسيمات السكر وجسيمات الماء، فتزداد سرعة الذوبان.', '["الذوبان يحدث بالتصادم عند السطح","السكر المطحون مساحة سطحه أكبر","زيادة المساحة تزيد عدد التصادمات فتزداد السرعة"]'::jsonb, '[]'::jsonb, '[{"element":"ربط الذوبان بالتصادمات عند السطح","marks":1},{"element":"المقارنة بين مساحتي السطح","marks":1},{"element":"الاستنتاج: تصادمات أكثر وسرعة أكبر","marks":1}]'::jsonb, '[{"level":"3","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات علمية سليمة."},{"level":"2","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb, '["القول إن السكر المطحون أخف فيذوب أسرع","القول إن الطحن يزيد ذائبية السكر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T11:36:22.373Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) مساحة سطح المكعب الأصلي = 6 × (3 cm)² = 54 cm². (ب) عدد المكعبات الصغيرة = (3 ÷ 1)³ = 27 مكعبًا، ومساحة سطحها الكلية = 27 × 6 × (1 cm)² = 162 cm². (ج) 162 ÷ 54 = 3، أي تضاعفت مساحة السطح 3 مرات مع بقاء الكتلة نفسها. وبما أن زيادة مساحة السطح تزيد عدد التصادمات بين جسيمات السكر وجسيمات المذيب، فإن سرعة ذوبان القطع الصغيرة تكون أكبر.', '["مساحة المكعب الأصلي 54 cm²","27 مكعبًا مساحتها الكلية 162 cm²","النسبة 3 مرات","زيادة المساحة تزيد التصادمات وسرعة الذوبان"]'::jsonb, '["مساحة سطح المكعب = 6 × (طول الضلع)² = 6 × 3² = 54 cm²","عدد المكعبات = 3³ = 27","المساحة الكلية = 27 × 6 × 1² = 162 cm²","النسبة = 162 ÷ 54 = 3"]'::jsonb, '[{"element":"حساب المساحة الأصلية","marks":1},{"element":"حساب العدد والمساحة الكلية","marks":2},{"element":"حساب النسبة","marks":1},{"element":"التفسير بالتصادمات","marks":1}]'::jsonb, '[{"level":"5","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات علمية سليمة."},{"level":"3–4","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1–2","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb, '["حساب عدد المكعبات 9 بدل 27","استعمال الحجم بدل المساحة","نسيان الضرب في 6 أوجه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (37%)"}],"at":"2026-10-17T11:36:22.373Z"}'::jsonb),
('essay', 3, null::int, null, null, 'توضع كمية متساوية من الماء عند درجة الحرارة نفسها في كأسين متماثلتين. توزن كتلتان متساويتان من الملح، إحداهما قطع كبيرة والأخرى ملح ناعم، وتوضع كل منهما في كأس في اللحظة نفسها دون تحريك (أو بالتحريك نفسه في الكأسين)، ويُقاس زمن ذوبان كل منهما بساعة الإيقاف. المتغير المستقل: مساحة السطح (حجم الحبيبات). المتغيرات المضبوطة: كتلة الملح، وكمية الماء، ودرجة حرارته، والتحريك. النتيجة المتوقعة: يذوب الملح الناعم أسرع لأن مساحة سطحه أكبر فتزداد التصادمات بين جسيماته وجزيئات الماء.', '["خطوات التجربة بكتلتين متساويتين","المتغير المستقل: حجم الحبيبات/مساحة السطح","ضبط كمية الماء ودرجة حرارته والتحريك والكتلة","النتيجة المتوقعة مع التفسير"]'::jsonb, '[]'::jsonb, '[{"element":"الخطوات","marks":1},{"element":"المتغير المستقل","marks":1},{"element":"المتغيرات المضبوطة","marks":2},{"element":"النتيجة والتفسير","marks":1}]'::jsonb, '[{"level":"5","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات علمية سليمة."},{"level":"3–4","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1–2","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb, '["استعمال كتلتين مختلفتين من الملح","تحريك كأس دون الأخرى فيختلط أثر التحريك بأثر مساحة السطح"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.374Z"}'::jsonb)
