('mcq', 4, 'ما الكمية التي تبقى ثابتة لغاز مذاب في سائل وفق قانون هنري عند درجة حرارة معينة؟', null, '["حاصل ضرب الذائبية في الضغط","الذائبية مهما تغير الضغط","ناتج قسمة الذائبية على الضغط","ناتج قسمة الضغط على درجة الحرارة"]'::jsonb, 'فهم', 'تفسير صيغة', 'متوسط', 'الكتاب ص 36 — قانون هنري'),
('mcq', 5, 'وفق قانون هنري، إذا زاد ضغط غاز فوق سائل إلى ثلاثة أمثاله عند ثبوت درجة الحرارة، فإن ذائبية الغاز:', null, '["تزداد إلى ثلاثة أمثالها","تقل إلى ثلث قيمتها","تبقى ثابتة","تزداد إلى تسعة أمثالها"]'::jsonb, 'فهم', 'تطبيق مباشر للنص', 'متوسط', 'الكتاب ص 36 — قانون هنري'),
('mcq', 6, 'لماذا يشترط قانون هنري ثبوت درجة الحرارة؟', null, '["لأن ضغط الغاز لا يتغير إلا بتغير الحرارة","لأن السائل يتجمد إذا تغيرت درجة حرارته","لأن الغازات لا تذوب في السوائل الساخنة مطلقًا","لأن ذائبية الغاز تتغير بتغير درجة الحرارة أيضًا"]'::jsonb, 'فهم', 'تعليل شرط', 'صعب', 'الكتاب ص 35–36 — ذائبية الغازات وقانون هنري'),
