('essay', 1, 'اذكر نص قانون هنري، واكتب علاقته الرياضية موضحًا دلالة كل رمز فيها.', null, null, 'تذكر', 'ذكر نص قانون وصيغته', 'سهل', 'الكتاب ص 36 — قانون هنري'),
('essay', 2, 'ذائبية غاز في الماء 0.20 g/L عند ضغط 1.0 atm ودرجة حرارة ثابتة. اعتمادًا على نص قانون هنري، أكمل الذائبية عند 2.0 atm و3.0 atm، ثم بيّن كيف تدل القيم على معنى «التناسب الطردي» في نص القانون.', null, null, 'فهم', 'توضيح نص قانون بالأرقام', 'متوسط', 'الكتاب ص 36 — قانون هنري'),
