('mcq', 1, 0, 'نص قانون هنري: «تتناسب ذائبية الغاز في سائل (S) تناسبًا طرديًا مع ضغط الغاز (P) الموجود فوق السائل عند ثبوت درجة الحرارة».', '["","العلاقة طردية لا عكسية؛ فكلما زاد الضغط زادت الذائبية.","القانون يربط الذائبية بالضغط، وذائبية الغازات تقل بارتفاع الحرارة.","حجم السائل ليس من متغيرات قانون هنري."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.374Z"}'::jsonb),
('mcq', 2, 3, 'يُمثَّل قانون هنري بالعلاقة S₁/P₁ = S₂/P₂، أي إن ناتج قسمة الذائبية على الضغط ثابت عند درجة حرارة معينة، وهذا تعبير عن التناسب الطردي.', '["حاصل الضرب الثابت يعبر عن تناسب عكسي، وقانون هنري تناسب طردي.","القانون يتعلق بالضغط عند ثبوت درجة الحرارة لا بدرجة الحرارة.","هذا قانون بويل للغازات ولا يتضمن الذائبية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.374Z"}'::jsonb),
('mcq', 3, 1, 'في قانون هنري يمثل S الذائبية ويمثل P الضغط.', '["الترتيب معكوس؛ S للذائبية وP للضغط.","","S في القانون رمز الذائبية لا السرعة.","P رمز الضغط، ودرجة الحرارة ثابتة في القانون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.374Z"}'::jsonb),
('mcq', 4, 2, 'ينص قانون هنري على أنه «يبقى ناتج قسمة الذائبية على الضغط ثابتًا عند درجة حرارة معينة»، أي S/P = ثابت.', '["ثبات حاصل الضرب يعني تناسبًا عكسيًا يخالف قانون هنري.","الذائبية تتغير بتغير الضغط طرديًا.","","القانون يتعلق بالعلاقة بين الذائبية والضغط لا بين الضغط والحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.375Z"}'::jsonb),
('mcq', 5, 0, 'بما أن الذائبية تتناسب طرديًا مع الضغط عند ثبوت درجة الحرارة، فإن مضاعفة الضغط ثلاث مرات تضاعف الذائبية ثلاث مرات (S₂ = S₁ × 3P₁/P₁ = 3S₁).', '["","هذا يناسب علاقة عكسية، والعلاقة في قانون هنري طردية.","الذائبية تعتمد على الضغط ولا تبقى ثابتة عند تغيره.","التناسب طردي بسيط وليس مع مربع الضغط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:36:22.375Z"}'::jsonb),
('mcq', 6, 3, 'ذائبية الغازات في السوائل تقل بارتفاع درجة الحرارة، فلو تغيرت الحرارة لتغيرت الذائبية لسبب غير الضغط، ولما بقي ناتج S/P ثابتًا؛ لذا يُثبَّت عامل الحرارة لتظهر العلاقة بين الذائبية والضغط وحدها.', '["يمكن تغيير الضغط فوق السائل عند ثبوت الحرارة، كما عند فتح عبوة مشروب غازي.","التجمد ليس سبب الشرط؛ السبب تأثر ذائبية الغاز بالحرارة.","الغازات تذوب في السوائل الساخنة لكن ذائبيتها أقل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.375Z"}'::jsonb),
('mcq', 7, 1, 'التناسب الطردي S = (ثابت) × P يُمثل بيانيًا بخط مستقيم يمر بنقطة الأصل، ميله يساوي الثابت S/P.', '["الخط الهابط يعني نقصان الذائبية بزيادة الضغط، وهذا يخالف القانون.","","الخط الأفقي يعني ثبات الذائبية مع تغير الضغط.","هذا شكل العلاقة العكسية التي يكون فيها حاصل الضرب ثابتًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:36:22.375Z"}'::jsonb),
('essay', 1, null::int, null, null, 'نص قانون هنري: تتناسب ذائبية الغاز في سائل (S) تناسبًا طرديًا مع ضغط الغاز (P) الموجود فوق السائل عند ثبوت درجة الحرارة. العلاقة الرياضية: S₁/P₁ = S₂/P₂، حيث S₁ ذائبية الغاز عند الضغط P₁، وS₂ ذائبيته عند الضغط P₂، ودرجة الحرارة ثابتة.', '["النص: تناسب طردي بين الذائبية والضغط","شرط ثبوت درجة الحرارة","العلاقة S₁/P₁ = S₂/P₂","دلالة الرموز"]'::jsonb, '[]'::jsonb, '[{"element":"النص مع ذكر التناسب الطردي","marks":1},{"element":"شرط ثبوت درجة الحرارة","marks":1},{"element":"العلاقة الرياضية","marks":1},{"element":"دلالة الرموز","marks":1}]'::jsonb, '[{"level":"4","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات علمية سليمة."},{"level":"2–3","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb, '["ذكر تناسب عكسي","إغفال شرط ثبوت درجة الحرارة","كتابة S₁P₁ = S₂P₂"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.375Z"}'::jsonb),
('essay', 2, null::int, null, null, 'وفق قانون هنري تتناسب الذائبية طرديًا مع الضغط عند ثبوت الحرارة: عند 2.0 atm تكون الذائبية 0.20 × 2.0/1.0 = 0.40 g/L، وعند 3.0 atm تكون 0.20 × 3.0/1.0 = 0.60 g/L. نلاحظ أن مضاعفة الضغط ضاعفت الذائبية، ومضاعفته ثلاث مرات ضاعفت الذائبية ثلاث مرات، وأن ناتج S/P بقي ثابتًا (0.20 g/L لكل atm) في الحالات الثلاث، وهذا هو معنى التناسب الطردي.', '["الذائبية عند 2.0 atm = 0.40 g/L","الذائبية عند 3.0 atm = 0.60 g/L","ثبات ناتج S/P","الربط بمعنى التناسب الطردي"]'::jsonb, '["S₂ = S₁ × P₂/P₁ = 0.20 × 2.0/1.0 = 0.40 g/L","S₃ = 0.20 × 3.0/1.0 = 0.60 g/L","S/P = 0.20/1.0 = 0.40/2.0 = 0.60/3.0 = 0.20"]'::jsonb, '[{"element":"القيمة الأولى","marks":1},{"element":"القيمة الثانية","marks":1},{"element":"بيان ثبات S/P","marks":1},{"element":"تفسير التناسب الطردي","marks":1}]'::jsonb, '[{"level":"4","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات علمية سليمة."},{"level":"2–3","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb, '["قسمة الذائبية على نسبة الضغط فتنقص الذائبية","عدم الربط بين النتائج ونص القانون"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.375Z"}'::jsonb),
('essay', 3, null::int, null, null, 'يطبق قانون هنري على الغازات المذابة في السوائل؛ فهو يربط ذائبية الغاز في سائل بضغط الغاز فوق السائل، بشرط ثبوت درجة الحرارة. ولا يصلح لمقارنة حالتين اختلفت فيهما درجة الحرارة، لأن ذائبية الغاز تتأثر أيضًا بدرجة الحرارة (تقل بارتفاعها لأن الطاقة الحركية لجسيمات الغاز تسمح لها بالتحرر من المحلول بسهولة أكبر)، فيصبح تغير الذائبية ناتجًا عن عاملين معًا، ولا يبقى ناتج S/P ثابتًا.', '["يطبق على الغازات المذابة في السوائل","شرط ثبوت درجة الحرارة","الحرارة تغير ذائبية الغاز (تقل بارتفاعها)","فيختلط أثر العاملين ولا يبقى S/P ثابتًا"]'::jsonb, '[]'::jsonb, '[{"element":"نوع المواد","marks":1},{"element":"الشرط","marks":1},{"element":"أثر الحرارة في ذائبية الغاز","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات علمية سليمة."},{"level":"2–3","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb, '["القول إن القانون يطبق على المواد الصلبة الذائبة","القول إن الحرارة لا تؤثر في ذائبية الغازات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.376Z"}'::jsonb)
