('mcq', 2, 0, 'عند فتح العبوة يكون ضغط CO₂ داخلها أعلى من الضغط خارجها فيقل الضغط فوق السائل، ووفق قانون هنري تقل ذائبية الغاز بنقصان الضغط، فيخرج CO₂ الزائد من المحلول على شكل فقاعات تتصاعد وتتطاير.', '["","زيادة الذائبية تجعل الغاز يبقى مذابًا ولا تسبب تصاعده.","الغاز موجود مذابًا مسبقًا؛ الفتح يغير الضغط ولا يبدأ تفاعلًا.","فتح العبوة لا يرفع حرارة المشروب؛ السبب نقصان الضغط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.376Z"}'::jsonb),
('mcq', 3, 3, 'يمكن وصف انخفاض ذائبية غاز ثاني أكسيد الكربون في المشروب الغازي بعد فتح العبوة بقانون هنري، الذي يربط ذائبية الغاز بضغطه فوق السائل.', '["قانون بويل يربط ضغط الغاز بحجمه، لا ذائبيته في سائل.","قانون شارل يربط حجم الغاز بدرجة حرارته.","قانون حفظ الكتلة يخص التفاعلات الكيميائية ولا يفسر تغير الذائبية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.376Z"}'::jsonb),
('mcq', 4, 1, 'الضغط الذي فوق السائل في القارورة المغلقة يحافظ على بقاء CO₂ ذائبًا في المحلول ويمنعه من التطاير.', '["الضغط المرتفع يبقي الغاز مذابًا ولا يسرّع تطايره.","","CO₂ يبقى مذابًا في المحلول، ولا يتكون سائل منفصل.","الضغط لا يذيب الغاز برفع الحرارة؛ وارتفاع الحرارة يقلل ذائبية الغاز أصلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.377Z"}'::jsonb),
('mcq', 5, 2, 'عملية تصاعد فقاعات CO₂ وتطايرها تستمر حتى يفقد المحلول غاز CO₂ كله تقريبًا، ويصبح المحلول بلا طعم.', '["المحلول المفتوح يفقد الغاز لأن الضغط فوقه انخفض.","CO₂ الزائد يتطاير من المحلول بعد انخفاض الضغط.","","لا يتبلور CO₂ في المشروب؛ بل يخرج غازًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.377Z"}'::jsonb),
('mcq', 6, 0, 'خلال تسرب CO₂ من المحلول يزداد الضغط داخل القارورة المغلقة. وبارتفاع الضغط فوق السائل تزداد ذائبية الغاز وفق قانون هنري، فيتباطأ خروج CO₂ من المحلول ويبقى جزء منه مذابًا.', '["","الغاز المتسرب يتجمع في الحيز المغلق فيرفع الضغط ولا يخفضه.","التسرب يستمر لحظيًا ويرفع الضغط حتى يبطؤ خروج الغاز.","الغاز الذي خرج إلى الهواء الخارجي عند الفتح لا يعود."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.377Z"}'::jsonb),
('mcq', 7, 3, 'وفق قانون هنري ذائبية CO₂ تحت 4 atm ضعف ذائبيته تحت 2 atm، فالقارورة الأولى تحتوي كمية أكبر من الغاز المذاب، وعند الفتح ينخفض الضغط فوق السائلين إلى الضغط الجوي نفسه، فتطلق الأولى كمية أكبر من CO₂.', '["الضغط الأقل يعني كمية مذابة أقل، فما تطلقه أقل.","ثبات الحرارة لا يعني تساوي الكمية المذابة؛ فالكمية تتبع الضغط.","انخفاض الضغط وحده كافٍ لتقليل الذائبية وتحرير الغاز.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.377Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يحتوي المشروب الغازي على CO₂ مذاب في محلول مائي تحت ضغط أعلى من الضغط الجوي، وهذا الضغط فوق السائل يبقي الغاز ذائبًا. ووفق قانون هنري تتناسب ذائبية الغاز طرديًا مع ضغطه فوق السائل عند ثبوت درجة الحرارة. عند فتح العلبة يكون ضغط CO₂ داخلها أعلى من الضغط خارجها، فينخفض الضغط فوق السائل، فتقل ذائبية CO₂، فيخرج الغاز الزائد من المحلول على هيئة فقاعات تتصاعد إلى السطح وتتطاير، وتستمر العملية حتى يفقد المحلول CO₂ كله تقريبًا.', '["CO₂ مذاب تحت ضغط أعلى من الجوي","نص قانون هنري (تناسب طردي)","الفتح يخفض الضغط فوق السائل","تقل الذائبية فيخرج الغاز الزائد فقاعات"]'::jsonb, '[]'::jsonb, '[{"element":"الحالة قبل الفتح","marks":1},{"element":"قانون هنري","marks":1},{"element":"انخفاض الضغط عند الفتح","marks":1},{"element":"نقصان الذائبية وتصاعد الفقاعات","marks":1}]'::jsonb, '[{"level":"4","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات علمية سليمة."},{"level":"2–3","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb, '["تفسير الفقاعات بتفاعل كيميائي","تفسيرها بارتفاع الحرارة","إغفال ذكر أن الضغط قبل الفتح أعلى من الجوي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T11:36:22.377Z"}'::jsonb),
('essay', 2, null::int, null, null, 'القارورة المغلقة: الضغط فوق السائل مرتفع (ضغط CO₂ أعلى من الجوي)، فذائبية CO₂ كبيرة، ويبقى CO₂ ذائبًا في المحلول ولا يتطاير. بعد الفتح: يقل الضغط فوق السائل، فتقل ذائبية CO₂ وفق قانون هنري، فتهرب جزيئات CO₂ من المحلول على شكل فقاعات وتتطاير إلى الهواء.', '["الضغط: مرتفع مغلقة / منخفض مفتوحة","الذائبية: كبيرة / تقل","الجزيئات: تبقى ذائبة / تهرب فقاعات"]'::jsonb, '[]'::jsonb, '[{"element":"المقارنة في الضغط","marks":1},{"element":"المقارنة في الذائبية","marks":1},{"element":"المقارنة في سلوك الجزيئات","marks":1}]'::jsonb, '[{"level":"3","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات علمية سليمة."},{"level":"2","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb, '["عكس اتجاه تغير الذائبية","عدم ربط المقارنة بقانون هنري"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.377Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة؛ فغاز CO₂ موجود أصلًا في المشروب مذابًا تحت ضغط أعلى من الضغط الجوي، ولا ينتج عن تفاعل عند الفتح. التفسير الصحيح: الفتح يقلل الضغط فوق السائل، وبحسب قانون هنري تتناسب ذائبية الغاز طرديًا مع ضغطه فوق السائل عند ثبوت درجة الحرارة، فتقل ذائبية CO₂، فيخرج الغاز الزائد من المحلول على هيئة فقاعات. والدليل أن الفقاعات تتباطأ إذا أعيد إغلاق العلبة، لأن الضغط داخلها يعود فيرتفع، وهذا تغير فيزيائي في الذائبية لا تفاعل كيميائي.', '["الحكم: العبارة خاطئة","CO₂ موجود مذابًا مسبقًا تحت ضغط مرتفع","التفسير بقانون هنري وانخفاض الضغط","دليل أو تعليل يدعم أنه تغير فيزيائي"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"بيان أن الغاز موجود مسبقًا","marks":1},{"element":"التفسير بقانون هنري","marks":2},{"element":"الدليل","marks":1}]'::jsonb, '[{"level":"5","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات علمية سليمة."},{"level":"3–4","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1–2","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb, '["الموافقة على العبارة","الحكم بخطئها دون تقديم التفسير البديل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.377Z"}'::jsonb)
