('mcq', 1, 1, 'من قانون هنري: S₂ = S₁ × P₂/P₁ = 0.60 g/L × (3.0 atm / 1.0 atm) = 1.8 g/L. زيادة الضغط ثلاث مرات تزيد الذائبية ثلاث مرات.', '["نتيجة قلب نسبة الضغطين (S₁ × P₁/P₂)، فنقصت الذائبية مع أن الضغط زاد.","","نتيجة قسمة الضغط الجديد على الذائبية (3.0/0.60) دون استعمال القانون، والوحدة لا تكون g/L.","افتراض خاطئ أن الذائبية لا تتغير بتغير الضغط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-17T11:36:22.378Z"}'::jsonb),
('mcq', 2, 3, 'S₂ = S₁ × P₂/P₁ = 0.400 g/L × (125 kPa / 50.0 kPa) = 1.00 g/L. يمكن استعمال kPa مباشرة لأن الوحدتين تُختصران في النسبة.', '["نتيجة قلب نسبة الضغطين (S₁ × P₁/P₂).","هذه نسبة الضغطين فقط (125/50.0) دون ضربها في الذائبية الأصلية.","إهمال أثر الضغط وافتراض بقاء الذائبية ثابتة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (60%)"}],"at":"2026-10-17T11:36:22.378Z"}'::jsonb),
('mcq', 3, 0, 'من S₁/P₁ = S₂/P₂ نحصل على P₂ = S₂ × P₁/S₁ = 2.7 g/L × 2.0 atm / 0.90 g/L = 6.0 atm. الذائبية زادت ثلاث مرات فيلزم ضغط أكبر بثلاث مرات.', '["","نتيجة الحل بالمقلوب (S₁ × P₁/S₂)، فقلّ الضغط مع أن الذائبية زادت.","نتيجة ضرب الذائبيتين وقسمة الناتج على الضغط (S₂ × S₁/P₁)، وهي إعادة ترتيب خاطئة.","هذه نسبة الذائبيتين فقط (2.7/0.90) دون ضربها في الضغط الأصلي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-17T11:36:22.378Z"}'::jsonb),
('mcq', 4, 2, 'وفق قانون هنري S₂ = S₁ × P₂/P₁ = S₁ × (½P₁)/P₁ = ½S₁، أي تقل الذائبية إلى النصف لأن العلاقة طردية.', '["هذا يناسب علاقة عكسية، وقانون هنري علاقة طردية.","الذائبية تتغير مع الضغط عند ثبوت الحرارة.","","العلاقة طردية بسيطة وليست مع مربع الضغط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.378Z"}'::jsonb),
('mcq', 5, 3, 'من الجدول S/P ثابت = 0.15 g/L ÷ 1.0 atm = 0.15 g/(L·atm). إذن P = S ÷ 0.15 = 1.2 ÷ 0.15 = 8.0 atm. (أو: P₂ = S₂P₁/S₁ = 1.2 × 1.0/0.15 = 8.0 atm.)', '["نتيجة الحل بالمقلوب (S₁ × P₁/S₂ = 0.15 × 1.0/1.2).","نتيجة خلط صفين من الجدول: استعمال ذائبية 0.30 g/L مع ضغط 1.0 atm.","افتراض خاطئ أن الضغط يساوي الذائبية عدديًا، مع أن ثابت التناسب 0.15 لا 1.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T11:36:22.379Z"}'::jsonb),
('mcq', 6, 1, 'S₂ = S₁ × P₂/P₁ = 0.55 g/L × (110 kPa / 20.0 kPa) = 3.025 g/L ≈ 3.0 g/L، فيذوب نحو 3.0 g في 1.0 L (رقمان معنويان كما في 0.55).', '["نتيجة قلب نسبة الضغطين (0.55 × 20.0/110).","","نتيجة استعمال فرق الضغطين (110 − 20.0) بدل الضغط الجديد.","افتراض أن الكمية الذائبة لا تتغير بتغير الضغط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-17T11:36:22.379Z"}'::jsonb),
('mcq', 7, 0, 'أولًا الذائبية عند 2.5 atm: S₂ = 0.24 g/L × 2.5 atm/1.0 atm = 0.60 g/L. ثم الكتلة في 2.0 L: 0.60 g/L × 2.0 L = 1.2 g.', '["","هذه الذائبية لكل لتر، ونسي الطالب ضربها في الحجم 2.0 L.","نتيجة قلب نسبة الضغطين ثم الضرب في الحجم (0.24 × 1.0/2.5 × 2.0).","نتيجة قسمة الذائبية على الحجم بدل ضربها فيه (0.60 ÷ 2.0)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (56%)"}],"at":"2026-10-17T11:36:22.379Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المعطيات: S₁ = 0.66 g/L، P₁ = 10 atm، S₂ = 1.5 g ÷ 1.0 L = 1.5 g/L. المطلوب P₂. من قانون هنري S₁/P₁ = S₂/P₂ نحصل على P₂ = S₂ × P₁/S₁ = 1.5 g/L × 10 atm / 0.66 g/L ≈ 23 atm. التحقق: الذائبية زادت (من 0.66 إلى 1.5 g/L) فيجب أن يزيد الضغط، وهذا ما حدث.', '["تحديد المعطيات وحساب S₂ = 1.5 g/L","كتابة القانون وإعادة ترتيبه لإيجاد P₂","التعويض والناتج ≈ 23 atm","التحقق من منطقية الإجابة"]'::jsonb, '["S₂ = 1.5 g / 1.0 L = 1.5 g/L","S₁/P₁ = S₂/P₂ ⇐ P₂ = S₂P₁/S₁","P₂ = (1.5 g/L × 10 atm) / 0.66 g/L = 22.7 atm ≈ 23 atm"]'::jsonb, '[{"element":"المعطيات وS₂","marks":1},{"element":"إعادة ترتيب القانون","marks":1},{"element":"التعويض والناتج بالوحدة","marks":2}]'::jsonb, '[{"level":"4","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات علمية سليمة."},{"level":"2–3","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb, '["حساب P₂ = S₁P₁/S₂ = 4.4 atm (قلب النسبة)","نسيان الوحدة atm","تقريب غير مناسب للأرقام المعنوية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-17T11:36:22.380Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) S₂ = S₁ × P₂/P₁ = 1.6 g/L × 5.0 atm/2.0 atm = 4.0 g/L. (ب) P₂ = S₂ × P₁/S₁ = 0.40 g/L × 2.0 atm/1.6 g/L = 0.50 atm. النتائج منطقية: زيادة الضغط زادت الذائبية، وقلة الذائبية تتطلب ضغطًا أقل.', '["(أ) كتابة القانون والتعويض","(أ) الناتج 4.0 g/L","(ب) إعادة الترتيب لإيجاد P₂","(ب) الناتج 0.50 atm"]'::jsonb, '["(أ) S₂ = S₁P₂/P₁ = 1.6 × 5.0 / 2.0 = 4.0 g/L","(ب) P₂ = S₂P₁/S₁ = 0.40 × 2.0 / 1.6 = 0.50 atm"]'::jsonb, '[{"element":"خطوات الجزء (أ)","marks":1},{"element":"ناتج (أ) بالوحدة","marks":1},{"element":"خطوات الجزء (ب)","marks":1},{"element":"ناتج (ب) بالوحدة","marks":1}]'::jsonb, '[{"level":"4","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات علمية سليمة."},{"level":"2–3","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb, '["قلب النسبة في أحد الجزأين","كتابة الناتج دون وحدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-17T11:36:22.380Z"}'::jsonb),
('essay', 3, null::int, null, null, 'خطأ الطالب أنه قلب نسبة الضغطين؛ فالصحيح من S₁/P₁ = S₂/P₂ أن S₂ = S₁ × P₂/P₁. ويمكن اكتشاف الخطأ بالتقدير: قانون هنري تناسب طردي، فزيادة الضغط من 1.0 إلى 4.0 atm يجب أن تزيد الذائبية لا أن تنقصها، بينما ناتج الطالب (0.075 g/L) أقل من الذائبية الأصلية. الحل الصحيح: S₂ = 0.30 g/L × 4.0 atm/1.0 atm = 1.2 g/L.', '["تحديد الخطأ: قلب نسبة الضغطين","طريقة الاكتشاف: الضغط زاد فيجب أن تزيد الذائبية","الصيغة الصحيحة S₂ = S₁P₂/P₁","الناتج 1.2 g/L"]'::jsonb, '["S₁/P₁ = S₂/P₂ ⇐ S₂ = S₁ × P₂/P₁","S₂ = 0.30 g/L × 4.0 atm / 1.0 atm = 1.2 g/L"]'::jsonb, '[{"element":"تحديد الخطأ","marks":1},{"element":"التحقق بالتقدير","marks":1},{"element":"الصيغة الصحيحة","marks":1},{"element":"الناتج الصحيح بالوحدة","marks":1}]'::jsonb, '[{"level":"4","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات علمية سليمة."},{"level":"2–3","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb, '["تصحيح الناتج دون تحديد سبب الخطأ","الاعتقاد أن زيادة الضغط تقلل الذائبية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.380Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
