from (values
('mcq', 1, 'ما المقصود بالمحلول غير المشبع؟', null, '["محلول يحتوي على أكبر كمية من المذاب يمكن أن تذوب عند درجة حرارة وضغط معينين","محلول يحتوي على كمية مذاب أكبر مما في المحلول المشبع عند درجة الحرارة نفسها","محلول لا يمكن إذابة أي كمية إضافية من المذاب فيه عند الظروف نفسها","محلول يحتوي على كمية مذاب أقل مما في المحلول المشبع عند درجة حرارة وضغط معينين"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 33 — المحلول غير المشبع'),
('mcq', 2, 'ما الصفة المميزة للمحلول غير المشبع؟', null, '["تبقى فيه كمية المذاب الذائبة ثابتة مهما أضيف إليه","يترسب فيه المذاب الزائد عند إضافة نواة تبلور","يمكن إذابة كميات أكبر من المذاب فيه","تتساوى فيه سرعة الذوبان وسرعة التبلور"]'::jsonb, 'تذكر', 'تعرّف خاصية', 'سهل', 'الكتاب ص 33 — المحلول غير المشبع'),
('mcq', 3, 'ذائبية KCl في الماء عند 20 °C هي 34.2 g/100 g H₂O. كيف يُصنّف محلول يحتوي على 25.0 g من KCl ذائبة في 100 g من الماء عند 20 °C؟', null, '["محلول مشبع","محلول غير مشبع","محلول فوق مشبع","محلول مشبع مع راسب"]'::jsonb, 'تطبيق', 'تصنيف من بيانات', 'متوسط', 'الكتاب ص 33–34 — المحلول غير المشبع، الجدول 1-4'),
('mcq', 4, 'أضيفت بلورة صغيرة من مذاب إلى محلول غير مشبع منه عند درجة حرارة ثابتة. ماذا يُتوقع أن يحدث لها؟', null, '["تذوب البلورة في المحلول","تبقى البلورة كما هي دون تغير في الكمية الذائبة","يترسب مذاب إضافي على البلورة بسرعة","يكبر حجم البلورة تدريجيًا"]'::jsonb, 'فهم', 'تنبؤ بالسلوك', 'متوسط', 'الكتاب ص 33 — المحلول غير المشبع'),
('mcq', 5, 'ذائبية NaCl عند 20 °C هي 35.9 g/100 g H₂O. كم غرامًا إضافيًا من NaCl يمكن أن يذوب في محلول يحتوي على 30.0 g منه في 100 g من الماء عند 20 °C؟', null, '["30.0 g","35.9 g","5.9 g","65.9 g"]'::jsonb, 'تطبيق', 'حساب الكمية المتبقية', 'صعب', 'الكتاب ص 33–34 — المحلول غير المشبع، الجدول 1-4'),
('mcq', 6, 'اعتمادًا على الجدول، أيّ المحاليل الآتية المحضّرة في 100 g من الماء عند 60 °C غير مشبع؟', '{"headers":["المادة","الذائبية عند 60 °C (g/100 g H₂O)"],"rows":[["KCl","45.8"],["NaCl","37.1"],["C₁₂H₂₂O₁₁","287.3"],["AgNO₃","440"]]}'::jsonb, '["37.1 g من NaCl","440 g من AgNO₃","290 g من السكروز","40.0 g من KCl"]'::jsonb, 'تحليل', 'تصنيف بمقارنة بيانات', 'صعب', 'الكتاب ص 34 — الجدول 1-4'),
('mcq', 7, 'أيّ العبارات الآتية تقارن بين المحلول غير المشبع والمحلول المشبع للمادة نفسها عند درجة الحرارة والضغط نفسيهما مقارنة صحيحة؟', null, '["غير المشبع يحتوي على مذاب أكثر ولا يستطيع إذابة المزيد","غير المشبع يحتوي على مذاب أقل ويستطيع إذابة المزيد، والمشبع لا يستطيع","كلاهما يحتوي على أقصى كمية ممكنة من المذاب","كلاهما يستطيع إذابة كميات إضافية من المذاب"]'::jsonb, 'فهم', 'مقارنة مفهومين', 'متوسط', 'الكتاب ص 33 — المحلول غير المشبع'),
('essay', 1, 'عرّف المحلول غير المشبع، ثم صف اختبارًا عمليًّا بسيطًا تتحقق به من أن محلولًا ما غير مشبع.', null, null, 'تذكر', 'تعريف واختبار', 'سهل', 'الكتاب ص 33 — المحلول غير المشبع'),
('essay', 2, 'ذائبية KCl في الماء 34.2 g/100 g H₂O عند 20 °C، و45.8 g/100 g H₂O عند 60 °C. حُضّر محلول يحتوي على 30.0 g من KCl في 100 g ماء. (أ) صنّف المحلول عند 20 °C وعند 60 °C. (ب) احسب الكتلة الإضافية من KCl اللازمة ليصبح مشبعًا عند كل من الدرجتين.', null, null, 'تطبيق', 'تصنيف وحساب من بيانات', 'متوسط', 'الكتاب ص 33–34 — المحلول غير المشبع، الجدول 1-4'),
('essay', 3, 'كيف يمكنك تحويل محلول غير مشبع من السكر إلى محلول مشبع دون تغيير درجة الحرارة؟ وكيف تعرف أنه أصبح مشبعًا؟ فسّر ما يحدث في المحلول عندئذٍ على مستوى الجسيمات.', null, null, 'فهم', 'تفسير وتحويل بين حالتين', 'صعب', 'الكتاب ص 33 — المحلول غير المشبع والمحلول المشبع')
