('mcq', 1, 3, 'المحلول غير المشبع هو المحلول الذي يحتوي على كمية مذاب أقل مما في المحلول المشبع عند درجة حرارة وضغط معينين.', '["هذا تعريف المحلول المشبع.","هذا وصف المحلول فوق المشبع.","عدم القدرة على إذابة المزيد صفة المحلول المشبع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:36:22.381Z"}'::jsonb),
('mcq', 2, 2, 'المحلول غير المشبع يمكن إضافة كميات أكبر من المذاب إليه لتذوب، لأنه يحتوي على كمية أقل من أقصى ما يمكن أن يذوب.', '["ثبات الكمية الذائبة مع إضافة المذاب صفة المحلول المشبع.","هذه صفة المحلول فوق المشبع غير الثابت.","","تساوي السرعتين (الاتزان الديناميكي) يميز المحلول المشبع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:36:22.381Z"}'::jsonb),
('mcq', 3, 1, 'الكمية الذائبة (25.0 g) أقل من أقصى كمية يمكن أن تذوب عند 20 °C (34.2 g)، فالمحلول غير مشبع ويمكن أن يذيب نحو 9.2 g إضافية.', '["المشبع يحتوي على 34.2 g في 100 g ماء عند 20 °C، والمعطى أقل من ذلك.","","فوق المشبع يحتوي على أكثر من 34.2 g، والمعطى أقل.","لا يتكون راسب لأن الكمية الذائبة (25.0 g) أقل من الذائبية (34.2 g)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-17T11:36:22.382Z"}'::jsonb),
('mcq', 4, 0, 'المحلول غير المشبع يحتوي على كمية مذاب أقل من الحد الأقصى، فيمكنه إذابة كميات إضافية، لذلك تذوب البلورة المضافة.', '["","بقاء الكمية الذائبة ثابتة يحدث في المحلول المشبع.","ترسب المذاب على نواة التبلور يحدث في المحلول فوق المشبع.","المحلول غير المشبع لا يرسّب المذاب، فلا تنمو البلورة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.382Z"}'::jsonb),
('mcq', 5, 2, 'الكمية الإضافية = الذائبية − الكمية الذائبة = 35.9 g − 30.0 g = 5.9 g، وبعدها يصبح المحلول مشبعًا.', '["هذه الكمية الذائبة فعلًا، لا الكمية الإضافية التي يمكن أن تذوب.","هذه أقصى كمية تذوب في 100 g ماء، دون طرح ما ذاب مسبقًا.","","نتيجة جمع الكميتين بدل طرحهما."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-17T11:36:22.382Z"}'::jsonb),
('mcq', 6, 3, 'ذائبية KCl عند 60 °C هي 45.8 g، و40.0 g أقل منها، فالمحلول غير مشبع. أما 37.1 g NaCl و440 g AgNO₃ فتساويان الذائبية (مشبعان)، و290 g سكروز أكبر من 287.3 g.', '["الكمية تساوي ذائبية NaCl عند 60 °C، فالمحلول مشبع.","الكمية تساوي ذائبية AgNO₃ عند 60 °C، فالمحلول مشبع.","الكمية أكبر من ذائبية السكروز (287.3 g)، فلا يكون المحلول غير مشبع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.382Z"}'::jsonb),
('mcq', 7, 1, 'المحلول المشبع يحتوي على أكبر كمية من المذاب ذائبة عند درجة حرارة وضغط معينين، أما غير المشبع فيحتوي على كمية أقل ويمكن إضافة مذاب آخر إليه ليذوب.', '["العبارة عكست الصفتين؛ غير المشبع هو الأقل مذابًا.","","أقصى كمية صفة المشبع فقط.","المشبع لا يذيب المزيد عند الظروف نفسها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T11:36:22.382Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المحلول غير المشبع هو محلول يحتوي على كمية مذاب أقل مما في المحلول المشبع عند درجة حرارة وضغط معينين، أي يمكن إذابة كميات أكبر من المذاب فيه. الاختبار: نضيف كمية صغيرة من المذاب نفسه إلى المحلول مع التحريك عند درجة الحرارة نفسها؛ فإذا ذابت كان المحلول غير مشبع، وإذا بقيت دون ذوبان كان المحلول مشبعًا.', '["التعريف: كمية مذاب أقل مما في المشبع عند درجة حرارة وضغط معينين","إضافة كمية صغيرة من المذاب عند الحرارة نفسها","ذوبانها يدل على أنه غير مشبع"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"خطوة الاختبار","marks":1},{"element":"تفسير النتيجة","marks":1}]'::jsonb, '[{"level":"4","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات علمية سليمة."},{"level":"2–3","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb, '["إغفال ذكر درجة الحرارة والضغط في التعريف","اختبار المحلول بالتسخين فتتغير الذائبية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.382Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) عند 20 °C: 30.0 g أقل من 34.2 g فالمحلول غير مشبع. عند 60 °C: 30.0 g أقل من 45.8 g فالمحلول غير مشبع أيضًا. (ب) عند 20 °C: 34.2 − 30.0 = 4.2 g. عند 60 °C: 45.8 − 30.0 = 15.8 g.', '["تصنيف المحلول عند 20 °C","تصنيفه عند 60 °C","الكتلة الإضافية 4.2 g","الكتلة الإضافية 15.8 g"]'::jsonb, '["المقارنة: 30.0 g < 34.2 g، و30.0 g < 45.8 g ⇐ غير مشبع في الحالتين","الإضافة عند 20 °C = 34.2 − 30.0 = 4.2 g","الإضافة عند 60 °C = 45.8 − 30.0 = 15.8 g"]'::jsonb, '[{"element":"التصنيفان","marks":2},{"element":"الحساب عند 20 °C","marks":1},{"element":"الحساب عند 60 °C","marks":1}]'::jsonb, '[{"level":"4","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات علمية سليمة."},{"level":"2–3","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb, '["جمع الكمية الذائبة مع الذائبية بدل الطرح","تصنيف المحلول مشبعًا لأنه «يحتوي على كمية كبيرة»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.383Z"}'::jsonb),
('essay', 3, null::int, null, null, 'نضيف كميات صغيرة من السكر مع التحريك عند درجة الحرارة نفسها، فتذوب ما دام المحلول غير مشبع. نعرف أنه أصبح مشبعًا عندما تبقى كمية من السكر المضاف دون ذوبان مهما حرّكنا. عندئذٍ يحتوي المحلول على أكبر كمية من السكر يمكن أن تذوب عند تلك الدرجة، وتستمر جسيمات السكر في الذوبان من البلورات بينما يتبلور عدد مساوٍ من الجسيمات الذائبة على سطحها، أي تتساوى سرعة الذوبان وسرعة التبلور، فتبقى كمية المذاب الذائبة ثابتة.', '["إضافة المذاب تدريجيًا عند الحرارة نفسها","علامة التشبع: بقاء مذاب غير ذائب","تساوي سرعتي الذوبان والتبلور وثبات الكمية الذائبة"]'::jsonb, '[]'::jsonb, '[{"element":"طريقة التحويل","marks":1},{"element":"علامة التشبع","marks":1},{"element":"التفسير الجسيمي","marks":2}]'::jsonb, '[{"level":"4","description":"إجابة كاملة صحيحة علميًا تتضمن جميع العناصر المطلوبة بلغة دقيقة ومصطلحات علمية سليمة."},{"level":"2–3","description":"إجابة صحيحة في معظمها مع نقص عنصر أو عنصرين أو خطأ بسيط في التعبير أو الحساب."},{"level":"1","description":"إجابة جزئية تذكر عنصرًا صحيحًا واحدًا دون تفسير أو مع أخطاء جوهرية."},{"level":"صفر","description":"لا إجابة، أو إجابة خاطئة كليًا أو لا علاقة لها بالمطلوب."}]'::jsonb, '["اقتراح التبريد أو التسخين مع أن المطلوب تثبيت الحرارة","القول إن الذوبان يتوقف تمامًا في المحلول المشبع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.383Z"}'::jsonb)
