('mcq', 3, 'عند إذابة نترات الأمونيوم في وعاء يحتوي على ماء يصبح الوعاء باردًا. ما التفسير الصحيح لذلك؟', null, '["الطاقة اللازمة لفصل جسيمات المذاب والمذيب أكبر من طاقة التميه المنطلقة","طاقة التميه المنطلقة أكبر من الطاقة اللازمة لفصل جسيمات المذاب والمذيب","تجاذب جزيئات الماء مع الأيونات يمتص الطاقة من الوعاء","تكوّن روابط جديدة بين أيونات المذاب يمتص الطاقة"]'::jsonb, 'فهم', 'تفسير ظاهرة', 'متوسط', 'الكتاب ص 32 — حرارة الذوبان'),
('mcq', 4, 'يسخن الوعاء عند إذابة كلوريد الكالسيوم في الماء. أيّ العبارات الآتية تصف العلاقة بين الطاقات في هذه العملية؟', null, '["الطاقة الممتصة لفصل الجسيمات أكبر من طاقة التميه المنطلقة","طاقة التميه المنطلقة أكبر من الطاقة الممتصة لفصل الجسيمات","طاقة الشبكة البلورية تنطلق عند تفكك بلورة المذاب","طاقة التميه تساوي الطاقة الممتصة لفصل الجسيمات"]'::jsonb, 'فهم', 'تفسير ظاهرة', 'متوسط', 'الكتاب ص 32 — حرارة الذوبان'),
('mcq', 5, 'أُذيبت ثلاث مواد صلبة كلٌّ على حدة في كميات متساوية من الماء، وقيست درجة حرارة الماء قبل الذوبان وبعده كما في الجدول. أيّ الاستنتاجات الآتية صحيح؟', '{"headers":["المادة","درجة حرارة الماء قبل الذوبان","درجة حرارة الماء بعد الذوبان"],"rows":[["A","25 °C","18 °C"],["B","25 °C","34 °C"],["C","25 °C","25 °C"]]}'::jsonb, '["ذوبان المادة A طارد للطاقة؛ لأن الحرارة انتقلت منه إلى الماء","ذوبان المادة B ماص للطاقة؛ لأن درجة حرارة الماء ارتفعت","ذوبان المادة C لا يتضمن أي خطوة ماصة أو طاردة للطاقة","ذوبان المادة B طارد للطاقة؛ لأن طاقة التميه فيه تفوق طاقة فصل الجسيمات"]'::jsonb, 'تحليل', 'تفسير بيانات', 'صعب', 'الكتاب ص 32 — حرارة الذوبان'),
('mcq', 6, 'لماذا تُعدّ خطوة التغلب على قوى التجاذب بين جسيمات المذاب ماصة للطاقة؟', null, '["لأن جسيمات المذاب تتجاذب بعضها مع بعض فتنطلق طاقة","لأن جسيمات المذيب تحيط بجسيمات المذاب فتنطلق طاقة","لأن فصل الجسيمات المتجاذبة بعضها عن بعض يتطلب تزويدها بطاقة","لأن حجم المذاب يزداد عند انتقاله إلى المذيب"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 32 — حرارة الذوبان'),
('mcq', 7, 'تعمل الكمادة الباردة الفورية بإذابة ملح في ماء داخل كيس مغلق عند الضغط عليه. أيّ الاختيارات الآتية مناسب لصنعها مع التعليل الصحيح؟', null, '["نترات الأمونيوم؛ لأن ذوبانها في الماء ماص للطاقة","كلوريد الكالسيوم؛ لأن ذوبانه في الماء ماص للطاقة","كلوريد الكالسيوم؛ لأن ذوبانه في الماء طارد للطاقة","نترات الأمونيوم؛ لأن ذوبانها في الماء طارد للطاقة"]'::jsonb, 'تطبيق', 'تطبيق حياتي', 'صعب', 'الكتاب ص 32 — حرارة الذوبان'),
('essay', 1, 'فسّر لماذا تُنتج بعض المحاليل طاقة في أثناء تكوّنها بينما يمتص بعضها الآخر طاقة، مستعينًا بمفهومي طاقة الشبكة البلورية وطاقة التميه.', null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 32 — حرارة الذوبان'),
('essay', 2, 'رتّب خطوات عملية تكوّن المحلول من مذاب أيوني صلب في الماء، وصنّف كل خطوة إلى ماصة أو طاردة للطاقة، ثم وضّح كيف تحدد هذه الخطوات معًا أن ذوبان نترات الأمونيوم ماص للطاقة وأن ذوبان كلوريد الكالسيوم طارد لها.', null, null, 'تحليل', 'ترتيب وتصنيف وتفسير', 'صعب', 'الكتاب ص 32 — حرارة الذوبان'),
('essay', 3, 'أذاب طالب ملحًا X في ماء درجة حرارته 24 °C، فانخفضت درجة حرارة المحلول إلى 16 °C. (أ) هل ذوبان X ماص للطاقة أم طارد لها؟ (ب) قارن بين طاقة التميه والطاقة اللازمة لفصل الجسيمات في هذه العملية. (ج) ماذا يشعر الطالب إذا لمس الكأس؟ علّل.', null, null, 'تطبيق', 'تفسير بيانات', 'متوسط', 'الكتاب ص 32 — حرارة الذوبان')
