select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'يُسمّى التغير الكلي للطاقة الذي يحدث خلال عملية تكوّن المحلول حرارة الذوبان، وهو محصلة الطاقة الممتصة لفصل الجسيمات والطاقة المنطلقة عند تجاذب المذيب والمذاب.', '["هذه طاقة الشبكة البلورية، وهي خطوة واحدة من خطوات الذوبان وليست التغير الكلي.","","هذه طاقة التميه، وهي الخطوة الطاردة فقط وليست التغير الكلي للطاقة.","حرارة الذوبان كمية طاقة وليست درجة حرارة، والخلط هنا مع مفهوم الذائبية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.383Z"}'::jsonb),
('mcq', 2, 2, 'عند خلط جسيمات المذيب مع جسيمات المذاب تتجاذب وتنطلق طاقة تُسمّى طاقة التميه، لذا فهذه الخطوة طاردة للطاقة، أما خطوتا فصل جسيمات المذاب وفصل جسيمات المذيب فماصتان.', '["فصل جسيمات المذاب يتطلب التغلب على قوى التجاذب بينها، فهو ماص للطاقة.","تباعد جسيمات المذيب يتطلب التغلب على قوى التجاذب بينها، فهو ماص للطاقة.","","التغلب على طاقة الشبكة البلورية يحتاج إلى طاقة، فهو خطوة ماصة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.384Z"}'::jsonb),
('mcq', 3, 0, 'برودة الوعاء تعني أن الذوبان ماص للطاقة؛ أي أن الطاقة الممتصة للتغلب على قوى التجاذب بين جسيمات المذاب وبين جسيمات المذيب أكبر من طاقة التميه المنطلقة، فتؤخذ الطاقة الزائدة من الماء والوعاء فيبردان.', '["","هذه الحالة تجعل الذوبان طاردًا للطاقة فيسخن الوعاء كما في كلوريد الكالسيوم، لا العكس.","تجاذب المذيب مع المذاب خطوة طاردة تنطلق فيها طاقة التميه، وليست ماصة.","في الذوبان تنفصل أيونات المذاب ولا تتكون روابط بينها، وتكوّن الروابط أصلًا يطلق طاقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T11:36:22.384Z"}'::jsonb),
('mcq', 4, 1, 'سخونة الوعاء تعني أن الذوبان طارد للطاقة، أي أن طاقة التميه المنطلقة عند تجاذب المذيب والمذاب تفوق الطاقة الممتصة لفصل جسيمات المذاب وجسيمات المذيب، فتنطلق الطاقة الزائدة إلى الماء والوعاء.', '["هذه العلاقة تجعل الذوبان ماصًا للطاقة فيبرد الوعاء، وهو عكس المشاهَد.","","طاقة الشبكة البلورية تُمتص عند تفكك البلورة ولا تنطلق؛ فهي خطوة ماصة.","لو تساوت الطاقتان لكان التغير الكلي صفرًا تقريبًا ولما سخن الوعاء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T11:36:22.384Z"}'::jsonb),
('mcq', 5, 3, 'في B ارتفعت درجة حرارة الماء من 25 °C إلى 34 °C، أي انطلقت طاقة، فالطاقة المنطلقة عند تجاذب المذيب والمذاب (طاقة التميه) أكبر من الطاقة الممتصة لفصل الجسيمات، والذوبان طارد للطاقة.', '["انخفاض درجة حرارة الماء في A يعني أن الذوبان امتص طاقة من الماء، فهو ماص لا طارد.","ارتفاع درجة الحرارة دليل على انطلاق طاقة، فالذوبان طارد؛ والخطأ هنا عكس دلالة التغير.","كل ذوبان يتضمن خطوات ماصة (فصل الجسيمات) وطاردة (التميه)، وثبات الحرارة يعني تقارب الطاقتين فقط.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.384Z"}'::jsonb),
('mcq', 6, 2, 'يلزم طاقة للتغلب على قوى التجاذب التي تربط جسيمات المذاب بعضها ببعض (طاقة الشبكة البلورية في المركبات الأيونية)، لذا فهذه الخطوة ماصة للطاقة.', '["انطلاق الطاقة يجعل الخطوة طاردة، ثم إن المطلوب فصل الجسيمات لا تجاذبها.","إحاطة المذيب بالمذاب خطوة أخرى طاردة للطاقة (التميه) وليست خطوة فصل المذاب.","","تصنيف الخطوة يعتمد على كسر قوى التجاذب لا على تغير الحجم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.384Z"}'::jsonb),
('mcq', 7, 0, 'الكمادة الباردة تحتاج إلى ذوبان ماص للطاقة يأخذ الطاقة من المحيط فيبرد. وذوبان نترات الأمونيوم في الماء يجعل الوعاء باردًا، فهو ماص للطاقة ومناسب.', '["","ذوبان كلوريد الكالسيوم طارد للطاقة؛ يجعل الوعاء ساخنًا فلا يصلح للكمادة الباردة.","التعليل صحيح لكلوريد الكالسيوم، لكن الذوبان الطارد يسخّن الكيس فيصلح لكمادة ساخنة لا باردة.","الاختيار صحيح لكن التعليل خاطئ؛ فذوبان نترات الأمونيوم ماص للطاقة ولهذا يبرد الوعاء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.385Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يتضمن الذوبان خطوات ماصة للطاقة هي التغلب على قوى التجاذب بين جسيمات المذاب (طاقة الشبكة البلورية U°) وبين جسيمات المذيب، وخطوة طاردة للطاقة هي تجاذب جسيمات المذيب مع جسيمات المذاب وانطلاق طاقة التميه. والتغير الكلي للطاقة هو حرارة الذوبان: فإذا كانت الطاقة المنطلقة (التميه) أكبر من الطاقة الممتصة كان الذوبان طاردًا للطاقة فينتج المحلول طاقة (مثل كلوريد الكالسيوم)، وإذا كانت الطاقة الممتصة أكبر كان الذوبان ماصًا للطاقة (مثل نترات الأمونيوم).', '["فصل جسيمات المذاب والمذيب ماص للطاقة (طاقة الشبكة البلورية)","تجاذب المذيب والمذاب طارد للطاقة (طاقة التميه)","حرارة الذوبان هي التغير الكلي ومحصلة الخطوتين","المقارنة: التميه أكبر ← طارد؛ الممتصة أكبر ← ماص"]'::jsonb, '[]'::jsonb, '[{"element":"بيان أن فصل الجسيمات ماص للطاقة","marks":1},{"element":"بيان أن التميه طارد للطاقة","marks":1},{"element":"تعريف حرارة الذوبان بوصفها التغير الكلي","marks":1},{"element":"المقارنة التي تحدد نوع العملية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يذكر الخطوات الماصة والطاردة ويعرّف حرارة الذوبان ويقارن الطاقتين بشكل صحيح"},{"level":"2–3 درجات","description":"يذكر بعض الخطوات أو يقارن دون ربط واضح بحرارة الذوبان"},{"level":"درجة واحدة","description":"يذكر أن بعض المحاليل تسخن وبعضها يبرد دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ تجاذب المذيب والمذاب خطوة ماصة للطاقة","عدّ طاقة الشبكة البلورية طاقة منطلقة","تفسير البرودة بأن الماء نفسه يبرد دون علاقة بالطاقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-17T11:36:22.385Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الخطوة 1: فصل أيونات المذاب بعضها عن بعض بالتغلب على طاقة الشبكة البلورية — ماصة للطاقة. الخطوة 2: تباعد جزيئات الماء بالتغلب على قوى التجاذب بينها لتسمح بدخول جسيمات المذاب — ماصة للطاقة. الخطوة 3: تجاذب جزيئات الماء مع الأيونات وإحاطتها بها فتنطلق طاقة التميه — طاردة للطاقة. حرارة الذوبان هي محصلة هذه الخطوات: في نترات الأمونيوم مجموع الطاقة الممتصة في الخطوتين 1 و2 أكبر من طاقة التميه المنطلقة، فالمحصلة امتصاص طاقة من الماء ويبرد الوعاء. وفي كلوريد الكالسيوم طاقة التميه المنطلقة أكبر من الطاقة الممتصة، فالمحصلة انطلاق طاقة ويسخن الوعاء.', '["ترتيب الخطوات الثلاث","تصنيف الخطوتين الأوليين ماصتين","تصنيف خطوة التميه طاردة","تفسير نترات الأمونيوم (الممتصة أكبر)","تفسير كلوريد الكالسيوم (التميه أكبر)"]'::jsonb, '[]'::jsonb, '[{"element":"ترتيب الخطوات","marks":1},{"element":"تصنيف خطوتي الفصل ماصتين","marks":1},{"element":"تصنيف التميه طاردة","marks":1},{"element":"تفسير حالة نترات الأمونيوم","marks":1.5},{"element":"تفسير حالة كلوريد الكالسيوم","marks":1.5}]'::jsonb, '[{"level":"6 درجات","description":"يرتب الخطوات ويصنفها صحيحًا ويفسر الحالتين بمقارنة الطاقات"},{"level":"3–5 درجات","description":"يصنف الخطوات صحيحًا ويفسر حالة واحدة أو يفسر دون مقارنة كمية واضحة"},{"level":"1–2 درجة","description":"يذكر بعض الخطوات أو يصنف بعضها فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال خطوة تباعد جزيئات المذيب","تصنيف التميه ماصة للطاقة","تفسير الحالتين بنوع المذيب لا بمقارنة الطاقات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T11:36:22.385Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) ذوبان X ماص للطاقة؛ لأن درجة حرارة المحلول انخفضت، أي امتُصت طاقة من الماء. (ب) الطاقة اللازمة للتغلب على قوى التجاذب بين جسيمات المذاب وبين جسيمات المذيب أكبر من طاقة التميه المنطلقة عند تجاذب المذيب والمذاب. (ج) يشعر ببرودة الكأس؛ لأن العملية تأخذ الطاقة من الماء والكأس (كما في نترات الأمونيوم).', '["تحديد أن الذوبان ماص","الطاقة الممتصة لفصل الجسيمات أكبر من طاقة التميه","الكأس باردة مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) التحديد مع الدليل","marks":1},{"element":"(ب) المقارنة الصحيحة","marks":2},{"element":"(ج) الإحساس مع التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يجيب عن الأجزاء الثلاثة صحيحًا مع التعليل"},{"level":"2–3 درجات","description":"يحدد نوع العملية صحيحًا مع خطأ في المقارنة أو التعليل"},{"level":"درجة واحدة","description":"يحدد نوع العملية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الانخفاض في درجة الحرارة دليلًا على انطلاق طاقة","قلب المقارنة بين طاقة التميه وطاقة الفصل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T11:36:22.385Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
