from (values
('mcq', 1, 'ماذا تعني القاعدة العامة «المذيب يذيب شبيهه»؟', null, '["المواد المتشابهة في الكتلة المولية يذوب بعضها في بعض","المواد المتشابهة في الحالة الفيزيائية فقط يذوب بعضها في بعض","المواد المتشابهة في القطبية ونوع القوى بين الجزيئية يذوب بعضها في بعض","المواد المتشابهة في اللون والرائحة يذوب بعضها في بعض"]'::jsonb, 'فهم', 'تفسير قاعدة', 'سهل', 'الكتاب ص 29 — عملية الذوبان: المذيب يذيب شبيهه'),
('mcq', 2, 'أيّ المذيبات الآتية أنسب لإذابة زيت الطعام المكوّن أساسًا من الكربون والهيدروجين؟', null, '["الماء H₂O القطبي","الهكسان C₆H₁₄ غير القطبي","محلول كلوريد الصوديوم في الماء","محلول السكروز في الماء"]'::jsonb, 'تطبيق', 'تنبؤ', 'سهل', 'الكتاب ص 31 — محاليل المركبات الجزيئية والزيت'),
('mcq', 3, 'أيّ المواد الآتية يُتوقع أن تذوب في الماء؟', null, '["زيت الطعام النباتي","الهكسان C₆H₁₄","سكر المائدة (السكروز C₁₂H₂₂O₁₁)","شمع البارافين (هيدروكربون)"]'::jsonb, 'تطبيق', 'تنبؤ', 'متوسط', 'الكتاب ص 31 — محاليل المركبات الجزيئية والزيت'),
('mcq', 4, 'لماذا لا يكوّن الزيت محلولًا مع الماء؟', null, '["لأن قوى التجاذب بين جزيئات الماء القطبية وجزيئات الزيت غير القطبية ضعيفة","لأن جزيئات الزيت أيونية وتتجاذب أيوناتها بقوة كبيرة","لأن جزيئات الماء غير قطبية مثل جزيئات الزيت","لأن كثافة الزيت أكبر من كثافة الماء فيترسب أسفله"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 31 — محاليل المركبات الجزيئية والزيت'),
('mcq', 5, 'يبيّن الجدول طبيعة بعض المواد من حيث القطبية. أيّ الأزواج الآتية يُتوقع أن يكوّن محلولًا؟', '{"headers":["المادة","الصيغة","الطبيعة"],"rows":[["الماء","H₂O","قطبي"],["الهكسان","C₆H₁₄","غير قطبي"],["رابع كلوريد الكربون","CCl₄","غير قطبي"],["اليود","I₂","غير قطبي"],["كلوريد الصوديوم","NaCl","أيوني"]]}'::jsonb, '["الهكسان C₆H₁₄ في الماء H₂O","كلوريد الصوديوم NaCl في الهكسان C₆H₁₄","اليود I₂ في الماء H₂O","اليود I₂ في رابع كلوريد الكربون CCl₄"]'::jsonb, 'تطبيق', 'تنبؤ من بيانات', 'صعب', 'الكتاب ص 29 — عملية الذوبان: المذيب يذيب شبيهه'),
('mcq', 6, 'لم يُزِل الغسل بالماء وحده بقعة شحم من قطعة قماش. أيّ الحلول الآتية أنسب مع تعليله؟', null, '["استعمال مذيب غير قطبي؛ لأن الشحم مادة غير قطبية","استعمال ماء ساخن؛ لأن الحرارة تجعل الشحم مادة قطبية","استعمال ماء مالح؛ لأن الأيونات تجذب جزيئات الشحم بقوة","استعمال مذيب قطبي آخر؛ لأن المذيبات القطبية تذيب كل المواد"]'::jsonb, 'تطبيق', 'تطبيق حياتي', 'متوسط', 'الكتاب ص 31 — محاليل المركبات الجزيئية والزيت'),
('mcq', 7, 'يذوب الإيثانول C₂H₅OH في الماء بأي نسبة، في حين لا يذوب الهكسان C₆H₁₄ فيه. ما التفسير الأنسب لذلك؟', null, '["كتلة جزيء الإيثانول أصغر من كتلة جزيء الهكسان","يحتوي الإيثانول على رابطة O–H قطبية تكوّن روابط هيدروجينية مع الماء","الإيثانول مركب أيوني يتفكك إلى أيونات في الماء","الهكسان قطبي جدًّا فيتنافر مع جزيئات الماء"]'::jsonb, 'تحليل', 'مقارنة وتعليل', 'صعب', 'الكتاب ص 31 — محاليل المركبات الجزيئية والزيت'),
('essay', 1, 'تنبّأ بإمكانية تكوّن محلول في كل حالة مما يأتي، مع التعليل بقاعدة «المذيب يذيب شبيهه»: (أ) كلوريد الصوديوم في الماء. (ب) الزيت في الماء. (ج) الزيت في الهكسان C₆H₁₄. (د) السكروز في الماء.', null, null, 'تطبيق', 'تنبؤ وتعليل', 'متوسط', 'الكتاب ص 29 — عملية الذوبان: المذيب يذيب شبيهه'),
('essay', 2, 'قال طالب: «الماء مذيب عام، فهو يذيب جميع المواد». قوّم هذه العبارة مستعينًا بقاعدة «المذيب يذيب شبيهه»، واذكر مثالًا على مادة لا تذوب في الماء ومذيبًا مناسبًا لها.', null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 31 — محاليل المركبات الجزيئية والزيت'),
('essay', 3, 'ما الخاصيتان اللتان تجب دراستهما في المذيب والمذاب لتحديد ما إذا كانا متماثلين وفق قاعدة «المذيب يذيب شبيهه»؟ ووضّح ذلك بمثال من المحاليل المائية.', null, null, 'فهم', 'شرح بمثال', 'سهل', 'الكتاب ص 29 — عملية الذوبان: المذيب يذيب شبيهه')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
