from (values
('mcq', 1, 2, 'لتحديد ما إذا كان المذيب والمذاب متماثلين تجب دراسة قطبية المركبات ونوع الروابط بين الجزيئية فيها؛ فالمذيب القطبي يذيب المواد القطبية والأيونية، والمذيب غير القطبي يذيب المواد غير القطبية.', '["الكتلة المولية ليست أساس التماثل في القاعدة؛ الأساس هو القطبية ونوع الروابط بين الجزيئية.","تتكون محاليل من حالات مختلفة كالصلب في السائل (السكر في الماء)، فالحالة ليست المعيار.","","اللون والرائحة صفات ظاهرية لا تحدد قوى التجاذب بين الجسيمات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.386Z"}'::jsonb),
('mcq', 2, 1, 'الزيت يتكون من الكربون والهيدروجين وهو غير قطبي، فيذوب في مذيب غير قطبي مثل الهكسان C₆H₁₄ (هيدروكربون غير قطبي)، تطبيقًا لقاعدة «المذيب يذيب شبيهه».', '["الماء قطبي، وقوى التجاذب بين جزيئاته وجزيئات الزيت غير القطبية ضعيفة فلا يذيبه.","","المحلول مذيبه الماء القطبي، ووجود الأيونات لا يجعله يذيب مادة غير قطبية.","مذيبه الماء القطبي أيضًا، والسكروز المذاب لا يغير قطبية المذيب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.386Z"}'::jsonb),
('mcq', 3, 2, 'السكروز مركب جزيئي قطبي يحتوي على 8 روابط O–H تكوّن روابط هيدروجينية مع جزيئات الماء القطبية، فيذوب فيه. أما الزيت والهكسان والشمع فمواد غير قطبية.', '["الزيت غير قطبي، وتجاذبه مع جزيئات الماء القطبية ضعيف فلا يكوّن معه محلولًا.","الهكسان هيدروكربون غير قطبي، فلا يذوب في الماء القطبي.","","الشمع هيدروكربون غير قطبي، فلا يتماثل مع الماء القطبي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.386Z"}'::jsonb),
('mcq', 4, 0, 'يتكون الزيت من الكربون والهيدروجين فهو غير قطبي، وقوى التجاذب بين جزيئات الماء القطبية وجزيئاته ضعيفة لا تتغلب على قوى التجاذب بين جزيئات الماء نفسها، فلا يتكون محلول.', '["","الزيت مركب جزيئي من الكربون والهيدروجين، وليس مركبًا أيونيًا.","الماء مذيب قطبي، ولو تماثلا في عدم القطبية لذاب الزيت فيه.","الذوبان يحدده التجاذب بين الجسيمات لا الكثافة، والزيت أصلًا يطفو فوق الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T11:36:22.386Z"}'::jsonb),
('mcq', 5, 3, 'كلٌّ من اليود ورابع كلوريد الكربون غير قطبي، فهما متماثلان في القطبية وتتشابه القوى بين جزيئاتهما، لذا يذوب اليود في CCl₄ وفق قاعدة «المذيب يذيب شبيهه».', '["الهكسان غير قطبي والماء قطبي، فهما غير متماثلين ولا يكوّنان محلولًا.","NaCl أيوني يحتاج إلى مذيب قطبي يجذب أيوناته، والهكسان غير قطبي.","اليود غير قطبي والماء قطبي، فالتجاذب بينهما ضعيف.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.386Z"}'::jsonb),
('mcq', 6, 0, 'الشحم غير قطبي مثل الزيت، فلا يذوب في الماء القطبي، ويذوب في مذيب غير قطبي تطبيقًا لقاعدة «المذيب يذيب شبيهه».', '["","التسخين لا يغير قطبية جزيئات الشحم، فيبقى غير متماثل مع الماء.","جزيئات الشحم غير قطبية فلا تنجذب بقوة إلى الأيونات، والمذيب ما يزال الماء القطبي.","المذيبات القطبية لا تذيب كل المواد؛ فهي لا تذيب المواد غير القطبية كالشحم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.387Z"}'::jsonb),
('mcq', 7, 1, 'كما في السكروز الذي يذوب لأن روابط O–H فيه تكوّن روابط هيدروجينية مع الماء، يحتوي الإيثانول على مجموعة O–H قطبية تجعله شبيهًا بالماء فيذوب فيه، أما الهكسان فهيدروكربون غير قطبي.', '["صغر الكتلة لا يفسر الذوبان؛ المعيار هو القطبية ونوع القوى بين الجزيئية.","","الإيثانول مركب جزيئي لا يتفكك إلى أيونات، وإنما يذوب بالروابط الهيدروجينية.","الهكسان هيدروكربون غير قطبي، وعدم ذوبانه سببه ضعف تجاذبه مع الماء لا التنافر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.387Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) يذوب؛ NaCl مركب أيوني والماء مذيب قطبي تجذب أقطابه الأيونات. (ب) لا يذوب؛ الزيت غير قطبي والماء قطبي، والتجاذب بينهما ضعيف. (ج) يذوب؛ كلاهما غير قطبي فهما متماثلان. (د) يذوب؛ السكروز قطبي يحتوي على روابط O–H تكوّن روابط هيدروجينية مع الماء القطبي.', '["(أ) يذوب مع التعليل","(ب) لا يذوب مع التعليل","(ج) يذوب مع التعليل","(د) يذوب مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) التنبؤ والتعليل","marks":2},{"element":"(ب) التنبؤ والتعليل","marks":2},{"element":"(ج) التنبؤ والتعليل","marks":2},{"element":"(د) التنبؤ والتعليل","marks":2}]'::jsonb, '[{"level":"8 درجات","description":"تنبؤ صحيح وتعليل صحيح بالقطبية في الحالات الأربع"},{"level":"4–7 درجات","description":"تنبؤات صحيحة في معظم الحالات مع نقص في بعض التعليلات"},{"level":"1–3 درجات","description":"تنبؤات صحيحة دون تعليل أو تعليل حالة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الزيت قطبيًا لأنه سائل كالماء","التعليل بالكثافة بدل القطبية","إهمال الروابط الهيدروجينية في تعليل ذوبان السكروز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (8 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.387Z"}'::jsonb),
('essay', 2, null::int, null, null, 'العبارة غير صحيحة. الماء مذيب قطبي، فهو يذيب كثيرًا من المواد القطبية والأيونية كالسكروز وكلوريد الصوديوم، لكنه لا يذيب المواد غير القطبية؛ لأن قوى التجاذب بين جزيئاته القطبية وجزيئاتها ضعيفة. مثال: الزيت (يتكون من الكربون والهيدروجين) لا يذوب في الماء، ويذوب في مذيب غير قطبي مثل الهكسان. لذا فالحكم على الذوبان يتطلب دراسة قطبية المذيب والمذاب ونوع الروابط بين الجزيئية فيهما.', '["الحكم بأن العبارة خاطئة","الماء قطبي يذيب المواد القطبية والأيونية","لا يذيب المواد غير القطبية لضعف التجاذب","مثال صحيح (الزيت) ومذيب غير قطبي مناسب"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على العبارة","marks":1},{"element":"تفسير ما يذيبه الماء","marks":2},{"element":"تفسير ما لا يذيبه الماء","marks":2},{"element":"المثال والمذيب المناسب","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"يحكم صحيحًا ويفسر بالقطبية ويقدم مثالًا ومذيبًا مناسبين"},{"level":"3–5 درجات","description":"يحكم صحيحًا مع تفسير ناقص أو مثال دون مذيب"},{"level":"1–2 درجة","description":"يحكم بخطأ العبارة دون تفسير"},{"level":"صفر","description":"يؤيد العبارة أو لا إجابة"}]'::jsonb, '["تأييد العبارة لكثرة ما يذيبه الماء","ذكر مثال لمادة تذوب في الماء","اقتراح مذيب قطبي لإذابة الزيت"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.387Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تجب دراسة قطبية المركبات، ونوع الروابط (القوى) بين الجزيئية فيها. مثال: السكروز قطبي ويكوّن روابط هيدروجينية بروابط O–H فيه، والماء قطبي ويكوّن روابط هيدروجينية، فهما متماثلان ويذوب السكروز في الماء.', '["القطبية","نوع الروابط بين الجزيئية","مثال صحيح موضّح"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر القطبية","marks":1},{"element":"ذكر نوع الروابط بين الجزيئية","marks":1},{"element":"المثال مع التوضيح","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"يذكر الخاصيتين ويقدم مثالًا موضّحًا صحيحًا"},{"level":"2–3 درجات","description":"يذكر الخاصيتين دون مثال، أو خاصية واحدة مع مثال"},{"level":"درجة واحدة","description":"يذكر خاصية واحدة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر الكتلة أو الحالة الفيزيائية بدل القطبية","مثال لمادة لا تذوب في الماء دون بيان ذلك"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.387Z"}'::jsonb)
