('mcq', 4, 'أراد طالب دراسة أثر درجة حرارة المذيب وحدها في سرعة ذوبان السكر. أيّ الكأسين الموصوفتين في الجدول يجب أن يقارن بينهما؟', '{"headers":["الكأس","شكل السكر (5 g)","درجة حرارة الماء","التحريك"],"rows":[["1","مكعبات","20 °C","دون تحريك"],["2","مكعبات","70 °C","دون تحريك"],["3","مكعبات","20 °C","مع تحريك"],["4","مطحون","70 °C","مع تحريك"]]}'::jsonb, '["الكأس 1 والكأس 3","الكأس 2 والكأس 4","الكأس 3 والكأس 4","الكأس 1 والكأس 2"]'::jsonb, 'تطبيق', 'تصميم مقارنة عادلة', 'متوسط', 'الكتاب ص 32 — العوامل المؤثرة في الذوبان: الحرارة'),
('mcq', 5, 'قيس الزمن اللازم لذوبان 5 g من السكر المطحون في 100 mL من الماء عند درجات حرارة مختلفة دون تحريك، فكانت النتائج كما في الجدول. أيّ الاستنتاجات الآتية تدعمه البيانات؟', '{"headers":["درجة حرارة الماء","10 °C","30 °C","50 °C","70 °C"],"rows":[["زمن الذوبان","180 s","110 s","65 s","40 s"]]}'::jsonb, '["كلما ارتفعت درجة حرارة المذيب قلّ زمن الذوبان، أي زادت سرعته","كلما ارتفعت درجة حرارة المذيب زاد زمن الذوبان، أي قلّت سرعته","درجة حرارة المذيب لا تؤثر في سرعة ذوبان السكر","سرعة الذوبان تتضاعف كلما ارتفعت درجة الحرارة 10 °C بالضبط"]'::jsonb, 'تحليل', 'تفسير بيانات', 'صعب', 'الكتاب ص 32 — العوامل المؤثرة في الذوبان: الحرارة'),
('mcq', 6, 'أيّ الإجراءات الآتية يزيد سرعة ذوبان مكعب سكر في كوب شاي دون تحريكه ودون تغيير مساحة سطحه؟', null, '["إضافة مكعبات ثلج إلى الشاي","طحن المكعب قبل وضعه في الشاي","تسخين الشاي قبل وضع المكعب فيه","وضع مكعب سكر آخر بجانبه"]'::jsonb, 'فهم', 'اختيار إجراء', 'متوسط', 'الكتاب ص 32 — العوامل المؤثرة في الذوبان: الحرارة'),
