('essay', 1, 'فسّر على مستوى الجسيمات لماذا يذوب السكر في الشاي الساخن أسرع منه في الشاي المثلج.', null, null, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 32 — العوامل المؤثرة في الذوبان: الحرارة'),
('essay', 2, 'صمّم تجربة بسيطة لدراسة أثر درجة حرارة المذيب في سرعة ذوبان ملح الطعام، محددًا: المتغير المستقل، والمتغير التابع، وثلاثة متغيرات يجب تثبيتها، والنتيجة المتوقعة مع تفسيرها.', null, null, 'تطبيق', 'تصميم تجربة', 'صعب', 'الكتاب ص 32 — العوامل المؤثرة في الذوبان: الحرارة'),
('essay', 3, 'قال طالب: «رفع درجة حرارة المذيب يجعل السكر يذوب أسرع، لكنه لا يغيّر كمية السكر التي يمكن أن تذوب». قوّم هذه العبارة.', null, null, 'تقويم', 'تقويم عبارة', 'متوسط', 'الكتاب ص 32 — العوامل المؤثرة في الذوبان: الحرارة')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
