from (values
('mcq', 1, 3, 'ثلاث طرائق شائعة لزيادة التصادمات وسرعة الذوبان: التحريك، وزيادة مساحة سطح المذاب، ورفع درجة حرارة المذيب.', '["تقليل مساحة السطح يقلل التصادمات؛ الصحيح زيادة مساحة السطح بتكسير المذاب.","خفض درجة الحرارة يبطئ حركة الجسيمات فيقلل سرعة الذوبان لا يزيدها.","هذه الإجراءات لا تزيد التصادمات بين المذاب والمذيب، وخفض الحرارة يبطئ الذوبان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (4%)"}],"at":"2026-10-17T11:36:22.388Z"}'::jsonb),
('mcq', 2, 1, 'برفع درجة حرارة المذيب تزداد طاقة حركة جسيماته فتزداد تصادماتها مع جسيمات المذاب، وتزداد التصادمات ذات الطاقة الكبيرة، فيذوب السكر في الشاي الساخن أسرع.', '["عدد جسيمات المذيب لا يزداد بالتسخين؛ الذي يزداد هو طاقة حركتها.","","قطبية جزيئات السكر لا تتغير بتغير درجة الحرارة.","تقليل مساحة السطح يبطئ الذوبان، ثم إن الحرارة لا تغير حجم البلورات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T11:36:22.388Z"}'::jsonb),
('mcq', 3, 2, 'عند رفع درجة حرارة المذيب تزداد طاقة حركة جسيماته، فتزداد التصادمات، وتزداد التصادمات ذات الطاقة الكبيرة مقارنة بالتصادمات عند درجة حرارة منخفضة، فتزداد سرعة الذوبان.', '["رفع درجة الحرارة يزيد طاقة الحركة ولا يقللها.","عدد جسيمات المذيب ثابت، والذي يتغير بالحرارة هو طاقة حركتها.","","التصادمات لا تتوقف بالتسخين، بل يزداد عددها وطاقتها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.389Z"}'::jsonb),
('mcq', 4, 3, 'الكأسان 1 و2 متماثلتان في شكل السكر (مكعبات) وعدم التحريك، وتختلفان في درجة حرارة الماء فقط (20 °C و70 °C)، فأي فرق في سرعة الذوبان يُنسب إلى درجة الحرارة.', '["الكأسان تختلفان في التحريك فقط، فهذه المقارنة تدرس أثر التحريك لا الحرارة.","تختلفان في درجة الحرارة وشكل السكر معًا، فلا يمكن نسبة الفرق إلى الحرارة وحدها.","تختلفان في أكثر من عامل (الحرارة والتحريك وشكل السكر)، فالمقارنة غير عادلة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.389Z"}'::jsonb),
('mcq', 5, 0, 'نقص زمن الذوبان من 180 s عند 10 °C إلى 40 s عند 70 °C، ونقصان الزمن يعني زيادة سرعة الذوبان؛ لأن جسيمات المذيب الأسخن أسرع حركة وأكثر تصادمًا مع المذاب.', '["","البيانات تُظهر نقصان الزمن مع ارتفاع الحرارة؛ وهذا الاختيار يقرأ العلاقة معكوسة.","تغير الزمن من 180 s إلى 40 s يدل على تأثير واضح لدرجة الحرارة.","البيانات لا تُظهر تضاعفًا منتظمًا؛ فالزمن لم ينقص إلى النصف عند كل زيادة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.389Z"}'::jsonb),
('mcq', 6, 2, 'مع استبعاد التحريك ومساحة السطح يبقى العامل الثالث وهو رفع درجة حرارة المذيب؛ فتسخين الشاي يزيد طاقة حركة جسيماته وتصادماتها مع السكر فيذوب أسرع.', '["الثلج يخفض درجة حرارة المذيب فيبطئ حركة جسيماته وسرعة الذوبان.","الطحن يزيد مساحة السطح، وهو إجراء مستبعد بشرط السؤال.","","إضافة مذاب آخر لا تزيد سرعة ذوبان المكعب الأول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T11:36:22.389Z"}'::jsonb),
('mcq', 7, 1, 'تجتمع هنا العوامل الثلاثة التي تزيد التصادمات: مساحة سطح كبيرة (مطحون)، ودرجة حرارة مرتفعة للمذيب، والتحريك؛ فيكون زمن الذوبان أقصر ما يمكن.', '["مساحة سطح المكعبات أقل من المطحون، فتقل التصادمات ويطول الزمن.","","الماء البارد جسيماته أبطأ حركة، فيقل عدد التصادمات وطاقتها.","دون تحريك تبتعد الجسيمات الذائبة عن سطح التماس ببطء، فيكون الذوبان أبطأ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.389Z"}'::jsonb),
('essay', 1, null::int, null, null, 'يحدث الذوبان عند تصادم جسيمات المذيب والمذاب. في الشاي الساخن تكون طاقة حركة جسيمات المذيب أكبر، فتتحرك أسرع وتزداد تصادماتها مع جسيمات السكر، وتزداد التصادمات ذات الطاقة الكبيرة، فتنفصل جسيمات السكر وتحاط بجسيمات المذيب أسرع، أي تزداد سرعة الذوبان.', '["الذوبان يحدث بتصادم جسيمات المذيب والمذاب","الحرارة تزيد طاقة حركة جسيمات المذيب","تزداد التصادمات وطاقتها فتزداد سرعة الذوبان"]'::jsonb, '[]'::jsonb, '[{"element":"ربط الذوبان بالتصادمات","marks":1},{"element":"زيادة طاقة الحركة بالتسخين","marks":1.5},{"element":"زيادة عدد التصادمات وطاقتها ومن ثم السرعة","marks":1.5}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل يربط الحرارة بطاقة الحركة والتصادمات وسرعة الذوبان"},{"level":"2–3 درجات","description":"يذكر زيادة الحركة أو التصادمات دون ربط كامل"},{"level":"درجة واحدة","description":"يذكر أن الحرارة تسرّع الذوبان دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن عدد جسيمات المذيب يزداد بالتسخين","الخلط بين سرعة الذوبان ومساحة السطح"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T11:36:22.390Z"}'::jsonb),
('essay', 2, null::int, null, null, 'المتغير المستقل: درجة حرارة الماء (مثلًا 10 °C و40 °C و70 °C). المتغير التابع: الزمن اللازم لذوبان كتلة الملح كاملة (أو سرعة الذوبان). المتغيرات الثابتة: كتلة الملح (مثلًا 2 g)، وحجم الماء (100 mL)، وحجم حبيبات الملح (مساحة السطح)، وطريقة التحريك (دون تحريك أو تحريك متماثل). النتيجة المتوقعة: يقل زمن الذوبان كلما ارتفعت درجة الحرارة؛ لأن طاقة حركة جسيمات الماء تزداد فتزداد التصادمات ذات الطاقة الكبيرة مع جسيمات الملح.', '["المتغير المستقل: درجة الحرارة","المتغير التابع: زمن الذوبان","ثلاثة متغيرات مضبوطة","النتيجة المتوقعة","التفسير بالتصادمات"]'::jsonb, '[]'::jsonb, '[{"element":"المتغير المستقل","marks":1},{"element":"المتغير التابع","marks":1},{"element":"المتغيرات المضبوطة (لكل منها 1)","marks":3},{"element":"النتيجة المتوقعة","marks":0.5},{"element":"التفسير","marks":0.5}]'::jsonb, '[{"level":"6 درجات","description":"تصميم كامل بمتغيرات صحيحة ونتيجة مفسرة"},{"level":"3–5 درجات","description":"تصميم مقبول ينقصه ضبط بعض المتغيرات أو التفسير"},{"level":"1–2 درجة","description":"يحدد المتغير المستقل أو التابع فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ الكتلة الذائبة متغيرًا مستقلًا","إهمال تثبيت حجم الحبيبات أو التحريك","توقع زيادة زمن الذوبان بالتسخين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.390Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الجزء الأول صحيح: رفع درجة حرارة المذيب يزيد طاقة حركة جسيماته وتصادماتها مع السكر فيذوب أسرع. أما الجزء الثاني فخاطئ: المذيب الساخن يذيب كمية أكبر من المذاب مقارنة بالبارد، ولذلك يستوعب الشاي الساخن سكرًا ذائبًا أكثر من الشاي المثلج؛ فالحرارة تؤثر في السرعة والكمية معًا بالنسبة للسكر ومعظم المواد الصلبة.', '["الجزء الأول صحيح مع التعليل","الجزء الثاني خاطئ","المذيب الساخن يذيب كمية أكبر (مثال الشاي)"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم على الجزء الأول وتعليله","marks":2},{"element":"الحكم على الجزء الثاني","marks":1},{"element":"التعليل بمثال الشاي الساخن","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يحكم على الجزأين صحيحًا مع التعليل"},{"level":"2–3 درجات","description":"يحكم صحيحًا على جزء واحد مع تعليله"},{"level":"درجة واحدة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"يؤيد العبارة كلها دون تفسير أو لا إجابة"}]'::jsonb, '["تأييد العبارة كاملة","تعميم زيادة الكمية على الغازات أيضًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.390Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
