('mcq', 4, 'ذائبية كلوريد الصوديوم NaCl في الماء عند 20 °C هي 35.9 g/100 g H₂O. ما معنى ذلك؟', null, '["أقصى كتلة من NaCl تذوب في 100 g من الماء عند 20 °C هي 35.9 g","تذوب 35.9 g من NaCl في 100 g من الماء خلال دقيقة واحدة","أقل كتلة من NaCl تكفي لتكوين محلول في 100 g من الماء هي 35.9 g","أقصى كتلة من NaCl تذوب في 100 g من الماء عند أي درجة حرارة هي 35.9 g"]'::jsonb, 'فهم', 'تفسير قيمة', 'متوسط', 'الكتاب ص 34 — الجدول 1-4 الذائبية في الماء'),
('mcq', 5, 'ذائبية كلوريد البوتاسيوم KCl عند 20 °C هي 34.2 g/100 g H₂O. ما أقصى كتلة من KCl يمكن أن تذوب في 50 g من الماء عند الدرجة نفسها؟', null, '["34.2 g","68.4 g","17.1 g","14.0 g"]'::jsonb, 'تطبيق', 'حساب', 'متوسط', 'الكتاب ص 34 — الجدول 1-4 الذائبية في الماء'),
('mcq', 6, 'لماذا يجب ذكر درجة الحرارة عند التعبير عن ذائبية مادة ما؟', null, '["لأن كتلة المذيب تتغير بتغير درجة الحرارة","لأن طبيعة المذاب الكيميائية تتغير بتغير درجة الحرارة","لأن جميع المواد تذوب بالكمية نفسها عند درجة الحرارة نفسها","لأن ذائبية المادة تتغير بتغير درجة الحرارة"]'::jsonb, 'فهم', 'تعليل', 'صعب', 'الكتاب ص 33 — الذائبية'),
('mcq', 7, 'يذوب السكر المطحون أسرع من مكعبات السكر. ماذا يحدث لذائبية السكر في الماء عند 20 °C إذا طُحن قبل إضافته؟', null, '["تزداد؛ لأن الطحن يزيد مساحة سطح السكر","تبقى ثابتة؛ لأن الطحن يغير سرعة الذوبان لا أقصى كمية تذوب","تقل؛ لأن الحبيبات الصغيرة تتجمع فلا تذوب","تتضاعف؛ لأن عدد حبيبات السكر يتضاعف"]'::jsonb, 'فهم', 'تمييز مفاهيم', 'صعب', 'الكتاب ص 33 — الذائبية'),
('essay', 1, 'عرّف الذائبية، واذكر العوامل التي تعتمد عليها.', null, null, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 33 — الذائبية'),
('essay', 2, 'ذائبية كلوريد الصوديوم NaCl عند 20 °C هي 35.9 g/100 g H₂O، وذائبية نترات الفضة AgNO₃ عند الدرجة نفسها هي 216 g/100 g H₂O. (أ) فسّر معنى كل قيمة. (ب) أيّ المادتين أكثر ذائبية في الماء عند 20 °C؟ (ج) ما الذي يفسّر اختلاف الذائبية بين المادتين في المذيب نفسه وعند درجة الحرارة نفسها؟', null, null, 'فهم', 'تفسير ومقارنة', 'متوسط', 'الكتاب ص 34 — الجدول 1-4 الذائبية في الماء'),
('essay', 3, 'ذائبية السكروز في الماء عند 20 °C هي 203.9 g/100 g H₂O. (أ) احسب أقصى كتلة من السكروز يمكن أن تذوب في 250 g من الماء عند 20 °C. (ب) إذا أُضيف 600 g من السكروز إلى هذه الكمية من الماء عند 20 °C وحُرّك المزيج طويلًا، فما كتلة السكروز التي تبقى دون ذوبان؟', null, null, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 34 — الجدول 1-4 الذائبية في الماء')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
