select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 0, 'تُعرّف الذائبية بأنها أقصى كمية من المذاب يمكن أن تذوب في كمية محددة من المذيب عند درجة حرارة معينة.', '["","الذائبية تعبر عن الحد الأقصى لما يذوب، لا عن أقل كمية.","هذا وصف لسرعة الذوبان، وهي مفهوم مختلف عن الذائبية.","هذا تعريف الذوبان (عملية) لا الذائبية (كمية)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-17T11:36:22.391Z"}'::jsonb),
('mcq', 2, 2, 'يُعبَّر عن ذائبية المواد الصلبة بعدد غرامات المذاب التي تذوب في 100 g من الماء، أي g/100 g H₂O.', '["هذه وحدة الكتلة المولية لا الذائبية.","هذه وحدة سرعة (كمية لكل زمن)، والذائبية لا تتضمن الزمن.","","لا علاقة للذائبية بالضغط مقسومًا على درجة الحرارة؛ هذه وحدة لا معنى لها هنا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.391Z"}'::jsonb),
('mcq', 3, 3, 'تعتمد الذائبية على طبيعة كل من المذاب والمذيب، وتتغير بتغير درجة الحرارة، ولذلك تُذكر درجة الحرارة في تعريفها.', '["مساحة السطح والتحريك يؤثران في سرعة الذوبان لا في أقصى كمية تذوب.","حجم البلورات والزمن يؤثران في سرعة الوصول إلى الإشباع لا في الذائبية.","إضافة كتلة أكبر لا تغير الذائبية؛ فما يزيد عليها يبقى دون ذوبان.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.391Z"}'::jsonb),
('mcq', 4, 0, 'وفق التعريف تعني القيمة أن 100 g من الماء عند 20 °C يمكن أن تذيب 35.9 g من NaCl على الأكثر، وما يزيد على ذلك لا يذوب عند هذه الدرجة.', '["","الذائبية لا تتضمن زمنًا؛ هي كمية قصوى لا سرعة.","أي كمية أقل من 35.9 g تذوب أيضًا؛ فالرقم حد أقصى لا حد أدنى.","الذائبية تتغير بتغير درجة الحرارة؛ فالقيمة خاصة بـ 20 °C فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-17T11:36:22.391Z"}'::jsonb),
('mcq', 5, 2, 'الذائبية 34.2 g لكل 100 g ماء، فلـ 50 g ماء: 34.2 × (50/100) = 17.1 g.', '["هذه الكتلة تذوب في 100 g من الماء؛ أُهمل تحويل كمية الماء إلى 50 g.","ضُربت الذائبية في 2 بدل القسمة على 2؛ والماء الأقل يذيب كمية أقل.","","استُعملت ذائبية KCl عند 0 °C (28.0 g لكل 100 g ماء) بدل قيمتها عند 20 °C، فنتج 14.0 g."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-17T11:36:22.391Z"}'::jsonb),
('mcq', 6, 3, 'تتغير الذائبية بتغير درجة الحرارة؛ فمثلًا يذوب 203.9 g من السكروز في 100 g ماء عند 20 °C و487.2 g عند 100 °C، لذا لا معنى لقيمة الذائبية دون ذكر درجة الحرارة.', '["كتلة المذيب لا تتغير بالتسخين، والسبب تغير الذائبية نفسها.","المذاب يبقى المادة نفسها؛ الذي يتغير هو أقصى كمية تذوب.","الذائبية تختلف باختلاف المواد عند الدرجة نفسها.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.392Z"}'::jsonb),
('mcq', 7, 1, 'الذائبية تعتمد على طبيعة المذاب والمذيب ودرجة الحرارة فقط، أما الطحن فيزيد مساحة السطح فيزيد سرعة الذوبان، لذا تبقى ذائبية السكر عند 20 °C ثابتة.', '["زيادة مساحة السطح تزيد سرعة الذوبان، لا الكمية القصوى التي تذوب.","","الطحن لا يقلل الذائبية، والحبيبات الصغيرة تذوب أسرع.","عدد الحبيبات لا يغير الكتلة القصوى الذائبة، وهي تعتمد على طبيعة المواد والحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.392Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الذائبية هي أقصى كمية من المذاب يمكن أن تذوب في كمية محددة من المذيب عند درجة حرارة معينة. وتعتمد على طبيعة كل من المذاب والمذيب، وعلى درجة الحرارة (وعلى الضغط في حالة الغازات).', '["أقصى كمية من المذاب","في كمية محددة من المذيب","عند درجة حرارة معينة","تعتمد على طبيعة المذاب والمذيب ودرجة الحرارة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف (أقصى كمية/كمية محددة من المذيب/درجة حرارة معينة)","marks":3},{"element":"العوامل التي تعتمد عليها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف كامل بعناصره الثلاثة مع ذكر العوامل"},{"level":"2–3 درجات","description":"تعريف ينقصه عنصر أو دون ذكر العوامل"},{"level":"درجة واحدة","description":"إشارة عامة إلى «كمية ما يذوب»"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال ذكر درجة الحرارة في التعريف","الخلط بين الذائبية وسرعة الذوبان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.392Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) أقصى ما يذوب من NaCl في 100 g ماء عند 20 °C هو 35.9 g، وأقصى ما يذوب من AgNO₃ في 100 g ماء عند 20 °C هو 216 g. (ب) نترات الفضة أكثر ذائبية (216 g > 35.9 g). (ج) لأن الذائبية تعتمد على طبيعة المذاب؛ فالمذيب ودرجة الحرارة متماثلان، والاختلاف في طبيعة المادتين.', '["تفسير قيمة NaCl","تفسير قيمة AgNO₃","AgNO₃ أكثر ذائبية","الاختلاف بسبب طبيعة المذاب"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) تفسير القيمتين","marks":2},{"element":"(ب) المقارنة","marks":1},{"element":"(ج) التعليل بطبيعة المذاب","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"يفسر القيمتين ويقارن صحيحًا ويعلل بطبيعة المذاب"},{"level":"2–3 درجات","description":"يفسر القيمتين أو يقارن مع نقص في التعليل"},{"level":"درجة واحدة","description":"يحدد الأكثر ذائبية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تفسير القيمة على أنها كتلة تذوب في لتر من الماء","التعليل بمساحة السطح أو التحريك"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-17T11:36:22.392Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الكتلة القصوى = 203.9 g × (250 g / 100 g) = 509.75 g ≈ 509.8 g. (ب) الكتلة غير الذائبة = 600 g − 509.8 g = 90.2 g تقريبًا؛ لأن الماء لا يستطيع إذابة أكثر من ذائبيته عند هذه الدرجة مهما طال التحريك.', '["تحويل الذائبية إلى 250 g ماء","الناتج 509.8 g","الكتلة غير الذائبة 90.2 g","التحريك لا يزيد الذائبية"]'::jsonb, '["الذائبية لكل 1 g ماء = 203.9/100 = 2.039 g","لـ 250 g ماء: 2.039 × 250 = 509.75 g ≈ 509.8 g","غير الذائب = 600 − 509.8 = 90.2 g"]'::jsonb, '[{"element":"(أ) خطوة التناسب","marks":1},{"element":"(أ) الناتج مع الوحدة","marks":1},{"element":"(ب) الطرح والناتج","marks":1},{"element":"(ب) تعليل بقاء الكمية دون ذوبان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حسابات صحيحة بالوحدات مع التعليل"},{"level":"2–3 درجات","description":"حساب (أ) صحيح مع خطأ في (ب) أو دون تعليل"},{"level":"درجة واحدة","description":"خطوة تناسب صحيحة مع خطأ حسابي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال 203.9 g مباشرة دون تحويل كمية الماء","القسمة على 2.5 بدل الضرب","الظن أن التحريك الطويل يذيب الكمية كلها"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:36:22.392Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K3-C1-L3-O13') and x.type = v.type and x.number = v.number
