from (values
('mcq', 1, 'ما المحلول المشبع؟', null, '["محلول يحتوي على كمية من المذاب أقل مما يمكن أن يذوب عند درجة حرارة وضغط معينين","محلول يحتوي على أكبر كمية من المذاب ذائبة في كمية محددة من المذيب عند درجة حرارة وضغط معينين","محلول يحتوي على كمية من المذاب أكبر مما يحتويه محلول مشبع عند درجة الحرارة نفسها","محلول توقفت فيه جسيمات المذاب تمامًا عن الذوبان والتبلور عند درجة حرارة معينة"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 33 — المحلول المشبع والاتزان الديناميكي'),
('mcq', 2, 'محلول مشبع على تماس مع بلورات من المذاب غير الذائب عند درجة حرارة ثابتة. أيّ العبارات الآتية تصف ما يحدث فيه؟', null, '["يتوقف الذوبان تمامًا ويستمر التبلور","سرعة التبلور أكبر من سرعة الذوبان","سرعة الذوبان أكبر من سرعة التبلور","تتساوى سرعة الذوبان مع سرعة التبلور"]'::jsonb, 'فهم', 'وصف حالة', 'متوسط', 'الكتاب ص 33 — المحلول المشبع والاتزان الديناميكي'),
('mcq', 3, 'لماذا توصف حالة المحلول المشبع بأنها اتزان «ديناميكي»؟', null, '["لأن الذوبان والتبلور يستمران معًا بسرعتين متساويتين","لأن جسيمات المذاب تتوقف عن الحركة بعد الإشباع","لأن كمية المذاب الذائبة تتزايد باستمرار مع الزمن","لأن درجة حرارة المحلول تتغير باستمرار في أثناء الاتزان"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 33 — المحلول المشبع والاتزان الديناميكي'),
('mcq', 4, 'ماذا يحدث لكمية المذاب الذائبة في محلول مشبع مع مرور الزمن إذا بقيت درجة الحرارة ثابتة؟', null, '["تزداد تدريجيًا","تقل تدريجيًا","تزداد ثم تقل باستمرار","تبقى ثابتة"]'::jsonb, 'فهم', 'تنبؤ', 'سهل', 'الكتاب ص 33 — المحلول المشبع والاتزان الديناميكي'),
('mcq', 5, 'عند إضافة كمية كبيرة من مذاب صلب إلى مذيب، كيف تتغير سرعتا الذوبان والتبلور حتى الوصول إلى الإشباع؟', null, '["تزداد سرعة الذوبان تدريجيًا، وتبقى سرعة التبلور ثابتة حتى تساويها","تبقى سرعة الذوبان ثابتة، وتزداد سرعة التبلور تدريجيًا حتى تساويها","تقل سرعتا الذوبان والتبلور معًا حتى تصبحا صفرًا","تبدأ سرعة التبلور أكبر من سرعة الذوبان ثم تقل حتى تساويها"]'::jsonb, 'فهم', 'وصف تسلسل', 'صعب', 'الكتاب ص 33 — المحلول المشبع والاتزان الديناميكي'),
('mcq', 6, 'أُضيف 40.0 g من NaCl إلى 100 g من الماء عند 20 °C وحُرّك المزيج طويلًا، فبقي 4.1 g دون ذوبان (ذائبية NaCl عند 20 °C هي 35.9 g/100 g H₂O). كيف يُصنَّف المحلول الموجود فوق الملح المتبقي؟', null, '["مشبع، وفي حالة اتزان ديناميكي مع الملح المتبقي","غير مشبع؛ لأن جزءًا من الملح لم يذب","فوق مشبع؛ لأن الكتلة المضافة أكبر من الذائبية","مشبع، وقد توقف فيه الذوبان والتبلور تمامًا"]'::jsonb, 'تطبيق', 'تصنيف من بيانات', 'متوسط', 'الكتاب ص 33 — المحلول المشبع والاتزان الديناميكي'),
('mcq', 7, 'وُضعت بلورة غير منتظمة الشكل من KCl كتلتها 2.00 g في محلول مشبع من KCl في وعاء مغلق عند درجة حرارة ثابتة. بعد عدة أيام بقيت كتلة البلورة 2.00 g لكن شكلها تغيّر. ما التفسير الأنسب؟', null, '["لم يحدث أي ذوبان أو تبلور لأن المحلول مشبع","ذابت البلورة كلها ثم تبلورت من جديد مرة واحدة","بعض جسيمات البلورة ذابت وتبلورت جسيمات أخرى على سطحها بالسرعة نفسها","تبخر جزء من الماء فتبلورت كمية إضافية على البلورة"]'::jsonb, 'تحليل', 'تفسير مشاهدة', 'صعب', 'الكتاب ص 33 — المحلول المشبع والاتزان الديناميكي'),
('essay', 1, 'عرّف المحلول المشبع، وفسّر كيف يصل المحلول إلى حالة الاتزان الديناميكي بين الذوبان والتبلور.', null, null, 'فهم', 'تعريف وتفسير', 'متوسط', 'الكتاب ص 33 — المحلول المشبع والاتزان الديناميكي'),
('essay', 2, 'أُضيف 60.0 g من KCl إلى 100 g من الماء عند 20 °C، وذائبية KCl عند هذه الدرجة 34.2 g/100 g H₂O. (أ) ما كتلة KCl التي تذوب؟ (ب) ما كتلة KCl المتبقية دون ذوبان؟ (ج) صنّف المحلول، وصف ما يحدث على مستوى الجسيمات بين المحلول وKCl المتبقي.', null, null, 'تطبيق', 'حساب وتفسير', 'صعب', 'الكتاب ص 33–34 — المحلول المشبع والجدول 1-4'),
('essay', 3, 'قارن بين المحلول المشبع والمحلول غير المشبع عند درجة الحرارة نفسها من حيث: (أ) إمكانية إذابة مزيد من المذاب. (ب) العلاقة بين سرعة الذوبان وسرعة التبلور.', null, null, 'فهم', 'مقارنة', 'سهل', 'الكتاب ص 33 — المحلول المشبع والاتزان الديناميكي')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
