select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'يُعرّف المحلول المشبع بأنه المحلول الذي يحتوي على أكبر كمية من المذاب ذائبة في كمية محددة من المذيب عند درجة حرارة وضغط معينين.', '["هذا وصف المحلول غير المشبع الذي يمكن إذابة مزيد من المذاب فيه.","","هذا تعريف المحلول فوق المشبع، وهو غير ثابت.","الذوبان والتبلور لا يتوقفان في المحلول المشبع، بل يستمران بسرعتين متساويتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.393Z"}'::jsonb),
('mcq', 2, 3, 'في المحلول المشبع يصل النظام إلى حالة اتزان ديناميكي تتساوى فيها سرعة الذوبان وسرعة التبلور، لذا لا تتغير كمية المذاب الذائبة.', '["لو استمر التبلور وحده لنقصت كمية المذاب الذائبة، وهي ثابتة في المحلول المشبع.","هذا يؤدي إلى نقص الكمية الذائبة باستمرار، فلا يكون المحلول في حالة اتزان.","هذه حالة المحلول قبل الوصول إلى الإشباع، حين تزداد الكمية الذائبة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-17T11:36:22.393Z"}'::jsonb),
('mcq', 3, 0, 'كلمة «ديناميكي» تعني أن العمليتين لم تتوقفا؛ فالجسيمات تستمر في الذوبان وأخرى في التبلور، لكن بسرعتين متساويتين، فتبقى الكمية الذائبة ثابتة.', '["","الجسيمات لا تتوقف عن الحركة؛ الذوبان والتبلور مستمران.","الكمية الذائبة في المحلول المشبع تبقى ثابتة ولا تتزايد.","الاتزان يتحقق إذا بقيت درجة الحرارة ثابتة، لا متغيرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.393Z"}'::jsonb),
('mcq', 4, 3, 'رغم استمرار ذوبان جسيمات المذاب وتبلورها في المحلول الذي وصل إلى حالة الاتزان، فإن كمية المذاب الذائبة تبقى ثابتة لتساوي السرعتين.', '["زيادتها تتطلب أن تكون سرعة الذوبان أكبر من سرعة التبلور، وهذا لا يحدث بعد الإشباع.","نقصانها يتطلب أن تكون سرعة التبلور أكبر من سرعة الذوبان، وهذا لا يحدث عند الاتزان.","لا يتذبذب المحلول المشبع؛ فالسرعتان متساويتان باستمرار.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-17T11:36:22.393Z"}'::jsonb),
('mcq', 5, 1, 'مع زيادة عدد جسيمات المذاب الذائبة يزداد تصادمها مع بقية البلورة فيلتصق بعضها بسطحها (يتبلور)، فتزداد سرعة التبلور بينما تبقى سرعة الذوبان ثابتة، ويستمر الذوبان ما دامت سرعته أعلى، حتى تتساوى السرعتان.', '["هذا عكس ما يحدث؛ فسرعة التبلور هي التي تزداد مع زيادة الجسيمات الذائبة.","","السرعتان لا تصبحان صفرًا؛ فالاتزان ديناميكي تستمر فيه العمليتان.","في البداية لا توجد جسيمات ذائبة كثيرة لتتبلور، فسرعة الذوبان هي الأكبر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.394Z"}'::jsonb),
('mcq', 6, 0, 'الكتلة الذائبة = 40.0 − 4.1 = 35.9 g، وهي تساوي ذائبية NaCl عند 20 °C، فالمحلول مشبع، والملح المتبقي في حالة اتزان ديناميكي معه: يذوب منه جزء ويتبلور جزء بالسرعة نفسها.', '["","بقاء ملح دون ذوبان دليل على أن المحلول وصل إلى أقصى ما يذيبه، فهو مشبع لا غير مشبع.","الكتلة الذائبة فعليًا 35.9 g تساوي الذائبية، ولا تزيد عليها.","التصنيف صحيح لكن الوصف خاطئ؛ فالذوبان والتبلور مستمران بسرعتين متساويتين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.394Z"}'::jsonb),
('mcq', 7, 2, 'ثبات الكتلة مع تغير الشكل دليل على الاتزان الديناميكي: جسيمات تغادر البلورة (ذوبان) من مواضع، وجسيمات أخرى تلتصق بها (تبلور) في مواضع أخرى، بسرعتين متساويتين.', '["لو توقفت العمليتان لما تغير شكل البلورة.","الكتلة بقيت ثابتة باستمرار، والتغير حدث تدريجيًا بعمليتين متزامنتين لا بخطوتين منفصلتين.","","الوعاء مغلق، ولو تبلورت كمية إضافية لزادت كتلة البلورة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.394Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المحلول المشبع يحتوي على أكبر كمية من المذاب ذائبة في كمية محددة من المذيب عند درجة حرارة وضغط معينين. عند إضافة المذاب تتصادم جسيمات المذيب مع سطحه فتذوب جسيماته، ومع زيادة عدد الجسيمات الذائبة يزداد تصادمها مع بقية البلورة فيلتصق بعضها بسطحها (تبلور)، فتزداد سرعة التبلور بينما تبقى سرعة الذوبان ثابتة. وعندما تتساوى السرعتان يصل المحلول إلى اتزان ديناميكي (إذا بقيت درجة الحرارة ثابتة)، فلا يذوب مزيد من المذاب وتبقى الكمية الذائبة ثابتة.', '["تعريف المحلول المشبع","زيادة الجسيمات الذائبة تزيد سرعة التبلور","سرعة الذوبان ثابتة","تساوي السرعتين = اتزان ديناميكي وثبات الكمية الذائبة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"تزايد سرعة التبلور وسببه","marks":1.5},{"element":"ثبات سرعة الذوبان","marks":0.5},{"element":"تساوي السرعتين وثبات الكمية","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تعريف كامل وتفسير متسلسل صحيح لبلوغ الاتزان"},{"level":"3–5 درجات","description":"تعريف صحيح وتفسير ناقص"},{"level":"1–2 درجة","description":"تعريف فقط أو ذكر «تساوي السرعتين» دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الذوبان يتوقف عند الإشباع","إغفال شرط ثبات درجة الحرارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.394Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) يذوب 34.2 g فقط (أقصى ما يذوب). (ب) المتبقي = 60.0 − 34.2 = 25.8 g. (ج) المحلول مشبع؛ ويحدث بينه وبين الملح المتبقي اتزان ديناميكي: تستمر جسيمات KCl في الذوبان من سطح البلورات، وتتبلور جسيمات ذائبة أخرى على سطحها بالسرعة نفسها، فتبقى كتلة KCl الذائبة (34.2 g) وكتلة المتبقي ثابتتين ما دامت درجة الحرارة ثابتة.', '["الكتلة الذائبة 34.2 g","المتبقي 25.8 g","المحلول مشبع","وصف الاتزان الديناميكي"]'::jsonb, '["الذائب = الذائبية في 100 g ماء = 34.2 g","المتبقي = 60.0 − 34.2 = 25.8 g"]'::jsonb, '[{"element":"(أ) الكتلة الذائبة","marks":1},{"element":"(ب) الكتلة المتبقية","marks":1},{"element":"(ج) التصنيف","marks":1},{"element":"(ج) وصف الاتزان الديناميكي","marks":3}]'::jsonb, '[{"level":"6 درجات","description":"حسابات صحيحة وتصنيف صحيح ووصف كامل للاتزان الديناميكي"},{"level":"3–5 درجات","description":"حسابات وتصنيف صحيحان مع وصف ناقص للاتزان"},{"level":"1–2 درجة","description":"حساب واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ المحلول فوق مشبع لأن الكتلة المضافة أكبر من الذائبية","القول بتوقف الذوبان والتبلور","طرح خاطئ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.394Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) المحلول غير المشبع يمكن إذابة مزيد من المذاب فيه، أما المشبع فلا يذوب فيه مزيد من المذاب عند الدرجة نفسها. (ب) في المحلول غير المشبع (الذي يحتوي على مذاب صلب يذوب) تكون سرعة الذوبان أكبر من سرعة التبلور فتزداد الكمية الذائبة، أما في المحلول المشبع فتتساوى السرعتان (اتزان ديناميكي) فتبقى الكمية الذائبة ثابتة.', '["غير المشبع يذيب المزيد","المشبع لا يذيب المزيد","غير المشبع: الذوبان أسرع من التبلور","المشبع: السرعتان متساويتان"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) المقارنة","marks":2},{"element":"(ب) المقارنة","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة في البندين"},{"level":"2–3 درجات","description":"مقارنة صحيحة في بند واحد وناقصة في الآخر"},{"level":"درجة واحدة","description":"وصف أحد المحلولين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن التبلور أسرع في المحلول المشبع","الخلط بين المشبع وفوق المشبع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.395Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
