insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K3-C1-L3-O15'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المحلول فوق المشبع؟', null, '["محلول يحتوي على أكبر كمية من المذاب يمكن أن تذوب عند درجة حرارة وضغط معينين","محلول يحتوي على كمية من المذاب أقل مما في المحلول المشبع عند درجة الحرارة نفسها","محلول يحتوي على كمية من المادة المذابة أكبر مما يحتويه محلول مشبع عند درجة الحرارة نفسها","محلول مشبع أُضيفت إليه كمية زائدة من المذاب فبقيت راسبة في قاعه"]'::jsonb, 'تذكر', 'تعريف مصطلح', 'سهل', 'الكتاب ص 34 — المحاليل فوق المشبعة'),
('mcq', 2, 'أيّ العبارات الآتية تصف المحاليل فوق المشبعة؟', null, '["غير ثابتة، وقد تترسب منها المادة الزائدة بسرعة","ثابتة تمامًا ولا يترسب منها المذاب مهما حدث","تحتوي دائمًا على بلورات غير ذائبة في قاعها","أقل تركيزًا من المحاليل المشبعة عند الدرجة نفسها"]'::jsonb, 'تذكر', 'استرجاع', 'سهل', 'الكتاب ص 34 — المحاليل فوق المشبعة'),
('mcq', 3, 'ذائبية السكروز عند 20 °C هي 203.9 g/100 g H₂O. محلول صافٍ لا توجد فيه بلورات يحتوي على 250 g من السكروز ذائبة في 100 g من الماء عند 20 °C. كيف يُصنَّف هذا المحلول؟', null, '["محلول غير مشبع","محلول فوق مشبع","محلول مشبع","محلول مشبع فيه راسب"]'::jsonb, 'فهم', 'تصنيف', 'متوسط', 'الكتاب ص 34 — المحاليل فوق المشبعة والجدول 1-4'),
('mcq', 4, 'يبيّن الجدول أربعة محاليل صافية في كلٍّ منها 100 g من الماء، وذائبية كل مذاب عند درجة حرارة المحلول. أيّ المحاليل فوق مشبع؟', '{"headers":["المحلول","المذاب","الكتلة الذائبة","درجة الحرارة","الذائبية (g/100 g H₂O)"],"rows":[["1","NaCl","30.0 g","20 °C","35.9"],["2","KCl","50.0 g","60 °C","45.8"],["3","AgNO₃","200 g","20 °C","216"],["4","KCl","34.2 g","20 °C","34.2"]]}'::jsonb, '["المحلول 1","المحلول 3","المحلول 2","المحلول 4"]'::jsonb, 'فهم', 'تصنيف من بيانات', 'متوسط', 'الكتاب ص 34 — المحاليل فوق المشبعة والجدول 1-4'),
('mcq', 5, 'بماذا يتميّز المحلول فوق المشبع من المحلول المشبع عند درجة الحرارة نفسها؟', null, '["يحتوي على كمية مذابة أكبر من الكمية في المحلول المشبع","يحتوي على كمية مذابة أقل من الكمية في المحلول المشبع","يحتوي على الكمية المذابة نفسها لكن عند ضغط أعلى","يحتوي على الكمية المذابة نفسها مع وجود راسب في قاعه"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 34 — المحاليل فوق المشبعة'),
('mcq', 6, 'ذائبية كبريتات الليثيوم Li₂SO₄ هي 36.1 g/100 g H₂O عند 0 °C و34.8 g/100 g H₂O عند 20 °C. محلول صافٍ يحتوي على 35.5 g منها ذائبة في 100 g من الماء عند 20 °C. ما تصنيفه؟', null, '["غير مشبع؛ لأن 35.5 g أقل من ذائبيتها عند 0 °C","فوق مشبع؛ لأن 35.5 g أكبر من ذائبيتها عند 20 °C","مشبع؛ لأن 35.5 g تقع بين ذائبيتيها عند 0 °C و20 °C","غير مشبع؛ لأن ذائبية Li₂SO₄ تزداد بارتفاع الحرارة"]'::jsonb, 'تطبيق', 'تصنيف من بيانات', 'صعب', 'الكتاب ص 34 — المحاليل فوق المشبعة والجدول 1-4'),
('mcq', 7, 'أيّ مما يأتي يتكوّن من محاليل فوق مشبعة؟', null, '["الماء المقطر","محلول السكر المخفف في الشاي","محلول ملحي مخفف للغرغرة","سكر النبات (Rock Candy)"]'::jsonb, 'فهم', 'تطبيق حياتي', 'صعب', 'الكتاب ص 35 — تطبيقات المحاليل فوق المشبعة'),
('essay', 1, 'عرّف المحلول فوق المشبع، وبيّن الفرق بينه وبين المحلول المشبع من حيث الكمية المذابة والثبات.', null, null, 'تذكر', 'تعريف ومقارنة', 'سهل', 'الكتاب ص 34 — المحاليل فوق المشبعة'),
('essay', 2, 'ذائبية نترات الفضة AgNO₃ عند 20 °C هي 216 g/100 g H₂O. صنّف كل محلول مما يأتي (مشبع، غير مشبع، فوق مشبع) مع التعليل، علمًا بأن كل محلول صافٍ ويحتوي على 100 g من الماء عند 20 °C: (أ) 216 g من AgNO₃ ذائبة. (ب) 150 g من AgNO₃ ذائبة. (ج) 250 g من AgNO₃ ذائبة.', null, null, 'فهم', 'تصنيف وتعليل', 'متوسط', 'الكتاب ص 34 — المحاليل فوق المشبعة والجدول 1-4'),
('essay', 3, 'محلول صافٍ يحتوي على 120 g من السكروز ذائبة في 50 g من الماء عند 20 °C، وذائبية السكروز عند هذه الدرجة 203.9 g/100 g H₂O. (أ) احسب أقصى كتلة من السكروز يذيبها 50 g من الماء في المحلول المشبع عند 20 °C. (ب) هل المحلول فوق مشبع؟ علّل. (ج) احسب الكتلة الزائدة على حالة الإشباع.', null, null, 'تطبيق', 'حساب وتصنيف', 'صعب', 'الكتاب ص 34 — المحاليل فوق المشبعة والجدول 1-4')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C1-L3-O15') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'يحتوي المحلول فوق المشبع على كمية أكبر من المادة المذابة مقارنة بمحلول مشبع عند درجة الحرارة نفسها.', '["هذا تعريف المحلول المشبع لا فوق المشبع.","هذا وصف المحلول غير المشبع.","","المذاب الراسب غير ذائب، والمحلول فوقه مشبع فقط لا فوق مشبع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.395Z"}'::jsonb),
('mcq', 2, 0, 'المحاليل فوق المشبعة غير ثابتة؛ فعند إضافة نواة تبلور أو كشط الوعاء أو تحريك المحلول تترسب المادة المذابة الزائدة بسرعة.', '["","المحاليل فوق المشبعة غير ثابتة؛ فإضافة نواة تبلور أو الرج قد يرسّب الزيادة.","المحلول فوق المشبع صافٍ عادةً؛ والمذاب الزائد فيه ذائب لا راسب.","هي أكثر احتواءً للمذاب من المشبعة عند الدرجة نفسها لا أقل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.395Z"}'::jsonb),
('mcq', 3, 1, 'الكتلة الذائبة 250 g أكبر من ذائبية السكروز عند 20 °C (203.9 g)، والمحلول صافٍ أي أن كل المذاب ذائب، فهو يحتوي على كمية أكبر مما يحتويه المحلول المشبع عند الدرجة نفسها: فوق مشبع.', '["غير المشبع يحتوي على أقل من 203.9 g، والمحلول هنا يحتوي على أكثر منها.","","المشبع يحتوي على 203.9 g بالضبط في 100 g ماء عند 20 °C، والكمية هنا أكبر.","لا توجد بلورات في المحلول، وكل الـ 250 g ذائبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-10-17T11:36:22.396Z"}'::jsonb),
('mcq', 4, 2, 'في المحلول 2 ذاب 50.0 g من KCl، وهي أكبر من ذائبيته عند 60 °C (45.8 g)، فهو يحتوي على مذاب أكثر من المحلول المشبع عند الدرجة نفسها، أي فوق مشبع.', '["الكتلة الذائبة 30.0 g أقل من الذائبية 35.9 g، فالمحلول غير مشبع.","الكتلة الذائبة 200 g أقل من الذائبية 216 g، فالمحلول غير مشبع.","","الكتلة الذائبة تساوي الذائبية 34.2 g، فالمحلول مشبع لا فوق مشبع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.396Z"}'::jsonb),
('mcq', 5, 0, 'المحلول فوق المشبع يحتوي على كمية أكبر من المادة المذابة مقارنة بمحلول مشبع عند درجة الحرارة نفسها، وهذا ما يميزه.', '["","هذا وصف المحلول غير المشبع.","التعريف يقارن الكمية المذابة عند درجة الحرارة نفسها، لا الضغط.","وجود راسب يعني محلولًا مشبعًا على تماس مع المذاب، لا فوق مشبع."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.396Z"}'::jsonb),
('mcq', 6, 1, 'عند 20 °C يذيب المحلول المشبع 34.8 g فقط، والمحلول يحتوي على 35.5 g ذائبة، أي أكثر من المحلول المشبع عند الدرجة نفسها، فهو فوق مشبع.', '["المقارنة يجب أن تكون بالذائبية عند درجة حرارة المحلول (20 °C) لا عند 0 °C.","","المحلول المشبع يحتوي على الذائبية بالضبط عند درجته (34.8 g)، والقيمة هنا أكبر.","ذائبية Li₂SO₄ تقل بارتفاع الحرارة (من 36.1 إلى 34.8)، والتصنيف يعتمد على المقارنة عند 20 °C."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (34%)"}],"at":"2026-10-17T11:36:22.397Z"}'::jsonb),
('mcq', 7, 3, 'يتكون سكر النبات من محاليل سكر فوق مشبعة، كما تتكون الرواسب المعدنية على حواف الينابيع الحارة (كعيون الليث) من محاليل فوق مشبعة.', '["الماء المقطر مادة نقية وليس محلولًا أصلًا.","المحلول المخفف غير مشبع، ويمكن إذابة مزيد من السكر فيه.","المحلول المخفف غير مشبع ولا تتكون منه بلورات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.397Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المحلول فوق المشبع يحتوي على كمية من المادة المذابة أكبر مما يحتويه محلول مشبع عند درجة الحرارة نفسها. الفرق: الكمية المذابة فيه أكبر من الكمية في المشبع عند الدرجة نفسها، وهو غير ثابت تترسب منه الزيادة بسرعة عند إضافة نواة تبلور أو الرج، بينما المحلول المشبع ثابت تبقى فيه الكمية الذائبة ثابتة ما دامت درجة الحرارة ثابتة.', '["التعريف","الكمية المذابة أكبر","فوق المشبع غير ثابت والمشبع ثابت"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":2},{"element":"المقارنة في الكمية","marks":1},{"element":"المقارنة في الثبات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف صحيح ومقارنة صحيحة في الكمية والثبات"},{"level":"2–3 درجات","description":"تعريف صحيح مع مقارنة ناقصة"},{"level":"درجة واحدة","description":"وصف عام دون ذكر «عند درجة الحرارة نفسها»"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إغفال عبارة «عند درجة الحرارة نفسها»","وصف المحلول فوق المشبع بأنه يحتوي على راسب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T11:36:22.397Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) مشبع؛ لأن الكتلة الذائبة تساوي الذائبية (216 g). (ب) غير مشبع؛ لأن 150 g أقل من 216 g، ويمكن إذابة 66 g أخرى. (ج) فوق مشبع؛ لأن 250 g أكبر من 216 g، أي أكبر مما يحتويه المحلول المشبع عند الدرجة نفسها.', '["(أ) مشبع","(ب) غير مشبع","(ج) فوق مشبع","التعليل بالمقارنة بالذائبية"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) التصنيف والتعليل","marks":2},{"element":"(ب) التصنيف والتعليل","marks":2},{"element":"(ج) التصنيف والتعليل","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"تصنيفات صحيحة مع تعليل بالمقارنة بالذائبية"},{"level":"3–5 درجات","description":"تصنيفان صحيحان أو تصنيفات صحيحة دون تعليل كافٍ"},{"level":"1–2 درجة","description":"تصنيف واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تصنيف (ج) مشبعًا لأن المحلول صافٍ","تصنيف (أ) فوق مشبع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T11:36:22.397Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) 203.9 × (50/100) = 101.95 g ≈ 102.0 g. (ب) نعم، فوق مشبع؛ لأن الكتلة الذائبة 120 g أكبر مما يحتويه المحلول المشبع (102.0 g) عند الدرجة نفسها والكمية نفسها من الماء. (ج) الكتلة الزائدة = 120 − 101.95 ≈ 18.0 g.', '["الكتلة في المحلول المشبع 102.0 g","التصنيف فوق مشبع مع التعليل","الزيادة نحو 18.0 g"]'::jsonb, '["ذائبية 50 g ماء = 203.9 × 50/100 = 101.95 g","المقارنة: 120 g > 101.95 g ⇐ فوق مشبع","الزيادة = 120 − 101.95 = 18.05 g ≈ 18.0 g"]'::jsonb, '[{"element":"(أ) الحساب","marks":2},{"element":"(ب) الحكم والتعليل","marks":2},{"element":"(ج) الكتلة الزائدة","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"حسابات صحيحة بالوحدات وحكم معلل"},{"level":"3–5 درجات","description":"حكم صحيح مع خطأ في أحد الحسابات"},{"level":"1–2 درجة","description":"حكم دون حساب أو حساب جزئي"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["مقارنة 120 g بـ 203.9 g مباشرة دون مراعاة أن الماء 50 g فقط","الحكم بأن المحلول غير مشبع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-17T11:36:22.398Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K3-C1-L3-O15') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K3-C1-L3-O16'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما الطريقة التي ذكرها كتابك لتحضير محلول فوق مشبع؟', null, '["تحضير محلول مشبع عند درجة حرارة منخفضة ثم تسخينه بسرعة","إضافة نواة تبلور إلى محلول مشبع عند درجة حرارة ثابتة","تحضير محلول مشبع عند درجة حرارة عالية ثم تبريده بسرعة مع الرج","تحضير محلول مشبع عند درجة حرارة عالية ثم تبريده تدريجيًّا وببطء"]'::jsonb, 'تذكر', 'وصف إجراء', 'سهل', 'الكتاب ص 34–35 — تحضير المحاليل فوق المشبعة ونواة التبلور'),
('mcq', 2, 'ما دور التبريد البطيء في تحضير المحلول فوق المشبع؟', null, '["يزيد ذائبية المادة المذابة عند درجات الحرارة المنخفضة","يسمح للمادة المذابة الزائدة أن تبقى مذابة عند درجات الحرارة المنخفضة","يسرّع تبلور المادة الزائدة لتترسب في قاع الوعاء","يبخّر جزءًا من المذيب فيزداد تركيز المحلول"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 34–35 — تحضير المحاليل فوق المشبعة ونواة التبلور'),
('mcq', 3, 'ماذا يحدث عند إضافة نواة تبلور إلى محلول فوق مشبع؟', null, '["تذوب نواة التبلور ويزداد تركيز المحلول","لا يحدث أي تغير لأن المحلول ثابت","تترسب المادة المذابة الزائدة بسرعة","يترسب المذاب كله ويبقى الماء نقيًّا"]'::jsonb, 'فهم', 'تنبؤ', 'سهل', 'الكتاب ص 34–35 — تحضير المحاليل فوق المشبعة ونواة التبلور'),
('mcq', 4, 'أيّ الإجراءات الآتية يمكن أن يسبّب تبلور المادة الزائدة في محلول فوق مشبع دون إضافة نواة تبلور؟', null, '["ترك المحلول ساكنًا تمامًا في وعاء مغلق نظيف","كشط الجزء الداخلي من الوعاء الزجاجي بساق تحريك زجاجية بلطف","تسخين المحلول تسخينًا خفيفًا حتى يدفأ","إضافة كمية صغيرة من المذيب النقي إليه"]'::jsonb, 'فهم', 'استرجاع وتطبيق', 'متوسط', 'الكتاب ص 34–35 — تحضير المحاليل فوق المشبعة ونواة التبلور'),
('mcq', 5, 'في استمطار الغيوم يُنثر يوديد الفضة AgI في الهواء. ما دوره في هذه العملية؟', null, '["يتفاعل مع بخار الماء فينتج ماءً سائلًا جديدًا","يرفع درجة حرارة الهواء فيزيد ذائبية بخار الماء فيه","يذيب بخار الماء فيكوّن محلولًا غير مشبع في الهواء","يعمل نوى تكثّف في هواء فوق مشبع ببخار الماء فتتجمع جزيئات الماء حوله"]'::jsonb, 'فهم', 'تطبيق حياتي', 'متوسط', 'الكتاب ص 35 — استمطار الغيوم والرواسب المعدنية'),
('mcq', 6, 'حُضّر محلول مشبع من السكروز في 100 g من الماء عند 100 °C (الذائبية 487.2 g/100 g H₂O)، ثم بُرّد ببطء إلى 20 °C دون أن يتبلور (الذائبية 203.9 g/100 g H₂O). ما كتلة السكروز التي يُتوقع أن تتبلور عند إضافة نواة تبلور إليه عند 20 °C؟', null, '["487.2 g","203.9 g","283.3 g","691.1 g"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 34 — الجدول 1-4 والمحاليل فوق المشبعة'),
('mcq', 7, 'بعد إضافة نواة تبلور إلى محلول فوق مشبع وانتهاء التبلور عند درجة حرارة ثابتة، كيف يُصنَّف المحلول المتبقي فوق البلورات؟', null, '["مشبع؛ لأنه يحتوي على الكمية التي تساوي الذائبية عند تلك الدرجة","فوق مشبع؛ لأنه كان كذلك قبل إضافة نواة التبلور","غير مشبع؛ لأن جزءًا من المذاب خرج من المحلول","ماء نقي؛ لأن المذاب كله ترسب على نواة التبلور"]'::jsonb, 'تحليل', 'استنتاج', 'صعب', 'الكتاب ص 34–35 — تحضير المحاليل فوق المشبعة ونواة التبلور'),
('essay', 1, 'صف خطوات تحضير محلول فوق مشبع من السكروز في المختبر، وفسّر لماذا يجب أن يكون التبريد بطيئًا، ولماذا يجب تجنب رج الوعاء في أثناء ذلك.', null, null, 'فهم', 'وصف إجراء وتفسير', 'متوسط', 'الكتاب ص 34–35 — تحضير المحاليل فوق المشبعة ونواة التبلور'),
('essay', 2, 'ماذا يحدث إذا أُضيفت نواة تبلور إلى محلول فوق مشبع؟ فسّر ذلك، واذكر مثالين من الحياة تتكون فيهما بلورات من محاليل فوق مشبعة.', null, null, 'فهم', 'تنبؤ وتفسير', 'سهل', 'الكتاب ص 35 — استمطار الغيوم والرواسب المعدنية'),
('essay', 3, 'حُضّر محلول مشبع من KCl في 200 g من الماء عند 60 °C، ثم بُرّد ببطء إلى 20 °C دون ظهور بلورات. استعن بذائبية KCl: 45.8 g/100 g H₂O عند 60 °C، و34.2 g/100 g H₂O عند 20 °C. (أ) احسب كتلة KCl الذائبة في المحلول. (ب) ما نوع المحلول عند 20 °C قبل إضافة نواة تبلور؟ (ج) احسب كتلة KCl التي تتبلور عند إضافة نواة تبلور عند 20 °C، وما نوع المحلول بعدها؟', null, null, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 34 — الجدول 1-4 والمحاليل فوق المشبعة')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C1-L3-O16') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'لعمل محلول فوق مشبع يُحضَّر محلول مشبع عند درجة حرارة عالية، ثم يُبرَّد تدريجيًّا وببطء؛ إذ يسمح التبريد البطيء للمادة المذابة الزائدة أن تبقى مذابة في المحلول عند درجات حرارة منخفضة.', '["تسخين المحلول المشبع يزيد ذائبية معظم المواد الصلبة فيجعله غير مشبع لا فوق مشبع.","نواة التبلور تسبب ترسيب المذاب الزائد، فهي تُنهي حالة فوق الإشباع لا تكوّنها.","التبريد السريع والرج يسببان تبلور المادة الزائدة، فلا يتكون محلول فوق مشبع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.398Z"}'::jsonb),
('mcq', 2, 1, 'التبريد التدريجي البطيء يسمح للمادة المذابة الزائدة أن تبقى مذابة في المحلول عند درجات حرارة منخفضة رغم أن ذائبيتها عندها أقل، فيتكون محلول فوق مشبع.', '["التبريد لا يزيد الذائبية؛ فذائبية معظم المواد الصلبة تقل بانخفاض الحرارة.","","لو تبلورت الزيادة لنتج محلول مشبع لا فوق مشبع.","التبريد لا يهدف إلى تبخير المذيب، بل إلى إبقاء الزيادة ذائبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.398Z"}'::jsonb),
('mcq', 3, 2, 'المحاليل فوق المشبعة غير ثابتة؛ فعند إضافة قطعة صغيرة جدًّا من المذاب تسمى نواة التبلور تترسب المادة المذابة الزائدة بسرعة.', '["المحلول فوق المشبع لا يذيب مزيدًا؛ بل تعمل النواة سطحًا تتبلور عليه الزيادة.","المحاليل فوق المشبعة غير ثابتة، فتتغير بإضافة نواة التبلور.","","تترسب الكمية الزائدة فقط، ويبقى في المحلول ما يعادل الذائبية عند تلك الدرجة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-17T11:36:22.398Z"}'::jsonb),
('mcq', 4, 1, 'يمكن أن يحدث التبلور عند كشط الجزء الداخلي من الكأس أو الوعاء الزجاجي المحتوي على المحلول بساق تحريك زجاجية بلطف، أو تعريض المحلول فوق المشبع للحركة أو الرج.', '["السكون يحافظ على حالة فوق الإشباع، أما الحركة والرج فتسبب التبلور.","","التسخين يزيد ذائبية المذاب الصلب فيقلل احتمال التبلور.","إضافة المذيب تخفف المحلول فيقل احتمال التبلور."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-17T11:36:22.399Z"}'::jsonb),
('mcq', 5, 3, 'باستعمال يوديد الفضة AgI بوصفه نوى تكثّف في الهواء فوق المشبع ببخار الماء، تتجمع جزيئات الماء في صورة قطيرات قد تسقط على هيئة مطر، كما تعمل نواة التبلور في المحلول فوق المشبع.', '["AgI لا ينتج الماء؛ بل يوفر سطحًا تتجمع عليه جزيئات الماء الموجودة.","الهدف تجميع بخار الماء الزائد في قطيرات، لا زيادة ما يحمله الهواء منه.","AgI لا يذيب بخار الماء، والمطلوب إنهاء حالة فوق الإشباع لا تكوين محلول غير مشبع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-17T11:36:22.399Z"}'::jsonb),
('mcq', 6, 2, 'عند إضافة نواة التبلور تترسب المادة الزائدة على حالة الإشباع عند 20 °C: 487.2 − 203.9 = 283.3 g، ويبقى 203.9 g ذائبًا في محلول مشبع.', '["هذه كتلة السكروز الذائبة كلها؛ لكن الذي يترسب هو الزيادة فقط، ويبقى 203.9 g ذائبًا.","هذه الكتلة التي تبقى ذائبة عند 20 °C، لا الكتلة المترسبة.","","جُمعت الذائبيتان بدل طرحهما؛ ولا يمكن أن يترسب أكثر مما ذاب أصلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-17T11:36:22.399Z"}'::jsonb),
('mcq', 7, 0, 'تترسب المادة الزائدة فقط حتى تصبح الكمية الذائبة مساوية للذائبية عند تلك الدرجة، فيصبح المحلول مشبعًا وفي حالة اتزان ديناميكي مع البلورات المترسبة.', '["","الزيادة ترسبت بإضافة النواة، فلم يعد المحلول يحتوي على أكثر من الذائبية.","لا يترسب إلا ما زاد على الذائبية، فيبقى المحلول محتويًا على أقصى ما يذوب.","لا يترسب المذاب كله؛ يبقى منه ما يعادل الذائبية عند تلك الدرجة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-17T11:36:22.399Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الخطوات: (1) يُسخّن الماء إلى درجة حرارة عالية ويُذاب فيه السكروز حتى يصبح المحلول مشبعًا عند تلك الدرجة (ذائبية السكروز تزداد كثيرًا بارتفاع الحرارة). (2) يُترك المحلول ليبرد تدريجيًّا وببطء في وعاء نظيف دون إزعاج. التفسير: التبريد البطيء يسمح للمادة المذابة الزائدة أن تبقى مذابة عند درجات الحرارة المنخفضة رغم أن ذائبيتها عندها أقل، فيتكون محلول يحتوي على مذاب أكثر من المحلول المشبع عند الدرجة نفسها. ويجب تجنب الرج أو الحركة أو كشط الوعاء؛ لأن المحلول فوق المشبع غير ثابت، وهذه الإجراءات قد تسبب تبلور المادة الزائدة.', '["تحضير محلول مشبع عند درجة حرارة عالية","التبريد التدريجي البطيء","التبريد البطيء يبقي الزيادة مذابة","الرج أو الحركة يسبب التبلور لعدم ثبات المحلول"]'::jsonb, '[]'::jsonb, '[{"element":"تحضير محلول مشبع ساخن","marks":1.5},{"element":"التبريد البطيء","marks":1},{"element":"تفسير دور التبريد البطيء","marks":1.5},{"element":"تفسير تجنب الرج","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"خطوات صحيحة كاملة مع تفسير دور التبريد البطيء وتجنب الرج"},{"level":"3–5 درجات","description":"خطوات صحيحة مع تفسير ناقص"},{"level":"1–2 درجة","description":"ذكر خطوة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["البدء بمحلول غير مشبع","التبريد السريع في حمام ثلج","إضافة نواة تبلور لتكوين المحلول فوق المشبع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.399Z"}'::jsonb),
('essay', 2, null::int, null, null, 'تترسب (تتبلور) المادة المذابة الزائدة بسرعة؛ لأن المحلول فوق المشبع غير ثابت، ونواة التبلور (قطعة صغيرة جدًّا من المذاب) توفر سطحًا تلتصق به جسيمات المذاب الزائدة فتتكون بلورات أكبر، ويبقى محلول مشبع. مثالان: سكر النبات (Rock Candy)، والرواسب المعدنية على حواف الينابيع الحارة مثل عيون الليث في المملكة العربية السعودية (ويُقبل استمطار الغيوم بيوديد الفضة).', '["ترسب الزيادة بسرعة","المحلول غير ثابت والنواة سطح للتبلور","مثالان صحيحان"]'::jsonb, '[]'::jsonb, '[{"element":"ما يحدث","marks":1},{"element":"التفسير","marks":1},{"element":"المثالان (لكل منهما 1)","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"وصف وتفسير صحيحان ومثالان صحيحان"},{"level":"2–3 درجات","description":"وصف صحيح مع تفسير أو مثال واحد"},{"level":"درجة واحدة","description":"وصف ما يحدث فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن نواة التبلور تذوب في المحلول","القول إن المذاب كله يترسب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.400Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الكتلة الذائبة = 45.8 × (200/100) = 91.6 g. (ب) فوق مشبع؛ لأن 200 g ماء عند 20 °C تذيب في الحالة المشبعة 34.2 × 2 = 68.4 g فقط، والذائب 91.6 g. (ج) الكتلة المتبلورة = 91.6 − 68.4 = 23.2 g، ويصبح المحلول مشبعًا عند 20 °C.', '["91.6 g ذائبة","فوق مشبع مع التعليل","تتبلور 23.2 g","المحلول بعدها مشبع"]'::jsonb, '["الذائب عند 60 °C = 45.8 × 2 = 91.6 g","سعة الإشباع عند 20 °C = 34.2 × 2 = 68.4 g","91.6 > 68.4 ⇐ فوق مشبع","المتبلور = 91.6 − 68.4 = 23.2 g"]'::jsonb, '[{"element":"(أ) الحساب","marks":1.5},{"element":"(ب) الحكم مع التعليل","marks":1.5},{"element":"(ج) الكتلة المتبلورة","marks":2},{"element":"(ج) نوع المحلول بعدها","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"حسابات صحيحة بالوحدات وتصنيفان صحيحان"},{"level":"3–5 درجات","description":"معظم الحسابات صحيحة مع خطأ واحد"},{"level":"1–2 درجة","description":"حساب (أ) فقط أو تصنيف دون حساب"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["إهمال أن كمية الماء 200 g لا 100 g","طرح 34.2 من 45.8 فقط والحصول على 11.6 g","عدّ المحلول بعد التبلور غير مشبع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-17T11:36:22.400Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
