('mcq', 2, 0, 'التغير في الذائبية بين 0 °C و100 °C: Al₂(SO₄)₃ من 31.2 إلى 89.0 (زيادة 57.8 g)، وKCl زيادة 28.3 g، وNaCl زيادة 3.5 g، وCa(OH)₂ نقصان 0.113 g؛ فأكبر تغير لـ Al₂(SO₄)₃.', '["","ذائبية NaCl تزداد بمقدار 3.5 g فقط (من 35.7 إلى 39.2)، فهي الأقل تأثرًا تقريبًا.","ذائبية KCl تزداد بمقدار 28.3 g، وهي زيادة أقل من زيادة Al₂(SO₄)₃.","ذائبية Ca(OH)₂ تقل بمقدار 0.113 g فقط، فتأثرها صغير جدًّا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-10-17T11:36:22.401Z"}'::jsonb),
('mcq', 3, 3, 'تنخفض ذائبية Ca(OH)₂ من 0.189 عند 0 °C إلى 0.076 عند 100 °C، فهي من المواد القليلة التي تقل ذائبيتها بزيادة درجة الحرارة (مثل كبريتات السيريوم).', '["ذائبية KCl تزداد من 28.0 إلى 56.3 بارتفاع الحرارة.","ذائبية NaCl تزداد قليلًا من 35.7 إلى 39.2، فلا تقل.","ذائبية AgNO₃ تزداد كثيرًا من 122 إلى 733.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-10-17T11:36:22.401Z"}'::jsonb),
('mcq', 4, 0, 'مقدار الزيادة = 487.2 − 203.9 = 283.3 g، والنسبة = (283.3 / 203.9) × 100 ≈ 139% أي نحو 140%.', '["","قُسمت الذائبية الجديدة على القديمة (487.2/203.9 ≈ 2.39) بدل قسمة مقدار الزيادة على القيمة الأصلية.","قُسم مقدار الزيادة على الذائبية النهائية 487.2 بدل الذائبية الأصلية 203.9.","أُخذ مقدار الزيادة بالغرامات (283.3 g) على أنه نسبة مئوية دون قسمته على القيمة الأصلية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.402Z"}'::jsonb),
('mcq', 5, 2, 'عند 20 °C: NaCl (35.9) > KCl (34.2)، وعند 60 °C: KCl (45.8) > NaCl (37.1)؛ فمنحنيا الذائبية يتقاطعان بين 20 °C و60 °C.', '["عند 0 °C و20 °C ذائبية NaCl أكبر من KCl (35.7 > 28.0 و35.9 > 34.2)، فلم يتقاطعا بعد.","عند 60 °C كانت ذائبية KCl قد تجاوزت NaCl بالفعل (45.8 > 37.1)، فالتقاطع قبل ذلك.","","عند 0 °C و20 °C ذائبية KCl أقل من NaCl، فلا تتجاوزها عند جميع الدرجات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-17T11:36:22.402Z"}'::jsonb),
('mcq', 6, 3, 'الكتلة القصوى = 56.3 × (250/100) = 140.75 g ≈ 141 g (ثلاثة أرقام معنوية).', '["هذه الكتلة القصوى لـ 100 g من الماء فقط؛ لم تُضرب في 2.5.","قُسمت الذائبية على 2.5 بدل الضرب فيه.","استُعملت ذائبية KCl عند 20 °C (34.2 g) بدل قيمتها عند 100 °C.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T11:36:22.402Z"}'::jsonb),
('mcq', 7, 1, 'المتبلور = الذائبية عند 100 °C − الذائبية عند 0 °C: لـ KCl: 56.3 − 28.0 = 28.3 g، ولـ NaCl: 39.2 − 35.7 = 3.5 g؛ فـ KCl تتبلور منه كتلة أكبر لأن ذائبيته أكثر تأثرًا بالحرارة.', '["أُخذت ذائبية NaCl عند 0 °C (الكمية الباقية ذائبة) على أنها المتبلورة.","","أُخذت الذائبية عند 100 °C كلها؛ لكن يبقى 28.0 g ذائبًا عند 0 °C.","الحساب صحيح لـ NaCl، لكن KCl تتبلور منه كتلة أكبر بكثير (28.3 g)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T11:36:22.402Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) ذائبية Al₂(SO₄)₃ تزداد بارتفاع الحرارة، وKCl تزداد أيضًا، أما Li₂SO₄ فتقل قليلًا. (ب) Al₂(SO₄)₃: 59.2 − 31.2 = +28.0 g؛ KCl: 45.8 − 28.0 = +17.8 g؛ Li₂SO₄: 32.6 − 36.1 = −3.5 g. (ج) Al₂(SO₄)₃ أكثرها تأثرًا (أكبر تغير). (د) منحنى Li₂SO₄ ينحدر قليلًا إلى أسفل (شبه أفقي)، بينما منحنى Al₂(SO₄)₃ يرتفع بشدة إلى أعلى.', '["اتجاهات صحيحة للمواد الثلاث","حساب التغيرات الثلاثة","Al₂(SO₄)₃ الأكثر تأثرًا","وصف شكل المنحنيين"]'::jsonb, '["Al₂(SO₄)₃: 59.2 − 31.2 = 28.0 g","KCl: 45.8 − 28.0 = 17.8 g","Li₂SO₄: 32.6 − 36.1 = −3.5 g","المقارنة: 28.0 > 17.8 > |−3.5|"]'::jsonb, '[{"element":"(أ) الاتجاهات","marks":1.5},{"element":"(ب) الحسابات","marks":1.5},{"element":"(ج) الاستنتاج","marks":1},{"element":"(د) وصف المنحنيين","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"اتجاهات وحسابات صحيحة واستنتاج ووصف دقيق للمنحنيين"},{"level":"3–5 درجات","description":"معظم الأجزاء صحيحة مع خطأ في جزء"},{"level":"1–2 درجة","description":"وصف اتجاهات فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ Li₂SO₄ تزداد ذائبيتها","مقارنة قيم عند درجات حرارة مختلفة دون حساب التغير","استعمال 100 °C لـ Li₂SO₄ مع عدم وجود قيمة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.403Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) 50 g ماء تذيب عند 20 °C: 216 × 50/100 = 108 g، والذائب 80 g فقط، فالمحلول غير مشبع، ويمكن إذابة 108 − 80 = 28 g أخرى. (ب) عند 0 °C تذيب 50 g ماء: 122 × 50/100 = 61 g، فتتبلور 80 − 61 = 19 g.', '["سعة 50 g ماء عند 20 °C = 108 g","غير مشبع ويمكن إذابة 28 g","سعة 50 g ماء عند 0 °C = 61 g","يتبلور 19 g"]'::jsonb, '["216 × 50/100 = 108 g","108 − 80 = 28 g","122 × 50/100 = 61 g","80 − 61 = 19 g"]'::jsonb, '[{"element":"(أ) حساب السعة والحكم","marks":1.5},{"element":"(أ) الكتلة الإضافية","marks":1},{"element":"(ب) حساب السعة عند 0 °C","marks":1},{"element":"(ب) الكتلة المتبلورة","marks":1.5}]'::jsonb, '[{"level":"5 درجات","description":"جميع الحسابات والأحكام صحيحة بالوحدات"},{"level":"3–4 درجات","description":"الجزء (أ) صحيح مع خطأ في (ب) أو العكس"},{"level":"1–2 درجة","description":"خطوة تناسب صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال الذائبية لـ 100 g ماء مباشرة","طرح 80 من 216 والحصول على 136 g","الحكم بأن المحلول فوق مشبع"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.403Z"}'::jsonb),
('essay', 3, null::int, null, null, 'NaCl: 35.9 g/100 g H₂O عند 20 °C و39.2 g/100 g H₂O عند 100 °C، فذائبيته تزداد قليلًا بارتفاع الحرارة. Ca(OH)₂: 0.173 g/100 g H₂O عند 20 °C و0.076 g/100 g H₂O عند 100 °C، فذائبيته تقل بارتفاع الحرارة.', '["قيم NaCl بالوحدة","NaCl تزداد قليلًا","قيم Ca(OH)₂ بالوحدة","Ca(OH)₂ تقل"]'::jsonb, '[]'::jsonb, '[{"element":"قيم NaCl","marks":1},{"element":"أثر الحرارة في NaCl","marks":1},{"element":"قيم Ca(OH)₂","marks":1},{"element":"أثر الحرارة في Ca(OH)₂","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"قيم صحيحة بالوحدة ووصف صحيح للأثرين"},{"level":"2–3 درجات","description":"قيم صحيحة مع وصف أثر واحد"},{"level":"درجة واحدة","description":"قيم مادة واحدة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعميم أن ذائبية كل المواد تزداد بالحرارة","إغفال الوحدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.404Z"}'::jsonb)
