('mcq', 1, 0, 'تقل ذائبية غازي الأكسجين وثاني أكسيد الكربون عند درجات الحرارة المرتفعة مقارنة بالمنخفضة، وهذا سلوك متوقع لجميع الغازات المذابة في المذيبات السائلة.', '["","هذا سلوك معظم المواد الصلبة، أما الغازات فتقل ذائبيتها بارتفاع الحرارة.","الذائبية تتغير بتغير درجة الحرارة في الغازات.","لا يوجد هذا السلوك؛ فالذائبية تقل بارتفاع الحرارة بصورة مستمرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.405Z"}'::jsonb),
('mcq', 2, 1, 'الطاقة الحركية لجسيمات الغاز تسمح لها بالتحرر أو النفاذ من المحلول بسهولة أكبر عند درجات الحرارة المرتفعة؛ ولذلك كلما زادت درجة حرارة المحلول قلت ذائبية المذاب الغازي.', '["ارتفاع الحرارة لا يغير قطبية جسيمات الغاز.","","التفسير يعتمد على الطاقة الحركية لا على تغير الضغط.","ارتفاع الحرارة يزيد الطاقة الحركية ولا يقللها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (58%)"}],"at":"2026-10-17T11:36:22.405Z"}'::jsonb),
('mcq', 3, 2, 'ذوبان الغازات يقل بزيادة درجة الحرارة؛ لذا تفقد المشروبات الغازية طعمها اللاذع أسرع عند درجة حرارة الغرفة مما لو كانت باردة، إذ تتحرر جسيمات CO₂ ذات الطاقة الحركية الأكبر من المحلول.', '["ارتفاع الحرارة يقلل ذائبية الغاز ولا يزيدها.","زيادة الضغط تزيد الذائبية، لكن التفسير هنا بنقصان الذائبية بالحرارة.","","انخفاض الحرارة يزيد الذائبية فيبقى الغاز مذابًا أكثر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.406Z"}'::jsonb),
('mcq', 4, 3, 'تنخفض ذائبية CO₂ من 1.713 عند 0 °C إلى 0.878 عند 20 °C ثم 0.359 عند 60 °C، وهذا مثال على نقصان ذائبية الغازات بارتفاع الحرارة.', '["القيم تتناقص من 1.713 إلى 0.359 بارتفاع الحرارة.","القيم تتغير بوضوح؛ فالتأثر كبير.","القيم لا تتضاعف بل تتناقص.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.406Z"}'::jsonb),
('mcq', 5, 0, 'النقصان = 1.713 − 0.359 = 1.354، والنسبة = (1.354 / 1.713) × 100 ≈ 79%.', '["","هذه النسبة المتبقية من الذائبية (0.359/1.713) لا نسبة النقصان.","هذا مقدار النقصان بالوحدة (1.354) وليس نسبة مئوية.","قُسمت الذائبية الأكبر على الأصغر (1.713/0.359 ≈ 4.8) مع خلط بالنسبة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.407Z"}'::jsonb),
('mcq', 6, 1, 'نسب النقصان: NH₃ = (1130−200)/1130 ≈ 82%، CO₂ ≈ 79%، O₂ = (0.048−0.019)/0.048 ≈ 60%، فالأكبر لـ NH₃.', '["نسبة نقصان CO₂ نحو 79%، وهي أقل من NH₃ (نحو 82%).","","نسبة نقصان O₂ نحو 60%، وهي الأقل بين الثلاثة.","النسب مختلفة: 79% و60% و82% تقريبًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.407Z"}'::jsonb),
('mcq', 7, 0, 'ذائبية O₂ تقل بارتفاع الحرارة (من 0.048 إلى 0.019 L/L بين 0 و60 °C) لأن الطاقة الحركية الأكبر لجسيماته تحررها من الماء، فيقل الأكسجين المذاب.', '["","ذائبية الأكسجين تقل بارتفاع الحرارة.","قطبية الأكسجين لا تتغير بالحرارة والتفسير بالذائبية.","الضغط الجوي لا يتغير بهذه الصورة، والسبب نقصان الذائبية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.407Z"}'::jsonb),
('essay', 1, null::int, null, null, 'عند ارتفاع الحرارة تزداد الطاقة الحركية لجسيمات الغاز المذاب، فتتحرر أو تنفذ من المحلول بسهولة أكبر، فتقل كمية الغاز الذائبة. ولذلك كلما زادت درجة حرارة المحلول قلت ذائبية المذاب الغازي، وهذا سلوك لجميع الغازات في المذيبات السائلة.', '["ارتفاع الحرارة يزيد الطاقة الحركية","جسيمات الغاز تتحرر من المحلول بسهولة","تقل الذائبية"]'::jsonb, '[]'::jsonb, '[{"element":"زيادة الطاقة الحركية","marks":1.5},{"element":"التحرر من المحلول","marks":1.5},{"element":"نقصان الذائبية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل"},{"level":"2–3 درجات","description":"تفسير ناقص"},{"level":"درجة واحدة","description":"ذكر النقصان دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الغاز يتفاعل مع الماء بالتسخين","التفسير بتغير الضغط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (58%)"}],"at":"2026-10-17T11:36:22.407Z"}'::jsonb),
('essay', 2, null::int, null, null, 'ذائبية السكروز (صلب) تزداد من 179.2 إلى 287.3 (زيادة 108.1 g/100 g H₂O)، بينما ذائبية CO₂ (غاز) تقل من 1.713 إلى 0.359 (نقصان 1.354 L/L). التفسير: في المذاب الصلب تزيد حرارة المذيب طاقة حركة جسيماته وتصادماتها فتزداد الذائبية، أما في الغاز فتزداد الطاقة الحركية لجسيمات الغاز نفسها فتتحرر من المحلول بسهولة أكبر فتقل الذائبية.', '["السكروز تزداد","CO₂ تقل","حساب التغيرين","تفسير الفرق بالطاقة الحركية"]'::jsonb, '["السكروز: 287.3 − 179.2 = 108.1","CO₂: 1.713 − 0.359 = 1.354"]'::jsonb, '[{"element":"وصف الاتجاهين","marks":1.5},{"element":"حساب التغيرين","marks":1},{"element":"تفسير الفرق","marks":1.5}]'::jsonb, '[{"level":"4 درجات","description":"كل الأجزاء صحيحة"},{"level":"2–3 درجات","description":"اتجاهان صحيحان مع تفسير ناقص"},{"level":"درجة واحدة","description":"اتجاه واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعميم زيادة الذائبية على الغازات","خطأ في الطرح"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.409Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تحفظ في الثلاجة؛ لأن ذائبية الغازات تقل بارتفاع الحرارة (CO₂: 1.713 L/L عند 0 °C مقابل 0.878 عند 20 °C، أي نحو الضعف تقريبًا)، فعند البرودة تقل الطاقة الحركية لجسيمات الغاز فيصعب تحررها ويبقى الغاز مذابًا، أما في المكان الدافئ فتتحرر جسيمات CO₂ بسهولة أكبر ويفقد المشروب طعمه اللاذع.', '["الثلاجة","الذائبية تقل بارتفاع الحرارة مع الأرقام","الطاقة الحركية الأقل تبقي الغاز مذابًا"]'::jsonb, '[]'::jsonb, '[{"element":"القرار","marks":1},{"element":"الاستدلال بالبيانات","marks":1},{"element":"التفسير بالطاقة الحركية","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"قرار صحيح مع بيانات وتفسير"},{"level":"2 درجتان","description":"قرار صحيح مع تفسير أو بيانات"},{"level":"درجة واحدة","description":"قرار صحيح دون تعليل"},{"level":"صفر","description":"قرار خاطئ أو لا إجابة"}]'::jsonb, '["اختيار المكان الدافئ بناء على ذائبية المواد الصلبة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-17T11:36:22.409Z"}'::jsonb)
