('mcq', 1, 1, 'الخواص الجامعة هي الخواص الفيزيائية للمحاليل التي تتأثر بعدد جسيمات المذاب وليس بطبيعتها، فالبديل الصحيح هو «الخواص الفيزيائية للمحاليل التي تتأثر بعدد جسيمات المذاب وليس بطبيعتها».', '["الخواص الجامعة خواص فيزيائية، ولا تعتمد على نوع المذاب بل على عدد جسيماته.","","الخواص الجامعة خواص للمحلول تتغير بإضافة المذاب، لا خواص ثابتة للمذيب النقي.","هذا عكس التعريف؛ فالخواص الجامعة لا تعتمد على طبيعة المذاب بل على عدد جسيماته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.411Z"}'::jsonb),
('mcq', 2, 3, 'الفكرة الرئيسة للدرس: «تعتمد الخواص الجامعة على عدد جسيمات المذاب في المحلول»، فالإجابة «عدد جسيمات المذاب في المحلول».', '["الخواص الجامعة لا تتأثر بطبيعة المذاب؛ فالمذابات المختلفة بعدد الجسيمات نفسه تحدث الأثر نفسه.","الكتلة المولية صفة لنوع المذاب، والخواص الجامعة تعتمد على عدد الجسيمات لا على كتلتها.","حجم الجزيء وشكله من طبيعة المذاب، والخواص الجامعة لا تعتمد على طبيعته.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T11:36:22.411Z"}'::jsonb),
('mcq', 3, 0, 'الخاصية الجامعة تعتمد فقط على كمية (عدد) جسيمات المذاب في المحلول لا على طبيعة المادة المذابة، لذلك فإن ما يميزها أنها تتغير بتغير عدد جسيمات المذاب مهما كان نوعها.', '["","تغير الخاصية بتغير نوع المذاب مع ثبات عدد الجسيمات ينفي كونها خاصية جامعة.","الخاصية الجامعة تختلف قيمتها في المحلول عنها في المذيب النقي بسبب جسيمات المذاب.","الخواص الجامعة خواص فيزيائية، ولا تشترط حدوث تفاعل كيميائي بين المذاب والمذيب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.411Z"}'::jsonb),
('mcq', 4, 2, 'الجلوكوز والسكروز مادتان غير متأينتين، فالمحلولان المتساويان في المولالية يحويان العدد نفسه من جسيمات المذاب، ولأن الخواص الجامعة تعتمد على عدد الجسيمات لا على نوعها فإن لهما الانخفاض نفسه في درجة التجمد.', '["حجم الجزيء من طبيعة المذاب، والمحلولان غير المتأينين بالمولالية نفسها يحويان عدد الجسيمات نفسه فيرتفع غليانهما بالمقدار نفسه.","العكس هو الصحيح؛ فالانخفاض في درجة التجمد يعتمد على عدد مولات جسيمات المذاب لا على كتلتها المولية.","","المذاب غير المتطاير كالسكروز يخفض الضغط البخاري للمذيب ولا يرفعه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.411Z"}'::jsonb),
('mcq', 5, 0, 'الانخفاض في الضغط البخاري يعتمد على عدد جسيمات المذاب في المحلول، ولذلك فهو من الخواص الجامعة.', '["","الانخفاض في الضغط البخاري يحدث عند إضافة مذاب إلى المذيب، لا في المذيب النقي.","لو اعتمد على طبيعة المذاب لما كان خاصية جامعة.","العلاقة عكسية؛ فكلما ازداد عدد جسيمات المذاب قل الضغط البخاري أي ازداد الانخفاض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T11:36:22.411Z"}'::jsonb),
('mcq', 6, 3, 'المحاليل الثلاثة متساوية في المولالية ومذاباتها غير متأينة، أي تحوي العدد نفسه من الجسيمات، وقد تساوت درجات تجمدها رغم اختلاف نوع المذاب؛ وهذا يدعم أن الانخفاض في درجة التجمد يعتمد على عدد جسيمات المذاب لا على نوعها.', '["الكتل المولية للمذابات الثلاثة مختلفة ومع ذلك تساوت درجات التجمد، فالكتلة المولية لا تحدد الأثر.","درجات التجمد في الجدول أقل من 0.0 °C (درجة تجمد الماء النقي)، فقد تأثرت بإذابة المواد.","السكروز أكبر جزيئًا من الجلوكوز والجليسرول ومع ذلك أحدث الانخفاض نفسه.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-17T11:36:22.411Z"}'::jsonb),
('mcq', 7, 1, 'هذا هو تعريف الخواص الجامعة: الخواص الفيزيائية للمحاليل التي تتأثر بعدد جسيمات المذاب وليس بطبيعتها؛ فالإجابة «الخواص الجامعة».', '["الخواص المقصودة فيزيائية وليست كيميائية.","","الذوبانية تعتمد على طبيعة المذاب والمذيب، وليست هي المقصودة بالتعريف.","الخواص المميزة للمذاب تعتمد على طبيعته، بينما المقصود خواص لا تعتمد على طبيعته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T11:36:22.412Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الخواص الجامعة هي الخواص الفيزيائية للمحاليل التي تتأثر بعدد جسيمات المذاب وليس بطبيعتها. الجلوكوز والسكروز مادتان غير متأينتين، فلا تتفكك جزيئاتهما في الماء؛ ولأن المحلولين متساويان في المولالية فإن كلًّا منهما يحوي العدد نفسه من جسيمات المذاب في الكتلة نفسها من الماء، فيكون لهما الانخفاض نفسه في درجة التجمد رغم اختلاف نوع المذاب وحجم جزيئه.', '["تعريف الخواص الجامعة بأنها خواص فيزيائية للمحاليل","ربطها بعدد جسيمات المذاب لا بطبيعته","المذابان غير متأينين فلا تتفكك جزيئاتهما","تساوي المولالية يعني تساوي عدد الجسيمات فيتساوى الانخفاض"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف الخواص الجامعة بأنها خواص فيزيائية للمحاليل","marks":1},{"element":"تتأثر بعدد جسيمات المذاب لا بطبيعته","marks":1},{"element":"بيان أن المذابين غير متأينين","marks":1},{"element":"استنتاج تساوي عدد الجسيمات ومن ثم تساوي الانخفاض","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريف كامل وتفسير صحيح يربط تساوي المولالية وعدم التأين بتساوي عدد الجسيمات"},{"level":"3 درجات","description":"تعريف كامل مع تفسير ينقصه ذكر عدم التأين أو تساوي عدد الجسيمات"},{"level":"درجتان","description":"تعريف صحيح دون تفسير مقبول، أو تفسير صحيح مع تعريف ناقص"},{"level":"درجة واحدة","description":"ذكر أن الخواص الجامعة تعتمد على المذاب دون تحديد عدد الجسيمات"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["القول إن الخواص الجامعة تعتمد على نوع المذاب","عدّ السكروز أكبر أثرًا لأن جزيئه أكبر","إغفال أن المذابين غير متأينين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.412Z"}'::jsonb),
('essay', 2, null::int, null, null, 'عبارة الطالب غير صحيحة. الارتفاع في درجة الغليان خاصية جامعة، والخواص الجامعة تعتمد على عدد جسيمات المذاب لا على طبيعتها (حجمها أو نوعها). السكروز والجلوكوز كلاهما غير متأين، فالمحلولان المتساويان في المولالية يحويان العدد نفسه من جسيمات المذاب في كل 1 kg من الماء، لذلك يكون الارتفاع في درجة غليانهما متساويًا (مثلًا 0.512 °C لكل منهما عند 1 m).', '["الحكم بأن العبارة خاطئة","الارتفاع في درجة الغليان خاصية جامعة تعتمد على عدد الجسيمات","المذابان غير متأينين وبالمولالية نفسها فلهما العدد نفسه من الجسيمات","النتيجة: الارتفاع متساوٍ"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم الصحيح على العبارة","marks":1},{"element":"ذكر أن الخاصية جامعة تعتمد على عدد الجسيمات لا على طبيعتها أو حجمها","marks":1},{"element":"تساوي عدد الجسيمات لتساوي المولالية وعدم التأين ومن ثم تساوي الارتفاع","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"حكم صحيح مع تبرير كامل يستند إلى عدد الجسيمات وعدم التأين"},{"level":"درجتان","description":"حكم صحيح مع تبرير ناقص"},{"level":"درجة واحدة","description":"حكم صحيح دون تبرير، أو تبرير صحيح دون حكم واضح"},{"level":"صفر","description":"تأييد عبارة الطالب أو إجابة متروكة"}]'::jsonb, '["تأييد الطالب بحجة أن الجزيء الأكبر يشغل حيزًا أكبر","الخلط بين الكتلة المولية وعدد المولات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.412Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) خاصية جامعة؛ لأن مقدار الارتفاع في درجة الغليان يعتمد على عدد جسيمات المذاب. (ب) ليست خاصية جامعة؛ لأن اللون يعتمد على نوع المذاب (طبيعته). (ج) خاصية جامعة؛ لأن الضغط الأسموزي يعتمد على عدد جسيمات المذاب في كمية محددة من المحلول. (د) ليست خاصية جامعة؛ لأن التوصيل يعتمد على طبيعة المذاب، أي كونه مادة متأينة تنتج أيونات أو مادة غير متأينة.', '["(أ) جامعة مع التعليل","(ب) غير جامعة مع التعليل","(ج) جامعة مع التعليل","(د) غير جامعة مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف (أ) وتعليله","marks":1},{"element":"تصنيف (ب) وتعليله","marks":1},{"element":"تصنيف (ج) وتعليله","marks":1},{"element":"تصنيف (د) وتعليله","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف الأربع صحيحًا مع تعليل يستند إلى عدد الجسيمات أو طبيعة المذاب"},{"level":"3 درجات","description":"ثلاثة تصنيفات صحيحة معللة"},{"level":"درجتان","description":"تصنيفان صحيحان معللان، أو أربعة تصنيفات صحيحة بلا تعليل"},{"level":"درجة واحدة","description":"تصنيف واحد صحيح معلل"},{"level":"صفر","description":"لا تصنيف صحيحًا"}]'::jsonb, '["عدّ التوصيل الكهربائي خاصية جامعة لأنه يرتبط بعدد الأيونات","تصنيف دون تعليل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.412Z"}'::jsonb)
