('mcq', 2, 'أيّ المجموعات الآتية تضم الخواص الجامعة الأربع للمحاليل؟', null, '["الانخفاض في الضغط البخاري، والارتفاع في درجة الغليان، والانخفاض في درجة التجمد، والضغط الأسموزي","الارتفاع في الضغط البخاري، والارتفاع في درجة الغليان، والارتفاع في درجة التجمد، والضغط الأسموزي","الانخفاض في الضغط البخاري، والانخفاض في درجة الغليان، والارتفاع في درجة التجمد، والضغط الأسموزي","الانخفاض في الضغط البخاري، والارتفاع في درجة الغليان، والانخفاض في درجة التجمد، والتوصيل الكهربائي"]'::jsonb, 'تذكر', 'تذكر/تعرف', 'متوسط', 'الكتاب ص 38 — المواد المتأينة والخواص الجامعة'),
('mcq', 3, 'أعدّ طالب قائمة بخواص المحلول التي تعتمد على عدد جسيمات المذاب لا على طبيعتها. أيّ خاصية أخطأ في إدراجها ضمن قائمته؟', null, '["الضغط الأسموزي","الانخفاض في الضغط البخاري","الارتفاع في درجة الغليان","ذائبية المذاب في المذيب"]'::jsonb, 'تذكر', 'استثناء', 'سهل', 'الكتاب ص 38 — المواد المتأينة والخواص الجامعة'),
('mcq', 4, 'المحلول المائي لمذاب غير متطاير يحتاج إلى درجة حرارة أعلى من 100 °C ليغلي عند ضغط 1 atm. ما الخاصية الجامعة التي يصفها ذلك؟', null, '["الانخفاض في درجة التجمد","الارتفاع في درجة الغليان","الضغط الأسموزي","الانخفاض في درجة الغليان"]'::jsonb, 'فهم', 'ربط ظاهرة بمفهوم', 'متوسط', 'الكتاب ص 40 — الارتفاع في درجة الغليان'),
('mcq', 5, 'رُشّ الملح على طريق مغطى بالجليد فانصهر الجليد رغم أن درجة حرارة الجو أقل من 0 °C. أيّ الخواص الجامعة يوضحها ذلك؟', null, '["الارتفاع في درجة الغليان","الضغط الأسموزي","الانخفاض في درجة التجمد","الانخفاض في الضغط البخاري"]'::jsonb, 'فهم', 'ربط ظاهرة بمفهوم', 'سهل', 'الكتاب ص 41 — الانخفاض في درجة التجمد'),
('mcq', 6, 'ما اسم الخاصية الجامعة التي تمثل كمية الضغط الإضافي الناتج عن انتقال جزيئات الماء عبر غشاء شبه منفذ إلى المحلول المركز؟', null, '["الضغط الأسموزي","الضغط البخاري","الضغط الجوي","الانخفاض في الضغط البخاري"]'::jsonb, 'تذكر', 'تذكر مصطلح', 'متوسط', 'الكتاب ص 44 — الضغط الأسموزي'),
('mcq', 7, 'قاس طالب بعض الخواص للماء النقي ولمحلول مائي لمذاب غير متطاير، فسجّل النتائج في الجدول. أيّ الخواص الجامعة الأربع لم يتناولها الطالب في قياساته؟', '{"headers":["الخاصية المقيسة","الماء النقي","المحلول"],"rows":[["الضغط البخاري عند 25 °C (atm)","0.0313","0.0307"],["درجة الغليان عند 1 atm (°C)","100.0","100.3"],["درجة التجمد (°C)","0.0","−1.1"]]}'::jsonb, '["الانخفاض في الضغط البخاري","الارتفاع في درجة الغليان","الانخفاض في درجة التجمد","الضغط الأسموزي"]'::jsonb, 'تحليل', 'تفسير بيانات', 'صعب', 'الكتاب ص 38 — المواد المتأينة والخواص الجامعة'),
('essay', 1, 'عدّد الخواص الجامعة الأربع للمحاليل، واذكر لكل منها ما يحدث عند إذابة مذاب غير متطاير في مذيب نقي.', null, null, 'تذكر', 'تعداد ووصف', 'متوسط', 'الكتاب ص 44 — الضغط الأسموزي'),
('essay', 2, 'اكتب اسم الخاصية الجامعة التي تمثلها كل ظاهرة مما يأتي: (1) يتجمد ماء البحر عند درجة أقل من 0 °C. (2) يحتاج محلول السكر في الماء إلى تسخين أعلى من 100 °C ليغلي عند 1 atm. (3) يقل عدد جزيئات الماء المتحولة إلى بخار من سطح محلول ملحي في وعاء مغلق مقارنة بالماء النقي. (4) ينتقل الماء عبر غشاء شبه منفذ نحو محلول مركز فينشأ ضغط إضافي.', null, null, 'تطبيق', 'ربط ظواهر بمفاهيم', 'صعب', 'الكتاب ص 44 — الضغط الأسموزي'),
('essay', 3, 'بيّن ماذا يحدث لمقدار كل خاصية من الخواص الجامعة الأربع عند زيادة عدد جسيمات المذاب غير المتطاير في كمية ثابتة من المذيب، ثم استنتج الصفة المشتركة التي جمعت هذه الخواص في مجموعة واحدة.', null, null, 'تحليل', 'استنتاج', 'صعب', 'الكتاب ص 39 — الانخفاض في الضغط البخاري')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
