from (values
('mcq', 1, 2, 'الخواص الجامعة أربع: الانخفاض في الضغط البخاري، والارتفاع في درجة الغليان، والانخفاض في درجة التجمد، والضغط الأسموزي؛ ومن بين البدائل يرد منها «الانخفاض في درجة التجمد» فقط.', '["التوصيل الكهربائي يعتمد على طبيعة المذاب (متأين أو غير متأين)، وليس من الخواص الجامعة الأربع.","اللون يعتمد على نوع المذاب، وليس من الخواص الجامعة.","","الذائبية تعتمد على طبيعة المذاب والمذيب، وليست من الخواص الجامعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.413Z"}'::jsonb),
('mcq', 2, 0, 'تشمل الخواص الجامعة: الانخفاض في الضغط البخاري، والارتفاع في درجة الغليان، والانخفاض في درجة التجمد، والضغط الأسموزي، وهي المجموعة الواردة في البديل الصحيح بالاتجاهات الصحيحة.', '["","المذاب غير المتطاير يخفض الضغط البخاري ويخفض درجة التجمد، لا يرفعهما.","عكس اتجاه التغير في درجتي الغليان والتجمد؛ فالغليان يرتفع والتجمد ينخفض.","التوصيل الكهربائي ليس خاصية جامعة، والخاصية الرابعة هي الضغط الأسموزي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.413Z"}'::jsonb),
('mcq', 3, 3, 'الخواص الجامعة الأربع هي الانخفاض في الضغط البخاري والارتفاع في درجة الغليان والانخفاض في درجة التجمد والضغط الأسموزي؛ أما الذائبية فتعتمد على طبيعة المذاب والمذيب فليست خاصية جامعة.', '["الضغط الأسموزي خاصية جامعة؛ لأنه يعتمد على عدد جسيمات المذاب.","الانخفاض في الضغط البخاري إحدى الخواص الجامعة الأربع.","الارتفاع في درجة الغليان إحدى الخواص الجامعة الأربع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.413Z"}'::jsonb),
('mcq', 4, 1, 'غليان المحلول عند درجة أعلى من درجة غليان المذيب النقي هو الخاصية الجامعة المسماة «الارتفاع في درجة الغليان».', '["هذه الخاصية تتعلق بتحول السائل إلى صلب عند درجة أقل، لا بالغليان.","","الضغط الأسموزي يتعلق بانتقال المذيب عبر غشاء شبه منفذ، لا بدرجة الغليان.","درجة غليان المحلول ترتفع ولا تنخفض، وهذه ليست من الخواص الجامعة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.413Z"}'::jsonb),
('mcq', 5, 2, 'إضافة الملح تقلل درجة تجمد الماء فيبقى سائلًا عند درجات أقل من 0 °C وينصهر الجليد، وهذه هي خاصية الانخفاض في درجة التجمد.', '["انصهار الجليد يتعلق بدرجة التجمد لا بدرجة الغليان.","لا يوجد هنا غشاء شبه منفذ ينتقل عبره المذيب.","","الظاهرة الملاحظة بقاء الماء سائلًا تحت 0 °C، وهي تمثل الانخفاض في درجة التجمد مباشرة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.414Z"}'::jsonb),
('mcq', 6, 0, 'الضغط الأسموزي هو كمية الضغط الإضافي الناتج عن انتقال جزيئات الماء إلى المحلول المركز، وهو خاصية جامعة.', '["","الضغط البخاري ضغط بخار السائل المتزن مع سائله في وعاء مغلق، وليس له علاقة بالغشاء شبه المنفذ.","الضغط الجوي ضغط الهواء المحيط، وليس خاصية للمحلول.","هذه خاصية جامعة أخرى تتعلق بتبخر المذيب من سطح المحلول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.414Z"}'::jsonb),
('mcq', 7, 3, 'الجدول يتضمن الضغط البخاري ودرجة الغليان ودرجة التجمد، وهي ترتبط بثلاث خواص جامعة؛ أما الخاصية الرابعة «الضغط الأسموزي» فتحتاج إلى غشاء شبه منفذ ولم تُقَس.', '["قاس الطالب الضغط البخاري للماء والمحلول، والفرق بينهما يمثل هذه الخاصية.","قاس الطالب درجتي الغليان، والفرق بينهما يمثل هذه الخاصية.","قاس الطالب درجتي التجمد، والفرق بينهما يمثل هذه الخاصية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.414Z"}'::jsonb),
('essay', 1, null::int, null, null, '1) الانخفاض في الضغط البخاري: يصبح الضغط البخاري للمحلول أقل من الضغط البخاري للمذيب النقي. 2) الارتفاع في درجة الغليان: يغلي المحلول عند درجة أعلى من درجة غليان المذيب النقي. 3) الانخفاض في درجة التجمد: يتجمد المحلول عند درجة أقل من درجة تجمد المذيب النقي. 4) الضغط الأسموزي: ينشأ ضغط إضافي عند انتقال جزيئات المذيب عبر غشاء شبه منفذ إلى المحلول الأعلى تركيزًا.', '["الانخفاض في الضغط البخاري مع وصفه","الارتفاع في درجة الغليان مع وصفه","الانخفاض في درجة التجمد مع وصفه","الضغط الأسموزي مع وصفه"]'::jsonb, '[]'::jsonb, '[{"element":"الانخفاض في الضغط البخاري ووصفه","marks":1},{"element":"الارتفاع في درجة الغليان ووصفه","marks":1},{"element":"الانخفاض في درجة التجمد ووصفه","marks":1},{"element":"الضغط الأسموزي ووصفه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الخواص الأربع صحيحة مع وصف صحيح لكل منها"},{"level":"3 درجات","description":"ثلاث خواص صحيحة موصوفة"},{"level":"درجتان","description":"خاصيتان صحيحتان موصوفتان، أو أربع خواص بلا وصف"},{"level":"درجة واحدة","description":"خاصية واحدة صحيحة"},{"level":"صفر","description":"لا خاصية صحيحة"}]'::jsonb, '["كتابة «الارتفاع في درجة التجمد» بدل الانخفاض","ذكر الخاصية الأسموزية بدل الضغط الأسموزي دون وصف الضغط","إدراج التوصيل الكهربائي ضمن الخواص الجامعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.414Z"}'::jsonb),
('essay', 2, null::int, null, null, '(1) الانخفاض في درجة التجمد. (2) الارتفاع في درجة الغليان. (3) الانخفاض في الضغط البخاري. (4) الضغط الأسموزي.', '["(1) الانخفاض في درجة التجمد","(2) الارتفاع في درجة الغليان","(3) الانخفاض في الضغط البخاري","(4) الضغط الأسموزي"]'::jsonb, '[]'::jsonb, '[{"element":"الظاهرة (1)","marks":1},{"element":"الظاهرة (2)","marks":1},{"element":"الظاهرة (3)","marks":1},{"element":"الظاهرة (4)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الربط صحيح في الظواهر الأربع"},{"level":"3 درجات","description":"ثلاث ظواهر صحيحة"},{"level":"درجتان","description":"ظاهرتان صحيحتان"},{"level":"درجة واحدة","description":"ظاهرة واحدة صحيحة"},{"level":"صفر","description":"لا ربط صحيحًا"}]'::jsonb, '["الخلط بين الانخفاض في الضغط البخاري والضغط الأسموزي","تسمية الظاهرة (4) «الانتشار»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.414Z"}'::jsonb),
('essay', 3, null::int, null, null, 'عند زيادة عدد جسيمات المذاب: يقل الضغط البخاري للمحلول أكثر (يزداد الانخفاض في الضغط البخاري)، ويزداد الارتفاع في درجة الغليان، ويزداد الانخفاض في درجة التجمد، ويزداد الضغط الأسموزي. والصفة المشتركة أن جميعها خواص فيزيائية تعتمد على عدد جسيمات المذاب في المحلول وليس على طبيعتها، ولذلك تسمى الخواص الجامعة.', '["يزداد الانخفاض في الضغط البخاري","يزداد الارتفاع في درجة الغليان","يزداد الانخفاض في درجة التجمد","يزداد الضغط الأسموزي","الصفة المشتركة: الاعتماد على عدد الجسيمات لا طبيعتها"]'::jsonb, '[]'::jsonb, '[{"element":"الضغط البخاري","marks":1},{"element":"درجة الغليان","marks":1},{"element":"درجة التجمد","marks":1},{"element":"الضغط الأسموزي","marks":1},{"element":"الصفة المشتركة","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"وصف صحيح للخواص الأربع واستنتاج صحيح للصفة المشتركة"},{"level":"4 درجات","description":"خطأ واحد في وصف إحدى الخواص أو استنتاج ناقص"},{"level":"3 درجات","description":"ثلاث خواص صحيحة مع الصفة المشتركة، أو أربع دونها"},{"level":"درجتان","description":"خاصيتان صحيحتان"},{"level":"درجة واحدة","description":"خاصية واحدة صحيحة أو الصفة المشتركة فقط"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["القول إن الضغط البخاري يزداد بزيادة المذاب","الخلط بين «انخفاض درجة التجمد» و«انخفاض الانخفاض»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.415Z"}'::jsonb)
