('mcq', 1, 'ما العلاقة بين الارتفاع في درجة غليان محلول مذاب غير متطاير وغير متأين ومولالية هذا المحلول؟', null, '["يتناسب الارتفاع في درجة الغليان عكسيًا مع المولالية","لا يعتمد الارتفاع على المولالية بل على نوع المذاب","يتناسب الارتفاع طرديًا مع حجم المحلول","يتناسب الارتفاع في درجة الغليان طرديًا مع المولالية"]'::jsonb, 'تذكر', 'تذكر علاقة', 'سهل', 'الكتاب ص 40 — الارتفاع في درجة الغليان'),
('mcq', 2, 'إذا زادت مولالية محلول مائي لمذاب غير متطاير وغير متأين من 0.5 m إلى 1.0 m، فإن الارتفاع في درجة غليانه:', null, '["يقل إلى النصف","يبقى كما هو دون تغير","يزداد إلى مثليه","يزداد إلى أربعة أمثاله"]'::jsonb, 'فهم', 'تنبؤ', 'سهل', 'الكتاب ص 40 — الارتفاع في درجة الغليان'),
('mcq', 3, 'عند ضغط 1 atm، ما درجة غليان محلول مائي تركيزه 1 m من مذاب غير متطاير وغير متأين؟ (Kb للماء = 0.512 °C/m)', null, '["0.512 °C","100.512 °C","99.488 °C","101.024 °C"]'::jsonb, 'فهم', 'حساب بسيط', 'متوسط', 'الكتاب ص 40 — الارتفاع في درجة الغليان'),
('mcq', 4, 'يبين الجدول الارتفاع في درجة الغليان لمحاليل مائية لمذاب غير متطاير وغير متأين بمولاليات مختلفة. ما الارتفاع المتوقع في درجة غليان محلول مولاليته 0.80 m من المذاب نفسه؟', '{"headers":["المولالية (m)","الارتفاع في درجة الغليان ΔTb (°C)"],"rows":[["0.20","0.102"],["0.40","0.205"],["0.60","0.307"]]}'::jsonb, '["0.410 °C","0.307 °C","0.512 °C","0.800 °C"]'::jsonb, 'تحليل', 'تفسير بيانات', 'متوسط', 'الكتاب ص 40 — الارتفاع في درجة الغليان'),
('mcq', 5, 'لماذا تُستعمل المولالية للتعبير عن التركيز في العلاقة ΔTb = Kb·m؟', null, '["لأنها تعبر عن المذيب بالحجم فتتغير بتغير درجة الحرارة","لأنها تعتمد على نوع المذاب لا على عدد جسيماته","لأنها تساوي المولارية دائمًا في المحاليل المائية","لأنها تعبر عن المذيب بالكتلة فلا تتأثر بتغير درجة الحرارة"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 40 — الارتفاع في درجة الغليان'),
('mcq', 6, 'أيّ المحاليل المائية الآتية له أعلى درجة غليان؟ (اعتبر NaCl وCaCl₂ مادتين متأينتين قويتين)', null, '["NaCl تركيزه 0.10 m","سكروز تركيزه 0.25 m","جلوكوز تركيزه 0.15 m","CaCl₂ تركيزه 0.050 m"]'::jsonb, 'تحليل', 'مقارنة وترتيب', 'صعب', 'الكتاب ص 43 — مثال 1-6: التغيرات في درجات التجمد والغليان'),
('mcq', 7, 'ما المقصود بثابت الارتفاع في درجة الغليان المولالي Kb لمذيب ما؟', null, '["الفرق بين درجة غليان محلول تركيزه 1 m من مذاب غير متطاير وغير متأين ودرجة غليان المذيب النقي","درجة غليان محلول تركيزه 1 m من أي مذاب في ذلك المذيب","الفرق بين درجتي غليان محلولين تركيز كل منهما 1 m من مذابين مختلفين","مقدار ارتفاع درجة غليان المذيب النقي عند زيادة الضغط فوقه بمقدار 1 atm"]'::jsonb, 'تذكر', 'تعريف مفهوم', 'متوسط', 'الكتاب ص 40 — الارتفاع في درجة الغليان'),
('essay', 1, 'وضّح أثر زيادة مولالية محلول مائي لمذاب غير متطاير وغير متأين في درجة غليانه، مستعينًا بالعلاقة ΔTb = Kb·m، واذكر مدلول كل رمز فيها.', null, null, 'فهم', 'توضيح علاقة', 'سهل', 'الكتاب ص 40 — الارتفاع في درجة الغليان'),
('essay', 2, 'محلولان مائيان A وB لمذاب غير متطاير وغير متأين؛ مولالية A تساوي 0.30 m ومولالية B تساوي 0.90 m. (أ) قارن دون حساب بين الارتفاع في درجتي غليانهما. (ب) احسب درجة غليان كل منهما عند 1 atm. (Kb للماء = 0.512 °C/m) (ج) ماذا تستنتج من النسبة بين الارتفاعين؟', null, null, 'تحليل', 'حساب ومقارنة', 'صعب', 'الكتاب ص 40 — الارتفاع في درجة الغليان'),
('essay', 3, 'يرى طالب أن إذابة 0.50 mol من كلوريد الصوديوم NaCl في 1 kg من الماء ترفع درجة الغليان بالمقدار نفسه الذي ترفعه إذابة 0.50 mol من الجلوكوز في 1 kg من الماء. قوّم رأي الطالب، ثم احسب الارتفاع في درجة الغليان في كل حالة. (Kb للماء = 0.512 °C/m، وNaCl مادة متأينة قوية)', null, null, 'تقويم', 'تقويم رأي وحساب', 'صعب', 'الكتاب ص 43 — مثال 1-6: التغيرات في درجات التجمد والغليان')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
