select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'تتناسب قيمة الارتفاع في درجة الغليان ΔTb تناسبًا طرديًا مع مولالية المحلول (ΔTb = Kb·m)، فالإجابة «يتناسب طرديًا مع المولالية».', '["العلاقة ΔTb = Kb·m طردية؛ فزيادة المولالية تزيد الارتفاع.","الارتفاع خاصية جامعة تعتمد على عدد جسيمات المذاب (المولالية) لا على نوعه.","الحجم لا يدخل في العلاقة ΔTb = Kb·m، والمولالية تعبر عن المذيب بالكتلة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-17T11:36:22.415Z"}'::jsonb),
('mcq', 2, 2, 'بما أن ΔTb = Kb·m وKb ثابت للمذيب، فمضاعفة المولالية من 0.5 m إلى 1.0 m تضاعف الارتفاع في درجة الغليان (من 0.256 °C إلى 0.512 °C للماء).', '["اعتبر العلاقة عكسية، والصحيح أنها طردية.","أغفل أن ΔTb يعتمد على المولالية.","","افترض أن ΔTb يتناسب مع مربع المولالية، والعلاقة خطية ΔTb = Kb·m."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-17T11:36:22.415Z"}'::jsonb),
('mcq', 3, 1, 'ΔTb = Kb·m = 0.512 °C/m × 1 m = 0.512 °C، ودرجة غليان المحلول = 100.0 °C + 0.512 °C = 100.512 °C.', '["هذه قيمة الارتفاع ΔTb فقط، ونسي إضافتها إلى درجة غليان الماء النقي 100.0 °C.","","طرح الارتفاع من درجة غليان الماء بدل إضافته.","ضاعف الارتفاع كأن المذاب متأين ينتج جسيمين، والمذاب غير متأين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-17T11:36:22.416Z"}'::jsonb),
('mcq', 4, 0, 'البيانات تبين أن ΔTb يتناسب طرديًا مع المولالية بنسبة ثابتة هي Kb = 0.512 °C/m (مثلًا 0.205 ÷ 0.40 ≈ 0.512). إذن عند 0.80 m: ΔTb = 0.512 × 0.80 = 0.410 °C.', '["","اختار قيمة المحلول 0.60 m من الجدول دون استقراء العلاقة.","استعمل قيمة المحلول 1 m (Kb للماء) بدل حساب الارتفاع عند 0.80 m.","افترض أن الارتفاع يساوي المولالية عدديًا متجاهلًا الثابت Kb."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:36:22.416Z"}'::jsonb),
('mcq', 5, 3, 'المولالية مرتبطة بالكسر المولي الذي يتضمن عدد جسيمات المذاب، وتعبر عن المذيب بالكتلة بدلًا من الحجم، ولذلك لا تتأثر بتغير درجة الحرارة التي تتغير في أثناء التسخين للغليان.', '["المولالية تعبر عن المذيب بالكتلة (kg) لا بالحجم.","المولالية تعبر عن عدد مولات المذاب، والخواص الجامعة لا تعتمد على نوعه.","المولالية والمولارية تعريفان مختلفان ولا يتساويان دائمًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T11:36:22.416Z"}'::jsonb),
('mcq', 6, 1, 'الارتفاع يتناسب طرديًا مع مولالية الجسيمات الفعلية: السكروز 0.25 m، وNaCl: 0.20 m، والجلوكوز 0.15 m، وCaCl₂: 0.15 m؛ فأكبرها محلول السكروز 0.25 m فله أعلى درجة غليان.', '["مولالية الجسيمات الفعلية = 0.10 × 2 = 0.20 m، وهي أقل من 0.25 m.","","الجلوكوز غير متأين فمولالية جسيماته 0.15 m فقط.","مولالية الجسيمات الفعلية = 0.050 × 3 = 0.15 m فقط."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.416Z"}'::jsonb),
('mcq', 7, 0, 'Kb هو الفرق بين درجة غليان محلول يحتوي على 1 m من مذاب غير متطاير وغير متأين ودرجة غليان المذيب النقي، ووحدته °C/m.', '["","Kb فرق في درجتي الغليان لا درجة غليان، ويشترط مذابًا غير متطاير وغير متأين.","المقارنة تكون مع المذيب النقي لا بين محلولين.","Kb لا يتعلق بتغيير الضغط بل بإذابة 1 m من المذاب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T11:36:22.416Z"}'::jsonb),
('essay', 1, null::int, null, null, 'ΔTb: الارتفاع في درجة الغليان، Kb: ثابت الارتفاع في درجة الغليان المولالي (للماء 0.512 °C/m)، m: مولالية المحلول. لأن Kb ثابت لمذيب معين فإن ΔTb يتناسب طرديًا مع m؛ فكلما زادت مولالية المحلول (عدد جسيمات المذاب) زاد الارتفاع في درجة الغليان، فترتفع درجة غليان المحلول عن 100.0 °C أكثر.', '["مدلول ΔTb","مدلول Kb","مدلول m","زيادة المولالية تزيد ΔTb (تناسب طردي) فترتفع درجة الغليان"]'::jsonb, '[]'::jsonb, '[{"element":"مدلولات الرموز الثلاثة","marks":1.5},{"element":"بيان العلاقة الطردية وأثرها في درجة الغليان","marks":1.5}]'::jsonb, '[{"level":"3 درجات","description":"مدلولات صحيحة وبيان صحيح للعلاقة الطردية وأثرها"},{"level":"درجتان","description":"بيان صحيح للعلاقة مع نقص في مدلولات الرموز"},{"level":"درجة واحدة","description":"مدلولات صحيحة دون بيان الأثر، أو أثر صحيح دون أي مدلول"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["القول إن درجة الغليان تنخفض بزيادة التركيز","تفسير m بأنها المولارية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-17T11:36:22.417Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) مولالية B ثلاثة أمثال مولالية A، ولأن ΔTb يتناسب طرديًا مع المولالية فارتفاع B ثلاثة أمثال ارتفاع A. (ب) A: ΔTb = 0.512 × 0.30 = 0.154 °C، فدرجة غليانه 100.154 °C. B: ΔTb = 0.512 × 0.90 = 0.461 °C، فدرجة غليانه 100.461 °C. (ج) النسبة 0.461 ÷ 0.154 ≈ 3 تساوي نسبة المولاليتين؛ أي أن الارتفاع في درجة الغليان يتناسب طرديًا مع مولالية المحلول.', '["المقارنة النوعية: ارتفاع B ثلاثة أمثال A","حساب درجة غليان A","حساب درجة غليان B","استنتاج التناسب الطردي"]'::jsonb, '["ΔTb(A) = 0.512 °C/m × 0.30 m = 0.154 °C","Tb(A) = 100.0 °C + 0.154 °C = 100.154 °C","ΔTb(B) = 0.512 °C/m × 0.90 m = 0.461 °C","Tb(B) = 100.0 °C + 0.461 °C = 100.461 °C","ΔTb(B) ÷ ΔTb(A) ≈ 3 = 0.90 ÷ 0.30"]'::jsonb, '[{"element":"المقارنة دون حساب","marks":1},{"element":"حساب A","marks":1},{"element":"حساب B","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة صحيحة وحسابان صحيحان واستنتاج صحيح"},{"level":"3 درجات","description":"خطأ واحد في جزء من الأجزاء"},{"level":"درجتان","description":"حسابان صحيحان فقط أو مقارنة واستنتاج فقط"},{"level":"درجة واحدة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["الاكتفاء بـ ΔTb دون إضافته إلى 100.0 °C","استعمال Kf بدل Kb","القول إن الارتفاع يزداد تسعة أمثال"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-17T11:36:22.417Z"}'::jsonb),
('essay', 3, null::int, null, null, 'رأي الطالب غير صحيح. NaCl مادة متأينة قوية تتفكك: NaCl(s) → Na⁺(aq) + Cl⁻(aq)، فكل 0.50 mol منه تنتج 1.0 mol من الجسيمات، أي أن المولالية الفعلية للجسيمات 1.0 m، فيكون ΔTb = 0.512 × 1.0 = 0.512 °C. أما الجلوكوز فغير متأين، فمولالية جسيماته 0.50 m وΔTb = 0.512 × 0.50 = 0.256 °C. إذن ارتفاع محلول NaCl ضعف ارتفاع محلول الجلوكوز؛ لأن الأثر يعتمد على المولالية الفعلية للجسيمات.', '["الحكم بأن الرأي خاطئ","تفكك NaCl إلى أيونين ومولالية فعلية 1.0 m","حساب ΔTb لمحلول NaCl","حساب ΔTb لمحلول الجلوكوز"]'::jsonb, '["المولالية الفعلية لجسيمات NaCl = 0.50 m × 2 = 1.0 m","ΔTb(NaCl) = 0.512 °C/m × 1.0 m = 0.512 °C","ΔTb(الجلوكوز) = 0.512 °C/m × 0.50 m = 0.256 °C"]'::jsonb, '[{"element":"الحكم مع التعليل بتفكك NaCl","marks":1},{"element":"المولالية الفعلية لجسيمات NaCl","marks":1},{"element":"حساب ΔTb لـ NaCl","marks":1},{"element":"حساب ΔTb للجلوكوز","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"حكم صحيح معلل وحسابان صحيحان"},{"level":"3 درجات","description":"حكم صحيح مع خطأ في أحد الحسابين"},{"level":"درجتان","description":"حسابان صحيحان دون حكم واضح، أو حكم معلل دون حساب"},{"level":"درجة واحدة","description":"حساب واحد صحيح"},{"level":"صفر","description":"تأييد رأي الطالب دون أي حساب صحيح"}]'::jsonb, '["إهمال تفكك NaCl فيكون الارتفاع 0.256 °C في الحالتين","ضرب مولالية الجلوكوز في 2"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T11:36:22.418Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
