from (values
('mcq', 1, 'السبب في ارتفاع درجة غليان المحلول المحتوي على مذاب غير متطاير عن درجة غليان المذيب النقي أن المذاب:', null, '["يقلل الضغط البخاري للمذيب","يزيد الضغط البخاري للمذيب","يرفع الضغط الجوي فوق سطح المحلول","يتبخر مع المذيب فيبطئ غليانه"]'::jsonb, 'فهم', 'تعليل', 'سهل', 'الكتاب ص 40 — الارتفاع في درجة الغليان'),
('mcq', 2, 'متى يغلي السائل؟', null, '["عندما يصبح ضغطه البخاري صفرًا","عندما تتساوى سرعتا التبخر والتكاثف في وعاء مغلق","عندما يقل ضغطه البخاري عن الضغط الجوي","عندما يعادل ضغطه البخاري الضغط الجوي"]'::jsonb, 'تذكر', 'تذكر/تعرف', 'سهل', 'الكتاب ص 40 — الارتفاع في درجة الغليان'),
('mcq', 3, 'سُخّن محلول مائي لمذاب غير متطاير حتى 100.0 °C عند ضغط 1 atm. ماذا يحدث له عند هذه الدرجة؟', null, '["يغلي؛ لأن درجة غليان الماء 100.0 °C","يغلي؛ لأن ضغطه البخاري أكبر من الضغط الجوي","لا يغلي؛ لأن ضغطه البخاري يبقى أقل من الضغط الجوي","لا يغلي؛ لأن ضغطه البخاري أصبح أكبر من الضغط الجوي"]'::jsonb, 'فهم', 'تنبؤ وتعليل', 'متوسط', 'الكتاب ص 40 — الارتفاع في درجة الغليان'),
('mcq', 4, 'محلول مائي لمذاب غير متطاير وصل إلى درجة غليان الماء النقي ولم يغلِ. ما الذي يلزم كي يغلي؟', null, '["خفض ضغطه البخاري إلى ما دون الضغط الجوي","تسخينه إلى درجة أعلى ليرتفع ضغطه البخاري إلى ما يعادل الضغط الجوي","إضافة مزيد من المذاب غير المتطاير إليه","تبريده حتى يتساوى ضغطه البخاري مع الضغط الجوي"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 40 — الارتفاع في درجة الغليان'),
('mcq', 5, 'أيّ الترتيبات الآتية يمثل التسلسل الصحيح لتفسير ارتفاع درجة غليان المحلول؟
(1) تشغل جسيمات المذاب جزءًا من سطح السائل. (2) يقل عدد جسيمات المذيب التي تتبخر. (3) ينخفض الضغط البخاري للمحلول. (4) يلزم تسخين المحلول إلى درجة أعلى ليعادل ضغطه البخاري الضغط الجوي.', null, '["3 ثم 1 ثم 2 ثم 4","1 ثم 3 ثم 4 ثم 2","4 ثم 3 ثم 2 ثم 1","1 ثم 2 ثم 3 ثم 4"]'::jsonb, 'تحليل', 'ترتيب تسلسل سببي', 'متوسط', 'الكتاب ص 39 — الانخفاض في الضغط البخاري'),
('mcq', 6, 'عند 100.0 °C كان الضغط البخاري للماء النقي 1.00 atm، وكان الضغط البخاري لمحلول مائي لمذاب غير متطاير 0.98 atm. ما الاستنتاج الصحيح عند ضغط جوي 1.00 atm؟', null, '["يغلي الماء النقي عند 100.0 °C، ويلزم المحلول درجة أعلى ليغلي","يغلي المحلول عند درجة أقل من 100.0 °C لأن ضغطه البخاري أقل","يغلي الاثنان عند 100.0 °C لأن درجة الحرارة واحدة","لا يغلي المحلول مطلقًا مهما ارتفعت درجة حرارته"]'::jsonb, 'تحليل', 'تفسير بيانات', 'صعب', 'الكتاب ص 40 — الارتفاع في درجة الغليان'),
('mcq', 7, 'لماذا يُشترط أن يكون المذاب غير متطاير في تفسير الارتفاع في درجة غليان المحلول؟', null, '["لأنه يتبخر أسرع من المذيب فيرفع الضغط البخاري للمحلول","لأن المذاب المتطاير لا يذوب في المذيبات","لأنه قليل الميل إلى التحول إلى غاز فلا يسهم في الضغط البخاري للمحلول","لأنه يزيد عدد جسيمات المذيب على سطح المحلول"]'::jsonb, 'فهم', 'تعليل', 'صعب', 'الكتاب ص 39 — الانخفاض في الضغط البخاري'),
('essay', 1, 'فسّر: درجة غليان المحلول المحتوي على مذاب غير متطاير أعلى من درجة غليان المذيب النقي.', null, null, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 40 — الارتفاع في درجة الغليان'),
('essay', 2, 'سُخّن كأسان عند ضغط جوي 1 atm؛ في الأولى ماء نقي، وفي الثانية محلول مائي للسكروز (مذاب غير متطاير). (أ) ماذا يحدث لكل منهما عند 100.0 °C؟ (ب) فسّر الفرق بينهما. (ج) ماذا يلزم ليغلي المحلول؟ (د) ماذا يسمى الفرق بين درجتي غليانهما؟', null, null, 'تحليل', 'مقارنة وتفسير', 'متوسط', 'الكتاب ص 40 — الارتفاع في درجة الغليان'),
('essay', 3, 'في مخطط تغير الحالة (الضغط مقابل درجة الحرارة) يقع منحنى الضغط البخاري للمحلول المائي أسفل منحنى الضغط البخاري للماء النقي عند أي درجة حرارة. فسّر كيف يؤدي ذلك إلى أن تكون درجة غليان المحلول أعلى من درجة غليان الماء النقي، مستعينًا بخط الضغط 1 atm.', null, null, 'تحليل', 'تفسير رسم بياني', 'صعب', 'الكتاب ص 41 — الانخفاض في درجة التجمد')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
