from (values
('mcq', 1, 0, 'المذاب غير المتطاير يؤثر في درجة غليان المذيب لأنه يقلل الضغط البخاري له، فيحتاج المحلول إلى درجة أعلى ليعادل ضغطه البخاري الضغط الجوي.', '["","المذاب غير المتطاير يقلل الضغط البخاري ولا يزيده؛ ولو زاده لانخفضت درجة الغليان.","الضغط الجوي لا يتأثر بإذابة مادة في السائل.","المذاب غير المتطاير له ميل قليل إلى التحول إلى غاز فلا يتبخر مع المذيب."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (64%)"}],"at":"2026-10-17T11:36:22.418Z"}'::jsonb),
('mcq', 2, 3, 'تذكّر أن السائل يغلي عندما يعادل ضغطه البخاري الضغط الجوي، وهذا أساس تفسير الارتفاع في درجة الغليان.', '["انعدام الضغط البخاري يعني عدم التبخر، والغليان يحتاج إلى ضغط بخاري مساوٍ للضغط الجوي.","هذا وصف حالة الاتزان الديناميكي التي يقاس عندها الضغط البخاري، لا شرط الغليان.","ما دام الضغط البخاري أقل من الضغط الجوي فلا يغلي السائل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-17T11:36:22.418Z"}'::jsonb),
('mcq', 3, 2, 'عند وصول المحلول إلى درجة غليان المذيب النقي يبقى ضغط بخاره أقل من الضغط الجوي لأن المذاب خفّض الضغط البخاري، لذا لا يغلي المحلول عند 100.0 °C.', '["100.0 °C درجة غليان الماء النقي، والمحلول ضغطه البخاري أقل فلا يغلي عندها.","الضغط البخاري للمحلول أقل من ضغط الماء النقي، أي أقل من 1 atm عند 100.0 °C.","","لو زاد ضغطه البخاري على الضغط الجوي لغلى؛ والصحيح أنه أقل منه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:36:22.418Z"}'::jsonb),
('mcq', 4, 1, 'يجب تسخين المحلول إلى درجة حرارة أعلى لتزويده بالطاقة الحركية الإضافية اللازمة لرفع ضغطه البخاري إلى ما يعادل الضغط الجوي، وعندها يغلي.', '["خفض الضغط البخاري يبعد المحلول عن الغليان لا يقربه منه.","","زيادة المذاب تخفض الضغط البخاري أكثر فترفع درجة الغليان أكثر.","التبريد يقلل الضغط البخاري ولا يرفعه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.419Z"}'::jsonb),
('mcq', 5, 3, 'تشغل جسيمات المذاب جزءًا من السطح (1)، فيقل عدد جسيمات المذيب المتبخرة (2)، فينخفض الضغط البخاري (3)، فيلزم تسخين المحلول إلى درجة أعلى ليعادل ضغطه البخاري الضغط الجوي (4)؛ فالتسلسل 1 ثم 2 ثم 3 ثم 4.', '["جعل انخفاض الضغط البخاري سببًا لشغل المذاب للسطح، والصحيح أنه نتيجة له.","قلة تبخر جسيمات المذيب هي سبب انخفاض الضغط البخاري، فتأتي قبله لا في النهاية.","عكس التسلسل كاملًا فجعل النتيجة النهائية سببًا أول.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.419Z"}'::jsonb),
('mcq', 6, 0, 'عند 100.0 °C يساوي الضغط البخاري للماء النقي الضغط الجوي (1.00 atm) فيغلي، أما المحلول فضغطه البخاري 0.98 atm أقل من الضغط الجوي، فيحتاج إلى تسخين لدرجة أعلى من 100.0 °C ليرتفع ضغطه البخاري إلى 1.00 atm ويغلي.', '["","الضغط البخاري الأقل يعني الحاجة إلى درجة أعلى لا أقل كي يعادل الضغط الجوي.","المحلول ضغطه البخاري 0.98 atm أقل من الضغط الجوي فلا يغلي عند 100.0 °C.","رفع درجة الحرارة يزيد الضغط البخاري حتى يعادل الضغط الجوي فيغلي المحلول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:36:22.419Z"}'::jsonb),
('mcq', 7, 2, 'المذاب غير المتطاير له ميل قليل إلى التحول إلى غاز، فلا تشارك جسيماته في البخار، بينما تشغل جزءًا من سطح السائل فيقل الضغط البخاري للمحلول وترتفع درجة غليانه.', '["المذاب غير المتطاير قليل الميل إلى التبخر، ولا يرفع الضغط البخاري بل يخفضه.","التطاير لا علاقة له بالذوبان؛ فهناك مذابات متطايرة تذوب في الماء.","","جسيمات المذاب تشغل جزءًا من السطح فتقلل عدد جسيمات المذيب عليه لا تزيده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (35%)"}],"at":"2026-10-17T11:36:22.419Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المذاب غير المتطاير يقلل الضغط البخاري للمذيب؛ لأن جسيماته تشغل جزءًا من سطح السائل فيقل عدد جسيمات المذيب التي تتبخر. والسائل يغلي عندما يعادل ضغطه البخاري الضغط الجوي، فعند درجة غليان المذيب النقي يبقى ضغط بخار المحلول أقل من الضغط الجوي فلا يغلي، ويلزم تسخينه إلى درجة حرارة أعلى ليرتفع ضغطه البخاري إلى ما يعادل الضغط الجوي؛ ولذلك تكون درجة غليانه أعلى.', '["المذاب غير المتطاير يقلل الضغط البخاري","شرط الغليان: تساوي الضغط البخاري والضغط الجوي","الحاجة إلى درجة حرارة أعلى ليعادل الضغط البخاري الضغط الجوي"]'::jsonb, '[]'::jsonb, '[{"element":"انخفاض الضغط البخاري بسبب المذاب","marks":1},{"element":"شرط الغليان","marks":1},{"element":"الحاجة إلى تسخين لدرجة أعلى","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تفسير متكامل يربط العناصر الثلاثة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"تفسير خاطئ أو متروك"}]'::jsonb, '["القول إن المذاب يرفع الضغط البخاري","إغفال شرط تساوي الضغط البخاري مع الضغط الجوي","القول إن المذاب يمتص الحرارة فيؤخر الغليان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (64%)"}],"at":"2026-10-17T11:36:22.420Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) يغلي الماء النقي عند 100.0 °C، ولا يغلي محلول السكروز. (ب) لأن السكروز مذاب غير متطاير تشغل جزيئاته جزءًا من سطح المحلول، فيقل الضغط البخاري للمحلول فيبقى عند 100.0 °C أقل من الضغط الجوي، بينما يعادل الضغط البخاري للماء النقي الضغط الجوي عند هذه الدرجة. (ج) يلزم تسخين المحلول إلى درجة أعلى من 100.0 °C لتزويده بطاقة حركية إضافية ترفع ضغطه البخاري إلى ما يعادل الضغط الجوي. (د) الارتفاع في درجة الغليان ΔTb.', '["(أ) الماء يغلي والمحلول لا يغلي","(ب) انخفاض الضغط البخاري للمحلول عن الضغط الجوي","(ج) التسخين إلى درجة أعلى","(د) الارتفاع في درجة الغليان"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1},{"element":"(د)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأجزاء الأربعة صحيحة"},{"level":"3 درجات","description":"ثلاثة أجزاء صحيحة"},{"level":"درجتان","description":"جزءان صحيحان"},{"level":"درجة واحدة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["القول إن المحلول يغلي قبل الماء","تسمية الفرق «الانخفاض في الضغط البخاري»"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:36:22.420Z"}'::jsonb),
('essay', 3, null::int, null, null, 'وقوع منحنى المحلول أسفل منحنى الماء النقي يعني أن الضغط البخاري للمحلول أقل من الضغط البخاري للماء عند كل درجة حرارة، بسبب المذاب غير المتطاير. والغليان يحدث عندما يصل الضغط البخاري إلى الضغط الجوي (خط 1 atm). منحنى الماء النقي يقطع خط 1 atm عند 100.0 °C، أما منحنى المحلول فلأنه أسفل لا يصل إلى 1 atm عند هذه الدرجة، بل عند درجة حرارة أعلى. فنقطة تقاطع منحنى المحلول مع خط 1 atm تقع إلى يمين نقطة تقاطع منحنى الماء، والمسافة بينهما على محور درجة الحرارة هي الارتفاع في درجة الغليان ΔTb.', '["المنحنى الأدنى يعني ضغطًا بخاريًا أقل عند كل درجة","الغليان عند تقاطع المنحنى مع خط 1 atm","منحنى المحلول يصل 1 atm عند درجة أعلى","المسافة بين نقطتي التقاطع تمثل ΔTb"]'::jsonb, '[]'::jsonb, '[{"element":"دلالة وقوع المنحنى أسفل","marks":1},{"element":"شرط الغليان وخط 1 atm","marks":1},{"element":"المحلول يصل 1 atm عند درجة أعلى","marks":1},{"element":"تحديد ΔTb على المخطط","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل يربط المخطط بالغليان ويحدد ΔTb"},{"level":"3 درجات","description":"تفسير صحيح ينقصه تحديد ΔTb أو شرط الغليان"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["القول إن المنحنى الأدنى يصل إلى 1 atm عند درجة أقل","الخلط بين محوري الضغط ودرجة الحرارة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.420Z"}'::jsonb)
