('mcq', 1, 2, 'الضغط الأسموزي هو كمية الضغط الإضافي الناتج عن انتقال جزيئات الماء إلى المحلول المركز عبر الغشاء شبه المنفذ.', '["هذا تعريف الضغط البخاري لا الضغط الأسموزي.","جزيئات المذاب لا تعبر الغشاء، والضغط الأسموزي ناتج عن انتقال جزيئات الماء.","","هذا الضغط الجوي، ولا علاقة له بالغشاء شبه المنفذ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.423Z"}'::jsonb),
('mcq', 2, 0, 'الضغط الإضافي الناتج عن انتقال جزيئات الماء من المحلول المخفف إلى المحلول المركز يسمى «الضغط الأسموزي».', '["","الضغط البخاري ضغط بخار السائل فوق سطحه، ولا يرتبط بالغشاء شبه المنفذ.","الخاصية الأسموزية هي عملية انتشار المذيب عبر الغشاء، أما الضغط الناتج عنها فهو الضغط الأسموزي.","الضغط الجوي ضغط الهواء المحيط وليس ناتجًا عن انتقال الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (12%)"}],"at":"2026-10-17T11:36:22.423Z"}'::jsonb),
('mcq', 3, 1, 'يعتمد الضغط الأسموزي على عدد جسيمات المذاب في كمية محددة من المحلول، وهو خاصية جامعة للمحاليل.', '["الضغط الأسموزي خاصية جامعة لا تعتمد على نوع المذاب أو حجم جسيماته.","","الضغط الأسموزي لا يرتبط بمساحة الغشاء، بل بعدد جسيمات المذاب.","الضغط الأسموزي ينتج عن انتقال الماء عبر الغشاء لا عن الضغط الجوي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-10-17T11:36:22.423Z"}'::jsonb),
('mcq', 4, 3, 'الخاصية الجامعة تعتمد على عدد جسيمات المذاب لا على طبيعتها، والضغط الأسموزي يعتمد على عدد جسيمات المذاب في كمية محددة من المحلول، ولذلك فهو خاصية جامعة.', '["حدوثه في الخلايا لا يجعله خاصية جامعة؛ المعيار هو الاعتماد على عدد الجسيمات.","الخاصية الجامعة لا تُعرّف بالاعتماد على نوع الغشاء بل على عدد جسيمات المذاب.","جزيئات المذاب لا تستطيع عبور الغشاء شبه المنفذ.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-17T11:36:22.423Z"}'::jsonb),
('mcq', 5, 0, 'ينشأ الضغط الأسموزي من انتقال جزيئات الماء عبر غشاء شبه منفذ من المحلول المخفف إلى المحلول المركز، فلا بد من غشاء شبه منفذ ومن اختلاف في التركيز بين جانبيه.', '["","التطاير يتعلق بالضغط البخاري، والضغط الأسموزي يحتاج إلى غشاء شبه منفذ.","عند تساوي التركيزين لا يكون هناك صافي انتقال للماء نحو أحد الجانبين، فلا ينشأ ضغط إضافي.","هذه ظروف قياس الضغط البخاري لا الضغط الأسموزي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (57%)"}],"at":"2026-10-17T11:36:22.423Z"}'::jsonb),
('mcq', 6, 2, 'الضغط الأسموزي يعتمد على عدد جسيمات المذاب، والسكروز غير متأين، فأكثر المحاليل جسيمات هو الأعلى تركيزًا (0.50 m)، وفيه ينشأ أكبر ضغط أسموزي.', '["عدد جسيمات المذاب فيه أقل، فضغطه الأسموزي أقل.","تركيزه أقل من 0.50 m، فعدد جسيماته أقل وضغطه الأسموزي أقل.","","هذا أقلها جسيمات، فضغطه الأسموزي هو الأصغر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.424Z"}'::jsonb),
('mcq', 7, 3, 'الضغط الأسموزي خاصية جامعة تعتمد على عدد جسيمات المذاب: الجلوكوز والسكروز 1 جسيم، وNaCl جسيمان (Na⁺ وCl⁻)، وAlCl₃ أربعة جسيمات (Al³⁺ و3Cl⁻)؛ فأكبرها ضغطًا أسموزيًا محلول AlCl₃.', '["غير متأين، فينتج 1 mol من الجسيمات لكل 1 mol مذاب فقط.","غير متأين، فعدد جسيماته مساوٍ لعدد جسيمات الجلوكوز.","ينتج جسيمين لكل وحدة صيغة، وهذا أقل من AlCl₃ الذي ينتج أربعة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.424Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الضغط الأسموزي هو كمية الضغط الإضافي الناتج عن انتقال جزيئات الماء (المذيب) عبر غشاء شبه منفذ من المحلول المخفف إلى المحلول المركز. ويعتمد على عدد جسيمات المذاب في كمية محددة من المحلول. ولأنه يعتمد على عدد الجسيمات لا على طبيعتها فهو خاصية جامعة.', '["التعريف","العامل: عدد جسيمات المذاب في كمية محددة من المحلول","التعليل بأنه يعتمد على العدد لا على الطبيعة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"العامل","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريف وعامل وتعليل صحيحة"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["الخلط بين الضغط الأسموزي والضغط البخاري","القول إن جزيئات المذاب هي التي تنتقل"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-17T11:36:22.424Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الضغط البخاري: الضغط الناتج عن بخار السائل عندما يكون في حالة اتزان ديناميكي مع سائله في وعاء مغلق. الخاصية الأسموزية: عملية انتشار المذيب خلال غشاء شبه منفذ من المحلول الأقل تركيزًا إلى المحلول الأعلى تركيزًا. الضغط الأسموزي: كمية الضغط الإضافي الناتج عن انتقال جزيئات الماء إلى المحلول المركز، أي أنه الضغط الناتج عن الخاصية الأسموزية.', '["الضغط البخاري","الخاصية الأسموزية (عملية)","الضغط الأسموزي (ضغط ناتج عن العملية)"]'::jsonb, '[]'::jsonb, '[{"element":"الضغط البخاري","marks":1},{"element":"الخاصية الأسموزية","marks":1},{"element":"الضغط الأسموزي مع التمييز بينه وبين الخاصية الأسموزية","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريفات صحيحة مع تمييز واضح بين العملية والضغط"},{"level":"درجتان","description":"تعريفان صحيحان"},{"level":"درجة واحدة","description":"تعريف واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["عدّ الخاصية الأسموزية والضغط الأسموزي شيئًا واحدًا","عكس اتجاه انتشار المذيب"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.424Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) تنتقل جزيئات الماء في الاتجاهين، لكن صافي حركتها من الماء النقي (الأقل تركيزًا) إلى محلول السكروز (الأعلى تركيزًا)، ولا تعبر جزيئات السكروز الغشاء؛ فيرتفع مستوى السائل في الذراع الأيمن وينخفض في الأيسر. (ب) ينشأ الضغط الأسموزي في جهة المحلول المركز (الذراع الأيمن)، وهو الضغط الإضافي الناتج عن انتقال الماء إليه. (ج) يزداد الضغط الأسموزي؛ لأن NaCl مادة متأينة قوية تنتج جسيمين (Na⁺ وCl⁻) لكل وحدة صيغة، فيكون عدد جسيمات المذاب أكبر من السكروز غير المتأين، والضغط الأسموزي يعتمد على عدد الجسيمات.', '["صافي انتقال الماء نحو المحلول وارتفاع مستواه","الضغط الأسموزي في جهة المحلول المركز","زيادة الضغط الأسموزي مع NaCl","التعليل بعدد الجسيمات"]'::jsonb, '[]'::jsonb, '[{"element":"(أ) وصف المستويين وتعليله","marks":1},{"element":"(ب) موضع الضغط الأسموزي","marks":1},{"element":"(ج) الحكم بالزيادة","marks":1},{"element":"(ج) التعليل بعدد الجسيمات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأجزاء كلها صحيحة ومعللة"},{"level":"3 درجات","description":"خطأ أو نقص في تعليل واحد"},{"level":"درجتان","description":"جزءان صحيحان"},{"level":"درجة واحدة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["القول إن السكروز ينتقل إلى الماء النقي","القول إن الضغط الأسموزي لا يتغير لأن المولالية واحدة","عكس اتجاه ارتفاع المستوى"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.425Z"}'::jsonb)
