('mcq', 1, 'ما المقصود بالمواد المتأينة (الإلكتروليتية)؟', null, '["مواد تذوب جزيئاتها في الماء دون أن تتفكك إلى أيونات","مواد تتأين في الماء وتوصل محاليلها التيار الكهربائي","مواد لا تذوب في الماء لكنها توصل التيار وهي صلبة","مواد تتحول بسهولة إلى بخار من سطح المحلول"]'::jsonb, 'تذكر', 'تعريف مفهوم', 'سهل', 'الكتاب ص 38 — المواد المتأينة والخواص الجامعة'),
('mcq', 2, 'ماذا تُسمّى المواد المتأينة التي تنتج عددًا قليلًا من الأيونات في المحلول؟', null, '["مواد متأينة قوية","مواد غير متأينة","مواد غير متطايرة","مواد متأينة ضعيفة"]'::jsonb, 'تذكر', 'تذكر مصطلح', 'سهل', 'الكتاب ص 38 — المواد المتأينة والخواص الجامعة'),
('mcq', 3, 'اختُبرت ثلاثة محاليل مائية متساوية التركيز بدارة كهربائية فيها مصباح، فكانت النتائج كما في الجدول. ما التصنيف الصحيح للمواد المذابة؟', '{"headers":["المحلول","إضاءة المصباح"],"rows":[["X","ساطعة"],["Y","خافتة"],["Z","لا يضيء"]]}'::jsonb, '["X متأينة قوية، وY متأينة ضعيفة، وZ غير متأينة","X متأينة ضعيفة، وY متأينة قوية، وZ غير متأينة","X متأينة قوية، وY غير متأينة، وZ متأينة ضعيفة","X وY متأينتان قويتان، وZ متأينة ضعيفة"]'::jsonb, 'فهم', 'تفسير بيانات', 'متوسط', 'الكتاب ص 38 — المواد المتأينة والخواص الجامعة'),
('mcq', 4, 'يوصل محلول كلوريد الصوديوم التيار الكهربائي، بينما لا يوصله محلول السكروز؛ لأن:', null, '["السكروز لا يذوب في الماء فلا يكوّن محلولًا","السكروز يتفكك إلى أيونات أقل شحنة من أيونات NaCl","NaCl يتفكك إلى أيونات، وجزيئات السكروز تذوب دون أن تتفكك","NaCl مركب جزيئي يتأين، والسكروز مركب أيوني لا يتأين"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 38 — المواد المتأينة والخواص الجامعة'),
('mcq', 5, 'أيّ المواد الآتية مادة غير متأينة؟', null, '["كلوريد الصوديوم","الجليسرول","كبريتات الصوديوم","كلوريد الألومنيوم"]'::jsonb, 'تذكر', 'تصنيف', 'سهل', 'الكتاب ص 42 — الانخفاض في درجة التجمد والجدول 1-6'),
('mcq', 6, 'ما الفرق بين المادة المتأينة القوية والمادة المتأينة الضعيفة؟', null, '["القوية توصل محاليلها التيار، والضعيفة لا توصله مطلقًا","القوية مركبات جزيئية دائمًا، والضعيفة مركبات أيونية دائمًا","القوية لا تذوب في الماء، والضعيفة تذوب فيه","القوية تنتج أيونات كثيرة في المحلول، والضعيفة تنتج عددًا قليلًا منها"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 38 — المواد المتأينة والخواص الجامعة'),
('mcq', 7, 'مركب جزيئي X يذوب في الماء، ويتأين جزء صغير جدًا من جزيئاته فقط، فيكون محلوله موصلًا ضعيفًا للتيار الكهربائي. كيف يُصنَّف X؟', null, '["مادة متأينة ضعيفة","مادة غير متأينة لأنه مركب جزيئي","مادة متأينة قوية لأن محلوله موصل","مادة متأينة قوية لأنه يذوب كليًا"]'::jsonb, 'تحليل', 'تصنيف حالة', 'صعب', 'الكتاب ص 38 — المواد المتأينة والخواص الجامعة'),
('essay', 1, 'قارن بين المواد المتأينة القوية والمواد المتأينة الضعيفة والمواد غير المتأينة من حيث: (أ) سلوكها عند الذوبان في الماء. (ب) توصيل محاليلها للتيار الكهربائي. ثم اذكر مثالًا على المادة المتأينة القوية وآخر على المادة غير المتأينة.', null, null, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 38 — المواد المتأينة والخواص الجامعة'),
('essay', 2, 'لديك ثلاثة محاليل مائية مجهولة متساوية التركيز، أحدها لمادة متأينة قوية، والثاني لمادة متأينة ضعيفة، والثالث لمادة غير متأينة. صمّم تجربة بسيطة باستعمال دارة كهربائية فيها مصباح للتمييز بينها، موضحًا الخطوات والنتائج المتوقعة وتفسيرها.', null, null, 'إبداع', 'تصميم تجربة', 'صعب', 'الكتاب ص 38 — المواد المتأينة والخواص الجامعة'),
('essay', 3, 'فسّر تصنيف كلوريد الصوديوم مادة متأينة قوية، واكتب معادلة تفككه في الماء، ثم وضّح لماذا لا يوصل محلول السكروز التيار الكهربائي رغم ذوبان السكروز في الماء.', null, null, 'فهم', 'تفسير', 'صعب', 'الكتاب ص 39 — الانخفاض في الضغط البخاري')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
