from (values
('mcq', 1, 1, 'المواد التي تتفكك (تتأين) في الماء إلى أيونات فتوصل محاليلها التيار الكهربائي تسمى مواد متأينة (إلكتروليتية)، كالمركبات الأيونية.', '["هذا وصف المواد غير المتأينة كالسكروز.","","المواد المتأينة تُعرّف بتوصيل محاليلها المائية للتيار، لا بتوصيلها وهي صلبة.","هذا وصف المواد المتطايرة، ولا علاقة له بالتأين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.425Z"}'::jsonb),
('mcq', 2, 3, 'المواد المتأينة التي تنتج عددًا قليلًا من الأيونات في المحلول تسمى مواد متأينة ضعيفة.', '["المواد المتأينة القوية تنتج أيونات كثيرة في المحلول.","المواد غير المتأينة لا تنتج أيونات أصلًا ولا توصل محاليلها التيار.","التطاير صفة تتعلق بالتحول إلى غاز، لا بعدد الأيونات الناتجة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.426Z"}'::jsonb),
('mcq', 3, 0, 'المصباح الساطع يعني أيونات كثيرة (مادة متأينة قوية)، والخافت يعني أيونات قليلة (مادة متأينة ضعيفة)، وعدم الإضاءة يعني غياب الأيونات (مادة غير متأينة)؛ إذن X قوية وY ضعيفة وZ غير متأينة.', '["","الإضاءة الساطعة تدل على أيونات كثيرة (قوية)، والخافتة على أيونات قليلة (ضعيفة)، فقد عكس التصنيف.","Y أضاء المصباح فمحلوله يحوي أيونات، وZ لم يضئه فمذابه غير متأين.","خفوت الإضاءة يدل على أيونات قليلة، وعدم الإضاءة يدل على عدم التأين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.426Z"}'::jsonb),
('mcq', 4, 2, 'كلوريد الصوديوم مادة متأينة قوية تتفكك في الماء إلى Na⁺ وCl⁻ فيوصل محلوله التيار، أما السكروز فمادة غير متأينة تذوب جزيئاتها دون تفكك فلا يوصل محلوله التيار.', '["السكروز يذوب في الماء، لكن جزيئاته لا تتأين.","السكروز لا يتفكك إلى أيونات أصلًا، فهو مادة غير متأينة.","","عكس التصنيف؛ فـ NaCl مركب أيوني والسكروز مركب جزيئي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-17T11:36:22.426Z"}'::jsonb),
('mcq', 5, 1, 'الجليسرول مذاب غير متأين، بينما NaCl وNa₂SO₄ وAlCl₃ مواد متأينة.', '["مادة متأينة قوية تتفكك إلى Na⁺ وCl⁻.","","مادة متأينة تتفكك إلى Na⁺ وSO₄²⁻.","مادة متأينة تتفكك إلى Al³⁺ وCl⁻."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.426Z"}'::jsonb),
('mcq', 6, 3, 'يُميَّز بينهما بعدد الأيونات الناتجة: المواد المتأينة القوية تنتج أيونات كثيرة في المحلول، والضعيفة تنتج عددًا قليلًا من الأيونات.', '["الضعيفة توصل محاليلها التيار أيضًا لكن بدرجة أقل لقلة أيوناتها.","المركبات الأيونية كـ NaCl تكون متأينة قوية، فالتعميم المذكور معكوس وغير صحيح.","المواد المتأينة القوية كـ NaCl تذوب في الماء وتتفكك إلى أيونات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.426Z"}'::jsonb),
('mcq', 7, 0, 'القليل من المركبات الجزيئية يتأين في الماء ويكوّن محلولًا متأينًا، والمادة التي تنتج عددًا قليلًا من الأيونات متأينة ضعيفة؛ فـ X مادة متأينة ضعيفة.', '["","بعض المركبات الجزيئية تتأين في الماء؛ وما دام محلوله يحوي أيونات ويوصل التيار فليس غير متأين.","التوصيل الضعيف يدل على أيونات قليلة، والقوية تنتج أيونات كثيرة.","الذوبان لا يعني التأين؛ فقد تأين جزء صغير فقط من جزيئاته."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.426Z"}'::jsonb),
('essay', 1, null::int, null, null, '(أ) المتأينة القوية تتفكك في الماء وتنتج أيونات كثيرة، والمتأينة الضعيفة تنتج عددًا قليلًا من الأيونات، وغير المتأينة تذوب جزيئاتها دون أن تتأين. (ب) محاليل المتأينة القوية موصلة جيدة للتيار، ومحاليل المتأينة الضعيفة توصله توصيلًا ضعيفًا، ومحاليل غير المتأينة لا توصله. مثال المتأينة القوية: كلوريد الصوديوم NaCl، ومثال غير المتأينة: السكروز (أو الجليسرول). ويقبل أي مثال صحيح.', '["سلوك القوية","سلوك الضعيفة","سلوك غير المتأينة","توصيل القوية","توصيل الضعيفة","توصيل غير المتأينة","مثال متأينة قوية","مثال غير متأينة"]'::jsonb, '[]'::jsonb, '[{"element":"السلوك عند الذوبان للأنواع الثلاثة","marks":3},{"element":"التوصيل الكهربائي للأنواع الثلاثة","marks":3},{"element":"المثالان","marks":2}]'::jsonb, '[{"level":"8 درجات","description":"مقارنة كاملة صحيحة للأنواع الثلاثة مع مثالين صحيحين"},{"level":"6 درجات","description":"مقارنة صحيحة في أحد البعدين كاملًا مع نقص في الآخر، والمثالان صحيحان"},{"level":"4 درجات","description":"مقارنة صحيحة لنوعين فقط"},{"level":"درجتان","description":"عناصر متفرقة صحيحة أو المثالان فقط"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["القول إن المواد المتأينة الضعيفة لا توصل التيار","عدّ السكروز مادة متأينة لأنه يذوب","الخلط بين الذوبان والتأين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (8 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.427Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الخطوات: أُركّب دارة كهربائية من مصدر كهربائي ومصباح وقطبين، وأغمس القطبين في كل محلول على حدة بالعمق نفسه وأغسلهما بالماء المقطر بين كل اختبار وآخر، وألاحظ إضاءة المصباح. النتائج: المحلول الذي يضيء معه المصباح إضاءة ساطعة هو محلول المادة المتأينة القوية؛ لأنها تنتج أيونات كثيرة. والمحلول الذي يضيء معه المصباح إضاءة خافتة هو محلول المادة المتأينة الضعيفة؛ لأنها تنتج أيونات قليلة. والمحلول الذي لا يضيء معه المصباح هو محلول المادة غير المتأينة؛ لأنها لا تنتج أيونات.', '["تركيب الدارة واختبار كل محلول بالظروف نفسها","إضاءة ساطعة: متأينة قوية مع التفسير","إضاءة خافتة: متأينة ضعيفة مع التفسير","لا إضاءة: غير متأينة مع التفسير"]'::jsonb, '[]'::jsonb, '[{"element":"خطوات التجربة وضبط المتغيرات","marks":1},{"element":"نتيجة القوية وتفسيرها","marks":1},{"element":"نتيجة الضعيفة وتفسيرها","marks":1},{"element":"نتيجة غير المتأينة وتفسيرها","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصميم سليم مع نتائج وتفسيرات صحيحة للمحاليل الثلاثة"},{"level":"3 درجات","description":"نتائج وتفسيرات صحيحة مع نقص في الخطوات أو ضبط المتغيرات"},{"level":"درجتان","description":"نتائج صحيحة دون تفسير، أو تفسير محلولين فقط"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["إغفال غسل القطبين أو تثبيت الظروف","عكس دلالة الإضاءة الساطعة والخافتة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.427Z"}'::jsonb),
('essay', 3, null::int, null, null, 'كلوريد الصوديوم مركب أيوني يتفكك في الماء تفككًا يُنتج أيونات كثيرة في المحلول، فيوصل محلوله التيار الكهربائي توصيلًا جيدًا؛ لذا يُصنَّف مادة متأينة قوية. معادلة التفكك: NaCl(s) → Na⁺(aq) + Cl⁻(aq). أما السكروز فمركب جزيئي تذوب جزيئاته في الماء دون أن تتأين، فلا توجد في محلوله أيونات تحمل التيار، ولذلك لا يوصل التيار الكهربائي؛ فهو مادة غير متأينة.', '["NaCl ينتج أيونات كثيرة فهو متأين قوي","معادلة التفكك الصحيحة","السكروز يذوب دون تأين","غياب الأيونات يعني عدم التوصيل"]'::jsonb, '[]'::jsonb, '[{"element":"تفسير تصنيف NaCl","marks":1},{"element":"معادلة التفكك","marks":1},{"element":"ذوبان السكروز دون تأين","marks":1},{"element":"ربط غياب الأيونات بعدم التوصيل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير ومعادلة وتوضيح صحيحة كاملة"},{"level":"3 درجات","description":"نقص عنصر واحد"},{"level":"درجتان","description":"عنصران صحيحان"},{"level":"درجة واحدة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["كتابة المعادلة دون حالات المواد أو بشحنات خاطئة","القول إن السكروز لا يذوب في الماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-17T11:36:22.427Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
