('mcq', 3, 1, 'AlCl₃(s) → Al³⁺(aq) + 3Cl⁻(aq)، فكل 1 mol ينتج 1 mol من Al³⁺ و3 mol من Cl⁻، أي 4 mol من الجسيمات.', '["افترض أن AlCl₃ ينتج أيونين كما في NaCl.","","عدّ ثلاثة جسيمات كما في Na₂SO₄ دون ملاحظة أن AlCl₃ ينتج Al³⁺ و3Cl⁻.","أهمل التفكك تمامًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-17T11:36:22.428Z"}'::jsonb),
('mcq', 4, 2, 'الأثر في الضغط البخاري يزداد بزيادة أعداد الجسيمات: الجلوكوز والإيثانول 1 mol، وNaCl: 2 mol، وNa₂SO₄ → 2Na⁺ + SO₄²⁻: 3 mol؛ فأكبرها Na₂SO₄.', '["غير متأين، فينتج 1 mol من الجسيمات فقط.","غير متأين، فينتج 1 mol من الجسيمات فقط.","","ينتج 2 mol من الجسيمات، وهي أقل من 3 mol الناتجة عن Na₂SO₄."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.428Z"}'::jsonb),
('mcq', 5, 1, 'السكروز غير متأين فمولالية جسيماته 0.10 m فقط، بينما NaCl: 0.20 m، وNa₂SO₄: 0.30 m، وAlCl₃: 0.40 m؛ فأقل انخفاض في درجة التجمد للسكروز.', '["مولالية جسيماته الفعلية 0.20 m فانخفاضه أكبر من السكروز.","","مولالية جسيماته الفعلية 0.30 m فانخفاضه أكبر من السكروز.","مولالية جسيماته الفعلية 0.40 m، وهو الأكبر انخفاضًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.428Z"}'::jsonb),
('mcq', 6, 0, 'CaCl₂ → Ca²⁺ + 2Cl⁻، فكل 0.50 mol ينتج 0.50 × 3 = 1.5 mol من الجسيمات في 1.0 kg من الماء، أي 1.5 m.', '["","أهمل تفكك CaCl₂ واستعمل عدد مولات الصيغة.","عدّ أيونين فقط بدل ثلاثة (Ca²⁺ و2Cl⁻).","عدّ أربعة جسيمات بدل ثلاثة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.429Z"}'::jsonb),
('mcq', 7, 2, 'مولالية جسيمات NaCl الفعلية = 0.20 × 2 = 0.40 m، ومولالية الجلوكوز 0.20 m؛ ولأن ΔTb يتناسب طرديًا مع المولالية الفعلية فارتفاع NaCl ضعف ارتفاع الجلوكوز.', '["عكس النسبة؛ فالمذاب الذي ينتج جسيمات أكثر يرفع الغليان أكثر.","المساواة تصح للمواد غير المتأينة فقط، أما NaCl فينتج ضعف عدد الجسيمات.","","NaCl ينتج جسيمين فقط فالنسبة 2:1 لا 3:1."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.429Z"}'::jsonb),
('essay', 1, null::int, null, null, 'NaCl → Na⁺ + Cl⁻ (2 mol). Na₂SO₄ → 2Na⁺ + SO₄²⁻ (3 mol). AlCl₃ → Al³⁺ + 3Cl⁻ (4 mol). الأثر في الضغط البخاري يزداد بزيادة عدد الجسيمات، فالترتيب التصاعدي للأثر: NaCl ثم Na₂SO₄ ثم AlCl₃.', '["معادلة NaCl وعدد الجسيمات 2","معادلة Na₂SO₄ وعدد الجسيمات 3","معادلة AlCl₃ وعدد الجسيمات 4","الترتيب الصحيح مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"NaCl","marks":1},{"element":"Na₂SO₄","marks":1},{"element":"AlCl₃","marks":1},{"element":"الترتيب والتعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"المعادلات والأعداد والترتيب صحيحة"},{"level":"3 درجات","description":"خطأ واحد"},{"level":"درجتان","description":"معادلتان صحيحتان أو الترتيب فقط"},{"level":"درجة واحدة","description":"معادلة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["عدّ Na₂SO₄ منتجًا جسيمين","عدّ AlCl₃ منتجًا ثلاثة جسيمات","ترتيب عكسي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.429Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) NaCl ينتج 0.50 mol من الجسيمات في 1.0 kg، أي 0.50 m؛ والسكروز غير متأين فمولالية جسيماته 0.25 m. (ب) النسبة 2:1؛ لأن NaCl ينتج ضعف عدد الجسيمات والخواص الجامعة تعتمد على عدد الجسيمات. (ج) ΔTf(NaCl) = 1.86 × 0.50 = 0.93 °C، وΔTf(السكروز) = 1.86 × 0.25 = 0.47 °C.', '["مولالية NaCl الفعلية 0.50 m","مولالية السكروز 0.25 m","النسبة 2:1 مع التعليل","ΔTf لكل منهما"]'::jsonb, '["NaCl → Na⁺ + Cl⁻: 0.25 mol × 2 = 0.50 mol جسيمات ÷ 1.0 kg = 0.50 m","السكروز: 0.25 mol ÷ 1.0 kg = 0.25 m","النسبة 0.50 ÷ 0.25 = 2","ΔTf(NaCl) = 1.86 × 0.50 = 0.93 °C","ΔTf(السكروز) = 1.86 × 0.25 = 0.465 ≈ 0.47 °C"]'::jsonb, '[{"element":"مولالية الجسيمات لكل منهما","marks":1},{"element":"النسبة والتعليل","marks":1},{"element":"ΔTf لـ NaCl","marks":1},{"element":"ΔTf للسكروز","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الأجزاء صحيحة"},{"level":"3 درجات","description":"خطأ واحد"},{"level":"درجتان","description":"جزءان صحيحان"},{"level":"درجة واحدة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["إهمال تفكك NaCl","ضرب مولالية السكروز في 2","استعمال Kb بدل Kf"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.429Z"}'::jsonb),
('essay', 3, null::int, null, null, 'قول الطالب غير صحيح؛ فإذابة 1 mol من NaCl في 1 kg ماء تنتج 2 mol من الجسيمات (Na⁺ وCl⁻)، أي أن مولالية الجسيمات 2 m. مولالية جسيمات NaCl 0.10 m = 0.10 × 2 = 0.20 m، ومولالية الجلوكوز (غير متأين) = 0.15 m. وبما أن الارتفاع في درجة الغليان يتناسب طرديًا مع مولالية الجسيمات، فمحلول NaCl 0.10 m يغلي عند درجة أعلى.', '["الحكم بخطأ القول مع التعليل بالتفكك","مولالية جسيمات NaCl = 0.20 m","مولالية الجلوكوز = 0.15 m","التنبؤ الصحيح مع التعليل"]'::jsonb, '["NaCl → Na⁺ + Cl⁻: 1 mol ينتج 2 mol","0.10 m × 2 = 0.20 m","الجلوكوز 0.15 m","0.20 m > 0.15 m فارتفاع غليان NaCl أكبر"]'::jsonb, '[{"element":"تقويم القول مع التعليل","marks":1},{"element":"مولالية جسيمات NaCl","marks":1},{"element":"مولالية الجلوكوز","marks":1},{"element":"التنبؤ والتبرير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الأجزاء صحيحة"},{"level":"3 درجات","description":"خطأ واحد"},{"level":"درجتان","description":"جزءان صحيحان"},{"level":"درجة واحدة","description":"جزء واحد صحيح"},{"level":"صفر","description":"تأييد قول الطالب أو إجابة متروكة"}]'::jsonb, '["تفضيل الجلوكوز لأن تركيزه الاسمي أكبر","إهمال تفكك NaCl"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.430Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
