('mcq', 5, 'يبين الجدول الضغط البخاري للماء النقي وثلاثة محاليل مائية عند 25 °C. ما الاستنتاج الذي تدعمه البيانات؟', '{"headers":["المحلول","مولالية المذاب (m)","الضغط البخاري عند 25 °C (mmHg)"],"rows":[["ماء نقي","0","23.8"],["محلول 1","1.0","23.4"],["محلول 2","2.0","23.0"],["محلول 3","3.0","22.6"]]}'::jsonb, '["كلما زاد عدد جسيمات المذاب زاد الضغط البخاري","الضغط البخاري للمحلول يساوي دائمًا الضغط البخاري للمذيب النقي","الضغط البخاري لا يعتمد على تركيز المذاب","كلما زاد عدد جسيمات المذاب قل الضغط البخاري"]'::jsonb, 'تحليل', 'تفسير بيانات', 'متوسط', 'الكتاب ص 39 — الانخفاض في الضغط البخاري'),
('mcq', 6, 'وُضع في وعاءين مغلقين متماثلين، عند 25 °C، ماء نقي في الأول ومحلول سكر في الثاني. بعد الوصول إلى الاتزان الديناميكي، أيّ العبارات صحيحة؟', null, '["الضغط البخاري في الوعاء الثاني أكبر منه في الأول","الضغط البخاري في الوعاء الثاني أقل منه في الأول","لا يحدث تبخر في الوعاء الثاني بسبب وجود السكر","سرعة التبخر في الوعاء الثاني تساوي ضعف سرعتها في الأول"]'::jsonb, 'تحليل', 'تفسير موقف', 'صعب', 'الكتاب ص 39 — الانخفاض في الضغط البخاري'),
('mcq', 7, 'أيّ التصورات الآتية يمثل بصورة صحيحة سطح محلول يحتوي مذابًا غير متطاير؟', null, '["سطح تشغله جسيمات المذيب فقط مع تبخر عدد أكبر منها","سطح تشغله جسيمات المذاب فقط ولا يتبخر منه شيء","سطح تشغله جسيمات مذيب وجسيمات مذاب معًا، فيتبخر عدد أقل من جسيمات المذيب","سطح تشغله جسيمات المذاب التي تتبخر بدل المذيب"]'::jsonb, 'فهم', 'تمييز تصور', 'صعب', 'الكتاب ص 39 — الانخفاض في الضغط البخاري'),
('essay', 1, 'فسّر انخفاض الضغط البخاري لمحلول مائي يحتوي مذابًا غير متطاير مقارنة بالماء النقي، مستعينًا بتصور جسيمي لسطح السائل.', null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 39 — الانخفاض في الضغط البخاري'),
('essay', 2, 'محلولان مائيان لهما المولالية نفسها 0.10 m: الأول من الجلوكوز والثاني من Na₂SO₄. (أ) أيهما ضغطه البخاري أقل؟ (ب) فسّر ذلك بحساب عدد مولات الجسيمات الناتجة من 1 mol من كل مادة. (ج) لماذا يُعدّ الانخفاض في الضغط البخاري خاصية جامعة؟', null, null, 'تطبيق', 'تنبؤ وتفسير', 'صعب', 'الكتاب ص 39 — الانخفاض في الضغط البخاري'),
('essay', 3, 'رسم طالب منحنيين للضغط البخاري مقابل درجة الحرارة، أحدهما للماء النقي والآخر لمحلول مائي لمذاب غير متطاير، لكنه وضع منحنى المحلول فوق منحنى الماء النقي. قوّم رسم الطالب مع التعليل، وبيّن كيف يجب أن يكون الموضع الصحيح.', null, null, 'تقويم', 'تقويم رسم', 'صعب', 'الكتاب ص 39 — الانخفاض في الضغط البخاري')
