from (values
('mcq', 1, 0, 'الضغط البخاري هو الضغط الناتج عن بخار السائل عندما يكون في حالة اتزان ديناميكي مع سائله في وعاء مغلق عند درجة حرارة وضغط ثابتين.', '["","هذا هو الضغط الجوي لا الضغط البخاري.","هذا هو الضغط الأسموزي.","التعريف يرتبط بحالة اتزان بين البخار والسائل لا بتحويل السائل كله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.430Z"}'::jsonb),
('mcq', 2, 1, 'تقلل المواد المذابة غير المتطايرة الضغط البخاري للمحلول، فالضغط البخاري للمحلول أقل منه للمذيب النقي.', '["المذاب غير المتطاير يقلل الضغط البخاري ولا يرفعه.","","المذاب يشغل جزءًا من سطح السائل فيتغير الضغط البخاري.","تبقى جسيمات المذيب في السطح قادرة على التبخر، فينخفض الضغط ولا ينعدم."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.430Z"}'::jsonb),
('mcq', 3, 2, 'في المحلول يحتل المذاب جزءًا من مساحة السطح، فيتحول عدد أقل من جسيمات المذيب إلى الحالة الغازية وينخفض الضغط البخاري.', '["المذاب غير المتطاير قليل الميل إلى التبخر.","الانخفاض سببه شغل السطح وقلة الجسيمات المتبخرة، والمذيب يستمر في التبخر بكمية أقل.","","المذاب لا يغير درجة حرارة المحلول، والضغط البخاري يزداد بارتفاع الحرارة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.430Z"}'::jsonb),
('mcq', 4, 0, 'كلما ازداد عدد جسيمات المذاب قل الضغط البخاري؛ وAlCl₃ ينتج أربعة جسيمات لكل وحدة، أكثر من NaCl (2) والمواد غير المتأينة (1)، فله أقل ضغط بخاري.', '["","ينتج جسيمين فقط، أقل من AlCl₃.","غير متأين فينتج أقل عدد من الجسيمات.","غير متأين فينتج أقل عدد من الجسيمات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-17T11:36:22.431Z"}'::jsonb),
('mcq', 5, 3, 'الضغط البخاري يتناقص من 23.8 إلى 23.4 إلى 23.0 إلى 22.6 mmHg مع زيادة مولالية المذاب (عدد الجسيمات)، فكلما زاد عدد جسيمات المذاب قل الضغط البخاري.', '["البيانات تظهر نقصان الضغط البخاري بزيادة المولالية.","جميع قيم المحاليل أقل من قيمة الماء النقي.","القيم تتناقص بانتظام مع زيادة المولالية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.431Z"}'::jsonb),
('mcq', 6, 1, 'السكر مذاب غير متطاير يشغل جزءًا من سطح المحلول فيقل ما يتبخر من الماء، فيستقر الاتزان عند ضغط بخاري أقل من ضغط الماء النقي.', '["المذاب غير المتطاير يخفض الضغط البخاري فلا يكون أكبر.","","يتبخر عدد أقل من جسيمات الماء لكن التبخر لا ينعدم.","المحلول يتبخر منه عدد أقل من الجسيمات فسرعة التبخر أقل لا أكبر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-17T11:36:22.431Z"}'::jsonb),
('mcq', 7, 2, 'سطح المحلول يشغله مذاب ومذيب معًا، فيقل عدد جسيمات المذيب المتبخرة وينخفض الضغط البخاري.', '["هذا تصور المذيب النقي.","جسيمات المذيب تبقى على السطح ويتبخر بعضها.","","المذاب غير المتطاير لا يتبخر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.431Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الضغط البخاري ناتج عن جسيمات المذيب التي تتبخر من سطح السائل. في الماء النقي يشغل جسيمات الماء السطح كله فيتبخر منها عدد كبير. وفي المحلول تحتل جسيمات المذاب غير المتطاير جزءًا من مساحة السطح، فيقل عدد جسيمات الماء المتواجدة على السطح، فيتحول عدد أقل منها إلى الحالة الغازية، وبذلك ينخفض الضغط البخاري. وكلما زاد عدد جسيمات المذاب قل الضغط البخاري أكثر.', '["الضغط البخاري يأتي من تبخر جسيمات المذيب من السطح","المذاب يشغل جزءًا من السطح","يتبخر عدد أقل من جسيمات المذيب فينخفض الضغط البخاري","زيادة الجسيمات تزيد الانخفاض"]'::jsonb, '[]'::jsonb, '[{"element":"مصدر الضغط البخاري","marks":1},{"element":"شغل المذاب للسطح","marks":1},{"element":"قلة المتبخر وانخفاض الضغط","marks":1},{"element":"أثر زيادة عدد الجسيمات","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل"},{"level":"3 درجات","description":"نقص عنصر"},{"level":"درجتان","description":"عنصران"},{"level":"درجة واحدة","description":"عنصر واحد"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["القول إن المذاب يتبخر ويخفض الضغط","القول إن المذاب يرفع الضغط","الخلط بالضغط الجوي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.431Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) محلول Na₂SO₄ ضغطه البخاري أقل. (ب) الجلوكوز غير متأين فينتج 1 mol من الجسيمات لكل 1 mol؛ أما Na₂SO₄ → 2Na⁺ + SO₄²⁻ فينتج 3 mol، فتكون مولالية جسيماته الفعلية 0.30 m مقابل 0.10 m للجلوكوز، فيشغل عدد أكبر من الجسيمات السطح ويقل التبخر أكثر. (ج) لأنه يعتمد على عدد جسيمات المذاب لا على طبيعتها.', '["Na₂SO₄ أقل ضغطًا بخاريًا","الجلوكوز 1 mol وNa₂SO₄ 3 mol","المولاليتان الفعليتان 0.10 m و0.30 m","الخاصية جامعة لاعتمادها على عدد الجسيمات"]'::jsonb, '["الجلوكوز: 0.10 m × 1 = 0.10 m","Na₂SO₄ → 2Na⁺ + SO₄²⁻: 0.10 m × 3 = 0.30 m","الأكبر عددًا للجسيمات هو الأقل ضغطًا بخاريًا"]'::jsonb, '[{"element":"(أ) الحكم","marks":1},{"element":"(ب) الحساب والتفسير","marks":2},{"element":"(ج) التعليل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الأجزاء صحيحة"},{"level":"3 درجات","description":"خطأ بسيط في أحد الأجزاء"},{"level":"درجتان","description":"جزءان صحيحان"},{"level":"درجة واحدة","description":"جزء واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["إهمال تفكك Na₂SO₄","عدّه ينتج جسيمين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.432Z"}'::jsonb),
('essay', 3, null::int, null, null, 'رسم الطالب خاطئ. المذاب غير المتطاير يقلل الضغط البخاري للمذيب؛ لأن جسيماته تشغل جزءًا من سطح السائل فيتبخر منه عدد أقل من جسيمات الماء. لذا يجب أن يقع منحنى المحلول أسفل منحنى الماء النقي عند أي درجة حرارة، لأن ضغطه البخاري أقل.', '["الحكم بخطأ الرسم","المذاب يقلل الضغط البخاري بشغله جزءًا من السطح","منحنى المحلول يجب أن يكون أسفل منحنى الماء"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم","marks":1},{"element":"التعليل","marks":1},{"element":"الموضع الصحيح","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الحكم والتعليل والموضع صحيحة"},{"level":"درجتان","description":"عنصران"},{"level":"درجة واحدة","description":"عنصر واحد"},{"level":"صفر","description":"تأييد الرسم أو إجابة متروكة"}]'::jsonb, '["القول إن المذاب يرفع الضغط البخاري","الخلط بين المحورين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.432Z"}'::jsonb)
