('mcq', 2, 'ما الانخفاض في درجة التجمد ΔTf؟', null, '["درجة تجمد المحلول مطروحًا منها درجة تجمد المذيب النقي","درجة تجمد المذيب النقي مطروحًا منها درجة تجمد المحلول","مجموع درجتي تجمد المذيب النقي والمحلول","درجة تجمد المحلول نفسها"]'::jsonb, 'تذكر', 'تعريف مفهوم', 'سهل', 'الكتاب ص 41 — الانخفاض في درجة التجمد'),
('mcq', 3, 'إذا كانت درجة تجمد الماء النقي 0.0 °C وتجمد محلول مائي عند −0.93 °C، فما قيمة الانخفاض في درجة التجمد ΔTf؟', null, '["−0.93 °C","0.0 °C","0.93 °C","1.86 °C"]'::jsonb, 'فهم', 'حساب بسيط', 'سهل', 'الكتاب ص 41 — الانخفاض في درجة التجمد'),
('mcq', 4, 'يبين الجدول درجات تجمد الماء النقي وثلاثة محاليل مائية. ما العلاقة بين عدد جسيمات المذاب ودرجة التجمد؟', '{"headers":["المحلول","المولالية (m) لمذاب غير متأين","درجة التجمد (°C)"],"rows":[["ماء نقي","0","0.0"],["أ","0.10","−0.19"],["ب","0.20","−0.37"],["ج","0.30","−0.56"]]}'::jsonb, '["كلما زاد عدد جسيمات المذاب ارتفعت درجة التجمد","درجة التجمد لا تتأثر بعدد جسيمات المذاب","كلما قل عدد جسيمات المذاب انخفضت درجة التجمد أكثر","كلما زاد عدد جسيمات المذاب انخفضت درجة التجمد أكثر"]'::jsonb, 'تحليل', 'تفسير بيانات', 'متوسط', 'الكتاب ص 42 — الانخفاض في درجة التجمد والجدول 1-6'),
('mcq', 5, 'ما الذي يميز نطاق درجات الحرارة التي يبقى فيها المحلول المائي سائلًا عن نطاق الماء النقي؟', null, '["نطاقه أكبر؛ لأن درجة تجمده أقل ودرجة غليانه أعلى","نطاقه أصغر؛ لأن درجة تجمده أعلى ودرجة غليانه أقل","نطاقه مساوٍ لنطاق الماء النقي","نطاقه أكبر؛ لأن درجة تجمده أعلى ودرجة غليانه أعلى"]'::jsonb, 'فهم', 'تفسير رسم', 'متوسط', 'الكتاب ص 41 — الانخفاض في درجة التجمد'),
('mcq', 6, 'إذا أضيف الملح إلى الماء فإن ماء المحلول لا يتجمد عند 0 °C. أيّ العبارات الآتية تفسر ذلك؟', null, '["جسيمات المذاب تمنع جسيمات الماء من الترتب في البنية المنتظمة للجليد عند 0 °C","الملح يتحول إلى جليد أولًا فيرفع درجة التجمد","الملح يزيد قوى التجاذب بين جزيئات الماء فيصعب فصلها","الملح يرفع الضغط البخاري للماء فيمنع التجمد"]'::jsonb, 'فهم', 'تعليل', 'صعب', 'الكتاب ص 41 — الانخفاض في درجة التجمد'),
('mcq', 7, 'محلولان مائيان لمذابين غير متأينين، مولالية الأول 0.20 m ومولالية الثاني 0.60 m. أيّ العبارات صحيحة؟', null, '["الانخفاض في درجة تجمد الأول ثلاثة أمثال الثاني","الانخفاض في درجة تجمد الثاني ثلاثة أمثال الانخفاض في درجة تجمد الأول","الانخفاضان متساويان لأن المذابين غير متأينين","درجة تجمد الثاني أعلى من درجة تجمد الأول"]'::jsonb, 'تحليل', 'مقارنة نسبية', 'صعب', 'الكتاب ص 42 — الانخفاض في درجة التجمد والجدول 1-6'),
('essay', 1, 'فسّر على المستوى الجسيمي لماذا تكون درجة تجمد المحلول المائي أقل من درجة تجمد الماء النقي.', null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 41 — الانخفاض في درجة التجمد'),
('essay', 2, 'محلول مائي لمذاب غير متطاير وغير متأين يتجمد عند −0.558 °C. (أ) احسب الانخفاض في درجة التجمد ΔTf. (ب) احسب مولالية المحلول (Kf للماء = 1.86 °C/m). (ج) فسّر لماذا لا يتجمد هذا المحلول عند 0.0 °C.', null, null, 'تطبيق', 'حساب وتفسير', 'متوسط', 'الكتاب ص 42 — الانخفاض في درجة التجمد والجدول 1-6'),
('essay', 3, 'يبيّن الجدول الآتي درجتي التجمد والغليان للماء النقي ولمحلول مائي لمذاب غير متطاير عند 1 atm. قارن بين نقطتي التجمد ونقطتي الغليان، ثم اشرح لماذا يكون نطاق الحالة السائلة للمحلول أكبر منه للماء النقي، وحدّد مقداري ΔTf وΔTb.', '{"headers":["السائل","درجة التجمد (°C)","درجة الغليان (°C)"],"rows":[["الماء النقي","0.0","100.0"],["المحلول المائي","-1.9","100.5"]]}'::jsonb, null, 'تحليل', 'تفسير رسم بياني', 'صعب', 'الكتاب ص 41 — الانخفاض في درجة التجمد')
