('essay', 1, null::int, null, null, 'عند التجمد تترتب جسيمات المذيب (الماء) في بنية أكثر تنظيمًا في الحالة الصلبة. وفي المحلول تعمل جسيمات المذاب على إضعاف قوى التجاذب بين جسيمات المذيب، فتمنع المذيب من الوصول إلى الحالة الصلبة عند درجة تجمده، لذا يلزم تبريد المحلول إلى درجة أقل ليتجمد، فتكون درجة تجمد المحلول دائمًا أقل من درجة تجمد المذيب النقي.', '["ترتب جسيمات المذيب في بنية منتظمة عند التجمد","جسيمات المذاب تضعف التجاذب بين جسيمات المذيب","لا يتجمد عند درجة تجمد المذيب النقي","يحتاج إلى درجة أقل"]'::jsonb, '[]'::jsonb, '[{"element":"البنية المنتظمة في الصلب","marks":1},{"element":"إضعاف المذاب للتجاذب","marks":1},{"element":"منع التجمد عند درجة المذيب النقي","marks":1},{"element":"النتيجة: درجة تجمد أقل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل"},{"level":"3 درجات","description":"نقص عنصر"},{"level":"درجتان","description":"عنصران"},{"level":"درجة واحدة","description":"عنصر"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["القول إن المذاب يرفع درجة التجمد","الخلط مع الارتفاع في درجة الغليان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (54%)"}],"at":"2026-10-17T11:36:22.434Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) ΔTf = 0.000 − (−0.558) = 0.558 °C. (ب) m = ΔTf ÷ Kf = 0.558 ÷ 1.86 = 0.300 m. (ج) لأن جسيمات المذاب تضعف قوى التجاذب بين جزيئات الماء فتمنعها من الترتب في بنية الجليد عند 0.0 °C، فيلزم تبريده إلى درجة أقل.', '["ΔTf = 0.558 °C","m = 0.300 m","تفسير جسيمي لعدم التجمد عند 0.0 °C"]'::jsonb, '["ΔTf = 0.000 °C − (−0.558 °C) = 0.558 °C","m = 0.558 °C ÷ 1.86 °C/m = 0.300 m"]'::jsonb, '[{"element":"ΔTf","marks":1},{"element":"المولالية","marks":1},{"element":"التفسير","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"جميع الأجزاء صحيحة"},{"level":"درجتان","description":"جزءان"},{"level":"درجة واحدة","description":"جزء واحد"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["كتابة ΔTf سالبة","ضرب بدل القسمة","استعمال Kb"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.434Z"}'::jsonb),
('essay', 3, null::int, null, null, 'نقطة تجمد المحلول (-1.9 °C) أقل من نقطة تجمد الماء النقي (0 °C)، ونقطة غليان المحلول (100.5 °C) أعلى من نقطة غليان الماء النقي (100 °C). لذا يمتد نطاق الحالة السائلة للمحلول من درجة تجمد أقل إلى درجة غليان أعلى، فيكون أكبر من نطاق الماء النقي. ΔTf = 0.0 − (−1.9) = 1.9 °C (الانخفاض في درجة التجمد)، وΔTb = 100.5 − 100.0 = 0.5 °C (الارتفاع في درجة الغليان).', '["تجمد المحلول أقل","غليان المحلول أعلى","النطاق السائل أكبر","تحديد ΔTf وΔTb"]'::jsonb, '[]'::jsonb, '[{"element":"مقارنة نقطتي التجمد","marks":1},{"element":"مقارنة نقطتي الغليان","marks":1},{"element":"تعليل اتساع النطاق","marks":1},{"element":"تحديد ΔTf وΔTb","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع العناصر صحيحة"},{"level":"3 درجات","description":"نقص عنصر"},{"level":"درجتان","description":"عنصران"},{"level":"درجة واحدة","description":"عنصر"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["الخلط بين ΔTf وΔTb","عكس موضع منحنى المحلول"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.435Z"}'::jsonb)
