('mcq', 1, 'لماذا يُرشّ الملح على الطرق المغطاة بالجليد في الشتاء؟', null, '["لأن الملح يرفع درجة حرارة الجو فيذيب الجليد","لأن الملح يرفع درجة تجمد الماء فيسرّع انصهار الجليد","لأن الملح يقلل درجة تجمد الماء فينصهر الجليد","لأن الملح يزيد الضغط البخاري للماء فيتبخر الجليد"]'::jsonb, 'تذكر', 'تذكر تطبيق', 'سهل', 'الكتاب ص 41 — الانخفاض في درجة التجمد'),
('mcq', 2, 'ما سبب إضافة الملح إلى الجليد المحيط بالوعاء عند صنع الآيس كريم؟', null, '["رفع درجة التجمد ليذوب الجليد ببطء","زيادة حلاوة الآيس كريم","رفع درجة غليان الماء الناتج","تقليل درجة التجمد ليتجمد الآيس كريم"]'::jsonb, 'تذكر', 'تذكر تطبيق', 'سهل', 'الكتاب ص 41 — الانخفاض في درجة التجمد'),
('mcq', 3, 'أيّ التطبيقات الآتية يعتمد على الانخفاض في درجة التجمد؟', null, '["منع تكوّن الجليد في ماء مبرد السيارة شتاءً بإضافة مانع تجمد","استعمال الملح لرفع درجة غليان ماء الطهي","إضافة السكر لزيادة حلاوة الشاي","غلي الماء في قدر مغلق لرفع ضغطه"]'::jsonb, 'فهم', 'تصنيف تطبيقات', 'متوسط', 'الكتاب ص 42 — الانخفاض في درجة التجمد والجدول 1-6'),
('mcq', 4, 'لماذا تستطيع الأسماك التي تعيش في المياه المالحة في المناطق القطبية البقاء أحياء؟', null, '["لأن الملح يرفع درجة حرارة المياه القطبية","لأن وجود الملح في الماء يقلل درجة تجمده فيحافظ على المياه سائلة","لأن الملح يزيد الضغط البخاري للماء","لأن الملح يحوّل الماء إلى جليد عازل"]'::jsonb, 'تذكر', 'تذكر تطبيق', 'متوسط', 'الكتاب ص 41 — الانخفاض في درجة التجمد'),
('mcq', 5, 'يبين الجدول درجة تجمد ماء نقي وثلاثة محاليل. أيّها أنسب لإذابة الجليد على طريق عند −5 °C، علمًا بأن التركيز نفسه (1 m) وجميع المواد متاحة؟', '{"headers":["المذاب","نوعه","درجة التجمد التقريبية للمحلول 1 m (°C)"],"rows":[["الجلوكوز","غير متأين","−1.9"],["NaCl","متأين قوي","−3.7"],["CaCl₂","متأين قوي","−5.6"],["الماء النقي","—","0.0"]]}'::jsonb, '["الجلوكوز C₆H₁₂O₆","كلوريد الصوديوم NaCl","كلوريد الكالسيوم CaCl₂","الماء النقي دون إضافات"]'::jsonb, 'تطبيق', 'اختيار مادة', 'صعب', 'الكتاب ص 41 — الانخفاض في درجة التجمد'),
('mcq', 6, 'أيّ العبارات الآتية تفسر لماذا يُفضَّل ملح الطعام الخشن على الناعم في إذابة الجليد، مع ثبات الكتلة؟', null, '["حبيبات الملح الخشن تخفض درجة التجمد أكثر بسبب كبر حجمها","الملح الناعم لا يتفكك في الماء إلى أيونات","الملح الخشن يتبخر بسهولة فيخفض الضغط البخاري","خفض درجة التجمد يتحدد بعدد الجسيمات لا بحجم الحبيبات"]'::jsonb, 'تحليل', 'تحليل مفهوم', 'صعب', 'الكتاب ص 41 — الانخفاض في درجة التجمد'),
('mcq', 7, 'وُضع الجليد في كأس مع الماء ثم أضيف الملح فانخفضت درجة حرارة الخليط إلى ما دون 0 °C دون أن يتجمد الماء كله. ما تفسير بقاء جزء من الماء سائلًا؟', null, '["الملح المذاب خفض درجة تجمد الماء إلى ما دون 0 °C","الملح المذاب رفع درجة تجمد الماء فوق 0 °C","الملح المذاب منع الماء من فقدان الحرارة","الملح المذاب رفع الضغط الجوي فوق الخليط"]'::jsonb, 'فهم', 'تفسير تجربة', 'متوسط', 'الكتاب ص 42 — الانخفاض في درجة التجمد والجدول 1-6'),
('essay', 1, 'اذكر تطبيقين حياتيين للانخفاض في درجة التجمد، ووضح في كل منهما كيف يعمل الملح.', null, null, 'تذكر', 'ذكر أمثلة', 'سهل', 'الكتاب ص 41 — الانخفاض في درجة التجمد'),
('essay', 2, 'يقول طالب إن رش الملح على الجليد يذيب الجليد لأن الملح «يسخّن» الجليد. قوّم قوله، وبيّن التفسير العلمي الصحيح، ثم وضّح لماذا قد لا ينفع الملح إذا انخفضت درجة الحرارة كثيرًا جدًا.', null, null, 'تقويم', 'تقويم عبارة', 'صعب', 'الكتاب ص 41 — الانخفاض في درجة التجمد'),
('essay', 3, 'اقترح محلولًا مانعًا للتجمد لماء مبرد سيارة في منطقة باردة جدًا، موضحًا المادة التي تستعملها ولماذا تفضل مادة غير متأينة، ومؤكدًا ما تتوقعه لدرجة تجمد الماء.', null, null, 'إبداع', 'اقتراح حل', 'صعب', 'الكتاب ص 42 — الانخفاض في درجة التجمد والجدول 1-6')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C1-L4-O11') and x.type = v.type and x.number = v.number);
