from (values
('mcq', 1, 2, 'إضافة الأملاح إلى الجليد تقلل درجة تجمده، مما يؤدي إلى انصهار الجليد على الطرق.', '["الملح لا يرفع حرارة الجو، بل يخفض درجة تجمد الماء.","الملح يخفض درجة التجمد ولا يرفعها.","","الملح غير المتطاير يخفض الضغط البخاري، والجليد لا يزول بالتبخر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-17T11:36:22.435Z"}'::jsonb),
('mcq', 2, 3, 'إضافة الملح إلى الجليد عند صنع الآيس كريم تقلل درجة التجمد، مما يسمح للماء الناتج بتجميد الآيس كريم.', '["الملح يخفض درجة التجمد لا يرفعها.","الغرض ليس تذوقيًا، بل خفض درجة تجمد خليط الجليد والماء.","رفع درجة الغليان لا علاقة له بتجميد الآيس كريم.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T11:36:22.435Z"}'::jsonb),
('mcq', 3, 0, 'مقاوم التجمد (مانع تكوّن الجليد) يحتوي على مذاب غير متأين هو جليكول الإيثيلين، ويستعمل لمنع تجمد الماء في الشتاء.', '["","هذا تطبيق للارتفاع في درجة الغليان لا الانخفاض في درجة التجمد.","لا علاقة له بالخواص الجامعة.","هذا يتعلق بالضغط الجوي لا بالمحلول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.436Z"}'::jsonb),
('mcq', 4, 1, 'وجود الملح في المناطق القطبية من المحيط ضروري لمنع المياه من التجمد، مما يسمح بالمحافظة على الحياة البحرية.', '["الملح لا يسخّن الماء، بل يخفض درجة تجمده.","","الملح غير المتطاير يخفض الضغط البخاري، وهذا لا يفسر بقاء الماء سائلًا.","الغرض منع التجمد لا تكوّن الجليد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-17T11:36:22.436Z"}'::jsonb),
('mcq', 5, 2, 'CaCl₂ → Ca²⁺ + 2Cl⁻ ينتج ثلاثة جسيمات (3 m) فيخفض درجة التجمد أكثر من NaCl (2 m) والجلوكوز (1 m)، لذلك هو الأنسب لإذابة الجليد عند −5 °C.', '["غير متأين فمولالية جسيماته 1 m فقط وانخفاض تجمده أقل.","ينتج جسيمين فانخفاضه أقل من CaCl₂ الذي ينتج ثلاثة.","","تجمد عند 0 °C ولن يذيب الجليد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T11:36:22.436Z"}'::jsonb),
('mcq', 6, 3, 'الخواص الجامعة تعتمد على عدد الجسيمات، فكتلة الملح المتساوية تنتج العدد نفسه من الأيونات سواء كان خشنًا أو ناعمًا؛ وحجم الحبيبات يؤثر في سرعة الذوبان فقط.', '["الملح يخفض درجة التجمد، وحجم الحبيبات لا يغير عدد الجسيمات.","الملح الناعم والخشن كلاهما NaCl يتفكك إلى أيونات.","الملح غير متطاير ولا يتبخر.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-17T11:36:22.436Z"}'::jsonb),
('mcq', 7, 0, 'إضافة الملح تقلل درجة تجمد الماء عن 0 °C، فيبقى الخليط سائلًا جزئيًا عند درجات أقل من 0 °C.', '["","رفع درجة التجمد يعني تجمد الماء عند أعلى من 0 °C، وهذا مخالف للملاحظة.","الحرارة تُمتص لصهر الجليد، والتفسير يتعلق بالانخفاض في درجة التجمد.","الملح لا يغير الضغط الجوي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.436Z"}'::jsonb),
('essay', 1, null::int, null, null, 'التطبيق الأول: رش الملح على الطرق المغطاة بالجليد؛ فالملح يقلل درجة تجمد الماء فينصهر الجليد. التطبيق الثاني: إضافة الملح إلى الجليد عند صنع الآيس كريم؛ فالملح يقلل درجة التجمد فتنخفض درجة حرارة الخليط ويتجمد الآيس كريم. (ويقبل أيضًا: مقاوم التجمد في مبرد السيارات، أو منع تجمد المياه القطبية للحفاظ على الحياة البحرية.)', '["تطبيق أول","عمل الملح في التطبيق الأول","تطبيق ثانٍ","عمل الملح في التطبيق الثاني"]'::jsonb, '[]'::jsonb, '[{"element":"التطبيق الأول","marks":1},{"element":"توضيح العمل","marks":1},{"element":"التطبيق الثاني","marks":1},{"element":"توضيح العمل","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تطبيقان صحيحان مع توضيح"},{"level":"3 درجات","description":"تطبيقان ونقص في توضيح"},{"level":"درجتان","description":"تطبيق واحد موضح"},{"level":"درجة واحدة","description":"ذكر تطبيق دون توضيح"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["القول إن الملح يرفع درجة التجمد","الخلط بالارتفاع في درجة الغليان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.436Z"}'::jsonb),
('essay', 2, null::int, null, null, 'قول الطالب غير صحيح؛ فالملح لا يسخّن الجليد. التفسير الصحيح أن الملح يذوب في طبقة الماء الرقيقة على الجليد فتقل درجة تجمد المحلول الناتج عن 0 °C، فينصهر الجليد عند درجات أقل من 0 °C. ولأن الانخفاض في درجة التجمد محدود بتركيز الملح (ΔTf = Kf·m)، فإذا انخفضت درجة الحرارة أكثر من الانخفاض الممكن لا يبقى المحلول سائلًا ويتجمد.', '["رفض قول الطالب","الملح يخفض درجة التجمد","ΔTf محدود بالتركيز","عند درجات أقل من درجة تجمد المحلول يتجمد"]'::jsonb, '[]'::jsonb, '[{"element":"تقويم القول","marks":1},{"element":"التفسير الصحيح","marks":1},{"element":"حدود الانخفاض","marks":1},{"element":"النتيجة عند الحرارة المنخفضة جدًا","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تقويم وتفسير وحدود صحيحة"},{"level":"3 درجات","description":"نقص عنصر"},{"level":"درجتان","description":"عنصران"},{"level":"درجة واحدة","description":"عنصر"},{"level":"صفر","description":"تأييد القول أو إجابة متروكة"}]'::jsonb, '["القول إن الملح يسخن الجليد","إهمال دور تركيز الملح"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.437Z"}'::jsonb),
('essay', 3, null::int, null, null, 'أقترح إضافة جليكول الإيثيلين، وهو مذاب غير متأين يُستعمل مانعًا للتجمد (ويقبل أي مانع تجمد غير متأين مناسب). إضافته تقلل درجة تجمد الماء في المبرد (ΔTf = Kf·m)، فلا يتجمد الماء عند 0 °C بل عند درجة أقل. ولأن المذاب غير متأين فإن كل 1 mol منه ينتج 1 mol من الجسيمات ولا يوصل محلوله التيار ويقلل التجمد كغيره من الخواص الجامعة. ونتوقع أن تنخفض درجة تجمد الماء المضاف إليه كلما زادت مولالية المذاب.', '["تحديد مادة مانعة للتجمد","تأثيرها في درجة تجمد الماء","تبرير كونها غير متأينة","توقع درجة التجمد وعلاقته بالمولالية"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد المادة","marks":1},{"element":"تأثيرها في درجة التجمد","marks":1},{"element":"التبرير","marks":1},{"element":"التوقع","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"اقتراح مبرر وتوقع صحيح"},{"level":"3 درجات","description":"نقص عنصر"},{"level":"درجتان","description":"عنصران"},{"level":"درجة واحدة","description":"عنصر"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["اقتراح مادة ترفع درجة التجمد","الخلط بين التجمد والغليان"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (3%)"}],"at":"2026-10-17T11:36:22.437Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
