select (select id from public.objectives where code = 'K3-C1-L4-O12'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما الخاصية الأسموزية؟', null, '["انتشار المذاب خلال غشاء شبه منفذ من المحلول الأعلى تركيزًا إلى الأقل تركيزًا","اختلاط الغازات أو السوائل نتيجة حركتها العشوائية دون وجود غشاء","انتقال المذيب من المحلول الأعلى تركيزًا إلى المحلول الأقل تركيزًا عبر غشاء شبه منفذ","انتشار المذيب خلال غشاء شبه منفذ من المحلول الأقل تركيزًا إلى المحلول الأعلى تركيزًا"]'::jsonb, 'تذكر', 'تعريف مفهوم', 'سهل', 'الكتاب ص 44 — الضغط الأسموزي'),
('mcq', 2, 'يفصل غشاء شبه منفذ بين محلول مخفف ومحلول مركز. ما اتجاه الحركة الصافية لجزيئات الماء؟', null, '["من المحلول المخفف إلى المحلول المركز","من المحلول المركز إلى المحلول المخفف","لا توجد حركة صافية بل تتوقف الحركة","تتحرك جزيئات الماء في اتجاه واحد فقط هو من المخفف إلى المركز"]'::jsonb, 'فهم', 'اتجاه الانتقال', 'سهل', 'الكتاب ص 44 — الضغط الأسموزي'),
('mcq', 3, 'لماذا لا تنتقل جزيئات المذاب عبر غشاء شبه منفذ يفصل بين محلول مخفف ومحلول مركز؟', null, '["لأن جزيئات المذاب أخف من جزيئات الماء","لأن الغشاء لا يسمح بمرور أي جسيمات","لأن الغشاء يسمح لبعض الجسيمات فقط بالعبور ولا تعبره جزيئات المذاب","لأن جزيئات المذاب تنجذب إلى المحلول المخفف"]'::jsonb, 'فهم', 'تعليل', 'متوسط', 'الكتاب ص 44 — الضغط الأسموزي'),
('mcq', 4, 'فُصل محلول سكروز تركيزه 0.10 m عن محلول سكروز تركيزه 0.40 m بغشاء شبه منفذ. ماذا يحدث؟', null, '["ينتقل الماء صافيًا من المحلول 0.40 m إلى المحلول 0.10 m","ينتقل السكروز من المحلول 0.40 m إلى المحلول 0.10 m","ينتقل الماء صافيًا من المحلول 0.10 m إلى المحلول 0.40 m","لا ينتقل شيء لأن المحلولين من المذاب نفسه"]'::jsonb, 'تطبيق', 'تنبؤ باتجاه الانتقال', 'متوسط', 'الكتاب ص 44 — الضغط الأسموزي'),
('mcq', 5, 'فُصل محلول NaCl تركيزه 0.20 m عن محلول جلوكوز تركيزه 0.30 m بغشاء شبه منفذ لا يعبره المذابان. في أي اتجاه يتحرك الماء صافيًا؟ (NaCl مادة متأينة قوية)', null, '["نحو محلول NaCl؛ لأن مولالية جسيماته 0.40 m وهي أعلى من 0.30 m","نحو محلول الجلوكوز؛ لأن تركيزه الاسمي 0.30 m أعلى من 0.20 m","لا يتحرك الماء لأن المحلولين مختلفان في نوع المذاب","نحو محلول الجلوكوز؛ لأن الجلوكوز لا يتأين"]'::jsonb, 'تحليل', 'تنبؤ مع الأيونات', 'صعب', 'الكتاب ص 44 — الضغط الأسموزي'),
('mcq', 6, 'ما الفرق بين الانتشار العادي والخاصية الأسموزية؟', null, '["الانتشار يحتاج إلى غشاء شبه منفذ بينما لا تحتاجه الخاصية الأسموزية","الأسموزية انتشار للمذيب عبر غشاء شبه منفذ، والانتشار اختلاط ناتج عن الحركة العشوائية","الانتشار خاص بالمذاب والخاصية الأسموزية خاصة بالغازات","لا فرق بينهما، فهما اسمان لعملية واحدة"]'::jsonb, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 44 — الضغط الأسموزي'),
('mcq', 7, 'ماذا يحدث لو استُبدل الغشاء شبه المنفذ الذي يفصل بين محلول مخفف ومحلول مركز بحاجز لا يسمح بمرور أي جسيمات؟', null, '["ينتقل الماء بسرعة أكبر نحو المحلول المركز","لا ينتقل الماء بين المحلولين فلا ينشأ ضغط أسموزي","ينتقل المذاب نحو المحلول المخفف","يتساوى التركيزان بعد فترة قصيرة"]'::jsonb, 'تحليل', 'تنبؤ بموقف', 'صعب', 'الكتاب ص 44 — الضغط الأسموزي'),
('essay', 1, 'فسّر الخاصية الأسموزية، موضحًا اتجاه انتقال جزيئات المذيب عبر الغشاء شبه المنفذ، ودور جزيئات المذاب.', null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 44 — الضغط الأسموزي'),
('essay', 2, 'وُضع محلول مركز من السكروز في أنبوب مغلق بغشاء شبه منفذ، وغُمر الأنبوب في كأس فيها ماء نقي. (أ) ما اتجاه انتقال الماء صافيًا؟ (ب) ماذا يحدث لمستوى السائل داخل الأنبوب؟ (ج) ماذا يحدث لجزيئات السكروز؟ (د) اربط ذلك بنشوء الضغط الأسموزي.', null, null, 'تطبيق', 'تطبيق وتنبؤ', 'صعب', 'الكتاب ص 44 — الضغط الأسموزي'),
('essay', 3, 'كأسان في كل منهما محلول مائي: الأولى فيها NaCl تركيزه 0.15 m، والثانية جلوكوز تركيزه 0.25 m، وتفصل بينهما غشاء شبه منفذ لا يعبره المذابان. (أ) احسب مولالية الجسيمات الفعلية في كل منهما. (ب) حدّد اتجاه انتقال الماء صافيًا مع التعليل. (ج) فسّر لماذا يعد الاعتماد على التركيز الاسمي وحده مضللًا هنا.', null, null, 'تحليل', 'حساب وتنبؤ', 'صعب', 'الكتاب ص 44 — الضغط الأسموزي')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C1-L4-O12') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'الخاصية الأسموزية هي انتشار المذيب خلال غشاء شبه منفذ من المحلول الأقل تركيزًا إلى المحلول الأعلى تركيزًا.', '["جزيئات المذاب لا تستطيع عبور الغشاء، والذي ينتشر هو المذيب.","هذا تعريف الانتشار العام لا الخاصية الأسموزية.","الاتجاه معكوس؛ فصافي حركة المذيب نحو المحلول الأعلى تركيزًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.437Z"}'::jsonb),
('mcq', 2, 0, 'تتحرك جزيئات الماء في الاتجاهين عبر الغشاء، لكن صافي حركتها (حركة الماء النهائية) يكون من المحلول المخفف إلى المحلول المركز.', '["","الاتجاه معكوس؛ فالصافي نحو الأعلى تركيزًا.","الجزيئات تتحرك في الاتجاهين لكن الصافي نحو المحلول المركز.","الجزيئات تعبر في الاتجاهين، لكن حركتها الصافية فقط نحو المركز."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-10-17T11:36:22.438Z"}'::jsonb),
('mcq', 3, 2, 'الأغشية شبه المنفذة حواجز تسمح لبعض الجسيمات بالعبور (جزيئات الماء)، أما جزيئات المذاب فلا تستطيع العبور، لذلك ينتقل الماء ويبقى المذاب.', '["التفسير يتعلق بخاصية الغشاء لا بخفة الجزيئات.","الغشاء شبه المنفذ يسمح لبعض الجسيمات (جزيئات الماء) بالعبور.","","جزيئات المذاب لا تنتقل لأنها لا تستطيع العبور وليس لانجذابها لجهة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-10-17T11:36:22.438Z"}'::jsonb),
('mcq', 4, 2, 'ينتقل المذيب (الماء) صافيًا من المحلول الأقل تركيزًا (0.10 m) إلى المحلول الأعلى تركيزًا (0.40 m) عبر الغشاء شبه المنفذ.', '["الاتجاه معكوس؛ الماء ينتقل نحو الأعلى تركيزًا.","جزيئات السكروز لا تعبر الغشاء شبه المنفذ.","","اختلاف التركيز كافٍ لحدوث صافي انتقال للماء، ولو كان المذاب نفسه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T11:36:22.438Z"}'::jsonb),
('mcq', 5, 0, 'مولالية جسيمات NaCl الفعلية = 0.20 × 2 = 0.40 m، ومولالية الجلوكوز 0.30 m؛ فمحلول NaCl أعلى تركيزًا بالجسيمات، وينتقل الماء صافيًا نحو الأعلى تركيزًا.', '["","أهمل تفكك NaCl؛ فمولالية جسيماته الفعلية 0.40 m.","اتجاه الانتقال يتحدد بعدد الجسيمات لا بنوع المذاب.","عدم التأين يعني جسيمات أقل (0.30 m) من NaCl (0.40 m)."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T11:36:22.438Z"}'::jsonb),
('mcq', 6, 1, 'الانتشار اختلاط الغازات أو السوائل الناتج عن حركتها العشوائية، أما الخاصية الأسموزية فهي انتشار المذيب خلال غشاء شبه منفذ من الأقل تركيزًا إلى الأعلى.', '["العكس صحيح؛ الخاصية الأسموزية هي التي تحتاج إلى غشاء شبه منفذ.","","الانتشار يشمل الغازات والسوائل، والخاصية الأسموزية خاصة بانتشار المذيب.","الخاصية الأسموزية حالة خاصة من الانتشار تتطلب غشاء شبه منفذ."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.438Z"}'::jsonb),
('mcq', 7, 1, 'الخاصية الأسموزية تتطلب غشاء يسمح بمرور المذيب؛ فبحاجز لا يسمح بمرور شيء لا ينتقل الماء ولا ينشأ الضغط الأسموزي.', '["الحاجز التام يمنع العبور، فلا ينتقل الماء.","","الحاجز يمنع مرور جزيئات المذاب أيضًا.","التركيزان يبقيان مختلفين لعدم انتقال الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-17T11:36:22.438Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الأغشية شبه المنفذة حواجز تسمح لبعض الجسيمات بالعبور. عند فصل محلول مخفف عن محلول مركز بغشاء شبه منفذ تتحرك جزيئات الماء في الاتجاهين، لكن صافي حركتها يكون من المحلول المخفف (الأقل تركيزًا) إلى المحلول المركز (الأعلى تركيزًا)، أما جزيئات المذاب فلا تستطيع العبور. وهذا هو انتشار المذيب عبر غشاء شبه منفذ ويسمى الخاصية الأسموزية.', '["الغشاء شبه المنفذ يسمح ببعض الجسيمات","حركة الماء في الاتجاهين","الصافي من المخفف إلى المركز","المذاب لا يعبر"]'::jsonb, '[]'::jsonb, '[{"element":"دور الغشاء","marks":1},{"element":"الحركة في الاتجاهين","marks":1},{"element":"اتجاه الصافي","marks":1},{"element":"عدم عبور المذاب","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل"},{"level":"3 درجات","description":"نقص عنصر"},{"level":"درجتان","description":"عنصران"},{"level":"درجة واحدة","description":"عنصر"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["عكس اتجاه انتقال الماء","القول إن المذاب هو الذي ينتشر"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.439Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) ينتقل الماء صافيًا من الكأس (الماء النقي، الأقل تركيزًا) إلى الأنبوب (المحلول المركز). (ب) يرتفع مستوى السائل داخل الأنبوب لدخول الماء إليه. (ج) لا تعبر جزيئات السكروز الغشاء فتبقى داخل الأنبوب. (د) الضغط الإضافي الناتج عن انتقال الماء إلى المحلول المركز هو الضغط الأسموزي.', '["اتجاه الانتقال من الكأس إلى الأنبوب","ارتفاع المستوى","السكروز لا يعبر","الضغط الإضافي هو الضغط الأسموزي"]'::jsonb, '[]'::jsonb, '[{"element":"(أ)","marks":1},{"element":"(ب)","marks":1},{"element":"(ج)","marks":1},{"element":"(د)","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"الأجزاء الأربعة صحيحة"},{"level":"3 درجات","description":"ثلاثة"},{"level":"درجتان","description":"اثنان"},{"level":"درجة واحدة","description":"جزء"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["عكس اتجاه الانتقال","القول إن السكروز يخرج إلى الكأس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.439Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) NaCl: 0.15 × 2 = 0.30 m؛ الجلوكوز غير متأين: 0.25 m. (ب) ينتقل الماء صافيًا من محلول الجلوكوز (الأقل تركيزًا بالجسيمات 0.25 m) إلى محلول NaCl (الأعلى 0.30 m)، لأن المذيب ينتقل نحو المحلول الأعلى تركيزًا. (ج) لأن NaCl يتفكك إلى أيونين فيكون عدد جسيماته ضعف عدد وحدات صيغته، فالتركيز الاسمي الأقل (0.15 m) يخفي عددًا من الجسيمات أكبر من الجلوكوز (0.25 m).', '["مولالية جسيمات NaCl = 0.30 m","مولالية الجلوكوز = 0.25 m","الماء نحو NaCl","التفسير بتفكك NaCl"]'::jsonb, '["NaCl → Na⁺ + Cl⁻: 0.15 m × 2 = 0.30 m","الجلوكوز: 0.25 m","0.30 m > 0.25 m فيتجه الماء إلى NaCl"]'::jsonb, '[{"element":"(أ) الحساب","marks":1},{"element":"(ب) الاتجاه مع التعليل","marks":2},{"element":"(ج) التفسير","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"جميع الأجزاء صحيحة"},{"level":"3 درجات","description":"نقص بسيط"},{"level":"درجتان","description":"الحسابات فقط أو الاتجاه فقط"},{"level":"درجة واحدة","description":"عنصر واحد"},{"level":"صفر","description":"إجابة خاطئة أو متروكة"}]'::jsonb, '["إهمال تفكك NaCl فيعكس الاتجاه","نقل الماء إلى الأقل تركيزًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (24%)"}],"at":"2026-10-17T11:36:22.439Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K3-C1-L4-O12') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K3-C2-L1-O01'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'أيّ مما يأتي من الخواص الفيزيائية للمحاليل الحمضية؟', null, '["ملمسها زلق","طعمها لاذع","طعمها مر","غير موصلة للكهرباء"]'::jsonb, 'تذكر', 'تذكر/تعرف', 'سهل', 'الكتاب ص 56 — خواص الأحماض والقواعد: الخواص الفيزيائية'),
('mcq', 2, 'ما الخاصيتان الفيزيائيتان اللتان تُعرف بهما المحاليل القاعدية؟', null, '["طعمها لاذع، وملمسها زلق","طعمها مر، ولا توصل الكهرباء","طعمها لاذع، وتوصل الكهرباء","طعمها مر، وملمسها زلق"]'::jsonb, 'تذكر', 'تذكر/تعرف', 'سهل', 'الكتاب ص 56 — خواص الأحماض والقواعد: الخواص الفيزيائية'),
('mcq', 3, 'يُعزى الطعم اللاذع لليمون والجريب فروت إلى احتوائهما على:', null, '["حمضي الستريك والأسكوربيك","حمضي الكربونيك والفوسفوريك","حمض الإيثانويك وحده","حمض الهيدروكلوريك وحده"]'::jsonb, 'تذكر', 'تذكر/تعرف', 'متوسط', 'الكتاب ص 56 — خواص الأحماض والقواعد: الخواص الفيزيائية'),
('mcq', 4, 'أيّ العبارات الآتية صحيحة بشأن التوصيل الكهربائي للماء ولمحاليل الأحماض والقواعد؟', null, '["الماء النقي موصل جيد، ويقل توصيله عند إضافة حمض إليه","محاليل الأحماض توصل الكهرباء، أما محاليل القواعد فلا توصلها","الماء النقي غير موصل، ويصبح موصلًا عند إضافة حمض أو قاعدة إليه","محاليل الأحماض والقواعد لا توصل الكهرباء لأنها مواد جزيئية"]'::jsonb, 'فهم', 'فهم/تفسير', 'متوسط', 'الكتاب ص 57 — التوصيل الكهربائي'),
('mcq', 5, 'ما سبب قدرة محاليل الأحماض والقواعد على توصيل التيار الكهربائي؟', null, '["تأينها في الماء وإنتاجها أيونات في المحلول","احتواؤها على إلكترونات حرة كالفلزات","احتواؤها على عدد كبير من جزيئات الماء","ذوبان غازات الهواء الجوي فيها"]'::jsonb, 'فهم', 'فهم/تفسير', 'متوسط', 'الكتاب ص 57 — التوصيل الكهربائي'),
('mcq', 6, 'أيّ مما يأتي يُعدّ من الخواص الفيزيائية للأحماض والقواعد، لا من خواصها الكيميائية؟', null, '["تغيّر لون ورق تبّاع الشمس","تفاعل الأحماض مع الخارصين منتجة H₂","تفاعل الأحماض مع الكربونات منتجة CO₂","توصيل محاليلها للتيار الكهربائي"]'::jsonb, 'فهم', 'تصنيف', 'صعب', 'الكتاب ص 56–57 — الخواص الفيزيائية والتوصيل الكهربائي'),
('mcq', 7, 'مادة منزلية محلولها المائي ملمسه زلق ويوصل التيار الكهربائي. ما التصنيف الأرجح لهذه المادة؟ ومن أمثلتها؟', null, '["حمض، ومن أمثلته الخل","قاعدة، ومن أمثلتها الصابون","حمض، ومن أمثلته عصير الليمون","مادة متعادلة، ومن أمثلتها الماء المقطر"]'::jsonb, 'فهم', 'تطبيق مفهوم', 'صعب', 'الكتاب ص 56–57 — الخواص الفيزيائية والتوصيل الكهربائي'),
('essay', 1, 'عدّد الخواص الفيزيائية للمحاليل الحمضية والمحاليل القاعدية، واذكر مثالًا من الحياة اليومية على كل نوع.', null, null, 'تذكر', 'تعداد', 'سهل', 'الكتاب ص 56–57 — الخواص الفيزيائية والتوصيل الكهربائي'),
('essay', 2, 'فسّر: الماء النقي لا يوصل التيار الكهربائي، بينما يوصله محلول الخل ومحلول الصابون. ولماذا يُحذَّر من تعرّف هذه المحاليل في المختبر بتذوقها أو لمسها؟', null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 56–57 — الخواص الفيزيائية والتوصيل الكهربائي'),
('essay', 3, 'لدى طالب ثلاثة سوائل عديمة اللون غير معنونة: ماء مقطر، ومحلول خل، ومحلول صابون. اقترح أن يستعمل جهاز اختبار التوصيل الكهربائي (مصباح وقطبان) وحده لتمييزها. حلّل: ماذا يستطيع هذا الاختبار أن يكشفه، وماذا لا يستطيع؟ مع التعليل.', null, null, 'تحليل', 'تحليل موقف', 'صعب', 'الكتاب ص 56–57 — الخواص الفيزيائية والتوصيل الكهربائي')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C2-L1-O01') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'من الخواص الفيزيائية المألوفة للمحاليل الحمضية أن طعمها لاذع، كطعم الليمون والخل والمشروبات الغازية؛ لذا فالخاصية الصحيحة هي أن طعمها لاذع.', '["الملمس الزلق خاصية فيزيائية للمحاليل القاعدية كمحلول الصابون، لا الحمضية.","","الطعم المر من خواص المحاليل القاعدية، أما الحمضية فطعمها لاذع.","المحاليل الحمضية توصل الكهرباء بسبب تأينها، والماء النقي وحده غير موصل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.440Z"}'::jsonb),
('mcq', 2, 3, 'المحاليل القاعدية طعمها مرّ ولها ملمس زلق، كما في قطعة الصابون عندما تبتل؛ فالخاصيتان هما: طعمها مر، وملمسها زلق.', '["الطعم اللاذع خاصية للمحاليل الحمضية؛ فالقاعدية طعمها مر.","المحاليل القاعدية توصل الكهرباء لأن إضافة القاعدة إلى الماء تنتج أيونات.","التوصيل صحيح لكن الطعم اللاذع للأحماض لا للقواعد.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T11:36:22.440Z"}'::jsonb),
('mcq', 3, 0, 'الليمون والجريب فروت طعمهما لاذع لاحتوائهما على حمضي الستريك والأسكوربيك.', '["","حمضا الكربونيك H₂CO₃ والفوسفوريك H₃PO₄ هما سبب الطعم اللاذع للمشروبات الغازية لا لليمون.","حمض الإيثانويك هو الحمض الموجود في الخل، وليس في الليمون والجريب فروت.","حمض الهيدروكلوريك حمض قوي يستعمل في التنظيف، وليس مكوّنًا لعصير الليمون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (0%)"}],"at":"2026-10-17T11:36:22.440Z"}'::jsonb),
('mcq', 4, 2, 'الماء النقي غير موصل للكهرباء، إلا أن إضافة حمض أو قاعدة إليه تنتج أيونات تجعل المحلول الناتج موصلًا؛ وهذا ما تنص عليه العبارة الصحيحة.', '["الماء النقي غير موصل للكهرباء، وإضافة الحمض تزيد الأيونات فيصبح موصلًا.","محاليل القواعد أيضًا توصل الكهرباء لأن ذوبان القاعدة في الماء ينتج أيونات.","","محاليل الأحماض والقواعد موصلة بسبب تأينها وإنتاجها أيونات في المحلول."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.440Z"}'::jsonb),
('mcq', 5, 0, 'تقدر المحاليل الحمضية والقاعدية على توصيل الكهرباء بسبب تأينها؛ إذ تنتج أيونات تتحرك في المحلول وتنقل التيار.', '["","التوصيل في المحاليل يتم بحركة الأيونات، لا بإلكترونات حرة كما في الفلزات.","جزيئات الماء وحدها لا توصل، فالماء النقي غير موصل للكهرباء.","ذوبان غازات الهواء ليس سبب التوصيل؛ السبب هو تأين الحمض أو القاعدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.440Z"}'::jsonb),
('mcq', 6, 3, 'الخواص الفيزيائية لا يتكوّن فيها مواد جديدة، ومنها الطعم والملمس وتوصيل المحاليل للتيار الكهربائي؛ أما تغيّر لون تبّاع الشمس والتفاعل مع الفلزات والكربونات فخواص كيميائية. لذا فالإجابة توصيل محاليلها للتيار الكهربائي.', '["تغيّر لون ورق تبّاع الشمس ناتج عن تفاعل كيميائي، فهو من الخواص الكيميائية.","تفاعل الحمض مع الفلز ينتج مادة جديدة (H₂)، فهو خاصية كيميائية.","إنتاج غاز CO₂ من الكربونات تغيّر كيميائي، فهو خاصية كيميائية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.440Z"}'::jsonb),
('mcq', 7, 1, 'الملمس الزلق من الخواص الفيزيائية للمحاليل القاعدية، وتوصيل المحلول للكهرباء يدل على وجود أيونات؛ فالمادة قاعدة ومن أمثلتها الصابون.', '["الخل حمضي طعمه لاذع، وليس ملمسه زلقًا؛ الملمس الزلق من خواص القواعد.","","عصير الليمون حمضي، والملمس الزلق لا يميّز الأحماض.","الماء المقطر (النقي) لا يوصل الكهرباء وليس ملمسه زلقًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.440Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المحاليل الحمضية: طعمها لاذع، وتوصل التيار الكهربائي بسبب تأينها؛ مثالها: الخل، أو عصير الليمون، أو المشروبات الغازية. المحاليل القاعدية: طعمها مر، وملمسها زلق، وتوصل التيار الكهربائي؛ مثالها: الصابون. (مع التنبيه إلى أنه لا يجوز تعرّف حمض أو قاعدة في المختبر بتذوقها أو لمسها.) ويقبل أي مثال صحيح.', '["الطعم اللاذع للمحاليل الحمضية","الطعم المر للمحاليل القاعدية","الملمس الزلق للمحاليل القاعدية","التوصيل الكهربائي لكلا النوعين","مثال صحيح لكل نوع"]'::jsonb, '[]'::jsonb, '[{"element":"الطعم اللاذع للأحماض","marks":1},{"element":"الطعم المر للقواعد","marks":1},{"element":"الملمس الزلق للقواعد","marks":1},{"element":"توصيل محاليل النوعين للكهرباء","marks":1},{"element":"مثال صحيح لكل نوع","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"ذكر الخواص الأربع كاملة مع مثالين صحيحين"},{"level":"3–4 درجات","description":"نقص خاصية أو مثال واحد"},{"level":"1–2 درجة","description":"ذكر خاصية أو خاصيتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسبة الطعم المر إلى الأحماض واللاذع إلى القواعد","إغفال التوصيل الكهربائي","ذكر تغيّر لون تبّاع الشمس ضمن الخواص الفيزيائية"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T11:36:22.441Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الماء النقي لا يحتوي إلا على قدر ضئيل جدًا من الأيونات فهو غير موصل للكهرباء. عند إضافة حمض (كحمض الإيثانويك في الخل) أو قاعدة (كالصابون) إلى الماء تتأين المادة منتجة أيونات حرة الحركة في المحلول، فتنقل هذه الأيونات التيار ويصبح المحلول موصلًا. ويُحذَّر من التذوق أو اللمس لأن كثيرًا من الأحماض والقواعد في المختبر مواد خطرة (أكّالة أو سامة)، لذا لا يجوز أبدًا تعرّف أي حمض أو قاعدة بتذوقها أو لمسها.', '["الماء النقي غير موصل","الحمض أو القاعدة تتأين في الماء","الأيونات الناتجة تنقل التيار","سبب التحذير: خطورة المواد في المختبر"]'::jsonb, '[]'::jsonb, '[{"element":"الماء النقي غير موصل لعدم وجود أيونات كافية","marks":1},{"element":"تأين الحمض أو القاعدة وإنتاج أيونات","marks":1},{"element":"حركة الأيونات تنقل التيار","marks":1},{"element":"تعليل التحذير من التذوق واللمس","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل للتوصيل مع تعليل التحذير"},{"level":"2–3 درجات","description":"تفسير التوصيل دون ربطه بالأيونات أو دون تعليل التحذير"},{"level":"1 درجة","description":"ذكر أن المحلولين موصلان دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاعتقاد أن الماء النقي موصل جيد","نسبة التوصيل إلى إلكترونات حرة","الاكتفاء بقول إن الطعم يكفي للتمييز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T11:36:22.441Z"}'::jsonb),
('essay', 3, null::int, null, null, 'يستطيع الاختبار تمييز الماء المقطر؛ لأنه لا يوصل التيار فلا يضيء المصباح، بينما يضيء في محلولي الخل والصابون لأن كليهما يحتوي على أيونات ناتجة عن تأين الحمض أو القاعدة. لكن الاختبار وحده لا يكفي لتحديد أيّ المحلولين الموصلين حمضي وأيّهما قاعدي؛ لأن التوصيل خاصية مشتركة بين المحاليل الحمضية والقاعدية. ولا يجوز اللجوء إلى التذوق (لاذع/مر) أو اللمس (زلق) في المختبر، لذا يحتاج الطالب إلى اختبار آخر مثل ورق تبّاع الشمس.', '["الماء المقطر لا يوصل فيُميَّز","الخل والصابون يوصلان لاحتوائهما أيونات","التوصيل مشترك بين الأحماض والقواعد فلا يميّز بينهما","عدم جواز التذوق واللمس والحاجة إلى اختبار آخر"]'::jsonb, '[]'::jsonb, '[{"element":"تمييز الماء المقطر مع التعليل","marks":2},{"element":"تعليل توصيل المحلولين الآخرين","marks":1},{"element":"بيان أن التوصيل لا يميّز الحمضي من القاعدي","marks":2},{"element":"رفض التذوق واللمس واقتراح اختبار آخر","marks":1}]'::jsonb, '[{"level":"6 درجات","description":"تحليل كامل لما يكشفه الاختبار وما لا يكشفه مع التعليل واقتراح بديل آمن"},{"level":"4–5 درجات","description":"تحليل صحيح ينقصه التعليل أو البديل"},{"level":"2–3 درجات","description":"تمييز الماء المقطر فقط"},{"level":"1 درجة","description":"إجابة جزئية غير معللة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الادعاء بأن التوصيل يميّز الحمض من القاعدة","اقتراح تذوق المحلولين","الاعتقاد أن الماء المقطر يوصل الكهرباء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-17T11:36:22.441Z"}'::jsonb)
