from (values
('mcq', 1, 'عند غمس ورقة تبّاع شمس زرقاء في محلول حمضي، فإن لونها:', null, '["يبقى أزرق دون تغيّر","يصبح أزرق داكنًا","يتحول إلى الأحمر","يتحول إلى عديم اللون"]'::jsonb, 'تذكر', 'تذكر/تعرف', 'سهل', 'الكتاب ص 57 — الخواص الكيميائية للأحماض والقواعد'),
('mcq', 2, 'وُضعت ورقتا تبّاع شمس، إحداهما حمراء والأخرى زرقاء، في محلول هيدروكسيد الصوديوم NaOH. ما الذي يُلاحَظ؟', null, '["تتحول الحمراء إلى زرقاء، وتبقى الزرقاء كما هي","تتحول الزرقاء إلى حمراء، وتبقى الحمراء كما هي","لا تتغير أي من الورقتين","تتحول الورقتان كلتاهما إلى اللون الأحمر"]'::jsonb, 'فهم', 'تطبيق مفهوم', 'سهل', 'الكتاب ص 57 — الخواص الكيميائية للأحماض والقواعد'),
('mcq', 3, 'ما الغاز الناتج عن تفاعل الخارصين Zn مع محلول حمض الهيدروكلوريك HCl؟', null, '["الكلور Cl₂","ثاني أكسيد الكربون CO₂","الأكسجين O₂","الهيدروجين H₂"]'::jsonb, 'تذكر', 'تذكر/تعرف', 'سهل', 'الكتاب ص 57 — الخواص الكيميائية للأحماض والقواعد'),
('mcq', 4, 'عند إضافة الخل إلى صودا الخبز NaHCO₃ تظهر فقاعات. ما الغاز المسبّب لهذه الفقاعات؟', null, '["الهيدروجين H₂","ثاني أكسيد الكربون CO₂","الأكسجين O₂","بخار الماء H₂O"]'::jsonb, 'تذكر', 'تذكر/تعرف', 'متوسط', 'الكتاب ص 57 — الخواص الكيميائية للأحماض والقواعد'),
('mcq', 5, 'يضع الجيولوجيون قطرات من محلول حمض الهيدروكلوريك على صخر ليعرفوا هل هو صخر جيري. على أيّ أساس يعتمد هذا الاختبار؟', null, '["يتفاعل الحمض مع CaCO₃ منتجًا فقاعات من غاز H₂","يحوّل الحمض لون الصخر الجيري إلى الأحمر","يتفاعل الحمض مع CaCO₃ منتجًا فقاعات من غاز CO₂","يذيب الحمض الصخر دون أن يتصاعد أي غاز"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 57 — الخواص الكيميائية للأحماض والقواعد'),
('mcq', 6, 'أيّ المعادلات الآتية تمثّل خاصية كيميائية للأحماض؟', null, '["NaOH → Na⁺ + OH⁻","Mg + 2HCl → MgCl₂ + H₂","2H₂ + O₂ → 2H₂O","H₂O + H₂O ⇌ H₃O⁺ + OH⁻"]'::jsonb, 'فهم', 'تطبيق مفهوم', 'متوسط', 'الكتاب ص 57 — الخواص الكيميائية للأحماض والقواعد'),
('mcq', 7, 'أيّ المجموعات الآتية تضم خواص كيميائية للأحماض فقط؟', null, '["تحوّل تبّاع الشمس الأزرق إلى الأحمر، وتنتج H₂ مع Zn، وتنتج CO₂ مع الكربونات","تحوّل تبّاع الشمس الأحمر إلى الأزرق، وتنتج H₂ مع Zn، وتنتج CO₂ مع الكربونات","طعمها لاذع، وتنتج H₂ مع Zn، وتنتج CO₂ مع الكربونات","تحوّل تبّاع الشمس الأزرق إلى الأحمر، وتنتج O₂ مع Zn، وتنتج CO₂ مع الكربونات"]'::jsonb, 'تذكر', 'تصنيف', 'صعب', 'الكتاب ص 57 — الخواص الكيميائية للأحماض والقواعد'),
('essay', 1, 'عدّد الخواص الكيميائية للأحماض والقواعد، واكتب معادلة كيميائية موزونة تمثّل كل تفاعل من تفاعلات الأحماض.', null, null, 'تذكر', 'تعداد مع معادلات', 'سهل', 'الكتاب ص 57 — الخواص الكيميائية للأحماض والقواعد'),
('essay', 2, 'اكتب معادلة كيميائية موزونة لكل من التفاعلين الآتيين، وسمِّ الغاز الناتج في كل منهما، ثم بيّن الخاصية الكيميائية للأحماض التي يمثّلها كل تفاعل:
(أ) المغنيسيوم مع حمض الهيدروكلوريك.
(ب) كربونات الكالسيوم CaCO₃ مع حمض الهيدروكلوريك.', null, null, 'تطبيق', 'كتابة معادلات', 'متوسط', 'الكتاب ص 57 — الخواص الكيميائية للأحماض والقواعد'),
('essay', 3, 'أُجريت اختبارات على ثلاثة محاليل مجهولة (أ، ب، ج)، وكانت النتائج كما يأتي:
(أ): يحوّل تبّاع الشمس الأزرق إلى الأحمر، وتتصاعد منه فقاعات عند إضافة قطعة خارصين، وكذلك عند إضافة NaHCO₃.
(ب): يحوّل تبّاع الشمس الأحمر إلى الأزرق، ولا تتصاعد منه فقاعات مع الخارصين ولا مع NaHCO₃.
(ج): لا يغيّر لون أيّ من ورقتي تبّاع الشمس، ولا يتفاعل مع الخارصين ولا مع NaHCO₃.
صنّف كل محلول (حمضي، قاعدي، متعادل) مع التعليل، وسمِّ الغازين المتصاعدين من المحلول (أ).', null, null, 'تحليل', 'تحليل بيانات', 'صعب', 'الكتاب ص 57 — الخواص الكيميائية للأحماض والقواعد')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
