from (values
('mcq', 1, 2, 'تحوّل محاليل الأحماض لون ورق تبّاع الشمس الأزرق إلى الأحمر، لذا يتحول لون الورقة إلى الأحمر.', '["الأحماض تغيّر لون تبّاع الشمس الأزرق؛ الذي يبقى دون تغيّر هو الورق الأحمر في الحمض.","ازدياد الزرقة ليس سلوك الأحماض؛ الأحماض تحوّل الأزرق إلى الأحمر.","","تبّاع الشمس لا يفقد لونه في الحمض، بل يتحول إلى اللون الأحمر."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.442Z"}'::jsonb),
('mcq', 2, 0, 'NaOH قاعدة قوية، ومحاليل القواعد تحوّل ورق تبّاع الشمس الأحمر إلى الأزرق؛ فتتحول الحمراء إلى زرقاء، أما الزرقاء فتبقى زرقاء.', '["","هذا سلوك محاليل الأحماض، أما NaOH فقاعدة.","محاليل القواعد تغيّر لون تبّاع الشمس الأحمر إلى الأزرق.","اللون الأحمر لتبّاع الشمس يظهر في الأحماض لا في القواعد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.442Z"}'::jsonb),
('mcq', 3, 3, 'تتفاعل الأحماض مع فلزات مثل Mg وZn منتجة غاز الهيدروجين: Zn + 2HCl → ZnCl₂ + H₂، فالغاز هو الهيدروجين H₂.', '["الكلور يبقى في الناتج على صورة ZnCl₂، ولا يتصاعد غاز الكلور.","CO₂ ينتج عن تفاعل الأحماض مع الكربونات، لا مع الفلزات.","لا ينتج الأكسجين من تفاعل الفلز مع الحمض؛ الناتج غاز الهيدروجين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.442Z"}'::jsonb),
('mcq', 4, 1, 'تتفاعل الكربونات الهيدروجينية مع الأحماض منتجة CO₂: NaHCO₃ + CH₃COOH → CH₃COONa + H₂O + CO₂، فالغاز ثاني أكسيد الكربون.', '["H₂ ينتج من تفاعل الحمض مع فلز نشط كالخارصين، لا مع الكربونات الهيدروجينية.","","لا يحتوي التفاعل على ما ينتج الأكسجين، والمعادلة تبيّن أن الغاز CO₂.","الماء ناتج في الحالة السائلة، والغاز المتصاعد هو CO₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.442Z"}'::jsonb),
('mcq', 5, 2, 'الصخر الجيري يتكون أساسًا من CaCO₃، والأحماض تتفاعل مع الكربونات منتجة CO₂؛ فظهور الفقاعات يدل على وجود الجير.', '["تفاعل الحمض مع الكربونات ينتج CO₂؛ أما H₂ فينتج مع الفلزات.","تغيّر اللون إلى الأحمر خاص بورق تبّاع الشمس، لا بالصخر.","","تفاعل الحمض مع كربونات الكالسيوم يصحبه تصاعد فقاعات CO₂ وهو دليل الاختبار."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.443Z"}'::jsonb),
('mcq', 6, 1, 'من الخواص الكيميائية للأحماض تفاعلها مع فلزات مثل المغنيسيوم منتجة غاز الهيدروجين، وهو ما تمثّله المعادلة Mg + 2HCl → MgCl₂ + H₂.', '["هذه معادلة تفكك قاعدة في الماء، ولا تمثّل خاصية للأحماض.","","هذا تفاعل احتراق الهيدروجين، ولا يدخل فيه حمض.","هذه معادلة التأين الذاتي للماء، لا تفاعل حمض مع فلز أو كربونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:36:22.443Z"}'::jsonb),
('mcq', 7, 0, 'الخواص الكيميائية للأحماض: تحويل تبّاع الشمس الأزرق إلى الأحمر، والتفاعل مع فلزات مثل Mg وZn منتجة H₂، والتفاعل مع الكربونات والكربونات الهيدروجينية منتجة CO₂.', '["","تحويل الأحمر إلى الأزرق خاصية للقواعد لا للأحماض.","الطعم اللاذع خاصية فيزيائية لا كيميائية.","تفاعل الأحماض مع الخارصين ينتج H₂ لا O₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:36:22.443Z"}'::jsonb),
('essay', 1, null::int, null, null, '1) ورق تبّاع الشمس: الأحماض تحوّل الأزرق إلى الأحمر، والقواعد تحوّل الأحمر إلى الأزرق. 2) تفاعل الأحماض مع الفلزات مثل Mg وZn منتجة غاز الهيدروجين: Zn + 2HCl → ZnCl₂ + H₂. 3) تفاعل الأحماض مع الكربونات والكربونات الهيدروجينية منتجة غاز CO₂: NaHCO₃ + CH₃COOH → CH₃COONa + H₂O + CO₂.', '["أثر الحمض على تبّاع الشمس الأزرق","أثر القاعدة على تبّاع الشمس الأحمر","تفاعل الحمض مع الفلز ومعادلته","تفاعل الحمض مع الكربونات ومعادلته"]'::jsonb, '[]'::jsonb, '[{"element":"أثر الأحماض والقواعد على تبّاع الشمس","marks":2},{"element":"تفاعل الحمض مع الفلز مع معادلة موزونة","marks":2},{"element":"تفاعل الحمض مع الكربونات مع معادلة موزونة","marks":2}]'::jsonb, '[{"level":"6 درجات","description":"الخواص الثلاث صحيحة مع معادلتين موزونتين"},{"level":"4–5 درجات","description":"الخواص صحيحة مع خطأ في وزن معادلة أو نقص فيها"},{"level":"2–3 درجات","description":"ذكر الخواص دون معادلات"},{"level":"1 درجة","description":"خاصية واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس ألوان تبّاع الشمس","ذكر CO₂ ناتجًا لتفاعل الحمض مع الفلز","عدم وزن معادلة الخارصين (HCl بدل 2HCl)"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (6 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.443Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) Mg + 2HCl → MgCl₂ + H₂؛ الغاز الناتج الهيدروجين، ويمثّل تفاعل الأحماض مع الفلزات. (ب) CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂؛ الغاز الناتج ثاني أكسيد الكربون، ويمثّل تفاعل الأحماض مع كربونات الفلزات (وهو أساس تعرّف الصخر الجيري).', '["معادلة (أ) موزونة","الغاز H₂","معادلة (ب) موزونة","الغاز CO₂","ربط كل تفاعل بالخاصية"]'::jsonb, '["(أ) Mg + 2HCl → MgCl₂ + H₂ : ذرات Mg 1=1، Cl 2=2، H 2=2","(ب) CaCO₃ + 2HCl → CaCl₂ + H₂O + CO₂ : Ca 1=1، C 1=1، O 3=1+2، H 2=2، Cl 2=2"]'::jsonb, '[{"element":"معادلة (أ) موزونة","marks":1.5},{"element":"تسمية H₂","marks":0.5},{"element":"معادلة (ب) موزونة","marks":1.5},{"element":"تسمية CO₂","marks":0.5},{"element":"ربط التفاعلين بالخاصيتين","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"معادلتان موزونتان وغازان صحيحان وربط صحيح"},{"level":"3–4 درجات","description":"خطأ في وزن إحدى المعادلتين أو نقص في الربط"},{"level":"1–2 درجة","description":"تسمية الغازين فقط أو معادلة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نسيان H₂O في معادلة الكربونات","كتابة MgCl بدل MgCl₂","تبديل الغازين بين التفاعلين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.443Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) حمضي: لأنه يحوّل تبّاع الشمس الأزرق إلى الأحمر ويتفاعل مع الفلز والكربونات الهيدروجينية، وهذه خواص كيميائية للأحماض؛ والغاز مع الخارصين H₂، ومع NaHCO₃ CO₂. (ب) قاعدي: لأنه يحوّل تبّاع الشمس الأحمر إلى الأزرق، ولا يسلك سلوك الأحماض مع الفلز والكربونات. (ج) متعادل: لا يؤثر في تبّاع الشمس ولا يُظهر خواص الأحماض.', '["(أ) حمضي مع التعليل","H₂ مع الخارصين","CO₂ مع NaHCO₃","(ب) قاعدي مع التعليل","(ج) متعادل مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف (أ) وتعليله","marks":1},{"element":"الغازان الناتجان من (أ)","marks":2},{"element":"تصنيف (ب) وتعليله","marks":1},{"element":"تصنيف (ج) وتعليله","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف الثلاثة صحيح ومعلل مع الغازين"},{"level":"3–4 درجات","description":"تصنيف صحيح مع خطأ في أحد الغازين أو نقص تعليل"},{"level":"1–2 درجة","description":"تصنيف صحيح دون تعليل أو غازات"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ (ج) قاعديًا لأنه لا يتفاعل مع الفلز","ذكر H₂ ناتجًا مع NaHCO₃","عكس دلالة ألوان تبّاع الشمس"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.444Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
