('mcq', 4, 'يبيّن الجدول نتائج اختبار التوصيل لمحلولين لهما التركيز نفسه. ما التفسير الأدق للفرق في شدة التوهج؟', '{"headers":["المحلول","التركيز","توهج المصباح"],"rows":[["HCl","0.10 M","قوي"],["CH₃COOH","0.10 M","خافت"]]}'::jsonb, '["يتأين HCl كليًا بينما يتأين CH₃COOH جزئيًا، فالأيونات في محلول HCl أكثر","تركيز محلول HCl أكبر من تركيز محلول CH₃COOH","لا يتأين CH₃COOH إطلاقًا في الماء","جزيئات CH₃COOH كبيرة فتعيق مرور الإلكترونات"]'::jsonb, 'تحليل', 'تحليل بيانات', 'صعب', 'الكتاب ص 66–67 — الأحماض القوية والضعيفة (الشكلان 2-11 و2-12)'),
('mcq', 5, 'ما الذي ينقل الشحنة الكهربائية في محلول حمض الهيدروكلوريك عند مرور التيار فيه؟', null, '["إلكترونات حرة تتحرك بين جزيئات الماء","جزيئات HCl القطبية غير المتأينة","جزيئات الماء التي يذوب فيها الحمض","أيونات H₃O⁺ الموجبة وأيونات Cl⁻ السالبة المتحركة"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 57 — التوصيل الكهربائي'),
('mcq', 6, 'أُذيب 0.10 mol من غاز HCl في الماء وأُكمل حجم المحلول إلى 1.0 L. ما تركيز أيونات H₃O⁺ في المحلول؟', null, '["0.050 M","0.20 M","0.10 M","1.0 × 10⁻⁷ M"]'::jsonb, 'تطبيق', 'حساب', 'صعب', 'الكتاب ص 67 — الأحماض القوية'),
('mcq', 7, 'يُصنَّف حمض الهيدروكلوريك HCl حمضًا قويًا لأنه:', null, '["يتأين كليًا في المحلول المائي","يحتوي على ذرة هيدروجين واحدة","محلوله ذو طعم لاذع","يتفاعل مع الخارصين منتجًا H₂"]'::jsonb, 'تذكر', 'تذكر/تعرف', 'سهل', 'الكتاب ص 67 — الأحماض القوية'),
('essay', 1, 'فسّر توصيل محلول حمض الهيدروكلوريك للتيار الكهربائي جيدًا، مدعّمًا إجابتك بمعادلة تأينه في الماء.', null, null, 'فهم', 'تفسير', 'سهل', 'الكتاب ص 66–67 — الأحماض القوية والضعيفة (الشكلان 2-11 و2-12)'),
('essay', 2, 'وُضع قطبا جهاز التوصيل في محلول HCl تركيزه 0.10 M فتوهج المصباح بقوة، ثم في محلول CH₃COOH تركيزه 0.10 M فكان التوهج خافتًا. قارن بين المحلولين من حيث درجة التأين والجسيمات الموجودة في كل منهما، وفسّر الفرق في التوهج.', null, null, 'تحليل', 'مقارنة', 'متوسط', 'الكتاب ص 66–67 — الأحماض القوية والضعيفة (الشكلان 2-11 و2-12)'),
