from (values
('mcq', 1, 3, 'HCl حمض قوي يتأين كليًا في الماء، فتتحول جميع جزيئاته إلى أيونات هيدرونيوم وكلوريد، فيكثر عدد الأيونات ويتوهج المصباح بقوة.', '["التأين الجزئي ينتج أيونات قليلة وتوهجًا خافتًا كما في CH₃COOH، أما HCl فيتأين كليًا.","في محلول HCl تتحول جميع الجزيئات تقريبًا إلى أيونات H₃O⁺ وCl⁻.","الماء النقي غير موصل، والتوصيل ناتج عن أيونات الحمض.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T11:36:22.444Z"}'::jsonb),
('mcq', 2, 1, 'يتأين HCl كليًا في الماء، فيُكتب تأينه بسهم في اتجاه واحد: HCl + H₂O → H₃O⁺ + Cl⁻.', '["سهم الاتزان ⇌ يُستعمل للأحماض الضعيفة التي تتأين جزئيًا، أما HCl فتأينه كلي فيُكتب بسهم في اتجاه واحد.","","تأين الحمض لا ينتج غاز الهيدروجين، بل ينتقل H⁺ إلى جزيء الماء مكوّنًا H₃O⁺.","أيون الكلوريد سالب الشحنة Cl⁻، والمعادلة بهذه الصورة غير متوازنة الشحنة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.444Z"}'::jsonb),
('mcq', 3, 2, 'جميع جزيئات HCl تتحول إلى أيونات هيدرونيوم وأيونات كلوريد، فالجسيمات الرئيسة هي H₃O⁺ وCl⁻.', '["HCl حمض قوي يتأين كليًا، فلا تبقى جزيئاته في المحلول.","هذا وصف محلول حمض ضعيف كحمض الإيثانويك، لا محلول HCl.","","تأين HCl ينتج H₃O⁺ لا OH⁻."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.445Z"}'::jsonb),
('mcq', 4, 0, 'شدة التوهج تعتمد على تركيز الأيونات في المحلول؛ HCl يتأين كليًا فيحتوي محلوله على أيونات كثيرة، أما CH₃COOH فيتأين جزئيًا فأيوناته قليلة والتوهج خافت.', '["","التركيزان متساويان (0.10 M)، فالفرق ليس في التركيز.","CH₃COOH يتأين جزئيًا، لذلك يضيء المصباح ولو بضوء خافت.","التيار في المحاليل تنقله الأيونات لا الإلكترونات، والسبب قلة الأيونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-17T11:36:22.445Z"}'::jsonb),
('mcq', 5, 3, 'يحتوي محلول HCl على أيونات هيدرونيوم موجبة وأيونات كلوريد سالبة ناتجة عن التأين الكلي، وحركة هذه الأيونات هي التي تنقل التيار.', '["المحاليل لا تحتوي إلكترونات حرة كالفلزات؛ الأيونات هي ناقلات الشحنة.","الجزيئات المتعادلة لا تنقل التيار، كما أن HCl يتأين كليًا.","الماء النقي غير موصل، فلا تنقل جزيئاته التيار.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.445Z"}'::jsonb),
('mcq', 6, 2, 'يتأين HCl كليًا، وكل جزيء ينتج أيون H₃O⁺ واحدًا، فتركيز H₃O⁺ = 0.10 mol ÷ 1.0 L = 0.10 M.', '["هذا يفترض أن نصف الحمض فقط يتأين، لكن HCl يتأين كليًا.","0.20 M هو مجموع تركيزي H₃O⁺ وCl⁻ معًا، لا تركيز H₃O⁺ وحده.","","هذه قيمة تقارب تركيز H₃O⁺ في الماء النقي، وتتجاهل تأين الحمض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-17T11:36:22.445Z"}'::jsonb),
('mcq', 7, 0, 'الأحماض القوية هي التي تتأين كليًا في المحاليل المائية، وHCl يتأين كليًا، لذلك يُعدّ حمضًا قويًا وموصلًا جيدًا للكهرباء.', '["","عدد ذرات الهيدروجين لا يحدد القوة؛ فـ HF يحتوي ذرة واحدة لكنه حمض ضعيف.","الطعم اللاذع مشترك بين الأحماض القوية والضعيفة، ولا يجوز التذوق في المختبر.","التفاعل مع الفلزات خاصية عامة للأحماض، ولا يميّز القوي من الضعيف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.445Z"}'::jsonb),
('essay', 1, null::int, null, null, 'HCl حمض قوي يتأين كليًا في الماء وفق المعادلة: HCl + H₂O → H₃O⁺ + Cl⁻. ينتج عن ذلك عدد كبير من الأيونات الموجبة (H₃O⁺) والسالبة (Cl⁻) الحرة الحركة في المحلول، وهذه الأيونات تنقل التيار الكهربائي، لذا يكون المحلول موصلًا جيدًا ويتوهج المصباح بقوة.', '["HCl حمض قوي يتأين كليًا","المعادلة الصحيحة بسهم في اتجاه واحد","عدد كبير من الأيونات","الأيونات تنقل التيار"]'::jsonb, '[]'::jsonb, '[{"element":"التأين الكلي لـ HCl","marks":1},{"element":"معادلة التأين صحيحة","marks":1},{"element":"كثرة الأيونات في المحلول","marks":1},{"element":"الأيونات هي ناقلة التيار","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل مع المعادلة"},{"level":"2–3 درجات","description":"تفسير صحيح دون معادلة أو دون ذكر التأين الكلي"},{"level":"1 درجة","description":"ذكر أن المحلول يحتوي أيونات فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["استعمال سهم الاتزان في معادلة HCl","نسبة التوصيل إلى جزيئات HCl","إغفال أيون الكلوريد"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.445Z"}'::jsonb),
('essay', 2, null::int, null, null, 'محلول HCl: يتأين الحمض كليًا (HCl + H₂O → H₃O⁺ + Cl⁻)، فالجسيمات في المحلول أيونات H₃O⁺ وCl⁻ بأعداد كبيرة. محلول CH₃COOH: يتأين جزئيًا (CH₃COOH + H₂O ⇌ H₃O⁺ + CH₃COO⁻)، فتبقى معظم جزيئاته غير متأينة مع قليل من الأيونات. شدة التوهج تعتمد على عدد الأيونات؛ لذلك يتوهج المصباح بقوة في HCl وبشكل خافت في CH₃COOH رغم تساوي التركيز.', '["HCl تأين كلي","CH₃COOH تأين جزئي","الجسيمات في كل محلول","ربط التوهج بعدد الأيونات"]'::jsonb, '[]'::jsonb, '[{"element":"وصف تأين HCl والجسيمات الناتجة","marks":1},{"element":"وصف تأين CH₃COOH والجسيمات الموجودة","marks":1},{"element":"ربط شدة التوهج بتركيز الأيونات","marks":1},{"element":"الإشارة إلى تساوي التركيز وأن الفرق في درجة التأين","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة مع تفسير صحيح"},{"level":"2–3 درجات","description":"مقارنة صحيحة ناقصة التفسير"},{"level":"1 درجة","description":"ذكر أن HCl أقوى دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عزو الفرق إلى اختلاف التركيز","القول إن CH₃COOH لا يتأين إطلاقًا","الخلط بين قوة الحمض وتركيزه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T11:36:22.446Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الحجم = 500 mL = 0.500 L. بما أن HCl يتأين كليًا وكل mol منه ينتج 1 mol من H₃O⁺ و1 mol من Cl⁻: [H₃O⁺] = 0.050 ÷ 0.500 = 0.10 M، و[Cl⁻] = 0.10 M، والتركيز الكلي للأيونات = 0.20 M. وجود هذا التركيز الكبير من الأيونات الحرة الحركة (الناتج عن التأين الكلي دون بقاء جزيئات HCl) يجعل المحلول موصلًا جيدًا.', '["تحويل الحجم إلى L","[H₃O⁺] = 0.10 M","[Cl⁻] = 0.10 M","التركيز الكلي 0.20 M","الربط بالتأين الكلي وكثرة الأيونات"]'::jsonb, '["V = 500 mL ÷ 1000 = 0.500 L","HCl + H₂O → H₃O⁺ + Cl⁻ (نسبة 1 : 1 : 1)","[H₃O⁺] = 0.050 mol ÷ 0.500 L = 0.10 M","[Cl⁻] = 0.10 M","مجموع الأيونات = 0.10 + 0.10 = 0.20 M"]'::jsonb, '[{"element":"تحويل الحجم","marks":1},{"element":"حساب [H₃O⁺] و[Cl⁻]","marks":2},{"element":"التركيز الكلي للأيونات","marks":1},{"element":"التفسير بالتأين الكلي","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حسابات صحيحة بوحداتها مع تفسير صحيح"},{"level":"3–4 درجات","description":"خطأ في التحويل أو في التركيز الكلي مع تفسير صحيح"},{"level":"1–2 درجة","description":"تفسير صحيح دون حسابات صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القسمة على 500 دون تحويل إلى L","افتراض تأين جزئي","إعطاء 0.10 M تركيزًا كليًا للأيونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (32%)"}],"at":"2026-10-17T11:36:22.446Z"}'::jsonb)
