('mcq', 1, 0, 'NaOH مركب أيوني يتفكك كليًا في الماء: NaOH → Na⁺ + OH⁻، فيكثر عدد الأيونات في المحلول فيوصل التيار جيدًا.', '["","NaOH قاعدة قوية تتفكك كليًا، ولا يبقى منها جزيئات غير متفككة.","التوصيل في المحلول ناتج عن الأيونات لا عن إلكترونات حرة.","ذوبان NaOH في الماء تفكك إلى أيونات، ولا ينتج غاز الهيدروجين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-10-17T11:36:22.446Z"}'::jsonb),
('mcq', 2, 2, 'يتفكك NaOH كليًا في الماء إلى أيونات الصوديوم والهيدروكسيد، وتُكتب المعادلة بسهم في اتجاه واحد: NaOH(s) → Na⁺(aq) + OH⁻(aq).', '["سهم الاتزان يدل على تفكك جزئي، أما NaOH فقاعدة قوية تتفكك كليًا.","NaOH لا يطلق H⁺؛ بل يطلق أيونات الهيدروكسيد OH⁻ لأنه قاعدة.","","التفكك في الماء ينتج أيونات مشحونة لا ذرات أو مجموعات متعادلة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.446Z"}'::jsonb),
('mcq', 3, 1, 'يتفكك NaOH إلى أيونات Na⁺ وOH⁻، وكلاهما يتحرك في المحلول نحو القطب المخالف لشحنته فينقلان التيار.', '["تنقل التيار الأيونات الموجبة والسالبة معًا، فأيونات Na⁺ تشارك أيضًا.","","أيونات OH⁻ السالبة تشارك أيضًا في نقل التيار.","هذه أيونات محلول HCl، لا محلول NaOH."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (42%)"}],"at":"2026-10-17T11:36:22.446Z"}'::jsonb),
('mcq', 4, 3, 'يعتمد توصيل القاعدة على مقدار ما تطلقه من أيونات OH⁻؛ NaOH قاعدة قوية تتفكك كليًا، أما CH₃NH₂ فقاعدة ضعيفة تتأين جزئيًا، لذا يتوهج المصباح بشدة أكبر في NaOH.', '["عدد الذرات في الجزيء لا يحدد التوصيل؛ المهم عدد الأيونات في المحلول.","تساوي التركيز لا يعني تساوي الأيونات؛ فالقاعدة الضعيفة تتأين جزئيًا.","استقبال H⁺ يحدث جزئيًا فقط، فتنتج أيونات OH⁻ أقل من NaOH.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.447Z"}'::jsonb),
('mcq', 5, 1, 'القاعدة القوية هي التي تتفكك كليًا في المحلول منتجة أيونات الهيدروكسيد، وهذا ما يحدث لـ NaOH.', '["احتواء مجموعة OH يجعله قاعدة أرهينيوس، لكن القوة تُحدَّد بالتفكك الكلي.","","الملمس الزلق خاصية عامة للقواعد القوية والضعيفة.","الاستعمال لا يحدد قوة القاعدة؛ القوة تعتمد على مدى التفكك."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.447Z"}'::jsonb),
('mcq', 6, 3, 'عدد المولات = 4.0 ÷ 40.0 = 0.10 mol، وكل mol من NaOH يطلق 1 mol من OH⁻ بالتفكك الكلي، فـ [OH⁻] = 0.10 mol ÷ 1.0 L = 0.10 M.', '["استُعملت الكتلة بالجرام مباشرة دون تحويلها إلى مولات بالقسمة على الكتلة المولية.","هذا يفترض تفكك نصف NaOH فقط، لكنه يتفكك كليًا.","0.20 M هو مجموع تركيزي Na⁺ وOH⁻ معًا لا تركيز OH⁻ وحده.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-17T11:36:22.447Z"}'::jsonb),
('mcq', 7, 2, 'Ba(OH)₂ → Ba²⁺ + 2OH⁻، فكل 1 mol منه يطلق 2 mol من OH⁻، و[OH⁻] = 2 × 0.10 = 0.20 M؛ لذلك يكون عدد الأيونات المسؤولة عن التوصيل فيه أكبر.', '["هذا تركيز OH⁻ في NaOH؛ أما Ba(OH)₂ فتطلق كل وحدة منه أيوني OH⁻.","قُسم التركيز على 2 بدل ضربه؛ كل وحدة Ba(OH)₂ تطلق أيوني OH⁻.","","هذا مجموع أيونات Ba²⁺ وOH⁻ معًا، لا تركيز OH⁻ وحده."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.447Z"}'::jsonb),
('essay', 1, null::int, null, null, 'NaOH مركب أيوني، وعند ذوبانه في الماء يتفكك كليًا (فهو قاعدة قوية) وفق المعادلة: NaOH(s) → Na⁺(aq) + OH⁻(aq). فيحتوي المحلول على عدد كبير من أيونات الصوديوم الموجبة وأيونات الهيدروكسيد السالبة الحرة الحركة، وهذه الأيونات تنقل التيار، لذا يوصل المحلول الكهرباء جيدًا.', '["NaOH مركب أيوني","يتفكك كليًا (قاعدة قوية)","المعادلة الصحيحة","الأيونات الكثيرة تنقل التيار"]'::jsonb, '[]'::jsonb, '[{"element":"NaOH مركب أيوني يتفكك كليًا","marks":1},{"element":"معادلة التفكك","marks":1},{"element":"كثرة الأيونات Na⁺ وOH⁻","marks":1},{"element":"الأيونات تنقل التيار","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل مع معادلة صحيحة"},{"level":"2–3 درجات","description":"تفسير صحيح دون معادلة أو دون ذكر التفكك الكلي"},{"level":"1 درجة","description":"ذكر وجود أيونات فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة سهم اتزان في معادلة NaOH","القول إن NaOH ينتج H⁺","إغفال أيونات Na⁺"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (31%)"}],"at":"2026-10-17T11:36:22.447Z"}'::jsonb),
('essay', 2, null::int, null, null, 'HCl مركب جزيئي لا يحتوي أيونات، وعند ذوبانه يتفاعل مع الماء فتتكون أيونات جديدة: HCl + H₂O → H₃O⁺ + Cl⁻، لذا يسمى ذلك تأينًا. أما NaOH فمركب أيوني يحتوي أصلًا على أيونات Na⁺ وOH⁻ في بلّورته، وعند ذوبانه تنفصل هذه الأيونات بعضها عن بعض: NaOH → Na⁺ + OH⁻، لذا يسمى تفككًا. ويشترك المحلولان في أن العملية كلية (HCl حمض قوي وNaOH قاعدة قوية)، فيحتوي كل منهما على تركيز كبير من الأيونات الحرة الحركة، فيوصلان التيار جيدًا.', '["HCl جزيئي تتكوّن أيوناته بالتفاعل مع الماء (تأين)","NaOH أيوني تنفصل أيوناته الموجودة (تفكك)","معادلتا العمليتين","كلتا العمليتين كلية ⇐ أيونات كثيرة"]'::jsonb, '[]'::jsonb, '[{"element":"وصف تأين HCl مع المعادلة","marks":1},{"element":"وصف تفكك NaOH مع المعادلة","marks":1},{"element":"التمييز بين التأين والتفكك","marks":1},{"element":"القاسم المشترك: عملية كلية وأيونات كثيرة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة دقيقة"},{"level":"2–3 درجات","description":"معادلتان صحيحتان دون تمييز واضح بين المفهومين"},{"level":"1 درجة","description":"ذكر أن المحلولين يحتويان أيونات فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن NaOH جزيئي","عدم التمييز بين التأين والتفكك","ذكر أن أحدهما يتأين جزئيًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-17T11:36:22.448Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) n = 2.0 ÷ 40.0 = 0.050 mol؛ V = 0.250 L؛ وبما أن NaOH يتفكك كليًا: [Na⁺] = [OH⁻] = 0.050 ÷ 0.250 = 0.20 M. (ب) يقل التوهج (يصبح خافتًا)؛ لأن CH₃NH₂ قاعدة ضعيفة تتأين جزئيًا (CH₃NH₂ + H₂O ⇌ CH₃NH₃⁺ + OH⁻) فتنتج أيونات OH⁻ أقل بكثير من NaOH الذي يتفكك كليًا، وتوصيل القاعدة يعتمد على مقدار ما تطلقه من أيونات.', '["عدد المولات 0.050 mol","V = 0.250 L","[Na⁺] = [OH⁻] = 0.20 M","التوهج يقل","التعليل بالتأين الجزئي وقلة OH⁻"]'::jsonb, '["n(NaOH) = 2.0 g ÷ 40.0 g/mol = 0.050 mol","V = 250 mL ÷ 1000 = 0.250 L","NaOH → Na⁺ + OH⁻ (1 : 1 : 1)","[Na⁺] = [OH⁻] = 0.050 ÷ 0.250 = 0.20 M"]'::jsonb, '[{"element":"حساب عدد المولات","marks":1},{"element":"تحويل الحجم","marks":0.5},{"element":"التركيزان الصحيحان","marks":1.5},{"element":"التوقع الصحيح","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حسابات صحيحة وتوقع معلل"},{"level":"3–4 درجات","description":"خطأ حسابي واحد مع توقع معلل، أو حسابات صحيحة مع تعليل ناقص"},{"level":"1–2 درجة","description":"توقع صحيح فقط أو خطوة حسابية واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القسمة على 250 بدل 0.250","نسيان القسمة على الكتلة المولية","توقع توهج متساوٍ لتساوي التركيز"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (28%)"}],"at":"2026-10-17T11:36:22.448Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K3-C2-L1-O04') and x.type = v.type and x.number = v.number
