select (select id from public.objectives where code = 'K3-C2-L1-O05'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'المحلول الحمضي هو المحلول الذي:', null, '["يحتوي على أيونات هيدروكسيد أكثر من أيونات الهيدروجين","يحتوي على أيونات هيدروجين أكثر من أيونات الهيدروكسيد","يحتوي على أيونات هيدروجين ولا يحتوي أيونات هيدروكسيد","يحتوي على تركيزين متساويين من الأيونين"]'::jsonb, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 58 — أيونات الهيدرونيوم والهيدروكسيد'),
('mcq', 2, 'أيّ مما يأتي يصف المحلول القاعدي؟', null, '["يحتوي على أيونات هيدروجين أكثر من أيونات الهيدروكسيد","لا يحتوي على أيونات هيدروجين إطلاقًا","يحتوي على أعداد متساوية من الأيونين","يحتوي على أيونات هيدروكسيد أكثر من أيونات الهيدروجين"]'::jsonb, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 58 — أيونات الهيدرونيوم والهيدروكسيد'),
('mcq', 3, 'يوصف المحلول بأنه متعادل عندما:', null, '["يتساوى فيه تركيزا أيونات الهيدروجين وأيونات الهيدروكسيد","لا يحتوي على أي أيونات على الإطلاق","يكون تركيز أيونات الهيدروجين فيه أكبر قليلًا","يكون تركيز أيونات الهيدروكسيد فيه أكبر قليلًا"]'::jsonb, 'تذكر', 'تعريف', 'متوسط', 'الكتاب ص 58 — أيونات الهيدرونيوم والهيدروكسيد'),
('mcq', 4, 'أيّ العبارات الآتية صحيحة عن المحلول المائي الحمضي؟', null, '["يحتوي على أيونات H⁺ فقط، ولا يوجد فيه OH⁻","يحتوي على أيونات OH⁻ فقط بكميات قليلة","يحتوي على أيونات H⁺ وOH⁻ معًا، وتكون H⁺ أكثر","يحتوي على أيونات OH⁻ أكثر من أيونات H⁺"]'::jsonb, 'فهم', 'فهم/تفسير', 'متوسط', 'الكتاب ص 58 — أيونات الهيدرونيوم والهيدروكسيد'),
('mcq', 5, 'ينتج الماء النقي أيونات بعملية التأين الذاتي: H₂O + H₂O ⇌ H₃O⁺ + OH⁻. ما الذي يمكن استنتاجه عن الماء النقي من هذه المعادلة؟', null, '["ينتج أعدادًا متساوية من H₃O⁺ وOH⁻ فهو متعادل","ينتج أيونات H₃O⁺ أكثر فهو حمضي","ينتج أيونات OH⁻ أكثر فهو قاعدي","لا ينتج أي أيونات فهو متعادل"]'::jsonb, 'فهم', 'استنتاج', 'متوسط', 'الكتاب ص 58 — أيونات الهيدرونيوم والهيدروكسيد'),
('mcq', 6, 'ما المقصود بأيون الهيدرونيوم H₃O⁺؟', null, '["أيون هيدروكسيد مرتبط مع جزيء هيدروجين","جزيء ماء فقد إلكترونًا واحدًا","ذرة هيدروجين مرتبطة بجزيء ماء برابطة أيونية","أيون هيدروجين مرتبط مع جزيء ماء برابطة تساهمية"]'::jsonb, 'تذكر', 'تعريف', 'متوسط', 'الكتاب ص 58 — أيونات الهيدرونيوم والهيدروكسيد'),
('mcq', 7, 'يمثّل مخطط تغيّر [H⁺] و[OH⁻] في الوقت نفسه؛ إذ يقع الطرف الحمضي يسارًا والقاعدي يمينًا. ماذا يحدث عند الانتقال من اليسار إلى اليمين؟ وأين يكون المحلول متعادلًا؟', null, '["يزداد [H⁺] ويقل [OH⁻]، ويكون متعادلًا عند تساويهما","يقل [H⁺] ويزداد [OH⁻]، ويكون متعادلًا عند تساويهما","يقل [H⁺] ويزداد [OH⁻]، ويكون متعادلًا عند انعدام H⁺","يقل التركيزان معًا، ويكون متعادلًا عند انعدامهما"]'::jsonb, 'فهم', 'تفسير رسم', 'صعب', 'الكتاب ص 58 — الشكل 2-3 وأيونات الهيدرونيوم والهيدروكسيد'),
('essay', 1, 'عرّف كلًّا من: المحلول الحمضي، والمحلول القاعدي، والمحلول المتعادل، بدلالة أيونات الهيدروجين وأيونات الهيدروكسيد.', null, null, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 58 — أيونات الهيدرونيوم والهيدروكسيد'),
('essay', 2, 'الماء النقي يحتوي على أيونات الهيدرونيوم H₃O⁺، ومع ذلك فهو ليس محلولًا حمضيًا. فسّر ذلك، مستعينًا بمعادلة التأين الذاتي للماء.', null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 58 — أيونات الهيدرونيوم والهيدروكسيد'),
('essay', 3, 'قال طالب: «المحلول القاعدي لا يحتوي على أيونات الهيدروجين، والمحلول الحمضي لا يحتوي على أيونات الهيدروكسيد». قيّم هذه العبارة، وصحّحها، ثم أعد صياغة تعريف المحلول الحمضي تعريفًا دقيقًا.', null, null, 'تقويم', 'تقييم عبارة', 'صعب', 'الكتاب ص 58 — أيونات الهيدرونيوم والهيدروكسيد')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
