from (values
('mcq', 1, 1, 'المحلول الحمضي هو المحلول الذي يحتوي على أيونات هيدروجين أكثر من أيونات الهيدروكسيد.', '["هذا تعريف المحلول القاعدي لا الحمضي.","","جميع المحاليل المائية تحتوي على النوعين معًا؛ والحمضي تكون فيه H⁺ أكثر.","تساوي التركيزين صفة المحلول المتعادل."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:36:22.448Z"}'::jsonb),
('mcq', 2, 3, 'المحلول القاعدي يحتوي على أيونات هيدروكسيد أكثر من أيونات الهيدروجين.', '["هذا وصف المحلول الحمضي.","المحلول القاعدي يحتوي أيونات هيدروجين لكن بتركيز أقل من OH⁻.","تساوي الأيونين يجعل المحلول متعادلًا لا قاعديًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.448Z"}'::jsonb),
('mcq', 3, 0, 'المحلول المتعادل ليس حمضيًا ولا قاعديًا، ويحتوي على تركيزين متساويين من أيونات الهيدروجين وأيونات الهيدروكسيد.', '["","حتى الماء النقي يحتوي على أيونات H₃O⁺ وOH⁻ ناتجة عن التأين الذاتي.","زيادة H⁺ ولو قليلًا تجعل المحلول حمضيًا.","زيادة OH⁻ ولو قليلًا تجعل المحلول قاعديًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.448Z"}'::jsonb),
('mcq', 4, 2, 'تحتوي المحاليل المائية جميعها على أيونات H⁺ وأيونات OH⁻، وتحدد الكميات النسبية منهما نوع المحلول؛ فالحمضي يحتوي على النوعين لكن H⁺ فيه أكثر.', '["جميع المحاليل المائية تحتوي على النوعين معًا، ويحدد الحمضية أيهما أكثر.","المحلول الحمضي يحتوي أيونات H⁺ بكمية أكبر من OH⁻.","","زيادة OH⁻ صفة المحلول القاعدي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:36:22.449Z"}'::jsonb),
('mcq', 5, 0, 'في التأين الذاتي يتفاعل جزيئا ماء فينتج أيون هيدرونيوم واحد وأيون هيدروكسيد واحد، فيحتوي الماء النقي على أعداد متساوية منهما ويكون متعادلًا.', '["","المعادلة تبيّن أن كل تأين ينتج أيون H₃O⁺ واحدًا مقابل أيون OH⁻ واحد.","عدد أيونات OH⁻ يساوي عدد أيونات H₃O⁺ الناتجة.","التأين الذاتي ينتج أيونات فعلًا، ولكن بأعداد متساوية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.449Z"}'::jsonb),
('mcq', 6, 3, 'أيون الهيدرونيوم هو أيون هيدروجين مرتبط مع جزيء ماء برابطة تساهمية، ويمكن استعمال الرمزين H⁺ وH₃O⁺ بالتبادل.', '["أيون الهيدروكسيد سالب، ولا يكوّن أيونًا موجبًا بارتباطه مع H₂.","H₃O⁺ يحتوي ثلاث ذرات هيدروجين، فهو جزيء ماء اكتسب H⁺ لا جزيء فقد إلكترونًا.","المرتبط أيون H⁺ لا ذرة متعادلة، والرابطة تساهمية لا أيونية.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.449Z"}'::jsonb),
('mcq', 7, 1, 'عندما يقل [H⁺] نحو اليمين تزداد قيمة [OH⁻]، والنقطة التي يتساوى فيها تركيزا الأيونين تمثّل المحلول المتعادل.', '["الانتقال نحو الطرف القاعدي يعني نقصان H⁺ وزيادة OH⁻، لا العكس.","","انعدام H⁺ لا يحدث في المحلول المائي، والتعادل عند تساوي التركيزين.","التركيزان يتغيران في اتجاهين متعاكسين، ولا ينعدمان."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.449Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المحلول الحمضي: محلول يحتوي على أيونات هيدروجين أكثر من أيونات الهيدروكسيد. المحلول القاعدي: محلول يحتوي على أيونات هيدروكسيد أكثر من أيونات الهيدروجين. المحلول المتعادل: محلول يحتوي على تركيزين متساويين من أيونات الهيدروجين وأيونات الهيدروكسيد، فهو ليس حمضيًا ولا قاعديًا.', '["تعريف المحلول الحمضي","تعريف المحلول القاعدي","تعريف المحلول المتعادل"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف المحلول الحمضي","marks":1},{"element":"تعريف المحلول القاعدي","marks":1},{"element":"تعريف المحلول المتعادل","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"التعريفات الثلاثة صحيحة"},{"level":"2 درجتان","description":"تعريفان صحيحان"},{"level":"1 درجة","description":"تعريف واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريف المحلول الحمضي بأنه لا يحتوي OH⁻","تعريف المتعادل بأنه خالٍ من الأيونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T11:36:22.450Z"}'::jsonb),
('essay', 2, null::int, null, null, 'يتأين الماء النقي تأينًا ذاتيًا وفق المعادلة: H₂O + H₂O ⇌ H₃O⁺ + OH⁻ (أو بالصورة المبسطة H₂O ⇌ H⁺ + OH⁻). كل تأين ينتج أيون هيدرونيوم واحدًا وأيون هيدروكسيد واحدًا، فتكون أعدادهما متساوية. والمحلول الحمضي هو الذي يحتوي على أيونات هيدروجين أكثر من أيونات الهيدروكسيد، وهذا لا يتحقق في الماء النقي؛ لذا فهو متعادل رغم احتوائه على H₃O⁺.', '["معادلة التأين الذاتي","أعداد متساوية من H₃O⁺ وOH⁻","تعريف المحلول الحمضي (H⁺ أكثر)","الاستنتاج: الماء متعادل"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة التأين الذاتي","marks":1},{"element":"تساوي أعداد الأيونين","marks":1},{"element":"الاستناد إلى تعريف المحلول الحمضي","marks":1},{"element":"الاستنتاج الصحيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل مع المعادلة والتعريف"},{"level":"2–3 درجات","description":"تفسير صحيح دون معادلة أو دون الاستناد للتعريف"},{"level":"1 درجة","description":"ذكر أن الماء متعادل دون تفسير"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الماء النقي لا يحتوي أيونات","عدّ وجود H₃O⁺ كافيًا لجعل المحلول حمضيًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.450Z"}'::jsonb),
('essay', 3, null::int, null, null, 'العبارة غير صحيحة؛ فجميع المحاليل المائية تحتوي على أيونات الهيدروجين H⁺ (أو H₃O⁺) وأيونات الهيدروكسيد OH⁻ معًا، لأن الماء نفسه يتأين ذاتيًا منتجًا النوعين. والذي يحدد نوع المحلول هو الكميات النسبية للأيونين لا وجود أحدهما وغياب الآخر. التصحيح: المحلول القاعدي يحتوي على أيونات هيدروجين أقل من أيونات الهيدروكسيد، والمحلول الحمضي يحتوي على أيونات هيدروكسيد أقل من أيونات الهيدروجين. التعريف الدقيق: المحلول الحمضي محلول يحتوي على أيونات هيدروجين أكثر من أيونات الهيدروكسيد.', '["الحكم: العبارة خاطئة","التعليل: كل المحاليل المائية تحتوي النوعين (التأين الذاتي)","النوع يحدده التركيز النسبي","تصحيح العبارة","التعريف الدقيق للمحلول الحمضي"]'::jsonb, '[]'::jsonb, '[{"element":"الحكم الصحيح على العبارة","marks":1},{"element":"التعليل بالتأين الذاتي ووجود النوعين","marks":1},{"element":"بيان أن الكميات النسبية هي المحددة","marks":1},{"element":"تصحيح العبارة","marks":1},{"element":"التعريف الدقيق","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"حكم صحيح معلل مع تصحيح وتعريف دقيق"},{"level":"3–4 درجات","description":"حكم صحيح مع نقص في التعليل أو التصحيح"},{"level":"1–2 درجة","description":"تعريف صحيح فقط دون تقييم"},{"level":"صفر","description":"إجابة خاطئة أو موافقة الطالب"}]'::jsonb, '["موافقة الطالب على العبارة","تعريف الحمضي بأنه يحتوي H⁺ فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T11:36:22.450Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
