('mcq', 7, 'أيّ الشروط الآتية يلزم توافرها معًا كي تُصنَّف مادة قاعدةً وفق نظرية أرهينيوس؟', null, '["أن تحتوي على مجموعة الهيدروكسيد، وتتفكك في الماء منتجة OH⁻","أن تنتج OH⁻ في الماء فقط، ولو لم تحتوِ مجموعة الهيدروكسيد","أن تحتوي على مجموعة الهيدروكسيد فقط، ولو لم تتفكك في الماء","أن تستقبل أيون الهيدروجين من جزيء الماء"]'::jsonb, 'فهم', 'فهم/تفسير', 'صعب', 'الكتاب ص 59 — نظرية أرهينيوس'),
('essay', 1, 'عرّف كلًّا من الحمض والقاعدة وفق نظرية أرهينيوس، واكتب معادلة كيميائية توضّح كل تعريف.', null, null, 'تذكر', 'تعريف مع أمثلة', 'سهل', 'الكتاب ص 59 — نظرية أرهينيوس'),
('essay', 2, 'إذا كان الماء النقي متعادلًا، فكيف يصبح المحلول المائي حمضيًا أو قاعديًا وفق نظرية أرهينيوس؟ وضّح ذلك بمثالي HCl وNaOH.', null, null, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 59 — نظرية أرهينيوس'),
('essay', 3, 'صنّف كل مادة مما يأتي وفق نظرية أرهينيوس إلى: حمض، أو قاعدة، أو لا هذا ولا ذاك، مع التعليل، واكتب معادلة التأين أو التفكك لما يُصنَّف منها حمضًا أو قاعدة:
HBr ، KOH ، C₆H₆ (البنزين) ، NH₃', null, null, 'تطبيق', 'تصنيف مع تعليل', 'صعب', 'الكتاب ص 59 و62 — نظرية أرهينيوس وذرات الهيدروجين القابلة للتأين')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
