from (values
('mcq', 1, 2, 'نصت نظرية أرهينيوس على أن الحمض مادة تحتوي على الهيدروجين وتتأين في المحاليل المائية منتجة أيونات الهيدروجين.', '["هذا تعريف الحمض وفق نظرية برونستد – لوري.","هذا تعريف الحمض وفق نظرية لويس.","","إنتاج OH⁻ صفة قاعدة أرهينيوس لا حمضه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-10-17T11:36:22.451Z"}'::jsonb),
('mcq', 2, 0, 'قاعدة أرهينيوس مادة تحتوي على مجموعة الهيدروكسيد، وتتفكك في المحلول المائي منتجة أيون الهيدروكسيد.', '["","هذا تعريف القاعدة وفق نظرية برونستد – لوري.","هذا تعريف القاعدة وفق نظرية لويس.","أرهينيوس اشترط احتواء القاعدة على مجموعة الهيدروكسيد، ولذلك لم تشمل نظريته الأمونيا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-10-17T11:36:22.451Z"}'::jsonb),
('mcq', 3, 3, 'تنص نظرية أرهينيوس على أن الحمض منتج لأيون H⁺ والقاعدة منتجة لأيون OH⁻.', '["هذان تعريفا برونستد – لوري.","هذان تعريفا لويس.","الترتيب معكوس؛ الحمض ينتج H⁺ والقاعدة تنتج OH⁻.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (29%)"}],"at":"2026-10-17T11:36:22.451Z"}'::jsonb),
('mcq', 4, 1, 'حمض أرهينيوس يتأين في المحلول المائي منتجًا أيونات H⁺، كما في HCl(g) → H⁺(aq) + Cl⁻(aq).', '["هذه معادلة تفكك قاعدة أرهينيوس منتجة OH⁻.","","الأمونيا هنا تستقبل H⁺ فهي قاعدة برونستد – لوري، وليست حمض أرهينيوس.","هذا تفاعل حمض لويس مع قاعدة لويس دون إنتاج H⁺ في الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-17T11:36:22.451Z"}'::jsonb),
('mcq', 5, 2, 'KOH يحتوي على مجموعة الهيدروكسيد ويتفكك في الماء: KOH → K⁺ + OH⁻، فهو قاعدة أرهينيوس.', '["الأمونيا لا تحتوي على مجموعة الهيدروكسيد، فلا تُعدّ قاعدة أرهينيوس.","حمض الإيثانويك حمض يتأين منتجًا H⁺، ومجموعته OH جزء من مجموعة الكربوكسيل لا تنفصل كأيون OH⁻.","","Na₂CO₃ لا تحتوي على مجموعة الهيدروكسيد رغم أن محلولها قاعدي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-10-17T11:36:22.451Z"}'::jsonb),
('mcq', 6, 1, 'HNO₃ يحتوي على الهيدروجين ويتأين في الماء منتجًا أيونات H⁺: HNO₃ → H⁺ + NO₃⁻، فهو حمض أرهينيوس.', '["يحتوي البنزين على الهيدروجين، لكن ذراته لا تتأين في المحلول المائي فلا ينتج H⁺.","","NaOH ينتج OH⁻ فهو قاعدة أرهينيوس.","الأمونيا لا تنتج H⁺ في الماء، بل تنتج OH⁻ باستقبالها H⁺."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-10-17T11:36:22.451Z"}'::jsonb),
('mcq', 7, 0, 'تعريف أرهينيوس للقاعدة يجمع شرطين: احتواء المادة على مجموعة الهيدروكسيد، وتفككها في المحلول المائي منتجة أيونات OH⁻.', '["","هذا الشرط يشمل NH₃ وNa₂CO₃، وهما ليستا قاعدتي أرهينيوس.","أرهينيوس اشترط التفكك في المحلول المائي وإنتاج أيون OH⁻.","استقبال H⁺ هو تعريف القاعدة وفق برونستد – لوري."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.451Z"}'::jsonb),
('essay', 1, null::int, null, null, 'حمض أرهينيوس: مادة تحتوي على الهيدروجين وتتأين في المحاليل المائية منتجة أيونات الهيدروجين، مثل: HCl(g) → H⁺(aq) + Cl⁻(aq). قاعدة أرهينيوس: مادة تحتوي على مجموعة الهيدروكسيد وتتفكك في المحلول المائي منتجة أيون الهيدروكسيد، مثل: NaOH(s) → Na⁺(aq) + OH⁻(aq).', '["تعريف الحمض","معادلة الحمض","تعريف القاعدة","معادلة القاعدة"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف حمض أرهينيوس","marks":1},{"element":"معادلة صحيحة للحمض","marks":1},{"element":"تعريف قاعدة أرهينيوس","marks":1},{"element":"معادلة صحيحة للقاعدة","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تعريفان صحيحان ومعادلتان صحيحتان"},{"level":"2–3 درجات","description":"تعريفان صحيحان دون معادلات أو بمعادلة واحدة"},{"level":"1 درجة","description":"تعريف واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين تعريف أرهينيوس وبرونستد – لوري","إغفال شرط المحلول المائي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-17T11:36:22.451Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الماء النقي يحتوي على أعداد متساوية من H⁺ وOH⁻ فهو متعادل. وفق أرهينيوس: عند إذابة غاز HCl في الماء تتأين جزيئاته: HCl → H⁺ + Cl⁻، فتزداد أيونات H⁺ في المحلول وتصبح أكثر من OH⁻ فيصبح المحلول حمضيًا. وعند إذابة المركب الأيوني NaOH يتفكك: NaOH → Na⁺ + OH⁻، فتزداد أيونات OH⁻ وتصبح أكثر من H⁺ فيصبح المحلول قاعديًا.', '["الماء النقي متعادل لتساوي الأيونين","HCl يتأين منتجًا H⁺ فيزيد H⁺","NaOH يتفكك منتجًا OH⁻ فيزيد OH⁻","الربط بتعريف المحلول الحمضي والقاعدي"]'::jsonb, '[]'::jsonb, '[{"element":"حالة الماء النقي","marks":1},{"element":"تفسير حمضية محلول HCl مع المعادلة","marks":1.5},{"element":"تفسير قاعدية محلول NaOH مع المعادلة","marks":1.5}]'::jsonb, '[{"level":"4 درجات","description":"تفسير كامل للحالتين مع المعادلتين"},{"level":"2–3 درجات","description":"تفسير حالة واحدة كاملة أو الحالتين دون معادلات"},{"level":"1 درجة","description":"ذكر أن الحمض ينتج H⁺ والقاعدة OH⁻ فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن HCl ينتج OH⁻","عدم الربط بين زيادة الأيون ونوع المحلول"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.451Z"}'::jsonb),
('essay', 3, null::int, null, null, 'HBr: حمض أرهينيوس؛ يحتوي على الهيدروجين ويتأين في الماء منتجًا H⁺: HBr → H⁺ + Br⁻. KOH: قاعدة أرهينيوس؛ تحتوي على مجموعة الهيدروكسيد وتتفكك منتجة OH⁻: KOH → K⁺ + OH⁻. C₆H₆: لا هذا ولا ذاك؛ يحتوي على الهيدروجين لكن ذراته لا تتأين في الماء، ولا يحتوي على مجموعة هيدروكسيد. NH₃: لا تُصنَّف قاعدة أرهينيوس (ولا حمضًا)؛ لأنها لا تحتوي على مجموعة الهيدروكسيد، مع أن محلولها قاعدي.', '["HBr حمض مع المعادلة","KOH قاعدة مع المعادلة","C₆H₆ لا هذا ولا ذاك مع التعليل","NH₃ ليست قاعدة أرهينيوس مع التعليل"]'::jsonb, '[]'::jsonb, '[{"element":"HBr تصنيف ومعادلة","marks":1.5},{"element":"KOH تصنيف ومعادلة","marks":1.5},{"element":"C₆H₆ تصنيف وتعليل","marks":1},{"element":"NH₃ تصنيف وتعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف الأربع صحيح مع التعليل والمعادلتين"},{"level":"3–4 درجات","description":"تصنيف صحيح مع نقص معادلة أو تعليل"},{"level":"1–2 درجة","description":"تصنيف صحيح لمادتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ البنزين حمضًا لاحتوائه على الهيدروجين","عدّ NH₃ قاعدة أرهينيوس لأن محلولها قاعدي"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.452Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
