('mcq', 1, 'يحتوي البنزين C₆H₆ على ذرات هيدروجين، ومع ذلك لا يُصنَّف حمض أرهينيوس. ما السبب؟', null, '["لأنه لا يحتوي على مجموعة الهيدروكسيد","لأنه يتأين كليًا في الماء منتجًا OH⁻","لأن عدد ذرات الهيدروجين فيه كبير جدًا","لأن ذرات الهيدروجين فيه لا تتأين في المحلول المائي منتجة H⁺"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 59 و62 و65 — نظرية أرهينيوس وذرات الهيدروجين القابلة للتأين'),
('mcq', 2, 'ما وجه قصور نظرية أرهينيوس الذي تكشفه الأمونيا NH₃؟', null, '["تحتوي الأمونيا على مجموعة OH، لكنها لا تتفكك في الماء","لا تحتوي الأمونيا على مجموعة OH، ومع ذلك تنتج OH⁻ في الماء","تنتج الأمونيا أيونات H⁺ في الماء فتُعدّ حمضًا","لا تذوب الأمونيا في الماء فلا يمكن اختبارها"]'::jsonb, 'فهم', 'فهم/تفسير', 'سهل', 'الكتاب ص 59 — نظرية أرهينيوس'),
('mcq', 3, 'ما المركب المسؤول عن جعل مياه بحيرة ناترون في تنزانيا قاعدية؟', null, '["هيدروكسيد الصوديوم NaOH","الأمونيا NH₃","كربونات الصوديوم Na₂CO₃","حمض الكربونيك H₂CO₃"]'::jsonb, 'تذكر', 'تذكر/تعرف', 'سهل', 'الكتاب ص 59 — الشكل 2-5 بحيرة ناترون'),
('mcq', 4, 'أيّ المعادلات الآتية تبيّن كيف تنتج الأمونيا أيونات الهيدروكسيد عند ذوبانها في الماء؟', null, '["NH₃ + H₂O ⇌ NH₄⁺ + OH⁻","NH₃ → NH₂⁻ + H⁺","NH₃ + H₂O ⇌ NH₂⁻ + H₃O⁺","NH₃ → N³⁻ + 3H⁺"]'::jsonb, 'فهم', 'تفسير', 'متوسط', 'الكتاب ص 61 — الأمونيا قاعدة برونستد – لوري'),
('mcq', 5, 'لماذا لا تستطيع نظرية أرهينيوس تصنيف الأمونيا قاعدةً رغم أن محلولها قاعدي؟', null, '["لأن تعريفها يشترط أن تكون القاعدة في الحالة الصلبة","لأن الأمونيا تمنح أيون H⁺ لجزيء الماء","لأن تعريفها يقتصر على المحاليل غير المائية","لأن تعريفها يشترط احتواء القاعدة على مجموعة OH تتفكك منها"]'::jsonb, 'فهم', 'فهم/تفسير', 'متوسط', 'الكتاب ص 59 — نظرية أرهينيوس'),
('mcq', 6, 'يبيّن الجدول بعض المواد وأثر محاليلها في ورق تبّاع الشمس الأحمر. أيّ هذه المواد يُعدّ قاعدة أرهينيوس؟', '{"headers":["المادة","الصيغة","أثر المحلول في تبّاع الشمس الأحمر"],"rows":[["هيدروكسيد البوتاسيوم","KOH","يتحول إلى الأزرق"],["كربونات الصوديوم","Na₂CO₃","يتحول إلى الأزرق"],["الأمونيا","NH₃","يتحول إلى الأزرق"]]}'::jsonb, '["KOH وNa₂CO₃","KOH وNa₂CO₃ وNH₃","KOH فقط","NH₃ فقط"]'::jsonb, 'تحليل', 'تحليل بيانات', 'صعب', 'الكتاب ص 57 و59 — تبّاع الشمس وقصور نظرية أرهينيوس'),
('mcq', 7, 'إلامَ دفعت حالاتٌ مثل الأمونيا وكربونات الصوديوم العلماءَ في دراسة الأحماض والقواعد؟', null, '["إلى نظرية أشمل تعرّف القاعدة بأنها مستقبلة لأيون الهيدروجين","إلى إلغاء مفهوم القاعدة والاكتفاء بمفهوم الحمض","إلى نظرية تعرّف القاعدة بأنها مانحة لأيون الهيدروجين","إلى تصنيف الأمونيا وكربونات الصوديوم أحماضًا"]'::jsonb, 'فهم', 'فهم/تفسير', 'صعب', 'الكتاب ص 59–61 — من أرهينيوس إلى برونستد – لوري'),
('essay', 1, 'وضّح قصور نظرية أرهينيوس في تفسير سلوك بعض القواعد، مستعينًا بمثال الأمونيا NH₃.', null, null, 'فهم', 'توضيح', 'سهل', 'الكتاب ص 59 — نظرية أرهينيوس'),
('essay', 2, 'تعدّ بحيرة ناترون في تنزانيا مثالًا طبيعيًا على المياه القاعدية بسبب كربونات الصوديوم Na₂CO₃ الذائبة فيها. وضّح لماذا يمثّل هذا المثال قصورًا في نظرية أرهينيوس، مستعينًا بمعادلة تفاعل أيون الكربونات CO₃²⁻ مع الماء.', null, null, 'فهم', 'توضيح مع معادلة', 'متوسط', 'الكتاب ص 59 و62 — بحيرة ناترون ومسائل تدريبية'),
('essay', 3, 'قارن بين تصنيف الأمونيا NH₃ وفق نظرية أرهينيوس ووفق نظرية برونستد – لوري، ثم حلّل كيف تتغلب نظرية برونستد – لوري على قصور نظرية أرهينيوس في هذه الحالة، مستعينًا بمعادلة.', null, null, 'تحليل', 'مقارنة وتحليل', 'صعب', 'الكتاب ص 59–61 — نظريتا أرهينيوس وبرونستد – لوري')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
