from (values
('mcq', 1, 3, 'يشترط أرهينيوس أن يتأين الحمض في المحلول المائي منتجًا أيونات H⁺، وذرات الهيدروجين في البنزين لا تتأين، لذا لا يُصنَّف حمضًا رغم احتوائه عليها.', '["احتواء مجموعة الهيدروكسيد شرط لقاعدة أرهينيوس لا لحمضه.","البنزين لا يتأين في الماء، ولا ينتج OH⁻.","عدد ذرات الهيدروجين لا يحدد الحمضية؛ المهم قابليتها للتأين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.452Z"}'::jsonb),
('mcq', 2, 1, 'تعريف أرهينيوس يشترط أن تحتوي القاعدة على مجموعة الهيدروكسيد، لكن NH₃ لا تحتويها ومع ذلك ينتج محلولها أيونات OH⁻؛ فالنظرية تعجز عن تصنيفها قاعدة.', '["الأمونيا NH₃ لا تحتوي على مجموعة الهيدروكسيد أصلًا.","","الأمونيا تستقبل H⁺ وينتج محلولها OH⁻، فهي قاعدية لا حمضية.","الأمونيا تذوب في الماء ومحلولها قاعدي."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.452Z"}'::jsonb),
('mcq', 3, 2, 'تصب في بحيرة ناترون مياه تحمل كميات كبيرة من كربونات الصوديوم الذائبة من الصخور البركانية، وNa₂CO₃ هي المسؤولة عن قاعدية البحيرة.', '["المياه تحمل كميات كبيرة من كربونات الصوديوم الذائبة لا هيدروكسيده.","الأمونيا مثال آخر على القصور، لكنها ليست سبب قاعدية بحيرة ناترون.","","حمض الكربونيك حمض، ولا يجعل الماء قاعديًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.453Z"}'::jsonb),
('mcq', 4, 0, 'تستقبل الأمونيا أيون H⁺ من جزيء الماء فيتكوّن أيون الأمونيوم NH₄⁺ ويبقى أيون OH⁻: NH₃ + H₂O ⇌ NH₄⁺ + OH⁻؛ فيصبح المحلول قاعديًا دون أن تحتوي NH₃ على مجموعة OH.', '["","هذه المعادلة تجعل الأمونيا مانحة لـ H⁺، وهي لا تنتج OH⁻.","هذا يجعل الأمونيا حمضًا ينتج H₃O⁺، وهو عكس سلوكها في الماء.","الأمونيا لا تتأين بهذه الصورة، ولا ينتج عنها OH⁻."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (7%)"}],"at":"2026-10-17T11:36:22.453Z"}'::jsonb),
('mcq', 5, 3, 'يعرّف أرهينيوس القاعدة بأنها مادة تحتوي على مجموعة الهيدروكسيد وتتفكك منتجة OH⁻، والأمونيا لا تحتوي هذه المجموعة؛ فلا ينطبق عليها التعريف رغم قاعدية محلولها.', '["لا يتضمن تعريف أرهينيوس شرطًا يتعلق بحالة المادة.","الأمونيا تستقبل H⁺ ولا تمنحه.","نظرية أرهينيوس خاصة بالمحاليل المائية تحديدًا.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (19%)"}],"at":"2026-10-17T11:36:22.453Z"}'::jsonb),
('mcq', 6, 2, 'المواد الثلاث تحوّل تبّاع الشمس الأحمر إلى الأزرق فمحاليلها قاعدية، لكن قاعدة أرهينيوس يجب أن تحتوي على مجموعة الهيدروكسيد وتتفكك منتجة OH⁻، وهذا يتحقق في KOH فقط.', '["Na₂CO₃ تحتوي على الأكسجين لكنها لا تحتوي على مجموعة الهيدروكسيد.","محاليل الثلاثة قاعدية، لكن KOH وحده يحتوي مجموعة OH تتفكك منه.","","الأمونيا مثال على قصور أرهينيوس؛ فهي لا تحتوي على مجموعة OH."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.453Z"}'::jsonb),
('mcq', 7, 0, 'قصور أرهينيوس يستلزم نظرية أكثر دقة تشمل القواعد جميعها، وهي نظرية برونستد – لوري التي تعرّف القاعدة بأنها مستقبلة لأيون الهيدروجين، فتشمل الأمونيا.', '["","لم تُلغَ القواعد، بل وُسّع تعريفها ليشمل مواد أكثر.","المادة المانحة لأيون الهيدروجين حمض لا قاعدة.","محلولا المادتين قاعديان، فلا تُصنَّفان أحماضًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-17T11:36:22.453Z"}'::jsonb),
('essay', 1, null::int, null, null, 'تعرّف نظرية أرهينيوس القاعدة بأنها مادة تحتوي على مجموعة الهيدروكسيد وتتفكك في الماء منتجة OH⁻. لكن الأمونيا NH₃ لا تحتوي على مجموعة الهيدروكسيد، ومع ذلك تنتج أيونات OH⁻ عند ذوبانها في الماء فيصبح محلولها قاعديًا. لذا تعجز النظرية عن تصنيف الأمونيا قاعدة، فهي لا تشمل جميع القواعد، وهذا قصور فيها.', '["تعريف أرهينيوس للقاعدة","الأمونيا لا تحتوي OH","الأمونيا تنتج OH⁻ في الماء","النتيجة: النظرية لا تشمل كل القواعد"]'::jsonb, '[]'::jsonb, '[{"element":"ذكر تعريف أرهينيوس للقاعدة","marks":1},{"element":"خلو NH₃ من مجموعة OH","marks":1},{"element":"إنتاج NH₃ لأيونات OH⁻ في الماء","marks":1},{"element":"استنتاج القصور","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"توضيح كامل مترابط"},{"level":"2–3 درجات","description":"ذكر المثال دون ربطه بالتعريف أو العكس"},{"level":"1 درجة","description":"ذكر أن النظرية قاصرة دون توضيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الأمونيا تحتوي مجموعة OH","عدّ الأمونيا حمضًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.453Z"}'::jsonb),
('essay', 2, null::int, null, null, 'Na₂CO₃ لا تحتوي على مجموعة الهيدروكسيد، فلا تُعدّ قاعدة وفق أرهينيوس. لكن عند ذوبانها في الماء يتفاعل أيون الكربونات مع الماء: CO₃²⁻ + H₂O ⇌ HCO₃⁻ + OH⁻، فيستقبل أيون الكربونات H⁺ من الماء وتنتج أيونات OH⁻ تجعل مياه البحيرة قاعدية. فالمحلول قاعدي مع أن المادة ليست قاعدة أرهينيوس، وهذا يبيّن أن النظرية لا تشمل جميع القواعد.', '["Na₂CO₃ لا تحتوي OH","المعادلة الصحيحة","إنتاج OH⁻ يجعل المياه قاعدية","استنتاج القصور"]'::jsonb, '[]'::jsonb, '[{"element":"خلو Na₂CO₃ من مجموعة OH","marks":1},{"element":"معادلة تفاعل CO₃²⁻ مع الماء","marks":1},{"element":"تفسير قاعدية المياه","marks":1},{"element":"ربط ذلك بقصور النظرية","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"توضيح كامل مع المعادلة"},{"level":"2–3 درجات","description":"توضيح صحيح دون معادلة أو مع خطأ فيها"},{"level":"1 درجة","description":"ذكر أن Na₂CO₃ تجعل المياه قاعدية فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة Na₂CO₃ → 2Na⁺ + CO₃²⁻ دون بيان مصدر OH⁻","القول إن Na₂CO₃ تحتوي مجموعة OH لاحتوائها على الأكسجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.454Z"}'::jsonb),
('essay', 3, null::int, null, null, 'وفق أرهينيوس: لا تُصنَّف NH₃ قاعدة لأنها لا تحتوي على مجموعة الهيدروكسيد. وفق برونستد – لوري: NH₃ قاعدة لأنها تستقبل أيون H⁺ من الماء: NH₃ + H₂O ⇌ NH₄⁺ + OH⁻. تتغلب برونستد – لوري على القصور لأنها تعرّف القاعدة بسلوكها (استقبال H⁺) لا بتركيبها (احتواء OH)؛ فأيون OH⁻ في المحلول مصدره جزيء الماء الذي منح H⁺، لا الأمونيا نفسها، ولذلك تشمل النظرية الأشمل قواعد لم تشملها نظرية أرهينيوس.', '["تصنيف أرهينيوس وتعليله","تصنيف برونستد – لوري وتعليله","المعادلة","التحليل: التعريف بالسلوك لا بالتركيب","مصدر OH⁻ هو الماء"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف أرهينيوس مع التعليل","marks":1},{"element":"تصنيف برونستد – لوري مع التعليل","marks":1},{"element":"المعادلة الصحيحة","marks":1},{"element":"تحليل سبب التغلب على القصور","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"مقارنة صحيحة وتحليل عميق مع المعادلة"},{"level":"3–4 درجات","description":"مقارنة صحيحة مع تحليل ناقص"},{"level":"1–2 درجة","description":"تصنيف صحيح وفق نظرية واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن الأمونيا تمنح H⁺","عدم بيان مصدر OH⁻"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.454Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
