('mcq', 6, 'أيّ الأزواج الآتية يمثّل (حمض، قاعدته المرافقة) بصورة صحيحة؟', null, '["(HSO₄⁻ ، H₂SO₄)","(HCl ، H₂)","(CH₃COOH ، CH₃COOH₂⁺)","(H₂SO₄ ، HSO₄⁻)"]'::jsonb, 'تطبيق', 'تحديد', 'متوسط', 'الكتاب ص 63 — الجدول 2-1 الأحماض الشائعة وقواعدها المرافقة'),
('mcq', 7, 'يبيّن الجدول أربعة أزواج (حمض ← قاعدة مرافقة مقترحة). أيّ الخيارات الآتية يمثّل الزوج الصحيح الوحيد؟', '{"headers":["الصف","الحمض","القاعدة المرافقة المقترحة"],"rows":[["1","HCN","CN²⁻"],["2","CH₃COOH","CH₃CO⁻"],["3","HF","F⁻"],["4","HCO₃⁻","H₂CO₃"]]}'::jsonb, '["HCN ← CN²⁻","CH₃COOH ← CH₃CO⁻","HCO₃⁻ ← H₂CO₃","HF ← F⁻"]'::jsonb, 'تحليل', 'تحليل بيانات', 'صعب', 'الكتاب ص 63 — الجدول 2-1 الأحماض الشائعة وقواعدها المرافقة'),
('essay', 1, 'عرّف القاعدة المرافقة، ثم اكتب القاعدة المرافقة لكل من الأحماض الآتية: HCl ، H₂SO₄ ، CH₃COOH ، H₂CO₃.', null, null, 'تذكر', 'تعريف وتطبيق', 'سهل', 'الكتاب ص 63 — الجدول 2-1 الأحماض الشائعة وقواعدها المرافقة'),
('essay', 2, 'اكتب خطوات تأين حمض الفوسفوريك H₃PO₄ الثلاث في الماء، وحدّد في كل خطوة الحمض والقاعدة المرافقة له.', null, null, 'تطبيق', 'كتابة معادلات', 'متوسط', 'الكتاب ص 63 — خطوات تأين حمض الفوسفوريك'),
('essay', 3, 'لديك التفاعل: HNO₂ + H₂O ⇌ NO₂⁻ + H₃O⁺ . (أ) حدّد الحمض والقاعدة في التفاعل الأمامي. (ب) اكتب القاعدة المرافقة لـ HNO₂ والحمض المرافق لـ H₂O. (ج) فسّر لماذا يُعدّ كل من HNO₂/NO₂⁻ وH₃O⁺/H₂O زوجًا مترافقًا، ولماذا لا يشكّل HNO₂ وH₃O⁺ زوجًا مترافقًا.', null, null, 'تحليل', 'تحليل معادلة', 'صعب', 'الكتاب ص 60–61 و65 — الأزواج المترافقة')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
