from (values
('mcq', 1, 1, 'القاعدة المرافقة تنتج عندما يمنح الحمض أيون H⁺؛ وبفقد HF لأيون H⁺ تبقى F⁻، فهي القاعدة المرافقة.', '["H₂F⁺ ينتج باكتساب H⁺ لا بفقده؛ فهو الحمض المرافق المحتمل لا القاعدة المرافقة.","","القاعدة المرافقة تنتج بفقد H⁺ من الحمض لا بإضافة F إليه.","H₃O⁺ هو الحمض المرافق للماء في التفاعل، وليس القاعدة المرافقة لـ HF."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-17T11:36:22.456Z"}'::jsonb),
('mcq', 2, 3, 'بفقد HNO₃ لأيون H⁺ ينتج NO₃⁻، وهو القاعدة المرافقة.', '["NO₂⁻ هو القاعدة المرافقة لحمض HNO₂ لا HNO₃.","H₂NO₃⁺ ناتج عن اكتساب H⁺ فهو حمض لا قاعدة مرافقة.","نزع H⁺ يخفض الشحنة بمقدار واحد فقط، فالناتج NO₃⁻ لا NO₃²⁻.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-17T11:36:22.456Z"}'::jsonb),
('mcq', 3, 0, 'يمنح HCO₃⁻ أيون H⁺ فيتحول إلى CO₃²⁻، وهي القاعدة المرافقة له.', '["","H₂CO₃ هو الحمض المرافق لـ HCO₃⁻ حين يسلك سلوك القاعدة.","الصيغة لا تعبّر عن فقد H⁺؛ إذ لا يتغير عدد ذرات الهيدروجين.","CO₂ ليس ناتج فقد H⁺ بل ناتج تحلل H₂CO₃."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.457Z"}'::jsonb),
('mcq', 4, 2, 'يتأين H₃PO₄ على ثلاث خطوات، والقاعدة المرافقة تنتج بفقد أول بروتون: H₃PO₄ → H₂PO₄⁻.', '["PO₄³⁻ ينتج بعد فقد ثلاثة بروتونات، أما القاعدة المرافقة فتنتج بفقد بروتون واحد.","HPO₄²⁻ ينتج بعد فقد بروتونين لا بروتون واحد.","","H₄PO₄⁺ ينتج باكتساب H⁺ فهو حمض لا قاعدة مرافقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-17T11:36:22.457Z"}'::jsonb),
('mcq', 5, 1, 'منح HBr أيون H⁺ لجزيء الماء فتحول إلى Br⁻، وهو القاعدة المرافقة للحمض HBr.', '["H₂O هي القاعدة (المتفاعلة) التي استقبلت H⁺، وليست القاعدة المرافقة.","","H₃O⁺ هو الحمض المرافق للماء.","HBr هو الحمض نفسه لا قاعدته المرافقة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.457Z"}'::jsonb),
('mcq', 6, 3, 'H₂SO₄ يمنح H⁺ فتنتج HSO₄⁻، والزوج الصحيح (حمض، قاعدة مرافقة) هو (H₂SO₄ ، HSO₄⁻).', '["الترتيب معكوس؛ H₂SO₄ هو الحمض وHSO₄⁻ قاعدته المرافقة.","فقد HCl لأيون H⁺ ينتج Cl⁻ لا H₂.","CH₃COOH₂⁺ ينتج باكتساب H⁺، والقاعدة المرافقة هي CH₃COO⁻.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.457Z"}'::jsonb),
('mcq', 7, 3, 'القاعدة المرافقة تنتج بفقد H⁺ واحد؛ HF يفقد H⁺ فينتج F⁻ فالصف (HF ← F⁻) هو الصحيح، أما بقية الصفوف ففيها خطأ في الشحنة أو الصيغة أو الاتجاه.', '["فقد H⁺ من HCN ينتج CN⁻ لا CN²⁻.","القاعدة المرافقة لـ CH₃COOH هي CH₃COO⁻ (أيون الإيثانوات).","H₂CO₃ هو الحمض المرافق لـ HCO₃⁻ لا قاعدته المرافقة.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.457Z"}'::jsonb),
('essay', 1, null::int, null, null, 'القاعدة المرافقة: المركب الكيميائي الذي ينتج عندما يمنح الحمض أيون الهيدروجين. القواعد المرافقة: HCl ← Cl⁻ ، H₂SO₄ ← HSO₄⁻ ، CH₃COOH ← CH₃COO⁻ ، H₂CO₃ ← HCO₃⁻.', '["تعريف القاعدة المرافقة","Cl⁻","HSO₄⁻","CH₃COO⁻","HCO₃⁻"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"Cl⁻ و HSO₄⁻","marks":1},{"element":"CH₃COO⁻ و HCO₃⁻","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريف صحيح وأربع قواعد صحيحة"},{"level":"2 درجتان","description":"تعريف صحيح مع قاعدتين صحيحتين على الأقل"},{"level":"1 درجة","description":"تعريف أو قاعدتان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة SO₄²⁻ قاعدةً مرافقة لـ H₂SO₄ (يُفقد بروتون واحد فقط)","إضافة H⁺ بدل نزعه"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.457Z"}'::jsonb),
('essay', 2, null::int, null, null, 'H₃PO₄ + H₂O ⇌ H₃O⁺ + H₂PO₄⁻ : الحمض H₃PO₄ وقاعدته المرافقة H₂PO₄⁻. H₂PO₄⁻ + H₂O ⇌ H₃O⁺ + HPO₄²⁻ : الحمض H₂PO₄⁻ وقاعدته المرافقة HPO₄²⁻. HPO₄²⁻ + H₂O ⇌ H₃O⁺ + PO₄³⁻ : الحمض HPO₄²⁻ وقاعدته المرافقة PO₄³⁻.', '["معادلة الخطوة الأولى","معادلة الخطوة الثانية","معادلة الخطوة الثالثة","القاعدة المرافقة في كل خطوة"]'::jsonb, '[]'::jsonb, '[{"element":"الخطوة الأولى (معادلة وقاعدة مرافقة)","marks":1},{"element":"الخطوة الثانية","marks":1},{"element":"الخطوة الثالثة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"الخطوات الثلاث صحيحة بقواعدها المرافقة"},{"level":"2 درجتان","description":"خطوتان صحيحتان"},{"level":"1 درجة","description":"خطوة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نزع أكثر من بروتون في خطوة واحدة","الخلط بين القاعدة المرافقة والحمض المرافق"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.457Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) الحمض HNO₂ لأنه يمنح H⁺، والقاعدة H₂O لأنها تستقبله. (ب) القاعدة المرافقة لـ HNO₂ هي NO₂⁻، والحمض المرافق لـ H₂O هو H₃O⁺. (ج) الزوج المترافق مادتان تختلفان بأيون هيدروجين واحد (منح أو استقبال)؛ فـ HNO₂ وNO₂⁻ يختلفان بـ H⁺ واحد، وكذلك H₃O⁺ وH₂O. أما HNO₂ وH₃O⁺ فيختلفان بأكثر من ذلك في التركيب ولا يرتبطان بمنح أو استقبال H⁺ واحد بينهما، فهما حمضان لا زوج مترافق.', '["HNO₂ حمض وH₂O قاعدة","NO₂⁻ قاعدة مرافقة","H₃O⁺ حمض مرافق","الزوج المترافق يختلف بـ H⁺ واحد","HNO₂ وH₃O⁺ ليسا زوجًا"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الحمض والقاعدة","marks":1},{"element":"القاعدة المرافقة والحمض المرافق","marks":2},{"element":"تعليل الأزواج المترافقة","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"إجابة كاملة وتعليل سليم"},{"level":"3–4 درجات","description":"تحديد صحيح مع تعليل ناقص"},{"level":"1–2 درجة","description":"تحديد الحمض والقاعدة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ HNO₂ وH₃O⁺ زوجًا مترافقًا","عكس الحمض المرافق والقاعدة المرافقة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.458Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
