('essay', 1, 'عرّف الحمض المرافق، ثم اكتب الحمض المرافق لكل من القواعد الآتية: H₂O ، NH₃ ، CO₃²⁻ ، Cl⁻.', null, null, 'تذكر', 'تعريف وتطبيق', 'سهل', 'الكتاب ص 60–61 — الحمض المرافق'),
('essay', 2, 'اكتب معادلة ذوبان الأمونيا في الماء، وحدّد فيها الأزواج المترافقة من الحمض والقاعدة، ووضّح كيف يستدل على الحمض المرافق للأمونيا.', null, null, 'تطبيق', 'كتابة معادلة وتحديد أزواج', 'متوسط', 'الكتاب ص 61 — الأمونيا قاعدة برونستد – لوري'),
('essay', 3, 'لدى المعادلة: SO₄²⁻ + H₃O⁺ ⇌ HSO₄⁻ + H₂O . (أ) حدّد الحمض والقاعدة في التفاعل الأمامي. (ب) اكتب الحمض المرافق للقاعدة SO₄²⁻. (ج) فسّر لماذا يمكن اعتبار HSO₄⁻ في التفاعل العكسي حمضًا، وفي الوقت نفسه هو القاعدة المرافقة لـ H₂SO₄.', null, null, 'تحليل', 'تحليل معادلة', 'صعب', 'الكتاب ص 63 و65 — الأزواج المترافقة')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
