('mcq', 2, 0, 'تستقبل NH₃ أيون H⁺ فتكوّن أيون الأمونيوم NH₄⁺، وهو الحمض المرافق لها.', '["","NH₂⁻ ينتج بفقد H⁺ من NH₃، فهو قاعدة مرافقة لا حمض.","المادة لا تكون حمضها المرافق؛ يلزم أن تستقبل H⁺.","OH⁻ هو القاعدة المرافقة للماء في تفاعل الأمونيا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-17T11:36:22.459Z"}'::jsonb),
