('mcq', 4, 1, 'تستقبل F⁻ أيون H⁺ فتتحول إلى HF، وهو الحمض المرافق لها.', '["F₂ جزيء عنصر ولا يمثّل اكتساب H⁺.","","H₂F⁺ يحتاج إلى بروتونين زائدين على F⁻.","HF₂⁻ لا ينتج باكتساب أيون هيدروجين واحد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-17T11:36:22.459Z"}'::jsonb),
('mcq', 5, 3, 'CH₃NH₂ يستقبل H⁺ من الماء فيكوّن CH₃NH₃⁺، وهو الحمض المرافق له.', '["OH⁻ هو القاعدة المرافقة للماء لا الحمض المرافق لـ CH₃NH₂.","H₂O هو الحمض (المتفاعل) وليس الحمض المرافق.","CH₃NH⁻ ينتج بفقد H⁺ فهو قاعدة لا حمض.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-17T11:36:22.459Z"}'::jsonb),
('mcq', 6, 0, 'تستقبل HPO₄²⁻ أيون H⁺ فتتحول إلى H₂PO₄⁻ وهو حمضها المرافق.', '["","الترتيب معكوس؛ HPO₄²⁻ قاعدة وحمضها المرافق H₂PO₄⁻.","اكتساب بروتون واحد ينتج HPO₄²⁻ لا H₃PO₄.","اكتساب H⁺ يعطي HCl لا Cl₂."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.459Z"}'::jsonb),
('mcq', 7, 1, 'يستقبل HCO₃⁻ أيون H⁺ من الماء فيصبح H₂CO₃ (حمضه المرافق)، ويفقد الماء H⁺ فيتحول إلى OH⁻ (قاعدته المرافقة).', '["HCO₃⁻ استقبل H⁺ فهو قاعدة، وH₂CO₃ حمضه المرافق.","","الماء منح H⁺ فهو حمض وقاعدته المرافقة OH⁻.","OH⁻ قاعدة مرافقة للماء، لا حمض مرافق لـ HCO₃⁻."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (13%)"}],"at":"2026-10-17T11:36:22.460Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الحمض المرافق: المركب الكيميائي الذي ينتج عندما تستقبل القاعدة أيون الهيدروجين. الأحماض المرافقة: H₂O ← H₃O⁺ ، NH₃ ← NH₄⁺ ، CO₃²⁻ ← HCO₃⁻ ، Cl⁻ ← HCl.', '["التعريف","H₃O⁺","NH₄⁺","HCO₃⁻","HCl"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"H₃O⁺ و NH₄⁺","marks":1},{"element":"HCO₃⁻ و HCl","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريف صحيح وأربعة أحماض صحيحة"},{"level":"2 درجتان","description":"تعريف مع حمضين صحيحين على الأقل"},{"level":"1 درجة","description":"تعريف فقط أو حمضان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["نزع H⁺ بدل إضافته","كتابة H₂CO₃ حمضًا مرافقًا لـ CO₃²⁻"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.460Z"}'::jsonb),
('essay', 2, null::int, null, null, 'NH₃ + H₂O ⇌ NH₄⁺ + OH⁻. الزوج الأول: NH₃ (قاعدة) / NH₄⁺ (حمض مرافق). الزوج الثاني: H₂O (حمض) / OH⁻ (قاعدة مرافقة). يُستدل على الحمض المرافق بأنه الناتج عندما تستقبل القاعدة (NH₃) أيون H⁺ من الماء، فيتكوّن NH₄⁺ الذي يستطيع منح H⁺ في التفاعل العكسي.', '["المعادلة صحيحة","NH₃/NH₄⁺","H₂O/OH⁻","تعليل الحمض المرافق"]'::jsonb, '[]'::jsonb, '[{"element":"المعادلة","marks":1},{"element":"الزوجان المترافقان","marks":2},{"element":"تعليل الاستدلال","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة"},{"level":"2–3 درجات","description":"معادلة وأحد الزوجين"},{"level":"1 درجة","description":"معادلة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ NH₄⁺ قاعدة مرافقة","الخلط بين الزوجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.460Z"}'::jsonb),
('essay', 3, null::int, null, null, '(أ) في التفاعل الأمامي: القاعدة SO₄²⁻ لأنها تستقبل H⁺، والحمض H₃O⁺ لأنه يمنحه. (ب) الحمض المرافق لـ SO₄²⁻ هو HSO₄⁻. (ج) HSO₄⁻ في التفاعل العكسي يمنح H⁺ إلى H₂O فهو حمض؛ وهو أيضًا ناتج فقد H₂SO₄ لأيون H⁺ فهو قاعدته المرافقة. أي أن المادة نفسها قد تكون حمضًا مرافقًا لقاعدة وقاعدة مرافقة لحمض آخر، فهي تقع في زوجين مترافقين مختلفين: (SO₄²⁻/HSO₄⁻) و(HSO₄⁻/H₂SO₄).', '["SO₄²⁻ قاعدة وH₃O⁺ حمض","HSO₄⁻ حمض مرافق","HSO₄⁻ يمنح H⁺ في العكسي","HSO₄⁻ قاعدة مرافقة لـ H₂SO₄","زوجان مترافقان مختلفان"]'::jsonb, '[]'::jsonb, '[{"element":"تحديد الحمض والقاعدة","marks":1},{"element":"الحمض المرافق","marks":1},{"element":"تفسير الدور المزدوج لـ HSO₄⁻","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"إجابة كاملة وتفسير صحيح"},{"level":"2–3 درجات","description":"تحديد صحيح مع تفسير ناقص"},{"level":"1 درجة","description":"تحديد الحمض والقاعدة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن المادة لا تكون إلا حمضًا أو قاعدة","عدّ SO₄²⁻ حمضًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.460Z"}'::jsonb)
