('essay', 3, 'لماذا تُعدّ نظرية لويس أشمل من نظريتي أرهينيوس وبرونستد – لوري؟ ناقش ذلك مستعينًا بتفاعل BF₃ مع NH₃ لتكوين BF₃NH₃ الذي لا يمكن تفسيره بالنظريتين الأخريين.', null, null, 'تحليل', 'مقارنة وتحليل', 'صعب', 'الكتاب ص 64 — تفاعل BF₃ مع NH₃')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
