('mcq', 3, 2, 'حمض لويس أيون أو جزيء فيه مدار ذري فارغ يستطيع أن يستقبل (يشارك) زوجًا من الإلكترونات.', '["هذه خاصية قاعدة لويس.","هذه خاصية حمض أرهينيوس لا لويس.","","هذه خاصية قاعدة أرهينيوس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-17T11:36:22.461Z"}'::jsonb),
('mcq', 4, 1, 'قاعدة لويس أيون أو جزيء له زوج إلكترونات حر يستطيع منحه أو المشاركة فيه.', '["هذه خاصية حمض لويس.","","هذه صفة حمض برونستد – لوري.","H⁺ لا يملك إلكترونات ليمنحها، فهو حمض لويس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (38%)"}],"at":"2026-10-17T11:36:22.461Z"}'::jsonb),
('mcq', 5, 1, 'يستقبل مدار 1s الفارغ في H⁺ زوجًا من الإلكترونات من F⁻، فـ H⁺ حمض لويس وF⁻ قاعدة لويس.', '["H⁺ يستقبل زوجًا من F⁻ فهو حمض، وF⁻ تمنحه فهي قاعدة.","","F⁻ يمنح زوج إلكترونات فهو قاعدة لويس.","H⁺ لا يملك إلكترونات ويستقبل زوجًا فهو حمض لويس."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (30%)"}],"at":"2026-10-17T11:36:22.461Z"}'::jsonb),
('mcq', 6, 0, 'تضم نظرية لويس جميع أحماض وقواعد برونستد – لوري، كما تضم مواد أخرى كثيرة لا تنطبق عليها تلك النظرية مثل BF₃.', '["","العكس صحيح؛ لويس أشمل.","تتفق النظريتان في أمثلة كثيرة كتفاعل H⁺ مع F⁻.","نظرية لويس لا تقتصر على المحاليل المائية."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.461Z"}'::jsonb),
('mcq', 7, 3, 'اقترح لويس نظرية زوج الإلكترونات للترابط الكيميائي وطبّقها على الأحماض والقواعد، فهي تركّز على استقبال زوج إلكترونات أو منحه.', '["هذا أساس نظرية برونستد – لوري.","هذا أساس نظرية أرهينيوس للقواعد.","درجة التأين تحدد قوة الحمض أو القاعدة لا تعريفها وفق لويس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (44%)"}],"at":"2026-10-17T11:36:22.461Z"}'::jsonb),
('essay', 1, null::int, null, null, 'حمض لويس: مادة مستقبلة لزوج من الإلكترونات؛ وشرطه أن يكون أيونًا أو جزيئًا فيه مدار ذري فارغ يستطيع استقبال زوج إلكترونات. قاعدة لويس: مادة مانحة لزوج من الإلكترونات؛ وشرطها أن يكون لها زوج إلكترونات حر (غير مرتبط) تستطيع منحه أو المشاركة به.', '["تعريف حمض لويس","مدار فارغ","تعريف قاعدة لويس","زوج إلكترونات حر"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف حمض لويس","marks":1},{"element":"شرطه: مدار فارغ","marks":1},{"element":"تعريف قاعدة لويس","marks":1},{"element":"شرطها: زوج حر","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"التعريفان والشرطان صحيحة"},{"level":"2–3 درجات","description":"التعريفان دون الشرطين"},{"level":"1 درجة","description":"تعريف واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الحمض والقاعدة","الخلط بين تعريفي لويس وبرونستد – لوري"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (27%)"}],"at":"2026-10-17T11:36:22.461Z"}'::jsonb),
('essay', 2, null::int, null, null, 'يمتلك أيون H⁺ مدار 1s فارغًا فيستقبل زوجًا من الإلكترونات غير المشترك من أيون الفلوريد F⁻ ليكوّن الرابطة H–F، فـ H⁺ حمض لويس وF⁻ قاعدة لويس. ويتفق ذلك مع برونستد – لوري لأن H⁺ يمكن اعتباره مانحًا لأيون الهيدروجين (حمضًا)، وF⁻ مستقبلًا له (قاعدة) في التفاعل.', '["H⁺ له مدار 1s فارغ","F⁻ يمنح زوجًا حرًا","تكوين الرابطة H–F","تطابق مع برونستد – لوري"]'::jsonb, '[]'::jsonb, '[{"element":"خصائص H⁺ كحمض لويس","marks":1},{"element":"خصائص F⁻ كقاعدة لويس","marks":1},{"element":"تكوين الرابطة","marks":1},{"element":"التوافق مع برونستد – لوري","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"شرح كامل"},{"level":"2–3 درجات","description":"شرح الجانب الإلكتروني دون الربط بـ برونستد – لوري"},{"level":"1 درجة","description":"تصنيف المادتين فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ F⁻ حمضًا","إغفال دور المدار الفارغ"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.462Z"}'::jsonb),
('essay', 3, null::int, null, null, 'تعرّف نظرية لويس الحمض والقاعدة بأنهما مستقبل ومانح لزوج إلكترونات دون اشتراط وجود H⁺ أو OH⁻. في تفاعل BF₃ مع NH₃: ذرة البورون في BF₃ لها ستة إلكترونات تكافؤ ومدار فارغ، فتستقبل زوج الإلكترونات الحر على النيتروجين في NH₃ مكوّنة رابطة BF₃NH₃؛ فـ BF₃ حمض لويس وNH₃ قاعدة لويس. هذا التفاعل لا ينتقل فيه أيون H⁺ ولا يُنتج OH⁻، فلا تفسّره أرهينيوس ولا برونستد – لوري؛ لذا تشمل نظرية لويس جميع المواد المصنفة وفق النظريتين وغيرها.', '["تعريف لويس لا يشترط H⁺ أو OH⁻","BF₃ مدار فارغ وحمض لويس","NH₃ زوج حر وقاعدة لويس","التفاعل لا يتضمن انتقال H⁺","لويس أشمل"]'::jsonb, '[]'::jsonb, '[{"element":"تعريف لويس","marks":1},{"element":"دور BF₃","marks":1},{"element":"دور NH₃","marks":1},{"element":"بيان عدم انطباق النظريتين الأخريين","marks":1},{"element":"الاستنتاج بالشمول","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"مناقشة كاملة بالأدلة"},{"level":"3–4 درجات","description":"تحديد الحمض والقاعدة دون ربط بالشمول"},{"level":"1–2 درجة","description":"تعريف لويس فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["القول إن NH₃ تمنح H⁺ في هذا التفاعل","عدّ BF₃ قاعدة لأنه يحتوي على فلور"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.462Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
