('mcq', 5, 'أيّ الجسيمات الآتية يُعدّ قاعدة لويس؟', null, '["H⁺","NH₃","BF₃","SO₃"]'::jsonb, 'تطبيق', 'تصنيف', 'سهل', 'الكتاب ص 64–65 — حمض لويس وقاعدة لويس'),
('mcq', 6, 'يبيّن الجدول وصف ذرتين مركزيتين: في الجسيم A ذرة مركزية ينقصها إلكترونان لإكمال الثمانية ولها مدار فارغ، وفي الجسيم B ذرة مركزية لها زوج إلكترونات حر. كيف يُصنَّف A وB؟', '{"headers":["الجسيم","الوصف الإلكتروني للذرة المركزية"],"rows":[["A","ينقصها إلكترونان لإكمال الثمانية، ولها مدار فارغ"],["B","لها زوج إلكترونات حر"]]}'::jsonb, '["A قاعدة لويس وB حمض لويس","A وB كلاهما حمض لويس","A وB كلاهما قاعدة لويس","A حمض لويس وB قاعدة لويس"]'::jsonb, 'تحليل', 'تحليل بيانات', 'صعب', 'الكتاب ص 64–65 — حمض لويس وقاعدة لويس'),
('mcq', 7, 'يحتوي جزيء PCl₃ على ذرة فوسفور مركزية مرتبطة بثلاث ذرات كلور، وعلى زوج إلكترونات حر واحد على الفوسفور، ولا يوجد مدار فارغ في غلاف التكافؤ. كيف يُصنَّف PCl₃ وفق نظرية لويس؟', null, '["قاعدة لويس؛ لأن له زوج إلكترونات حرًا يستطيع منحه","حمض لويس؛ لأنه يحتوي على ذرة كلور عالية الكهروسالبية","حمض لويس؛ لأن الفوسفور ينتمي إلى اللافلزات","ليس حمضًا ولا قاعدة؛ لأنه لا يحتوي على هيدروجين أو هيدروكسيد"]'::jsonb, 'تطبيق', 'تصنيف', 'صعب', 'الكتاب ص 65 — التقويم 2-1 سؤال 10'),
('essay', 1, 'صنّف كل متفاعل في التفاعل الآتي إلى حمض لويس أو قاعدة لويس، مع التعليل: SO₃(g) + MgO(s) → MgSO₄(s)', null, null, 'تطبيق', 'تصنيف', 'سهل', 'الكتاب ص 64–65 — حمض لويس وقاعدة لويس'),
