('mcq', 4, 3, 'BF₃ فيه ذرة بورون لها ستة إلكترونات تكافؤ ومدار فارغ، فهو يستقبل زوجًا من الإلكترونات؛ أي حمض لويس.', '["F⁻ له أزواج حرة يمنحها فهو قاعدة لويس.","NH₃ لها زوج حر على النيتروجين فهي قاعدة لويس.","O²⁻ يمنح أزواج إلكترونات فهو قاعدة لويس.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (67%)"}],"at":"2026-10-17T11:36:22.463Z"}'::jsonb),
