('mcq', 6, 3, 'الجسيم الذي له مدار فارغ يستقبل زوج إلكترونات فهو حمض لويس (A)، والذي له زوج حر يمنحه فهو قاعدة لويس (B).', '["المدار الفارغ يعني استقبال الزوج (حمض) والزوج الحر يعني المنح (قاعدة).","B يمنح الزوج الحر فهو قاعدة.","A يستقبل الزوج في مداره الفارغ فهو حمض.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.464Z"}'::jsonb),
