('essay', 1, null::int, null, null, 'SO₃ حمض لويس؛ لأنه يستقبل زوجًا من الإلكترونات من أيون الأكسيد. أيون O²⁻ (من MgO) قاعدة لويس؛ لأنه يمنح زوجًا من الإلكترونات إلى SO₃ مكوّنًا أيون الكبريتات SO₄²⁻ (في MgSO₄).', '["SO₃ حمض لويس","تعليل الاستقبال","O²⁻ قاعدة لويس","تعليل المنح"]'::jsonb, '[]'::jsonb, '[{"element":"SO₃ حمض مع التعليل","marks":2},{"element":"O²⁻ قاعدة مع التعليل","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف وتعليل صحيحان للمادتين"},{"level":"2–3 درجات","description":"تصنيف صحيح مع تعليل ناقص"},{"level":"1 درجة","description":"تصنيف مادة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ MgO حمضًا لأنه أكسيد","عدّ Mg²⁺ القاعدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (40%)"}],"at":"2026-10-17T11:36:22.464Z"}'::jsonb),
('essay', 2, null::int, null, null, '(أ) H⁺ حمض لويس لأن له مدار 1s فارغًا يستقبل زوجًا من الإلكترونات، وF⁻ قاعدة لويس لأن له زوج إلكترونات حرًا يمنحه. (ب) BF₃ حمض لويس لأن للبورون ستة إلكترونات تكافؤ ومدارًا فارغًا، وNH₃ قاعدة لويس لأن للنيتروجين زوج إلكترونات حرًا.', '["(أ) H⁺ حمض مع السبب","(أ) F⁻ قاعدة مع السبب","(ب) BF₃ حمض مع السبب","(ب) NH₃ قاعدة مع السبب"]'::jsonb, '[]'::jsonb, '[{"element":"H⁺ وسببه","marks":1},{"element":"F⁻ وسببه","marks":1},{"element":"BF₃ وسببه","marks":1},{"element":"NH₃ وسببه","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف صحيح معلل"},{"level":"2–3 درجات","description":"تصنيف صحيح مع نقص التعليل"},{"level":"1 درجة","description":"تصنيف صحيح لمتفاعل واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس الحمض والقاعدة","عدّ H⁺ قاعدة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.465Z"}'::jsonb),
('essay', 3, null::int, null, null, 'الزوج الأول: AlCl₃ + Cl⁻ → AlCl₄⁻ ؛ AlCl₃ حمض لويس لأن ذرة الألمنيوم ينقصها زوج إلكترونات ولها مدار فارغ يستقبل زوجًا، وCl⁻ قاعدة لويس لأن له أزواجًا حرة يمنحها. الزوج الثاني: AlCl₃ + H₂O → Cl₃Al–OH₂ ؛ AlCl₃ حمض لويس، وH₂O قاعدة لويس لأن للأكسجين فيه زوجين حرين يمنح أحدهما. أي أن الحمض هو الجسيم ذو المدار الفارغ، والقاعدة هي الجسيم ذو الزوج الحر.', '["اختيار زوجين صحيحين","AlCl₃ حمض لويس","Cl⁻ أو H₂O قاعدة لويس","التعليل بالمدار الفارغ والزوج الحر"]'::jsonb, '[]'::jsonb, '[{"element":"زوج أول صحيح","marks":1.5},{"element":"زوج ثانٍ صحيح","marks":1.5},{"element":"التعليل بالمدار الفارغ والزوج الحر","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"زوجان صحيحان وتعليل كامل"},{"level":"3–4 درجات","description":"زوج صحيح كامل وزوج ناقص"},{"level":"1–2 درجة","description":"تصنيف صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ AlCl₃ قاعدة لوجود الكلور","اختيار مادتين من القواعد فقط"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.465Z"}'::jsonb)
