from (values
('mcq', 1, 1, 'الماء والمواد الأخرى التي تستطيع أن تسلك سلوك الأحماض والقواعد تسمى مواد مترددة (أمفوتيرية) Amphoteric؛ فهي تسلك سلوك الحمض أو القاعدة بحسب المادة التي تتفاعل معها.', '["هذا وصف لمادة متعادلة لا تتفاعل حمضيًا ولا قاعديًا، والمادة المترددة على العكس تسلك السلوكين كليهما.","","هذا تعريف الحمض المتعدد البروتونات، ولا علاقة له بقدرة المادة على أن تكون حمضًا وقاعدة.","استقبال زوج الإلكترونات تعريف حمض لويس وحده، والمادة المترددة تسلك سلوك القاعدة أيضًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.466Z"}'::jsonb),
('mcq', 2, 3, 'مع HF يستقبل الماء أيون H⁺ فيكوّن H₃O⁺ فيسلك سلوك القاعدة، ومع NH₃ يمنح الماء أيون H⁺ للأمونيا فيتكوّن NH₄⁺ وOH⁻ فيسلك سلوك الحمض؛ إذن الماء قاعدة مع HF وحمض مع NH₃.', '["عكس الصحيح: HF هو الذي يمنح البروتون للماء، والأمونيا هي التي تستقبله من الماء.","الماء لا يمنح بروتونًا لـ HF، بل يستقبله منه، فهو قاعدة في هذا التفاعل.","الماء لا يستقبل بروتونًا من NH₃، بل يمنحه لها، فهو حمض في هذا التفاعل.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.466Z"}'::jsonb),
('mcq', 3, 0, 'أيون الكربونات الهيدروجينية HCO₃⁻ يستطيع أن يمنح أيون H⁺ فيتحول إلى CO₃²⁻ (يسلك سلوك الحمض)، ويستطيع أن يستقبل أيون H⁺ فيتحول إلى H₂CO₃ (يسلك سلوك القاعدة)، فهو مادة مترددة.', '["","أيون الكربونات لا يحتوي على هيدروجين يمنحه، فهو يسلك سلوك القاعدة فقط (مستقبل لـ H⁺).","أيون الكلوريد لا يحتوي على هيدروجين يمنحه، فلا يسلك سلوك الحمض، وهو القاعدة المرافقة لـ HCl.","أيون الفلوريد لا يملك هيدروجينًا يمنحه، فيسلك سلوك القاعدة فقط وهو القاعدة المرافقة لـ HF."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.466Z"}'::jsonb),
('mcq', 4, 2, 'تحوّل HCO₃⁻ إلى CO₃²⁻ يعني أنه فقد أيون H⁺ ومنحه للماء الذي تحوّل إلى H₃O⁺، فهو حمض برونستد – لوري في هذا التفاعل، وقاعدته المرافقة CO₃²⁻.', '["لو استقبل HCO₃⁻ أيون H⁺ لتحول إلى H₂CO₃ لا إلى CO₃²⁻؛ وهذا سلوكه القاعدي في تفاعل آخر.","الشحنة السالبة لا تحدد السلوك؛ المعيار في نظرية برونستد – لوري هو منح أيون H⁺ أو استقباله.","","الأيونات قد تكون أحماضًا أو قواعد وفق برونستد – لوري، وHCO₃⁻ هنا منح أيون H⁺ فعلًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-17T11:36:22.466Z"}'::jsonb),
('mcq', 5, 3, 'فقد جزيء الماء أيون H⁺ فتحوّل إلى OH⁻، واستقبل أيون CO₃²⁻ هذا الأيون فتحوّل إلى HCO₃⁻؛ فالماء مانح لأيون H⁺ أي حمض برونستد – لوري، وOH⁻ قاعدته المرافقة.', '["لا يظهر H₃O⁺ في نواتج هذا التفاعل، ولو استقبل الماء أيون H⁺ لكان قاعدة لا حمضًا.","الماء هنا يمنح أيون H⁺ ولا يستقبل زوج إلكترونات؛ بل أيون CO₃²⁻ هو الذي يعطي زوج الإلكترونات لأيون H⁺.","أيون CO₃²⁻ لم يتحول إلى OH⁻، بل استقبل أيون H⁺ فتحول إلى HCO₃⁻، وOH⁻ ناتج من الماء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (43%)"}],"at":"2026-10-17T11:36:22.466Z"}'::jsonb),
('mcq', 6, 0, 'الماء يسلك سلوك الحمض أو القاعدة بحسب طبيعة المواد المذابة في المحلول؛ فيكون قاعدة مع HF وحمضًا مع NH₃.', '["","سلوك الماء لا يرتبط بدرجة الحرارة، بل بطبيعة المادة المذابة التي يتفاعل معها.","زيادة كمية الماء أو نقصها لا تغير دوره؛ فدوره يتحدد بالمادة التي يمنحها البروتون أو يستقبله منها.","الماء النقي والمحاليل كلاهما يسلك فيه الماء سلوكًا يتحدد بالمادة المذابة، لا بدرجة نقائه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.466Z"}'::jsonb),
('mcq', 7, 2, 'يكوّن H₂PO₄⁻ قاعدةً مرافقة لحمض H₃PO₄، ويكون أيضًا حمضًا قاعدته المرافقة HPO₄²⁻؛ فهو يستقبل أيون H⁺ ويمنحه، أي أنه مادة مترددة.', '["يظهر PO₄³⁻ قاعدةً مرافقة فقط، ولا يحتوي على هيدروجين يمنحه فلا يكون حمضًا.","يظهر H₃PO₄ حمضًا فقط في الجدول، ولا يرد قاعدةً مرافقة لأي حمض.","","يظهر NO₃⁻ قاعدةً مرافقة لحمض النيتريك فقط، ولا يحتوي على هيدروجين يمنحه."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.467Z"}'::jsonb),
('essay', 1, null::int, null, null, 'المواد المترددة (الأمفوتيرية): الماء والمواد الأخرى التي تستطيع أن تسلك سلوك الأحماض والقواعد. الماء قاعدة عند ذوبان HF فيه: HF(aq) + H₂O(l) ⇌ H₃O⁺(aq) + F⁻(aq)، إذ يستقبل الماء أيون H⁺ ويتحول إلى H₃O⁺. الماء حمض عند ذوبان NH₃ فيه: NH₃(aq) + H₂O(l) ⇌ NH₄⁺(aq) + OH⁻(aq)، إذ يمنح الماء أيون H⁺ للأمونيا ويتحول إلى OH⁻.', '["التعريف: مادة تسلك سلوك الحمض وسلوك القاعدة","معادلة HF مع الماء وبيان أن الماء قاعدة (يستقبل H⁺)","معادلة NH₃ مع الماء وبيان أن الماء حمض (يمنح H⁺)"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف الصحيح","marks":1},{"element":"معادلة HF والماء مع تحديد دور الماء","marks":2},{"element":"معادلة NH₃ والماء مع تحديد دور الماء","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تعريف صحيح ومعادلتان صحيحتان مع تحديد دور الماء في كل منهما"},{"level":"3 درجات","description":"تعريف صحيح ومعادلة واحدة صحيحة مع دور الماء، أو معادلتان دون تعليل الدور"},{"level":"1 درجة","description":"تعريف صحيح فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس دور الماء في التفاعلين","كتابة H₂O + HF → H₂F⁺ أو نواتج غير صحيحة","تعريف المادة المترددة بأنها المادة المتعادلة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.467Z"}'::jsonb),
('essay', 2, null::int, null, null, '1) سلوك الحمض: HCO₃⁻(aq) + H₂O(l) ⇌ H₃O⁺(aq) + CO₃²⁻(aq)؛ يمنح HCO₃⁻ أيون H⁺. الأزواج: HCO₃⁻ (حمض)/CO₃²⁻ (قاعدته المرافقة)، وH₂O (قاعدة)/H₃O⁺ (حمضها المرافق). 2) سلوك القاعدة: HCO₃⁻(aq) + H₂O(l) ⇌ H₂CO₃(aq) + OH⁻(aq)؛ يستقبل HCO₃⁻ أيون H⁺. الأزواج: HCO₃⁻ (قاعدة)/H₂CO₃ (حمضها المرافق)، وH₂O (حمض)/OH⁻ (قاعدته المرافقة). ولأنه يستطيع منح H⁺ واستقباله فهو مادة مترددة.', '["معادلة سلوك الحمض","أزواج المعادلة الأولى","معادلة سلوك القاعدة","أزواج المعادلة الثانية","الاستنتاج: HCO₃⁻ مادة مترددة"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة HCO₃⁻ حمضًا","marks":1},{"element":"الأزواج المترافقة في المعادلة الأولى","marks":1},{"element":"معادلة HCO₃⁻ قاعدةً","marks":1},{"element":"الأزواج المترافقة في المعادلة الثانية","marks":1},{"element":"الاستنتاج","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"المعادلتان صحيحتان والأزواج الأربعة صحيحة مع الاستنتاج"},{"level":"3 درجات","description":"المعادلتان صحيحتان مع خطأ في تحديد الأزواج أو غياب الاستنتاج"},{"level":"1 درجة","description":"معادلة واحدة صحيحة فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة H₂CO₃ ناتجًا لسلوك الحمض","عدّ الماء حمضًا في المعادلتين","ربط HCO₃⁻ بـ OH⁻ زوجًا مترافقًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.467Z"}'::jsonb),
('essay', 3, null::int, null, null, 'نعم، H₂PO₄⁻ مادة مترددة؛ لأنه يمنح أيون H⁺ فيتحول إلى HPO₄²⁻ (سلوك الحمض)، ويستقبل أيون H⁺ فيتحول إلى H₃PO₄ (سلوك القاعدة)، والمادة التي تسلك السلوكين مادة مترددة. أما PO₄³⁻ فلا يحتوي على ذرة هيدروجين يمنحها، فلا يستطيع أن يسلك سلوك حمض برونستد – لوري، ويرد في الجدول قاعدةً مرافقة فقط؛ لذا فهو قاعدة وليس مادة مترددة.', '["H₂PO₄⁻ يمنح H⁺ ← HPO₄²⁻","H₂PO₄⁻ يستقبل H⁺ ← H₃PO₄","الحكم: H₂PO₄⁻ مترددة","PO₄³⁻ لا يحتوي H يمنحه فهو قاعدة فقط"]'::jsonb, '[]'::jsonb, '[{"element":"بيان سلوك H₂PO₄⁻ حمضًا","marks":1},{"element":"بيان سلوك H₂PO₄⁻ قاعدةً","marks":1},{"element":"الحكم بأنه مادة مترددة","marks":1},{"element":"تعليل عدم تردد PO₄³⁻","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تحليل كامل للأيونين مع التعليل"},{"level":"3 درجات","description":"تحليل صحيح لـ H₂PO₄⁻ مع تعليل ناقص لـ PO₄³⁻"},{"level":"2 درجتان","description":"حكم صحيح على H₂PO₄⁻ مع تعليل جزئي"},{"level":"1 درجة","description":"حكم صحيح دون تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ PO₄³⁻ مترددًا لوروده في الجدول","الخلط بين المادة المترددة والحمض المتعدد البروتونات","ذكر H₃PO₄ ناتجًا لسلوك الحمض"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.467Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
