('mcq', 3, 'لماذا تُكتب صيغة حمض الإيثانويك غالبًا في صورة CH₃COOH؟', null, '["لبيان أن الجزيء يحتوي على ذرتي أكسجين","لأن ذرات الهيدروجين الأربع كلها قابلة للتأين","لتمييزه من الأحماض القوية التامة التأين","لتأكيد أن ذرة هيدروجين واحدة فقط من الأربع قابلة للتأين"]'::jsonb, 'تذكر', 'تعليل', 'متوسط', 'الكتاب ص 62 — الأحماض الأحادية البروتون والمتعددة البروتونات'),
('mcq', 4, 'على أي أساس يُصنَّف الحمض بأنه أحادي البروتون؟', null, '["العدد الكلي لذرات الهيدروجين في صيغته","عدد ذرات الهيدروجين القابلة للتأين في جزيئه","قوة الحمض ومدى تأينه في الماء","عدد ذرات الأكسجين في جزيئه"]'::jsonb, 'فهم', 'تحديد معيار', 'متوسط', 'الكتاب ص 62 — الأحماض الأحادية البروتون والمتعددة البروتونات'),
('mcq', 5, 'أيّ معادلات التأين الآتية تمثل تأين حمض أحادي البروتون في الماء؟', null, '["H₂CO₃(aq) + H₂O(l) ⇌ H₃O⁺(aq) + HCO₃⁻(aq)","HBr(aq) + H₂O(l) → H₃O⁺(aq) + Br⁻(aq)","H₃PO₄(aq) + H₂O(l) ⇌ H₃O⁺(aq) + H₂PO₄⁻(aq)","H₂SO₄(aq) + H₂O(l) → H₃O⁺(aq) + HSO₄⁻(aq)"]'::jsonb, 'فهم', 'تمييز', 'متوسط', 'الكتاب ص 62 — الأحماض الأحادية البروتون والمتعددة البروتونات'),
('mcq', 6, 'أيّ العبارات الآتية صحيحة بشأن الحمض الأحادي البروتون؟', null, '["يحتوي جزيئه دائمًا على ذرة هيدروجين واحدة","يكون دائمًا حمضًا قويًا تام التأين","لا يحتوي جزيئه على ذرات أكسجين","قد يحتوي جزيئه على أكثر من ذرة هيدروجين"]'::jsonb, 'فهم', 'حكم على عبارات', 'صعب', 'الكتاب ص 62 — الأحماض الأحادية البروتون والمتعددة البروتونات'),
('mcq', 7, 'يحتوي جزيء البنزين C₆H₆ على ست ذرات هيدروجين، ويحتوي جزيء حمض الإيثانويك على أربع. ما الاستنتاج الصحيح؟', null, '["البنزين ليس حمضًا، وحمض الإيثانويك حمض أحادي البروتون","البنزين حمض سداسي البروتونات، وحمض الإيثانويك رباعي البروتونات","البنزين حمض أحادي البروتون، وحمض الإيثانويك ليس حمضًا","كلاهما حمض أحادي البروتون؛ لاحتوائهما على الكربون"]'::jsonb, 'تطبيق', 'تطبيق التعريف', 'صعب', 'الكتاب ص 62 — ذرات الهيدروجين القابلة للتأين (الشكل 2-9)'),
('essay', 1, 'عرّف الحمض الأحادي البروتون، واذكر مثالين عليه، ثم فسّر لماذا يُعد حمض الإيثانويك CH₃COOH أحادي البروتون رغم احتواء جزيئه على أربع ذرات هيدروجين.', null, null, 'تذكر', 'تعريف مع أمثلة وتفسير', 'سهل', 'الكتاب ص 62 — الأحماض الأحادية البروتون والمتعددة البروتونات'),
('essay', 2, 'قارن بين الحمض الأحادي البروتون والحمض الثنائي البروتونات من حيث: التعريف، وعدد ذرات الهيدروجين القابلة للتأين في الجزيء، مع مثال على كل منهما.', null, null, 'فهم', 'مقارنة', 'متوسط', 'الكتاب ص 62 — الأحماض الأحادية البروتون والمتعددة البروتونات'),
('essay', 3, 'لديك ثلاث مواد: HF، وCH₃COOH، وC₆H₆. حدّد لكل منها عدد ذرات الهيدروجين في الجزيء وعدد ذرات الهيدروجين القابلة للتأين، ثم صنّف كلًّا منها (حمض أحادي البروتون / ليس حمضًا) مع التعليل.', null, null, 'تحليل', 'تصنيف مع تعليل', 'صعب', 'الكتاب ص 62 — ذرات الهيدروجين القابلة للتأين (الشكل 2-9)')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C2-L1-O14') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'الحمض الذي يستطيع أن يمنح أيون هيدروجين واحدًا فقط لكل جزيء هو حمض أحادي البروتون، مثل HCl وHF وCH₃COOH.', '["العبرة بعدد ذرات الهيدروجين القابلة للتأين لا بالعدد الكلي؛ فحمض الإيثانويك فيه أربع ذرات هيدروجين وهو أحادي البروتون.","التأين التام صفة الحمض القوي، وقد يكون الحمض الأحادي البروتون ضعيفًا مثل HF وCH₃COOH.","","الحمض الذي يمنح أيوني هيدروجين حمض ثنائي البروتونات مثل H₂SO₄، لا أحادي البروتون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.468Z"}'::jsonb),
('mcq', 2, 0, 'من بين ذرات الهيدروجين الأربع في CH₃COOH ذرة واحدة فقط قابلة للتأين، وهي المرتبطة بذرة الأكسجين؛ لذا فهو حمض أحادي البروتون.', '["","لا توجد في الجزيء إلا رابطة O–H واحدة، فلا يتأين منه ذرتا هيدروجين.","ذرات الهيدروجين الثلاث في مجموعة CH₃ مرتبطة بالكربون ولا تتأين، وهي غير القابلة للتأين لا القابلة.","هذا هو العدد الكلي لذرات الهيدروجين في الجزيء، لكن ثلاثًا منها مرتبطة بالكربون ولا تتأين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.468Z"}'::jsonb),
('mcq', 3, 3, 'لأن حمض الإيثانويك أحادي البروتون تُكتب صيغته غالبًا في صورة CH₃COOH لتأكيد حقيقة أن ذرة هيدروجين واحدة فقط من الذرات الأربع قابلة للتأين.', '["عدد ذرات الأكسجين يظهر في أي صيغة، والغرض من هذه الكتابة إبراز ذرة الهيدروجين القابلة للتأين.","الصحيح أن ذرة واحدة فقط قابلة للتأين، ولو تأينت الأربع لكان الحمض رباعي البروتونات.","كتابة الصيغة لا تتعلق بقوة الحمض، بل بإبراز ذرة الهيدروجين الوحيدة القابلة للتأين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.468Z"}'::jsonb),
('mcq', 4, 1, 'تصنيف الحمض إلى أحادي البروتون أو متعدد البروتونات يعتمد على عدد ذرات الهيدروجين القابلة للتأين في كل جزيء، لا على العدد الكلي لذرات الهيدروجين.', '["قد يحتوي الجزيء على ذرات هيدروجين غير قابلة للتأين، كما في CH₃COOH ذي الذرات الأربع وهو أحادي البروتون.","","قوة الحمض لا تحدد عدد البروتونات التي يمنحها؛ فـ HCl قوي وHF ضعيف وكلاهما أحادي البروتون.","HCl وHF أحاديا البروتون ولا يحتويان على أكسجين، فعدد ذرات الأكسجين ليس معيار التصنيف."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.469Z"}'::jsonb),
('mcq', 5, 1, 'يمنح جزيء HBr أيون هيدروجين واحدًا فقط فيتكوّن Br⁻ الذي لا يحتوي على هيدروجين، فـ HBr حمض أحادي البروتون. أما البدائل الأخرى فخطوات تأين لأحماض متعددة البروتونات.', '["هذه الخطوة الأولى لتأين حمض الكربونيك الثنائي البروتونات؛ فالأيون الناتج HCO₃⁻ ما زال يحتوي على هيدروجين قابل للتأين.","","هذه الخطوة الأولى لتأين حمض الفوسفوريك الثلاثي البروتونات، ويبقى في H₂PO₄⁻ ذرتا هيدروجين قابلتان للتأين.","هذه الخطوة الأولى لتأين حمض الكبريتيك الثنائي البروتونات، ويبقى في HSO₄⁻ هيدروجين قابل للتأين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.469Z"}'::jsonb),
('mcq', 6, 3, 'الحمض الأحادي البروتون يمنح أيون هيدروجين واحدًا فقط، لكن جزيئه قد يحتوي على ذرات هيدروجين أخرى غير قابلة للتأين، كما في CH₃COOH الذي فيه أربع ذرات هيدروجين.', '["CH₃COOH أحادي البروتون وفيه أربع ذرات هيدروجين، فالعبارة غير صحيحة دائمًا.","HF وCH₃COOH أحاديا البروتون لكنهما حمضان ضعيفان.","HNO₃ وHClO₄ وCH₃COOH أحماض أحادية البروتون تحتوي على أكسجين.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.469Z"}'::jsonb),
('mcq', 7, 0, 'ذرات الهيدروجين في البنزين مرتبطة بالكربون بروابط غير قطبية فلا تتأين، فالبنزين ليس حمضًا؛ أما حمض الإيثانويك ففيه ذرة هيدروجين واحدة قابلة للتأين مرتبطة بالأكسجين، فهو أحادي البروتون.', '["","هذا الخطأ يعدّ كل ذرات الهيدروجين قابلة للتأين، والمرتبطة بالكربون منها لا تتأين.","عكس الصحيح؛ فالبنزين غير حمضي، وحمض الإيثانويك يتأين فيه هيدروجين واحد.","وجود الكربون لا يجعل المركب حمضًا؛ فالبنزين لا يحتوي على ذرة هيدروجين قابلة للتأين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.469Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الحمض الأحادي البروتون: الحمض الذي يستطيع أن يمنح أيون هيدروجين واحدًا فقط لكل جزيء. مثالان: HCl وHF (ويقبل HNO₃ أو HClO₄ أو HBr أو CH₃COOH). يُعد CH₃COOH أحادي البروتون لأن ذرة هيدروجين واحدة فقط من الأربع قابلة للتأين، وهي المرتبطة بذرة الأكسجين برابطة قطبية، أما الثلاث الأخرى فمرتبطة بالكربون ولا تتأين.', '["التعريف","مثالان صحيحان","ذرة هيدروجين واحدة فقط قابلة للتأين","هي المرتبطة بالأكسجين والأخرى مرتبطة بالكربون"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"مثالان صحيحان","marks":1},{"element":"تفسير حالة CH₃COOH","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"تعريف ومثالان وتفسير كامل"},{"level":"3 درجات","description":"تعريف ومثالان مع تفسير ناقص"},{"level":"2 درجتان","description":"تعريف صحيح فقط أو مثالان مع تفسير"},{"level":"1 درجة","description":"مثالان صحيحان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["تعريفه بأنه الحمض ذو ذرة الهيدروجين الواحدة","ذكر H₂SO₄ مثالًا","القول إن ذرات الهيدروجين الأربع تتأين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (17%)"}],"at":"2026-10-17T11:36:22.469Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الحمض الأحادي البروتون: يمنح أيون هيدروجين واحدًا فقط لكل جزيء؛ فيه ذرة هيدروجين واحدة قابلة للتأين؛ مثاله HCl (أو HNO₃، HF، CH₃COOH). الحمض الثنائي البروتونات: يمنح أيوني هيدروجين لكل جزيء؛ فيه ذرتا هيدروجين قابلتان للتأين؛ مثاله H₂SO₄ (أو H₂CO₃).', '["تعريف الأحادي","تعريف الثنائي","عدد الذرات القابلة للتأين في كل منهما","مثال لكل منهما"]'::jsonb, '[]'::jsonb, '[{"element":"التعريفان","marks":2},{"element":"عدد ذرات الهيدروجين القابلة للتأين","marks":1},{"element":"مثالان صحيحان","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة بالتعريفين والعدد والمثالين"},{"level":"3 درجات","description":"نقص عنصر واحد"},{"level":"2 درجتان","description":"تعريفان صحيحان فقط"},{"level":"1 درجة","description":"مثالان صحيحان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الاعتماد على العدد الكلي لذرات الهيدروجين","ذكر CH₃COOH مثالًا على الثنائي","الخلط بين عدد البروتونات وقوة الحمض"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.469Z"}'::jsonb),
('essay', 3, null::int, null, null, 'HF: ذرة هيدروجين واحدة، وهي قابلة للتأين لارتباطها بالفلور العالي الكهروسالبية برابطة قطبية ← حمض أحادي البروتون. CH₃COOH: أربع ذرات هيدروجين، واحدة فقط قابلة للتأين (المرتبطة بالأكسجين) ← حمض أحادي البروتون. C₆H₆: ست ذرات هيدروجين، لا شيء منها قابل للتأين؛ لأن كل ذرة مرتبطة بكربون كهروسالبيته تقارب كهروسالبية الهيدروجين فالروابط غير قطبية ← ليس حمضًا.', '["HF: 1 من 1، أحادي البروتون","CH₃COOH: 1 من 4، أحادي البروتون","C₆H₆: صفر من 6، ليس حمضًا","التعليل بالرابطة القطبية مع ذرة عالية الكهروسالبية"]'::jsonb, '[]'::jsonb, '[{"element":"تحليل HF","marks":1},{"element":"تحليل CH₃COOH","marks":1},{"element":"تحليل C₆H₆","marks":1},{"element":"التعليل","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تحليل صحيح للمواد الثلاث مع تعليل كامل"},{"level":"3 درجات","description":"تصنيف صحيح للمواد الثلاث مع تعليل ناقص"},{"level":"2 درجتان","description":"تصنيف صحيح لمادتين"},{"level":"1 درجة","description":"تصنيف صحيح لمادة واحدة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ البنزين حمضًا سداسي البروتونات","عدّ CH₃COOH رباعي البروتونات","التعليل بعدد الذرات لا بنوع الرابطة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.469Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
