from (values
('mcq', 1, 0, 'حمض النيتريك HNO₃ يمنح أيون هيدروجين واحدًا فقط لكل جزيء، وهو من الأحماض الأحادية البروتون.', '["","حمض الكبريتيك فيه ذرتا هيدروجين قابلتان للتأين، فهو ثنائي البروتونات.","حمض الفوسفوريك فيه ثلاث ذرات هيدروجين قابلة للتأين، فهو ثلاثي البروتونات.","حمض الكربونيك يمنح أيوني هيدروجين، فهو ثنائي البروتونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-10-17T11:36:22.470Z"}'::jsonb),
('mcq', 2, 2, 'حمض الهيدروكلوريك HCl والهيدروبروميك HBr والبيركلوريك HClO₄ كلها يمنح كل جزيء منها أيون هيدروجين واحدًا فقط.', '["H₂SO₄ في هذه المجموعة حمض ثنائي البروتونات.","H₂CO₃ في هذه المجموعة حمض ثنائي البروتونات.","","H₃PO₄ (حمض الفوسفوريك) في هذه المجموعة حمض ثلاثي البروتونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.470Z"}'::jsonb),
('mcq', 3, 1, 'صيغة حمض البيركلوريك HClO₄، وهو حمض أحادي البروتون.', '["HCl صيغة حمض الهيدروكلوريك، وهو أحادي البروتون لكنه ليس حمض البيركلوريك.","","HClO صيغة حمض الهيبوكلوروز، وليست صيغة حمض البيركلوريك.","هذه صيغة غير صحيحة؛ ولو صحّت لدلت على ذرتي هيدروجين، وحمض البيركلوريك فيه ذرة هيدروجين واحدة."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.470Z"}'::jsonb),
('mcq', 4, 3, 'يحتوي جزيء حمض الإيثانويك CH₃COOH على أربع ذرات هيدروجين، لكن واحدة منها فقط قابلة للتأين، فهو أحادي البروتون.', '["ذرتا الهيدروجين في H₂SO₄ كلتاهما قابلتان للتأين، فهو ثنائي البروتونات.","ذرات الهيدروجين الثلاث في حمض الفوسفوريك قابلة للتأين، فهو ثلاثي البروتونات.","ذرتا الهيدروجين في حمض الكربونيك قابلتان للتأين، فهو ثنائي البروتونات.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (45%)"}],"at":"2026-10-17T11:36:22.470Z"}'::jsonb),
('mcq', 5, 2, 'حمض الهيدروبروميك HBr أحادي البروتون؛ يمنح أيون هيدروجين واحدًا فيتكوّن Br⁻ الخالي من الهيدروجين، فيكتمل تأينه في خطوة واحدة.', '["هذه الخطوة الثالثة من تأين حمض الفوسفوريك الثلاثي البروتونات، لا تأين حمض أحادي البروتون.","هذه الخطوة الثانية من تأين حمض الكربونيك الثنائي البروتونات.","","هذه الخطوة الأولى لتأين حمض الكبريتيك الثنائي البروتونات، ويبقى في HSO₄⁻ هيدروجين قابل للتأين."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.470Z"}'::jsonb),
('mcq', 6, 1, 'في فلوريد الهيدروجين HF ترتبط ذرة الهيدروجين بذرة الفلور العالية الكهروسالبية برابطة قطبية فتكون قابلة للتأين، وهو حمض أحادي البروتون.', '["ترتبط ذرة الهيدروجين في HCl بذرة الكلور لا بالفلور.","","ترتبط ذرة الهيدروجين في HBr بذرة البروم لا بالفلور.","ترتبط ذرة الهيدروجين القابلة للتأين في HNO₃ بذرة أكسجين، ولا يحتوي الحمض على فلور."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (18%)"}],"at":"2026-10-17T11:36:22.471Z"}'::jsonb),
('mcq', 7, 3, 'حمض الكبريتيك H₂SO₄ يحتوي على ذرتي هيدروجين قابلتين للتأين، فهو ثنائي البروتونات ولا ينتمي إلى المجموعة؛ أما الثلاثة الأخرى فأحادية البروتون.', '["HCl يمنح أيون هيدروجين واحدًا فقط، فتصنيفه أحادي البروتون صحيح.","HF يمنح أيون هيدروجين واحدًا فقط، فتصنيفه أحادي البروتون صحيح.","CH₃COOH فيه ذرة هيدروجين واحدة قابلة للتأين، فتصنيفه أحادي البروتون صحيح رغم ذرات الهيدروجين الأربع.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.471Z"}'::jsonb),
('essay', 1, null::int, null, null, 'من الأمثلة: حمض الهيدروكلوريك HCl، فلوريد الهيدروجين (حمض الهيدروفلوريك) HF، حمض البيركلوريك HClO₄، حمض النيتريك HNO₃، حمض الهيدروبروميك HBr، حمض الإيثانويك CH₃COOH (يكفي أربعة).', '["أربعة أحماض أحادية البروتون صحيحة","الاسم الصحيح لكل حمض","الصيغة الصحيحة لكل حمض"]'::jsonb, '[]'::jsonb, '[{"element":"أربعة أسماء صحيحة","marks":2},{"element":"أربع صيغ صحيحة","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"أربعة أمثلة بأسمائها وصيغها صحيحة"},{"level":"3 درجات","description":"ثلاثة أمثلة كاملة"},{"level":"2 درجتان","description":"مثالان كاملان أو أربع صيغ دون أسماء"},{"level":"1 درجة","description":"مثال واحد كامل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر H₂SO₄ أو H₂CO₃ أو H₃PO₄","كتابة HClO₄ صيغةً لحمض الهيدروكلوريك","الخلط بين HClO وHClO₄"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (33%)"}],"at":"2026-10-17T11:36:22.471Z"}'::jsonb),
('essay', 2, null::int, null, null, 'أحادية البروتون (ذرة هيدروجين واحدة قابلة للتأين): HCl، HNO₃، CH₃COOH، HBr. غير أحادية البروتون: H₂SO₄ (2)، H₂CO₃ (2)، H₃PO₄ (3).', '["HCl، HNO₃، HBr أحادية","CH₃COOH أحادي (1 من 4)","H₂SO₄ وH₂CO₃: 2","H₃PO₄: 3"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف HCl وHNO₃ وHBr","marks":1},{"element":"تصنيف CH₃COOH مع عدد الذرات القابلة للتأين","marks":1},{"element":"تصنيف H₂SO₄ وH₂CO₃ مع العدد","marks":1},{"element":"تصنيف H₃PO₄ مع العدد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تصنيف صحيح لجميع الأحماض مع الأعداد"},{"level":"3 درجات","description":"خطأ في حمض واحد"},{"level":"2 درجتان","description":"خطأ في حمضين أو ثلاثة"},{"level":"1 درجة","description":"تصنيف صحيح دون أعداد أو لأقل من نصف الأحماض"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ CH₃COOH رباعي البروتونات","عدّ H₃PO₄ ثنائي البروتونات","الاعتماد على عدد ذرات الأكسجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.471Z"}'::jsonb),
('essay', 3, null::int, null, null, 'HCl(aq) + H₂O(l) → H₃O⁺(aq) + Cl⁻(aq). HNO₃(aq) + H₂O(l) → H₃O⁺(aq) + NO₃⁻(aq). كل منهما حمض أحادي البروتون؛ أي يحتوي جزيئه على ذرة هيدروجين واحدة قابلة للتأين، فيمنح أيون هيدروجين واحدًا لجزيء ماء واحد فيتكوّن أيون H₃O⁺ واحد، والقاعدة المرافقة الناتجة (Cl⁻ أو NO₃⁻) لا تحتوي على هيدروجين يمكن أن يتأين.', '["معادلة HCl","معادلة HNO₃","كل منهما أحادي البروتون (هيدروجين واحد قابل للتأين)","القاعدة المرافقة لا تحتوي على هيدروجين"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة HCl صحيحة وموزونة","marks":1},{"element":"معادلة HNO₃ صحيحة وموزونة","marks":1},{"element":"التفسير","marks":2}]'::jsonb, '[{"level":"4 درجات","description":"معادلتان صحيحتان وتفسير كامل"},{"level":"3 درجات","description":"معادلتان صحيحتان وتفسير ناقص"},{"level":"2 درجتان","description":"معادلتان صحيحتان دون تفسير"},{"level":"1 درجة","description":"معادلة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["كتابة NO₃²⁻ أو NO₂⁻ قاعدةً مرافقة","إهمال الماء وعدم كتابة H₃O⁺","التفسير بقوة الحمض بدلًا من عدد البروتونات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.471Z"}'::jsonb)
