('mcq', 1, 'أيّ الأحماض الآتية حمض ثلاثي البروتونات؟', null, '["H₂SO₄","HNO₃","CH₃COOH","H₃PO₄"]'::jsonb, 'تذكر', 'تعرف مثال', 'سهل', 'الكتاب ص 62 — الأحماض الأحادية البروتون والمتعددة البروتونات'),
('mcq', 2, 'أيّ الأحماض الآتية من الأحماض الثنائية البروتونات؟', null, '["H₃PO₄","H₂CO₃","HClO₄","HF"]'::jsonb, 'تذكر', 'تعرف مثال', 'سهل', 'الكتاب ص 62 — الأحماض الأحادية البروتون والمتعددة البروتونات'),
('mcq', 3, 'إلى أي نوع من الأحماض ينتمي حمض الفوسفوريك H₃PO₄؟', null, '["حمض أحادي البروتون","حمض ثنائي البروتونات","حمض ثلاثي البروتونات","ليس حمضًا لأنه يحتوي على الفوسفور"]'::jsonb, 'تذكر', 'تصنيف', 'متوسط', 'الكتاب ص 62 — الأحماض الأحادية البروتون والمتعددة البروتونات'),
('mcq', 4, 'أيّ المجموعات الآتية تتكوّن كلها من أحماض متعددة البروتونات؟', null, '["H₂SO₄، H₃PO₄، H₂CO₃","H₂SO₄، HNO₃، H₃PO₄","H₃PO₄، HBr، H₂CO₃","HCl، H₂CO₃، H₃PO₄"]'::jsonb, 'فهم', 'تصنيف مجموعة', 'متوسط', 'الكتاب ص 62 — الأحماض الأحادية البروتون والمتعددة البروتونات'),
('mcq', 5, 'يتأين حمض الفوسفوريك H₃PO₄ في الماء على ثلاث خطوات. ما الأيون الناتج من الخطوة الثانية إضافةً إلى H₃O⁺؟', null, '["HPO₄²⁻","H₂PO₄⁻","PO₄³⁻","H₄PO₄⁺"]'::jsonb, 'فهم', 'تتبع خطوات التأين', 'متوسط', 'الكتاب ص 63 — تأين حمض الفوسفوريك على خطوات'),
('mcq', 6, 'على أي حمض يُطلق مصطلح «حمض متعدد البروتونات»؟', null, '["أي حمض يحتوي على أكثر من ذرة هيدروجين في صيغته","الحمض الثلاثي البروتونات فقط","أي حمض يحتوي على أكثر من ذرة هيدروجين قابلة للتأين","أي حمض قوي يتأين تأينًا تامًا في الماء"]'::jsonb, 'فهم', 'تعريف مصطلح', 'متوسط', 'الكتاب ص 62 — الأحماض الأحادية البروتون والمتعددة البروتونات'),
('mcq', 7, 'أيّ المعادلات الآتية تمثل الخطوة الثانية لتأين حمض الكربونيك H₂CO₃ في الماء؟', null, '["H₂CO₃(aq) + H₂O(l) ⇌ H₃O⁺(aq) + HCO₃⁻(aq)","HCO₃⁻(aq) + H₂O(l) ⇌ H₃O⁺(aq) + CO₃²⁻(aq)","H₂CO₃(aq) + 2H₂O(l) ⇌ 2H₃O⁺(aq) + CO₃²⁻(aq)","HCO₃⁻(aq) + H₂O(l) ⇌ H₂CO₃(aq) + OH⁻(aq)"]'::jsonb, 'تطبيق', 'كتابة/تمييز معادلة', 'صعب', 'الكتاب ص 63 — تأين حمض الفوسفوريك على خطوات'),
('essay', 1, 'اذكر مثالين على الأحماض الثنائية البروتونات ومثالًا على الأحماض الثلاثية البروتونات، مع اسم كل حمض وصيغته، ثم بيّن ما المقصود بمصطلح الحمض المتعدد البروتونات.', null, null, 'تذكر', 'ذكر أمثلة وتعريف', 'سهل', 'الكتاب ص 62 — الأحماض الأحادية البروتون والمتعددة البروتونات'),
('essay', 2, 'اكتب معادلات تأين حمض الفوسفوريك H₃PO₄ في الماء على ثلاث خطوات، ثم وضّح ما الذي يدل على أنه حمض ثلاثي البروتونات.', null, null, 'تطبيق', 'كتابة معادلات', 'متوسط', 'الكتاب ص 63 — تأين حمض الفوسفوريك على خطوات'),
('essay', 3, 'حلّل الأحماض الثلاثة: HNO₃، وH₂SO₄، وH₃PO₄ من حيث عدد ذرات الهيدروجين القابلة للتأين وتصنيف كل منها، ثم فسّر لماذا يستطيع حمض الكبريتيك أن يمنح أيوني هيدروجين.', null, null, 'تحليل', 'تحليل وتفسير', 'صعب', 'الكتاب ص 62 — الأحماض الأحادية البروتون والمتعددة البروتونات')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C2-L1-O16') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 3, 'يحتوي حمض الفوسفوريك H₃PO₄ على ثلاث ذرات هيدروجين قابلة للتأين في كل جزيء، فهو ثلاثي البروتونات.', '["حمض الكبريتيك فيه ذرتا هيدروجين قابلتان للتأين، فهو ثنائي البروتونات.","حمض النيتريك يمنح أيون هيدروجين واحدًا فقط، فهو أحادي البروتون.","حمض الإيثانويك فيه أربع ذرات هيدروجين، لكن واحدة فقط قابلة للتأين، فهو أحادي البروتون.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-17T11:36:22.472Z"}'::jsonb),
('mcq', 2, 1, 'حمض الكربونيك H₂CO₃ يحتوي على ذرتي هيدروجين مرتبطتين بذرتي أكسجين بروابط قطبية، فيمنح أيوني هيدروجين، وهو ثنائي البروتونات.', '["حمض الفوسفوريك فيه ثلاث ذرات هيدروجين قابلة للتأين، فهو ثلاثي البروتونات.","","حمض البيركلوريك يمنح أيون هيدروجين واحدًا، فهو أحادي البروتون.","فلوريد الهيدروجين يمنح أيون هيدروجين واحدًا، فهو أحادي البروتون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (50%)"}],"at":"2026-10-17T11:36:22.472Z"}'::jsonb),
('mcq', 3, 2, 'حمض الفوسفوريك H₃PO₄ يحتوي على ثلاث ذرات هيدروجين قابلة للتأين في كل جزيء، فيسمى حمضًا ثلاثي البروتونات.', '["الحمض الأحادي يمنح أيون هيدروجين واحدًا، وحمض الفوسفوريك فيه ثلاث ذرات قابلة للتأين.","الحمض الثنائي فيه ذرتا هيدروجين قابلتان للتأين، وحمض الفوسفوريك فيه ثلاث.","","وجود الفوسفور لا يمنع الحمضية؛ فذرات الهيدروجين فيه قابلة للتأين وهو يُصنَّف حمضًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.472Z"}'::jsonb),
('mcq', 4, 0, 'H₂SO₄ وH₂CO₃ ثنائيا البروتونات، وH₃PO₄ ثلاثي البروتونات؛ فكلها تحتوي على أكثر من ذرة هيدروجين قابلة للتأين، أي أنها متعددة البروتونات.', '["","HNO₃ في هذه المجموعة حمض أحادي البروتون.","HBr في هذه المجموعة حمض أحادي البروتون.","HCl في هذه المجموعة حمض أحادي البروتون."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (22%)"}],"at":"2026-10-17T11:36:22.472Z"}'::jsonb),
('mcq', 5, 0, 'الخطوة الأولى: H₃PO₄ + H₂O ⇌ H₃O⁺ + H₂PO₄⁻، والخطوة الثانية: H₂PO₄⁻ + H₂O ⇌ H₃O⁺ + HPO₄²⁻، والثالثة تنتج PO₄³⁻؛ إذن ناتج الخطوة الثانية HPO₄²⁻.', '["","هذا ناتج الخطوة الأولى، وهو المتفاعل في الخطوة الثانية.","هذا ناتج الخطوة الثالثة الأخيرة بعد أن يفقد الحمض أيوناته الثلاثة.","هذا الأيون يتكوّن لو استقبل الحمض أيون H⁺، والتأين يعني منح أيون H⁺ لا استقباله."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T11:36:22.472Z"}'::jsonb),
('mcq', 6, 2, 'يمكن استعمال مصطلح حمض متعدد البروتونات لأي حمض يحتوي على أكثر من ذرة هيدروجين قابلة للتأين، فيشمل الثنائية والثلاثية البروتونات.', '["العدد الكلي لذرات الهيدروجين ليس المعيار؛ فـ CH₃COOH فيه أربع ذرات وهو أحادي البروتون.","المصطلح يشمل الحمض الثنائي البروتونات مثل H₂SO₄ أيضًا، لا الثلاثي فقط.","","عدد البروتونات لا يرتبط بقوة الحمض؛ فـ H₂CO₃ ضعيف وهو متعدد البروتونات."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (25%)"}],"at":"2026-10-17T11:36:22.472Z"}'::jsonb),
('mcq', 7, 1, 'حمض الكربونيك ثنائي البروتونات يتأين على خطوتين؛ في الأولى يتكوّن HCO₃⁻، وفي الثانية يمنح HCO₃⁻ أيون هيدروجين للماء فيتكوّن CO₃²⁻ وH₃O⁺.', '["هذه الخطوة الأولى لتأين حمض الكربونيك لا الثانية.","","هذه معادلة إجمالية تجمع الخطوتين، والأحماض المتعددة البروتونات تتأين على خطوات متتالية.","في هذه المعادلة يستقبل HCO₃⁻ أيون H⁺ فيسلك سلوك القاعدة، وهذا ليس تأينًا للحمض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (21%)"}],"at":"2026-10-17T11:36:22.472Z"}'::jsonb),
('essay', 1, null::int, null, null, 'ثنائية البروتونات: حمض الكبريتيك H₂SO₄، وحمض الكربونيك H₂CO₃. ثلاثية البروتونات: حمض الفوسفوريك H₃PO₄. الحمض المتعدد البروتونات: أي حمض يحتوي على أكثر من ذرة هيدروجين قابلة للتأين في الجزيء.', '["H₂SO₄ وH₂CO₃ ثنائيا البروتونات","H₃PO₄ ثلاثي البروتونات","معنى المتعدد البروتونات"]'::jsonb, '[]'::jsonb, '[{"element":"مثالان ثنائيا البروتونات","marks":1},{"element":"مثال ثلاثي البروتونات","marks":1},{"element":"تعريف المصطلح","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"ثلاثة أمثلة صحيحة وتعريف صحيح"},{"level":"2 درجتان","description":"ثلاثة أمثلة صحيحة دون تعريف، أو مثالان وتعريف"},{"level":"1 درجة","description":"مثالان صحيحان فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ CH₃COOH متعدد البروتونات","الخلط بين H₃PO₄ وH₂SO₄ في التصنيف","تعريف المتعدد بالعدد الكلي لذرات الهيدروجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.473Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الخطوة 1: H₃PO₄(aq) + H₂O(l) ⇌ H₃O⁺(aq) + H₂PO₄⁻(aq). الخطوة 2: H₂PO₄⁻(aq) + H₂O(l) ⇌ H₃O⁺(aq) + HPO₄²⁻(aq). الخطوة 3: HPO₄²⁻(aq) + H₂O(l) ⇌ H₃O⁺(aq) + PO₄³⁻(aq). يدل على أنه ثلاثي البروتونات أنه يمنح ثلاثة أيونات هيدروجين متتالية (ثلاث خطوات) لأن في جزيئه ثلاث ذرات هيدروجين قابلة للتأين.', '["الخطوة الأولى","الخطوة الثانية","الخطوة الثالثة","ثلاث ذرات هيدروجين قابلة للتأين/ثلاث خطوات"]'::jsonb, '[]'::jsonb, '[{"element":"الخطوة الأولى","marks":1},{"element":"الخطوة الثانية","marks":1},{"element":"الخطوة الثالثة","marks":1},{"element":"التوضيح","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"ثلاث معادلات صحيحة بالشحنات والتوضيح"},{"level":"3 درجات","description":"ثلاث معادلات صحيحة دون توضيح، أو خطأ في شحنة واحدة مع التوضيح"},{"level":"2 درجتان","description":"معادلتان صحيحتان"},{"level":"1 درجة","description":"معادلة واحدة صحيحة"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["أخطاء في شحنات H₂PO₄⁻ وHPO₄²⁻ وPO₄³⁻","كتابة التأين في خطوة واحدة","استعمال سهم باتجاه واحد مع أخطاء في نواتج الخطوات"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (26%)"}],"at":"2026-10-17T11:36:22.473Z"}'::jsonb),
('essay', 3, null::int, null, null, 'HNO₃: ذرة هيدروجين واحدة قابلة للتأين ← أحادي البروتون. H₂SO₄: ذرتان ← ثنائي البروتونات (متعدد). H₃PO₄: ثلاث ذرات ← ثلاثي البروتونات (متعدد). يستطيع H₂SO₄ منح أيوني هيدروجين لأن كل ذرة من ذرتي الهيدروجين فيه مرتبطة بذرة أكسجين برابطة قطبية؛ فالأكسجين أعلى كهروسالبية من الهيدروجين، فتصبح الذرتان قابلتين للتأين.', '["HNO₃ أحادي","H₂SO₄ ثنائي","H₃PO₄ ثلاثي","ذرتا H مرتبطتان بالأكسجين برابطتين قطبيتين"]'::jsonb, '[]'::jsonb, '[{"element":"تصنيف HNO₃","marks":1},{"element":"تصنيف H₂SO₄","marks":1},{"element":"تصنيف H₃PO₄","marks":1},{"element":"التفسير بالروابط القطبية مع الأكسجين","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف صحيح للثلاثة وتفسير كامل"},{"level":"3 درجات","description":"تصنيف صحيح للثلاثة مع تفسير ناقص"},{"level":"2 درجتان","description":"تصنيف صحيح لحمضين"},{"level":"1 درجة","description":"تصنيف صحيح لحمض واحد"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ H₃PO₄ غير حمضي","تفسير منح البروتونين بقوة الحمض","عدّ HNO₃ متعدد البروتونات لاحتوائه على أكسجين"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (11%)"}],"at":"2026-10-17T11:36:22.473Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K3-C2-L1-O16') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K3-C2-L1-O17'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما المقصود بالأنهيدريد الحمضي؟', null, '["أكسيد يتحد مع الماء ليكوّن قاعدة","أكسيد يتحد مع الماء ليكوّن حمضًا","حمض أضيف إليه جزيء ماء","ملح ينتج من تفاعل حمض مع قاعدة"]'::jsonb, 'تذكر', 'تعريف', 'سهل', 'الكتاب ص 65 — الربط مع علم الأرض: الأنهيدريدات'),
('mcq', 2, 'أيّ الأكاسيد الآتية مثال على الأنهيدريد الحمضي؟', null, '["CO₂","CaO","MgO","Na₂O"]'::jsonb, 'تذكر', 'تعرف مثال', 'سهل', 'الكتاب ص 65 — الربط مع علم الأرض: الأنهيدريدات'),
('mcq', 3, 'ما ناتج اتحاد غاز ثاني أكسيد الكربون مع الماء في الجو؟', null, '["كربونات الكالسيوم CaCO₃","حمض الكبريتيك H₂SO₄","حمض الإيثانويك CH₃COOH","حمض الكربونيك H₂CO₃"]'::jsonb, 'تذكر', 'استرجاع ناتج', 'متوسط', 'الكتاب ص 65 — الربط مع علم الأرض: الأنهيدريدات'),
('mcq', 4, 'ماذا تكوّن أكاسيد اللافلزات عمومًا عند اتحادها بالماء؟', null, '["قواعد","أملاحًا","أحماضًا","مواد متعادلة"]'::jsonb, 'فهم', 'تعميم', 'متوسط', 'الكتاب ص 65 — الربط مع علم الأرض: الأنهيدريدات'),
('mcq', 5, 'لماذا يُسهم غاز SO₃ المتصاعد من محطات الطاقة العاملة بالفحم في تكوين المطر الحمضي إذا انتشر في الغلاف الجوي؟', null, '["لأنه يتحد مع الماء في الهواء مكوّنًا قاعدة قوية","لأنه يتحد مع MgO في الهواء مكوّنًا حمضًا","لأنه يتحلل في الهواء إلى أيونات هيدروجين","لأنه يتحد مع الماء في الهواء مكوّنًا حمض الكبريتيك"]'::jsonb, 'فهم', 'تفسير ظاهرة', 'متوسط', 'الكتاب ص 65 — تفاعل SO₃ والمطر الحمضي'),
('mcq', 6, 'تتكوّن الكهوف الضخمة في الصخور الجيرية عبر آلاف السنين. ما التفسير الصحيح لذلك؟', null, '["CO₂ أنهيدريد قاعدي يكوّن مع ماء المطر قاعدة تذيب الصخور الجيرية","CO₂ أنهيدريد حمضي يكوّن مع ماء المطر حمضًا يذيب الصخور الجيرية ببطء","الماء النقي يذيب كربونات الكالسيوم بسرعة دون وجود CO₂","أكسيد الكالسيوم يتحد مع ماء المطر فيكوّن حمضًا يذيب الصخور"]'::jsonb, 'فهم', 'تفسير ظاهرة', 'صعب', 'الكتاب ص 65 — الربط مع علم الأرض: الأنهيدريدات'),
('mcq', 7, 'الأنهيدريد الحمضي حمض منزوع منه جزيء ماء. ما الأنهيدريد الحمضي لحمض الكبريتيك H₂SO₄؟', null, '["SO₃","SO₂","H₂S","MgSO₄"]'::jsonb, 'تطبيق', 'استنتاج صيغة', 'صعب', 'الكتاب ص 65 — تفاعل SO₃ والمطر الحمضي'),
('essay', 1, 'عرّف الأنهيدريد الحمضي، واذكر مثالًا عليه، واكتب معادلة اتحاده بالماء.', null, null, 'تذكر', 'تعريف مع مثال ومعادلة', 'سهل', 'الكتاب ص 65 — الربط مع علم الأرض: الأنهيدريدات'),
('essay', 2, 'فسّر تكوّن الكهوف والهوابط والصواعد في المناطق الجيرية، مبينًا دور ثاني أكسيد الكربون بوصفه أنهيدريدًا حمضيًا.', null, null, 'فهم', 'تفسير ظاهرة', 'متوسط', 'الكتاب ص 65 — الربط مع علم الأرض: الأنهيدريدات'),
('essay', 3, 'لديك ثلاثة أكاسيد: CO₂، وSO₃، وCaO. حدّد أيها أنهيدريد حمضي مع كتابة معادلة اتحاده بالماء، ثم تحقق من عبارة «الأنهيدريد الحمضي حمض منزوع منه جزيء ماء» بتطبيقها على حمض الكربونيك.', null, null, 'تحليل', 'تصنيف وتحقق', 'صعب', 'الكتاب ص 65 — تفاعل SO₃ والمطر الحمضي')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C2-L1-O17') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 1, 'الأنهيدريد الحمضي حمض منزوع منه جزيء ماء، وهو أكسيد يستطيع أن يتحد مع الماء ليكوّن حمضًا، مثل CO₂ الذي يكوّن H₂CO₃.', '["الأكسيد الذي يكوّن قاعدة مع الماء أكسيد فلزي مثل CaO، لا أنهيدريد حمضي.","","العكس هو الصحيح؛ الأنهيدريد حمض نُزع منه جزيء ماء، لا حمض أضيف إليه الماء.","هذا وصف الملح، والأنهيدريد الحمضي أكسيد لا ملح."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.473Z"}'::jsonb),
('mcq', 2, 0, 'ثاني أكسيد الكربون CO₂ أكسيد لافلز يتحد مع الماء مكوّنًا حمض الكربونيك H₂CO₃، فهو أنهيدريد حمضي.', '["","أكسيد الكالسيوم أكسيد فلزي يكوّن مع الماء القاعدة Ca(OH)₂.","أكسيد الماغنسيوم أكسيد فلزي، ويسلك في تفاعله مع SO₃ سلوك القاعدة.","أكسيد الصوديوم أكسيد فلزي يكوّن مع الماء قاعدة (NaOH)، وأكاسيد الفلزات عمومًا تكوّن القواعد."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.473Z"}'::jsonb),
('mcq', 3, 3, 'يتحد CO₂ مع الماء: CO₂ + H₂O → H₂CO₃، فيتكوّن حمض الكربونيك الذي يهطل مع المطر.', '["CaCO₃ مكوّن الصخور الجيرية التي يذيبها الحمض، وليس ناتج اتحاد CO₂ مع الماء.","H₂SO₄ ينتج من اتحاد SO₃ مع الماء لا من CO₂.","حمض الإيثانويك مركب عضوي لا ينتج من اتحاد CO₂ مع الماء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.473Z"}'::jsonb),
('mcq', 4, 2, 'أكاسيد العناصر الفلزية تكوّن القواعد، بينما تكوّن أكاسيد اللافلزات الأحماض، ومن أمثلتها CO₂ وSO₃.', '["القواعد تتكوّن من أكاسيد الفلزات مثل CaO، لا من أكاسيد اللافلزات.","اتحاد الأكسيد بالماء لا يكوّن ملحًا، بل يكوّن حمضًا في حالة أكاسيد اللافلزات.","","محاليل أكاسيد اللافلزات في الماء حمضية لا متعادلة؛ إذ تكوّن أحماضًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-17T11:36:22.474Z"}'::jsonb),
('mcq', 5, 3, 'إذا تُرك لينتشر في الغلاف الجوي اتحد مع الماء الموجود في الهواء مكوّنًا حمض الكبريتيك الذي يسقط في صورة مطر حمضي؛ فهو أكسيد لافلز يعمل أنهيدريدًا حمضيًا.', '["أكاسيد اللافلزات مثل SO₃ تكوّن أحماضًا مع الماء لا قواعد.","تفاعل SO₃ مع MgO ينتج ملح MgSO₄ لا حمضًا، ويُستعمل لمنع المطر الحمضي لا لتكوينه.","SO₃ لا يحتوي على هيدروجين، والحمض يتكوّن من اتحاده مع الماء.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-17T11:36:22.474Z"}'::jsonb),
('mcq', 6, 1, 'يتحد CO₂ مع الماء مكوّنًا H₂CO₃ الذي يهطل مع المطر ويتسرب إلى الصخور الجيرية فيذيبها ببطء، فتتكوّن الكهوف؛ وسبب ذلك أن CO₂ أنهيدريد حمضي.', '["CO₂ أكسيد لافلز فهو أنهيدريد حمضي، والذي يذيب الصخور الجيرية حمض لا قاعدة.","","تكوّن الكهوف مرتبط بماء المطر الحمضي الناتج من CO₂، والإذابة بطيئة عبر آلاف السنين.","CaO أكسيد فلزي يكوّن مع الماء قاعدة Ca(OH)₂ لا حمضًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.474Z"}'::jsonb),
('mcq', 7, 0, 'بنزع جزيء ماء من H₂SO₄ نحصل على: H₂SO₄ − H₂O = SO₃، وهذا يتفق مع أن SO₃ يتحد مع الماء مكوّنًا حمض الكبريتيك.', '["","SO₂ + H₂O تعطي H₂SO₃ لا H₂SO₄؛ فعدد ذرات الأكسجين لا يتوافق مع نزع جزيء ماء من H₂SO₄.","هذا ناتج نزع ذرات الأكسجين كلها لا نزع جزيء ماء، وH₂S ليس أكسيدًا.","MgSO₄ ملح ناتج من تفاعل SO₃ مع MgO، وليس أكسيدًا يكوّن حمضًا مع الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.474Z"}'::jsonb),
('essay', 1, null::int, null, null, 'الأنهيدريد الحمضي: حمض منزوع منه جزيء ماء، وهو أكسيد (لافلزي) يستطيع أن يتحد مع الماء ليكوّن حمضًا. مثاله ثاني أكسيد الكربون CO₂: CO₂(g) + H₂O(l) → H₂CO₃(aq). (ويقبل SO₃ + H₂O → H₂SO₄، ويقبل أي مثال صحيح مع معادلته.)', '["التعريف","مثال صحيح","معادلة صحيحة موزونة"]'::jsonb, '[]'::jsonb, '[{"element":"التعريف","marks":1},{"element":"المثال","marks":1},{"element":"المعادلة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"تعريف ومثال ومعادلة صحيحة"},{"level":"2 درجتان","description":"نقص عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["ذكر CaO مثالًا","كتابة ناتج اتحاد CO₂ بالماء CaCO₃","تعريفه بأنه حمض مضاف إليه ماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (16%)"}],"at":"2026-10-17T11:36:22.474Z"}'::jsonb),
('essay', 2, null::int, null, null, 'تتحد جزيئات CO₂ مع الماء في الجو مكوّنة حمض الكربونيك H₂CO₃ الذي يهطل مع المطر؛ لأن CO₂ أنهيدريد حمضي. يتسرب ماء المطر الحمضي في التربة إلى الصخور الجيرية فيذيبها ببطء، فتتكوّن كهوف ضخمة تحت الأرض عبر آلاف السنين. تقطر المياه من سقوف الكهوف مخلفة الجير المذاب، فيتكوّن على هيئة رقاقات تتدلى من السقف تسمى الهوابط، وتتكوّن كتل من كربونات الكالسيوم على أرض الكهوف تسمى الصواعد.', '["CO₂ + H₂O → H₂CO₃ (CO₂ أنهيدريد حمضي)","المطر الحمضي يذيب الصخور الجيرية ببطء فتتكون الكهوف","الهوابط: تتدلى من السقف","الصواعد: كتل CaCO₃ على أرض الكهف"]'::jsonb, '[]'::jsonb, '[{"element":"دور CO₂ وتكوّن H₂CO₃","marks":1},{"element":"إذابة الصخور الجيرية وتكوّن الكهوف","marks":1},{"element":"تفسير الهوابط","marks":1},{"element":"تفسير الصواعد","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"تفسير متكامل لعناصر الظاهرة الأربعة"},{"level":"3 درجات","description":"تفسير الكهوف ودور CO₂ مع أحد التكوينين"},{"level":"2 درجتان","description":"دور CO₂ وتكوّن الكهوف فقط"},{"level":"1 درجة","description":"ذكر تكوّن H₂CO₃ فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الهوابط والصواعد","عدّ CO₂ قاعدة","القول إن الإذابة سريعة"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (14%)"}],"at":"2026-10-17T11:36:22.474Z"}'::jsonb),
('essay', 3, null::int, null, null, 'CO₂ وSO₃ أنهيدريدان حمضيان لأنهما أكسيدا لافلزين: CO₂ + H₂O → H₂CO₃، SO₃ + H₂O → H₂SO₄. أما CaO فأكسيد فلزي يكوّن قاعدة: CaO + H₂O → Ca(OH)₂، فليس أنهيدريدًا حمضيًا. التحقق: H₂CO₃ − H₂O = CO₂ (ذرتا H وذرة O تُنزعان من H₂CO₃ فيبقى C وذرتا O)؛ إذن CO₂ هو حمض الكربونيك منزوعًا منه جزيء ماء.', '["CO₂ أنهيدريد حمضي مع معادلته","SO₃ أنهيدريد حمضي مع معادلته","CaO ليس أنهيدريدًا حمضيًا (يكوّن قاعدة)","التحقق: H₂CO₃ − H₂O = CO₂"]'::jsonb, '[]'::jsonb, '[{"element":"CO₂ ومعادلته","marks":1},{"element":"SO₃ ومعادلته","marks":1},{"element":"استبعاد CaO مع التعليل","marks":1},{"element":"التحقق بنزع الماء","marks":2}]'::jsonb, '[{"level":"5 درجات","description":"تصنيف صحيح ومعادلات صحيحة وتحقق كامل"},{"level":"3 درجات","description":"تصنيف ومعادلات صحيحة دون تحقق صحيح"},{"level":"2 درجتان","description":"تصنيف صحيح دون معادلات"},{"level":"1 درجة","description":"تحديد أنهيدريد حمضي واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عدّ CaO أنهيدريدًا حمضيًا","كتابة SO₃ + H₂O → H₂SO₃","طرح ذرة أكسجين واحدة بدل جزيء ماء"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (23%)"}],"at":"2026-10-17T11:36:22.474Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K3-C2-L1-O17') and x.type = v.type and x.number = v.number
on conflict (question_id) do nothing;

insert into public.questions (objective_id, type, number, stem, stimulus, options, thinking_level, question_kind, difficulty, source_ref, status, origin)
select (select id from public.objectives where code = 'K3-C2-L1-O18'), v.type, v.number, v.stem, v.stimulus::jsonb, v.options::jsonb, v.tl, v.qk, v.diff, v.src, 'generated', 'ai_generated'
from (values
('mcq', 1, 'ما ناتج ذوبان أكسيد الكالسيوم CaO (الجير الحي) في الماء؟', null, '["كربونات الكالسيوم CaCO₃","حمض الكربونيك H₂CO₃","هيدروكسيد الكالسيوم Ca(OH)₂","هيدريد الكالسيوم CaH₂"]'::jsonb, 'تذكر', 'استرجاع ناتج', 'سهل', 'الكتاب ص 65 — الربط مع علم الأرض: الأنهيدريدات (أكاسيد تكوّن قواعد)'),
('mcq', 2, 'ما الاسم الشائع لهيدروكسيد الكالسيوم Ca(OH)₂ الناتج من ذوبان الجير الحي في الماء؟', null, '["الجير الحي","الصخر الجيري","ملح إبسوم","الجير المطفأ"]'::jsonb, 'تذكر', 'استرجاع مصطلح', 'سهل', 'الكتاب ص 65 — الربط مع علم الأرض: الأنهيدريدات (أكاسيد تكوّن قواعد)'),
('mcq', 3, 'ماذا تكوّن أكاسيد العناصر الفلزية عمومًا عند اتحادها بالماء؟', null, '["تكوّن أحماضًا","تكوّن قواعد","تكوّن محاليل متعادلة","تكوّن أملاحًا"]'::jsonb, 'فهم', 'تعميم', 'متوسط', 'الكتاب ص 65 — الربط مع علم الأرض: الأنهيدريدات (أكاسيد تكوّن قواعد)'),
('mcq', 4, 'ما المقصود بالأنهيدريد القاعدي؟', null, '["أكسيد فلزي يتحد مع الماء فيكوّن قاعدة","أكسيد لافلزي يتحد مع الماء فيكوّن قاعدة","أكسيد فلزي يتحد مع الماء فيكوّن حمضًا","قاعدة أُضيف إليها جزيء ماء"]'::jsonb, 'تذكر', 'تعريف', 'متوسط', 'المحتوى المكمّل (ليس في الكتاب) — الأنهيدريد القاعدي'),
('mcq', 5, 'ما ناتج تفاعل أكسيد الصوديوم مع الماء وفق المعادلة: Na₂O(s) + H₂O(l) → ؟', null, '["NaOH(aq)","2NaOH(aq)","2NaH(aq) + O₂(g)","H₂NaO₂(aq)"]'::jsonb, 'تطبيق', 'إكمال معادلة', 'متوسط', 'المحتوى المكمّل (ليس في الكتاب) — الأنهيدريد القاعدي'),
('mcq', 6, 'أيّ الأكاسيد الآتية يكوّن عند ذوبانه في الماء محلولًا يحوّل ورق تبّاع الشمس الأحمر إلى الأزرق؟', null, '["CO₂","SO₃","CaO","SO₂"]'::jsonb, 'تطبيق', 'تنبؤ', 'صعب', 'الكتاب ص 65 — الربط مع علم الأرض: الأنهيدريدات (أكاسيد تكوّن قواعد)'),
('mcq', 7, 'يتفاعل أكسيد الماغنسيوم بوصفه أنهيدريدًا قاعديًا مع حمض الهيدروكلوريك: MgO + 2HCl → ؟ ما النواتج؟', null, '["Mg(OH)₂ + Cl₂","MgCl₂ + H₂","MgH₂ + Cl₂O","MgCl₂ + H₂O"]'::jsonb, 'تطبيق', 'تنبؤ بالنواتج', 'صعب', 'المحتوى المكمّل (ليس في الكتاب) — الأنهيدريد القاعدي'),
('essay', 1, 'وضّح بمعادلة كيميائية كيف يكوّن أكسيد الكالسيوم قاعدة عند اتحاده بالماء، واذكر الاسم الشائع لكل من المتفاعل الفلزي والناتج، ثم اذكر القاعدة العامة لأكاسيد الفلزات.', null, null, 'فهم', 'توضيح بمعادلة', 'سهل', 'الكتاب ص 65 — الربط مع علم الأرض: الأنهيدريدات (أكاسيد تكوّن قواعد)'),
('essay', 2, 'قارن بين الأنهيدريد الحمضي والأنهيدريد القاعدي من حيث: نوع العنصر المكوّن للأكسيد، وناتج اتحاده بالماء، مع مثال ومعادلة لكل منهما.', null, null, 'فهم', 'مقارنة', 'متوسط', 'المحتوى المكمّل (ليس في الكتاب) — الأنهيدريد القاعدي، والكتاب ص 65'),
('essay', 3, 'أُذيب أكسيد الصوديوم Na₂O في كأس ماء، وأُذيب ثالث أكسيد الكبريت SO₃ في كأس أخرى. تنبأ بطبيعة كل محلول (حمضي أو قاعدي) مع كتابة المعادلة، وبيّن أثر كل محلول في ورق تبّاع الشمس، ثم علّل تنبؤك.', null, null, 'تطبيق', 'تنبؤ وتعليل', 'صعب', 'المحتوى المكمّل (ليس في الكتاب) — الأنهيدريد القاعدي، والكتاب ص 57، 65')
) as v(type, number, stem, stimulus, options, tl, qk, diff, src)
where not exists (select 1 from public.questions x where x.objective_id = (select id from public.objectives where code = 'K3-C2-L1-O18') and x.type = v.type and x.number = v.number);
insert into public.question_answers (question_id, correct_index, explanation, distractor_notes, model_answer, answer_elements, solution_steps, marks, rubric, common_errors, auto_check)
select x.id, v.ci::int, v.ex::text, v.dn::jsonb, v.ma::text, v.ae::jsonb, v.ss::jsonb, v.mk::jsonb, v.rb::jsonb, v.ce::jsonb, v.ac::jsonb
from (values
('mcq', 1, 2, 'أكسيد الكالسيوم CaO يكوّن عندما يذوب في الماء القاعدة هيدروكسيد الكالسيوم: CaO + H₂O → Ca(OH)₂.', '["CaCO₃ هو الصخر الجيري، ولا يتكوّن من اتحاد CaO مع الماء وحده.","H₂CO₃ ينتج من اتحاد CO₂ بالماء، لا من أكسيد فلزي.","","اتحاد CaO بالماء يكوّن هيدروكسيدًا (يحتوي على OH⁻) لا هيدريدًا."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-17T11:36:22.475Z"}'::jsonb),
('mcq', 2, 3, 'يسمى أكسيد الكالسيوم CaO الجير الحي، وناتج ذوبانه في الماء Ca(OH)₂ الجير المطفأ.', '["الجير الحي هو أكسيد الكالسيوم CaO قبل اتحاده بالماء.","الصخر الجيري هو كربونات الكالسيوم CaCO₃.","ملح إبسوم هو كبريتات الماغنسيوم المائية MgSO₄·7H₂O.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (36%)"}],"at":"2026-10-17T11:36:22.475Z"}'::jsonb),
('mcq', 3, 1, 'أكاسيد العناصر الفلزية تكوّن القواعد عمومًا، بينما تكوّن أكاسيد اللافلزات الأحماض؛ ومثال ذلك CaO الذي يكوّن Ca(OH)₂.', '["الأحماض تتكوّن من أكاسيد اللافلزات مثل CO₂ وSO₃، لا من أكاسيد الفلزات.","","محلول CaO في الماء قاعدي لاحتوائه على أيونات OH⁻، وليس متعادلًا.","اتحاد الأكسيد الفلزي بالماء يكوّن هيدروكسيدًا (قاعدة) لا ملحًا؛ الملح ينتج من تفاعله مع حمض."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (6%)"}],"at":"2026-10-17T11:36:22.475Z"}'::jsonb),
('mcq', 4, 0, 'الأنهيدريد القاعدي أكسيد فلزي يتحد مع الماء مكوّنًا قاعدة (هيدروكسيدًا فلزيًا)، أي أنه القاعدة بعد نزع الماء منها، مثل CaO الذي يكوّن Ca(OH)₂.', '["","أكاسيد اللافلزات تكوّن أحماضًا مع الماء، فهي أنهيدريدات حمضية.","أكاسيد الفلزات تكوّن قواعد لا أحماضًا.","العكس هو الصحيح؛ «أنهيدريد» تعني بلا ماء، فهو القاعدة بعد نزع الماء منها."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (5%)"}],"at":"2026-10-17T11:36:22.475Z"}'::jsonb),
('mcq', 5, 1, 'أكسيد الصوديوم أنهيدريد قاعدي (أكسيد فلزي) يتحد مع الماء مكوّنًا هيدروكسيد الصوديوم: Na₂O + H₂O → 2NaOH، والمعادلة موزونة (Na: 2، O: 2، H: 2).', '["المعادلة غير موزونة بهذا الناتج؛ ففي المتفاعلات ذرتا صوديوم، فيلزم 2NaOH.","","الأكسيد الفلزي لا يتفكك في الماء إلى هيدريد وأكسجين، بل يكوّن هيدروكسيدًا.","هذه صيغة غير صحيحة لمركب؛ الناتج هيدروكسيد الصوديوم NaOH بمعامل 2."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (20%)"}],"at":"2026-10-17T11:36:22.475Z"}'::jsonb),
('mcq', 6, 2, 'CaO أكسيد فلزي يكوّن مع الماء القاعدة Ca(OH)₂، والقواعد تحوّل ورق تبّاع الشمس الأحمر إلى الأزرق.', '["CO₂ أكسيد لافلز يكوّن مع الماء H₂CO₃، والأحماض تحوّل ورق تبّاع الشمس الأزرق إلى الأحمر.","SO₃ أكسيد لافلز يكوّن مع الماء H₂SO₄، فمحلوله حمضي.","","SO₂ أكسيد لافلز، وأكاسيد اللافلزات تكوّن أحماضًا مع الماء."]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.476Z"}'::jsonb),
('mcq', 7, 3, 'الأنهيدريد القاعدي يتفاعل مع الأحماض مكوّنًا ملحًا وماءً: MgO + 2HCl → MgCl₂ + H₂O، والمعادلة موزونة.', '["تفاعل الأكسيد القاعدي مع الحمض ينتج ملحًا وماءً، ولا ينطلق غاز الكلور.","غاز الهيدروجين ينتج من تفاعل الحمض مع الفلز نفسه (مثل Mg)، لا مع أكسيده.","هذه نواتج غير صحيحة؛ الأكسيد القاعدي والحمض يكوّنان ملحًا وماءً.",""]'::jsonb, null, null, null, null, null, null, '{"passed":true,"checks":[{"ok":true,"label":"ثلاثة بدائل أو أربعة"},{"ok":true,"label":"البدائل غير مكررة"},{"ok":true,"label":"إجابة صحيحة واحدة محددة"},{"ok":true,"label":"أطوال البدائل متقاربة"},{"ok":true,"label":"لا توجد بدائل من نوع «جميع ما سبق»"},{"ok":true,"label":"تفسير الإجابة موجود"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (10%)"}],"at":"2026-10-17T11:36:22.476Z"}'::jsonb),
('essay', 1, null::int, null, null, 'CaO(s) + H₂O(l) → Ca(OH)₂(aq). أكسيد الكالسيوم CaO يسمى الجير الحي، وهيدروكسيد الكالسيوم Ca(OH)₂ يسمى الجير المطفأ، وهو قاعدة. القاعدة العامة: تكوّن أكاسيد العناصر الفلزية القواعد عند اتحادها بالماء (بينما تكوّن أكاسيد اللافلزات الأحماض).', '["المعادلة الصحيحة","CaO الجير الحي","Ca(OH)₂ الجير المطفأ وهو قاعدة","أكاسيد الفلزات تكوّن القواعد"]'::jsonb, '[]'::jsonb, '[{"element":"المعادلة","marks":1},{"element":"الاسمان الشائعان","marks":1},{"element":"القاعدة العامة","marks":1}]'::jsonb, '[{"level":"3 درجات","description":"معادلة واسمان وقاعدة عامة صحيحة"},{"level":"2 درجتان","description":"نقص عنصر واحد"},{"level":"1 درجة","description":"عنصر واحد صحيح"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["الخلط بين الجير الحي والجير المطفأ","كتابة الناتج CaCO₃","القول إن أكاسيد الفلزات تكوّن أحماضًا"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (3 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (9%)"}],"at":"2026-10-17T11:36:22.476Z"}'::jsonb),
('essay', 2, null::int, null, null, 'الأنهيدريد الحمضي: أكسيد عنصر لافلزي، يكوّن مع الماء حمضًا؛ مثاله CO₂ + H₂O → H₂CO₃ (أو SO₃ + H₂O → H₂SO₄). الأنهيدريد القاعدي: أكسيد عنصر فلزي، يكوّن مع الماء قاعدة (هيدروكسيدًا)؛ مثاله CaO + H₂O → Ca(OH)₂ (أو Na₂O + H₂O → 2NaOH).', '["الحمضي: أكسيد لافلز ← حمض","القاعدي: أكسيد فلز ← قاعدة","مثال ومعادلة للحمضي","مثال ومعادلة للقاعدي"]'::jsonb, '[]'::jsonb, '[{"element":"نوع العنصر في كل منهما","marks":1},{"element":"ناتج الاتحاد بالماء في كل منهما","marks":1},{"element":"مثال ومعادلة للحمضي","marks":1},{"element":"مثال ومعادلة للقاعدي","marks":1}]'::jsonb, '[{"level":"4 درجات","description":"مقارنة كاملة بمثالين ومعادلتين صحيحتين"},{"level":"3 درجات","description":"مقارنة صحيحة مع خطأ في معادلة"},{"level":"2 درجتان","description":"مقارنة صحيحة دون أمثلة ومعادلات"},{"level":"1 درجة","description":"ذكر مثال صحيح لنوع واحد فقط"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس نوع العنصر","كتابة Na₂O + H₂O → NaOH دون وزن","الاعتقاد بأن الأنهيدريد القاعدي يحتوي على OH⁻ في صيغته"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (4 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (8%)"}],"at":"2026-10-17T11:36:22.477Z"}'::jsonb),
('essay', 3, null::int, null, null, 'كأس Na₂O: Na₂O(s) + H₂O(l) → 2NaOH(aq)؛ المحلول قاعدي يحوّل ورق تبّاع الشمس الأحمر إلى الأزرق؛ لأن Na₂O أكسيد فلزي (أنهيدريد قاعدي) يكوّن قاعدة. كأس SO₃: SO₃(g) + H₂O(l) → H₂SO₄(aq)؛ المحلول حمضي يحوّل ورق تبّاع الشمس الأزرق إلى الأحمر؛ لأن SO₃ أكسيد لافلز (أنهيدريد حمضي) يكوّن حمضًا.', '["معادلة Na₂O","محلول Na₂O قاعدي ويحوّل الأحمر إلى أزرق","معادلة SO₃","محلول SO₃ حمضي ويحوّل الأزرق إلى أحمر","التعليل بنوع العنصر (فلز/لافلز)"]'::jsonb, '[]'::jsonb, '[{"element":"معادلة Na₂O موزونة","marks":1},{"element":"طبيعة محلول Na₂O وأثره في تبّاع الشمس","marks":1},{"element":"معادلة SO₃","marks":1},{"element":"طبيعة محلول SO₃ وأثره في تبّاع الشمس","marks":1},{"element":"التعليل","marks":1}]'::jsonb, '[{"level":"5 درجات","description":"تنبؤ صحيح للمحلولين بالمعادلات والأثر والتعليل"},{"level":"3 درجات","description":"تنبؤ صحيح للمحلولين مع نقص في المعادلات أو التعليل"},{"level":"2 درجتان","description":"تنبؤ صحيح لمحلول واحد كاملًا"},{"level":"1 درجة","description":"تحديد طبيعة المحلولين دون معادلات أو تعليل"},{"level":"صفر","description":"إجابة خاطئة أو لا إجابة"}]'::jsonb, '["عكس ألوان ورق تبّاع الشمس","كتابة SO₃ + H₂O → H₂SO₃","عدم وزن معادلة Na₂O"]'::jsonb, '{"passed":true,"checks":[{"ok":true,"label":"إجابة نموذجية موجودة"},{"ok":true,"label":"توزيع الدرجات (5 درجة)"},{"ok":true,"label":"سلم تصحيح بمستويين على الأقل"},{"ok":true,"label":"لا يوجد تشابه مرتفع مع أسئلة الهدف (15%)"}],"at":"2026-10-17T11:36:22.477Z"}'::jsonb)
) as v(type, number, ci, ex, dn, ma, ae, ss, mk, rb, ce, ac)
join public.questions x on x.objective_id = (select id from public.objectives where code = 'K3-C2-L1-O18') and x.type = v.type and x.number = v.number
